  },
  CollectionHall_100442_Desc = {
    Text = "<Title:รายละเอียด>\nเกิดในตระกูลผู้ค้าที่ร่ำรวย แต่ในร่างกายกลับไหลเวียนเลือดของซอมบี้ เส้นเลือดครึ่งคนครึ่งซอมบี้นี้มอบพรสวรรค์ที่ไม่เหมือนใครให้เขา ทำให้เขาสามารถเห็นโลกที่คนทั่วไปไม่สามารถมองเห็น โลกนั้นบ้าคลั่ง แปลกประหลาด และสีสันสดใสทำให้เขาไม่สามารถถอนตัวได้.\nแทบจะไม่มีเวลาคิด พิคแมนจึงเลือกที่จะบันทึกทุกอย่างที่เขาเห็นด้วยพู่กัน เขาจมอยู่ในความรู้สึกนี้ และสั่งสมทักษะการวาดให้เกิดความชำนาญในแต่ละวัน.\nการมองความงามที่น้อยคนจะยอมรับก็ทำให้พิคมันถูกทอดทิ้งไปโดยสิ้นเชิง ไม่มีใครสามารถยอมรับทฤษฎีที่บ้าคลั่งของเขาได้ พิคมันมักจะรู้สึกเศร้าใจเกี่ยวกับเรื่องนี้ แต่นเขาไม่เคยยอมแพ้.\nในที่สุด พิคแมนก็ยอมรับการย่อยสลาย และตื่นจากเลือดของซอมบี้ เขาออกจากโลกของมนุษย์มาอยู่ในเมืองของซอมบี้ สักวันหนึ่งเขาจะนำเสนอสถาบันจำลองเวทมนตร์เหล่านั้นที่อยู่ในโลกที่แท้จริงให้กับผู้คนต่อไป."
  },
  CollectionHall_100442_LockTip = {
