  },
  CollectionHall_100458_Desc = {
    Text = "วางความกังวลลงชั่วคราว ให้ความเหนื่อยหายไปให้เร็วที่สุด \n มาพักผ่อนกันสักหน่อยที่กองไฟอุ่นๆ กันเถอะ."
  },
  CollectionHall_100458_LockTip = {
