  CollectionHall_100458_Title = {
    Text = "พักผ่อนรอบกองไฟ"
  },
  CollectionHall_100459_Desc = {
    Text = "จงเผาผลาญเถอะ เผาผลาญเถอะ ทุกสิ่งที่เป็นของคุณ จงเผาผลาญมันทั้งหมดเถอะ\nแล้วในไฟอันไม่มีที่สิ้นสุดนั้น จงเริ่มงานศพของคุณและโลกเถอะ!"
  },
  CollectionHall_100459_LockTip = {
