  },
  CollectionHall_100460_Desc = {
    Text = "“ข้าบอกแล้วว่า ไม่ว่าจะต้องใช้วิธีใด ข้าจะพาทุกคนกลับบ้าน.”\n“ข้าจะเผาผลาญทุกสิ่งที่เป็นของข้า จากนั้น...\n”ด้วยไฟแห่งกรรมจากดวงดาว จะเผาไหม้โลกอันหลอกลวง สกปรก และเต็มไปด้วยความวุ่นวายให้หมดสิ้น!“\n”ข้าขอประกาศในนามเคทีไกลูร่า!“\n”รุ่งอรุณจะมาถึง!“"
  },
  CollectionHall_100460_LockTip = {
    Text = "เสร็จสิ้นการสำรวจจิตสำนึก「วันกลางคืนที่ไม่ตาย」"
  },
  CollectionHall_100460_Title = {
    Text = "รุ่งอรุณที่เผาไหม้ทุกสิ่ง"
  },
  CollectionHall_100461_Desc = {
    Text = "สภาพความตายที่บ้าคลั่งหมุนวนเหมือนกับไม้ระแนงหลายสี กลิ่นหวานและเหม็นของโรคและศพเป็นน้ำหอมที่ดีที่สุด คุณยกแก้วขึ้นจากระยะไกลที่มีผู้คนมากมายเดินทางไปสู่ความตาย——หากความตายเป็นสิ่งที่กำหนดไว้แล้ว ก็ให้เราเดินไปอย่างมีความสุขสู่การเต้นรำนี้ ในจังหวะสุดท้ายของการเต้นรำร่วมกันตกลงไปที่ประตูของนรก."
  },
  CollectionHall_100461_LockTip = {
    Text = "สำเร็จ「การล่องเรือในจิตสำนึก」ระดับ「งานเลี้ยงกลุ่มเพลิงไหม้」ความยาก「ยาก」"
