  CollectionHall_100461_Title = {
    Text = "ไวน์แดง,ดอกไม้ และความตายอันหรูหรา"
  },
  CollectionHall_100462_Desc = {
    Text = "นานมาแล้ว เธอเป็นจักรพรรดิผู้มีอำนาจในจักรวาล ทุกสิ่งที่เห็นเป็นของใต้บังคับบัญชาของเธอ \n ผ่านไปนาน เธอมองเห็นแต่ฝุ่นผงที่ไร้ขอบเขต ตั้งแต่นั้นมา สิ่งที่เธอปกครองเหลือเพียงความแห้งแล้งและความโดดเดี่ยว."
  },
  CollectionHall_100462_LockTip = {
    Text = "สำเร็จการล่องเรือในจิตสำนึก「งานเลี้ยงเพลิงที่ลุกโชน」"
  },
  CollectionHall_100462_Title = {
    Text = "ราชินีผู้ควบคุมความแห้งแล้ง"
  },
  CollectionHall_100463_Desc = {
    Text = "เธอเป็นคนที่บ้าคลั่ง โหดร้าย และอารมณ์แปรปรวน ในขณะเดียวกันเธอก็ใจดี มีความรู้ และเต็มไปด้วยปัญญา \n เธอเป็นทรราชผู้มีชีวิตเสเพล และเป็นผู้ปกป้องของลูกแกะ เธอมอบความรักให้กับคุณ และมอบความตายให้กับคุณเช่นกัน สรรพชีวิตในแผ่นดินนี้ต้องคุกเข่าลงที่เท้าของเธอ และเรียกชื่อของเธอด้วยความเคารพ \n จงดื่มด่ำในงานเลี้ยงของราชินีอย่างเต็มที่ แล้วร่วมกับเธอ ดำดิ่งสู่เปลวไฟสีดำที่เป็นนิรันดร์."
  },
  CollectionHall_100463_LockTip = {
    Text = "สำเร็จการล่องเรือในจิตสำนึก「งานเลี้ยงเพลิงที่ลุกโชน」"
