  CollectionHall_100464_Desc = {
    Text = "หากก่อนตายได้ทำสิ่งสุดท้ายเพียงอย่างเดียว ก็ให้เต้นรำเถอะ.\nดื่มเหล้าที่หวานหอม และเคี้ยวเนื้อย่างที่อร่อย ในเสียงเพลงที่ครึกครื้นอย่างเต็มที่.\nให้โลกที่สะท้อนอยู่ในสายตา ส่องแสงทองที่มึนเมา."
