  },
  CollectionHall_117976_Desc = {
    Text = "แสงแดดส่องผ่านกระจกของเรือนดอกไม้ไปยังใบหน้าของฮอร์ลา เธอผ่านมาในแสงแดด และมายังฮอร์ลาที่อยู่ในอาการงงงวย.\nทุกครั้งที่ปลุกเธอ เธอจะซ่อนไว้ด้วยดอกกุหลาบที่อยู่ข้างหลัง."
