  },
  CollectionHall_117978_Title = {
    Text = "ดินแดนแห่งจินตนาการ"
  },
  CollectionHall_117979_Desc = {
    Text = "ถ้าในฉากแรกมีปืน ปืนจะดังในตอนท้าย.\nคุณได้คิดเรื่องราวที่ต้องบอกกับเธอเมื่อพบกันอีกครั้งแล้ว.\nนั่นคือความฝัน ความฝันเริ่มต้นจากดวงอาทิตย์ที่สว่างไสว หล่นลงมา ความฝันจบลงด้วยดวงอาทิตย์ที่มืดมน"
  },
  CollectionHall_117979_LockTip = {
