    Text = "เธอก้าวเท้าในทรายเพื่อสร้างคลื่นสีดำ กดคุณ ขว้างคุณ ทิ้งทุกสิ่งที่ส่งจากความรกร้างให้แก่คุณ.\nคืนนี้ดวงจันทร์ปิดบังความลับอันวิจิตรและคลุมเครือ เธอทั้งนำเสนอคำถามให้แก่คุณในการเต้นรำและทิ้งปริศนามากมายให้คุณ"
