  CollectionHall_121154_Title = {
    Text = "สวนสนุก"
  },
  CollectionHall_121341_Desc = {
    Text = "<Title:บทนำ>\nเจ้าหญิงที่รับหน้าที่ในการตั้งครรภ์ \"พระนางศักดิ์สิทธิ์\"ปัจจุบันกลายเป็น \"พระมารดาเทพ\"ที่สำคัญในลัทธิผู้เหยียบทะเล.\nเธอเคยเป็นสุภาพสตรีผู้ไขว่คว้าอิสรภาพ,     เช่นเดียวกับที่มิซากะบันทึกไว้ เดินทางหลบหนีขึ้นเรือโซนาณิลหมายเลขพร้อมกับเมอร์ฟี่.\nแต่ในโลกที่ไม่มีผู้พิทักษ์ ชะตากรรมได้ทำลายคอที่สูงส่งของหงส์น้อย.\nเลือดที่ผิดปกติพันกันโดยไม่ให้เธอต่อสู้ แม้จะปล่อยให้ร่างกายตายก็ยังไม่อาจหลีกเลี่ยงได้.เธอฝืนตัวเองพูดออกมาทีละประโยค「ข้าคือพระมารดาเทพผู้ทรงเกียรติ」,     ล้วนเป็นเพียงการชี้แนะและชักจูงตัวเอง.\nต้องเชื่อฟังเท่านั้น,     มีเพียงการเชื่อฟัง.เชื่อฟังคำพยากรณ์อันหลอกลวง,     ยอมจำนนต่อชะตากรรมอันไร้สาระ,     แล้วจากความขมขื่นอันไร้ที่สิ้นสุด,     ยังพอได้ลิ้มรสความหวานอันเป็นเพียงภาพลวงตาอยู่บ้าง."
  },
  CollectionHall_121341_LockTip = {
    Text = "ปลุกตื่น「กำเนิดลวง·เมอร์ฟี่」หลังจากปลดล็อก"
  },
  CollectionHall_121341_Title = {
    Text = "ต้นกำเนิดมอร์ฟี่"
  },
  CollectionHall_121381_Desc = {
    Text = "คุณใช้ลูกโอ๊กหนึ่งพันลูกแลกกับเรื่องราวจากต่างโลก.\nเรื่องราวเกี่ยวกับฮีโร่กับปีศาจ เวลารอคอยและความมุ่งมั่น.\nเรื่องราวเกี่ยวกับความสิ้นหวังและความเศร้าโศก เพื่อนเก่าและเพื่อนใหม่.\nเรื่องราวที่เคยเกิดขึ้น."
  },
  CollectionHall_121381_LockTip = {
    Text = "ทำสำเร็จการเชื่อมต่อหลายมิติ「เทิร์นพลิกเกม」"
  },
  CollectionHall_121381_Title = {
    Text = "กึกก้องของโรงแรมรูปหล่อน"
  },
  CollectionHall_121382_Desc = {
    Text = "นานมาแล้ว เขากับเขาในที่สุดก็มีบทกวีที่ถูกขับขาน.\nเกี่ยวกับการฟื้นคืนชีพและการไถ่บาปของวิญญาณที่เป็นหนึ่งเดียวกัน."
  },
  CollectionHall_121382_LockTip = {
    Text = "สำเร็จโลกแห่งความฝัน 「นอกขอบฟ้า·ลง」"
  },
  CollectionHall_121382_Title = {
    Text = "บทกวีของนกไม่มีปีก"
  },
  CollectionHall_121383_Desc = {
    Text = "เด็กหนุ่มแลกทุกสิ่งที่ชั่วคราวด้วยราคาที่ต้องจ่ายแห่งการเรียกร้อง.\nตอนนี้ เหลือแค่สิทธิ์เงียบที่อยู่เคียงข้างเขา.\nพระราชาจะหลับไป เขาจะต้อนรับความสิ้นสุดของโลกในฝัน"
  },
  CollectionHall_121383_LockTip = {
    Text = "เสร็จสิ้นการล่องเรือในจิตสำนึก「วันสวมมงกุฎ」"
  },
  CollectionHall_121383_Title = {
