  CollectionHall_121384_Desc = {
    Text = "พวกเธอล้อมรอบคุณ พวกเธอนับถือคุณ พวกเธออยู่ข้างคุณ.\nพวกเธอแล่นเรือไปยังพระเจ้าแห่งการสร้างสรรค์"
