  CollectionHall_121384_Title = {
    Text = "ออกเดินเรือไปยังพระเจ้าผู้สร้าง"
  },
  CollectionHall_121385_Desc = {
    Text = "นั่นคือปีกที่เกิดใหม่จากการพังทลาย,      นั่นคือปีกที่ได้มาจากการสละชีพเพื่อความอิสระ.\nคำทำนายแห่งโชคชะตาได้กลายเป็นจริงแล้ว เขาได้ริเริ่มคำมั่นสัญญาว่าจะใช้เลือดชดใช้หนี้เลือด."
  },
  CollectionHall_121385_LockTip = {
    Text = "สำเร็จโลกแห่งความฝัน 「นอกขอบฟ้า·ลง」"
  },
  CollectionHall_121385_Title = {
    Text = "เมื่อพายุเริ่มขึ้น"
  },
  CollectionHall_121386_Desc = {
    Text = "ในจุดเริ่มต้นของความฝันที่ไร้สาระและเคออส เขาจะต้องเผชิญกับโชคชะตาของเขา.\nแต่เขาได้ประสบกับสิ่งมากมาย และนิยามสิ่งมากมาย.\nเขาต้องการที่จะเฝ้าดูต้นกำเนิดของเขาในปรัชญาสูงสุด ด้วยความมีสติที่สุดของมนุษย์."
  },
  CollectionHall_121386_LockTip = {
