  },
  CollectionHall_121386_Title = {
    Text = "สงครามแห่งชะตากรรมดั้งเดิม"
  },
  CollectionHall_121387_Desc = {
    Text = "ได้มา,      เสียไป,      ตัดขาด,      สละชีพ.\nวีรบุรุษได้จ่ายราคาที่ต้องจ่ายทั้งหมด,      อำนาจในการปกป้องสมบัตินั้นคือการตอบแทนของพระองค์."
  },
  CollectionHall_121387_LockTip = {
