  },
  CollectionHall_121387_Title = {
    Text = "ไม่ให้ความสำคัญ"
  },
  CollectionHall_121388_Desc = {
    Text = "เขาให้มงกุฎกับตัวเอง เขาเป็นทาสของตัวเอง.\nนั้นคือความอบอุ่นที่สั้นและลวงตา นั้นคือความรุ่งโรจน์ในอดีตที่ถูกกำหนดให้ล่มสลาย"
  },
  CollectionHall_121388_LockTip = {
    Text = "เสร็จสิ้นการล่องเรือในจิตสำนึก「วันสวมมงกุฎ」"
  },
  CollectionHall_121388_Title = {
    Text = "เส้นทางที่โดดเดี่ยวของพระราชาเด็ก"
  },
  CollectionHall_121389_Desc = {
    Text = "แม้ว่าสถานการณ์จะไม่อยู่ข้างคุณ แต่มุมปากของคุณก็ยกขึ้นเล็กน้อย.\n“นาทีของฉัน,     ดึงการ์ด!”\nไม่ว่าจะอยู่ที่โรงแรมมหัศจรรย์หรือในมีธาก,     \nอย่าประมาทความสามารถในการทำลายของการช่วยเหลือเด็ดขาด! อิกนาติส!"
  },
  CollectionHall_121389_LockTip = {
