  },
  CollectionHall_121389_Title = {
    Text = "ช่วงเวลาที่ทำให้ฉันพลิกกลับ!"
  },
  CollectionHall_121390_Desc = {
    Text = "ตำนานที่สมบูรณ์ไม่สามารถขาดการเปลี่ยนศัตรูเป็นมิตรได้."
  },
  CollectionHall_121390_LockTip = {
    Text = "ทำสำเร็จการสืบสวน · ความยาก 9-10 เปิดให้บริการ"
  },
  CollectionHall_121390_Title = {
    Text = "ศัตรู，เพื่อน"
  },
  CollectionHall_121391_Desc = {
    Text = "จากนี้ไป ท่านจะได้รับตำแหน่งผู้พิทักษ์ และอยู่ร่วมกับครูและนักเรียนนับหมื่นของมิซากะ"
  },
  CollectionHall_121391_LockTip = {
    Text = "ทำสำเร็จการสืบสวน · ความยาก 9-11 เปิดให้บริการ"
  },
  CollectionHall_121392_Desc = {
    Text = "เราอาจเป็นช่วงเวลาที่แวบผ่านในสมัยโบราณ เป็นกรวดในกระแสคลั่ง.\nแต่ว่าความยั่งยืนคือความเป็นนิรันดร์ที่มีค่า เพราะไม่ว่าวงการจะบ้าคลั่งและมีความโกลาหลอย่างไร——\nศักดิ์ศรีของมนุษย์จะสร้างอยู่บนแสงสว่างของเหตุผล."
  },
  CollectionHall_121392_LockTip = {
    Text = "ทำสำเร็จการสืบสวนบทที่ 9-11 เปิดให้บริการ"
  },
  CollectionHall_121392_Title = {
    Text = "บทกวีของการสถิตนิรันดร์"
  },
  CollectionHall_121393_Desc = {
    Text = "เหล่าฮีโร่กระโจนเข้าสู่เทพนิยาย ทุกเทพนิยายก็เหมือนกัน สัตว์ มาร นางฟ้า และปลายทางที่ไม่รู้จัก.\nข้ามผ่านความเป็นอิสระชั่วคราวและความต้องการอันหลอกลวง ท้ายเทพนิยายซ่อนใจที่ถูกบังคับมาให้เขา."
  },
  CollectionHall_121393_LockTip = {
    Text = "สำเร็จโลกแห่งความฝัน 「นอกขอบฟ้า·ลง」"
  },
  CollectionHall_121393_Title = {
    Text = "บินเข้าสู่ทางช้างเผือก"
  },
  CollectionHall_121394_Desc = {
    Text = "นี่คือโรงแรมมาฮาโจมที่ตั้งอยู่ในรอยแตกของโลกต่างมิติ.\nเชื่อมโยงกับจักรวาลที่แตกต่าง ส่องประกายอยู่ในดวงดาวอันกว้างใหญ่ ยินดีต้อนรับการมาถึงของคุณ.\nเดี๋ยวนะ... นี่ทำให้ผู้พิทักษ์มาที่นี่เหรอ?"
  },
  CollectionHall_121394_LockTip = {
    Text = "ทำสำเร็จการเชื่อมต่อหลายมิติ「เทิร์นพลิกเกม」"
  },
  CollectionHall_121394_Title = {
    Text = "ยินดีต้อนรับสู่โรงแรมมหัศจรรย์!"
  },
  CollectionHall_121395_Desc = {
    Text = "ดาบแห่งมีธากจะทำให้คุณชนะการต่อสู้นี้.\nความผูกพันระหว่างคุณกับคู่หูของคุณเป็นเหล็กกล้า.\nถึงแม้วันหนึ่งพวกคุณจะอยู่ในจักรวาลที่แตกต่างกัน ก็ไม่มีวันเปลี่ยนแปลงสิ่งนี้ได้."
  },
  CollectionHall_121395_LockTip = {
    Text = "ทำสำเร็จการเชื่อมต่อหลายมิติ「เทิร์นพลิกเกม」"
  },
  CollectionHall_121395_Title = {
    Text = "ดาบแห่งมิธธาก！"
  },
  CollectionHall_121396_Desc = {
    Text = "“การฝึกซ้อมประจำวันไม่ได้ทำ? ทำไมไม่ลองเล่นการ์ดวาเอลก่อนล่ะ!”\n“เขตช่วยภัยไม่มีใครไป? ทำไมไม่ลองเล่นการ์ดวาเอลก่อนล่ะ!”\n“นี่คือการต่อสู้ในระยะ หากไม่ใช่การ์ดวาเอล! ฉันจะเก็บลูกโอ๊กพันลูกให้คุณดู!”"
  },
  CollectionHall_121396_LockTip = {
    Text = "ทำสำเร็จการเชื่อมต่อหลายมิติ「เทิร์นพลิกเกม」"
  },
  CollectionHall_121396_Title = {
    Text = "มาร่วมเล่นไพ่รูปหล่อนกันเถอะ!"
  },
  CollectionHall_121397_Desc = {
    Text = "เรียกชื่อของฉัน ก่อนรุ่งอรุณที่ถูกลืม"
  },
  CollectionHall_121397_LockTip = {
    Text = "ทำสำเร็จการสืบสวน · ความยาก 9-11 เปิดให้บริการ"
  },
  CollectionHall_121397_Title = {
    Text = "มาจากการลืม @2"
  },
  CollectionHall_121398_Desc = {
    Text = "“มาเซ็นสัญญากับฉันเพื่อเป็นปรมาจารย์การ์ดกันเถอะ!”\nสาวน้อยมังกรจากโลกอื่นนี้ได้ส่งคำเชิญที่ร้อนแรงและไม่เข้าใจถึงคุณ.\nเพื่อให้เหตุการณ์เล็กๆ ในมิติการ์ดนี้กลับสู่สภาพปกติโดยเร็ว คุณไม่มีทางเลือกอื่น."
  },
  CollectionHall_121398_LockTip = {
    Text = "ทำสำเร็จการเชื่อมต่อหลายมิติ「เทิร์นพลิกเกม」"
  },
  CollectionHall_121398_Title = {
    Text = "คุณนาย เจ้าของร้าน! อิกนาติส！"
  },
  CollectionHall_121399_Desc = {
    Text = "ผู้ที่ตามหลังจะพบกับบันทึกอ้างอิงในสภาวะที่หนักหน่วงเท่านั้น\nคนที่หนีจากการเป็นฮีโร่กลายเป็นฮีโร่ และเด็กที่ให้ความสำคัญกับเพื่อนเหลือเพียงเพื่อนคนเดียว"
  },
  CollectionHall_121399_LockTip = {
    Text = "เสร็จสิ้นการล่องเรือในจิตสำนึก「วันสวมมงกุฎ」"
  },
  CollectionHall_121399_Title = {
    Text = "ข้าจะเดินคนเดียว"
  },
  CollectionHall_121400_Desc = {
    Text = "แยกตัวจากเจ้าเถอะ เผชิญหน้ากับเจ้า ปฏิเสธเจ้า.\nเรื่องราวของคุณไม่มีใครรู้ และความทรงจำของคุณจะคงอยู่ตลอดไป."
  },
  CollectionHall_121400_LockTip = {
    Text = "ทำสำเร็จการสืบสวนบทที่ 9-13 เปิดให้บริการ"
  },
  CollectionHall_121400_Title = {
    Text = "เจ้าแห่งความโง่เขลาผู้สร้างโลก"
  },
  CollectionHall_121401_Desc = {
    Text = "ทุกอย่างไม่มีความหมายอีกต่อไป,     ดังนั้นคุณจึงสามารถยืนอยู่ที่นี่ได้.\nทุกความทรงจำที่เคยเป็นมาคือความหมายทั้งหมดที่คุณสร้างขึ้น,     ดังนั้นถึงเวลาที่คุณยืนอยู่ที่นี่."
  },
  CollectionHall_121401_LockTip = {
    Text = "ทำสำเร็จการสืบสวนบทที่ 9-13 เปิดให้บริการ"
  },
  CollectionHall_121401_Title = {
    Text = "การดำรงอยู่"
  },
  CollectionHall_121402_Desc = {
    Text = "เส้นทางสู่พวกเขา หลีกหนีจากเส้นทางของพวกเขา.\nทุกอย่างกำลังจะแยกจากกัน ทุกอย่างกำลังจะสิ้นสุด ทุกอย่างกำลังจะเริ่มต้นใหม่.\nเงา ณ ประตูเริ่มต้นการรอคอยอันยาวนาน รอคอยให้กุญแจเงินนำทางคุณกลับบ้าน."
  },
  CollectionHall_121402_LockTip = {
    Text = "ทำสำเร็จการสืบสวนบทที่ 9-13 เปิดให้บริการ"
  },
  CollectionHall_121402_Title = {
    Text = "เส้นทางสู่พวกเขา"
  },
  CollectionHall_121403_Desc = {
    Text = "เส้นทางอาจเป็นของพวกเขา, แยกตัว, รวมก๊อดแตกสลาย.\nจนกระทั่งพบกับผู้ที่เป็นผู้ช่วยเหลือเพียงคนเดียว, จนในที่สุดก้าวเข้าสู่จุดสิ้นสุดที่เป็นเอกเทศ."
  },
  CollectionHall_121403_LockTip = {
    Text = "ทำสำเร็จการสืบสวน · ความยาก 9-10 เปิดให้บริการ"
  },
  CollectionHall_121403_Title = {
    Text = "จุดจบเพียงหนึ่งเดียว"
  },
  CollectionHall_121404_Desc = {
    Text = "เด็กน้อยรับดีลนี้.\nเขาพูดว่า ราชอาณาจักรของฉันจะปลอดภัย."
  },
  CollectionHall_121404_LockTip = {
    Text = "เสร็จสิ้นการล่องเรือในจิตสำนึก「วันสวมมงกุฎ」"
  },
  CollectionHall_121404_Title = {
    Text = "พิธีบรมราชาภิเษก"
  },
  CollectionHall_121405_Desc = {
    Text = "ในรอยแตกของกาลเวลาอันหายไปเคยตั้งอยู่โรงแรมมหัศจรรย์.\nเคยเชื่อมโยงกับจักรวาลที่แตกต่าง เคยส่องประกายอยู่ท่ามกลางดวงดาวอันกว้างใหญ่ เคยต้อนรับทุกท่านที่มาเยือน.\nและคุณ คือหลักฐานที่ก่อให้เกิดการมีอยู่ของทุกสิ่งนี้."
  },
  CollectionHall_121405_LockTip = {
    Text = "ทำสำเร็จการเชื่อมต่อหลายมิติ「เทิร์นพลิกเกม」"
  },
  CollectionHall_121405_Title = {
    Text = "ลาก่อนครับ, ผู้เชี่ยวชาญด้านการ์ด!"
  },
  CollectionHall_121406_Desc = {
    Text = "พระเจ้ามองมาที่คุณ และคุณได้ทำลายดวงตาของพระเจ้า"
  },
  CollectionHall_121406_LockTip = {
    Text = "ทำสำเร็จการสืบสวนบทที่ 9-13 เปิดให้บริการ"
  },
  CollectionHall_121406_Title = {
    Text = "จุดจบ"
  },
  CollectionHall_121407_Desc = {
    Text = "นักรบ ผู้ล้างแค้น ทาส เจ้า ผู้ค้า.\nมุมมองเดียวกัน? มุมมองที่แตกต่าง? มุมมองเดียวกัน."
  },
  CollectionHall_121407_LockTip = {
    Text = "ทำสำเร็จการสืบสวนบทที่ 9-11 เปิดให้บริการ"
  },
  CollectionHall_121407_Title = {
    Text = "เพลงรบหลายมิติ"
  },
  CollectionHall_121408_Desc = {
    Text = "คุณรู้ว่า คุณไม่ได้ต่อสู้เพื่อสิ่งที่ยิ่งใหญ่.\nเพื่อหนีจากการเรียน เพื่องานที่ต้องทำ เพื่อขนมหวาน เพื่อเพื่อน เพื่อเตาผิง เพื่อการใช้ชีวิตอย่างไร้จุดหมาย.\nคุณเป็นเพียงคนธรรมดา ที่ต้องตายไปในแต่ละวัน."
  },
  CollectionHall_121408_LockTip = {
    Text = "ทำสำเร็จการสืบสวน · ความยาก 9-11 เปิดให้บริการ"
  },
  CollectionHall_121408_Title = {
    Text = "สำหรับผู้ที่ไปตายทุกวัน"
  },
  CollectionHall_121409_Desc = {
    Text = "สัตว์ ทุกสัตว์ระดับสูง ย่อมไม่สามารถหลีกเลี่ยงการถูกควบคุมโดยพฤติกรรมทางสังคมได้.\nแต่เธอเดินเข้าไปยังความตาย เพื่อเปิดเผยความจริงตามที่เธอต้องการ.\nอัจฉริยะที่บ้าคลั่งและไม่มีใครเทียบเคียง เธอยอมที่จะเรียกหาการล่มสลาย และมอบชีวิตให้แก่ผู้คนให้รอดพ้นจากการกลืนกินชื่อว่า ความหวัง."
  },
  CollectionHall_121409_LockTip = {
    Text = "ทำสำเร็จการสืบสวนบทที่ 9-13 เปิดให้บริการ"
  },
  CollectionHall_121409_Title = {
    Text = "การแยกพฤติกรรมในสังคม"
  },
  CollectionHall_121410_Desc = {
    Text = "พระองค์ส่งน้ำกัดกร่อนจากสวรรค์มาอย่างไม่ขาดสาย รวมตัวกัน รวมตัวกัน. \nสุดท้ายถูกนำมาแสดงต่อหน้ากล้ามเนื้อและเลือดของเรา,     ซึ่งเป็นสายน้ำที่ต้องย้อนกลับไป"
  },
  CollectionHall_121410_LockTip = {
    Text = "สำเร็จโลกแห่งความฝัน 「นอกขอบฟ้า·ลง」"
  },
  CollectionHall_121410_Title = {
    Text = "แม่น้ำทุกข์"
  },
  CollectionHall_121411_Desc = {
    Text = "พวกเขาอำลาด้วยความคาดหวังที่จะพบกันอีกครั้ง.\nเนื่องจากนี่คือผู้มีค่าควร, นี่คือการตายของผู้มีค่าควรที่ไม่เป็นที่กำหนด."
  },
  CollectionHall_121411_LockTip = {
