  },
  CollectionHall_121411_Title = {
    Text = "การตายของผู้ที่มีค่าอันมากมาย"
  },
  CollectionHall_121412_Desc = {
    Text = "พักสักหน่อย หายใจเข้าลึก ๆ.\nแม้ว่าหัวข้อที่เผชิญหน้าคือวันสิ้นโลก ก็ไม่ใช่ทุกคนที่จะมีโอกาสพบกับอาจารย์ระดับใหญ่สามคนในเวลาเดียวกัน"
  },
  CollectionHall_121412_LockTip = {
    Text = "ทำสำเร็จการสืบสวนบทที่ 9-13 เปิดให้บริการ"
  },
  CollectionHall_121412_Title = {
    Text = "การแสดงกลางเวที"
  },
  CollectionHall_121413_Desc = {
    Text = "เรื่องราวของผลโอ๊คหนึ่งพันลูก ต้องเริ่มจากผลแรก.\nในTraphase,     ทุกครั้งที่คุณเล่นการ์ดหนึ่งใบ,     \nสายตาของอิกนาติสน้อยจะมีแสงความทรงจำสีทองไหลผ่าน."
  },
  CollectionHall_121413_LockTip = {
    Text = "ทำสำเร็จการเชื่อมต่อหลายมิติ「เทิร์นพลิกเกม」"
  },
  CollectionHall_121413_Title = {
    Text = "เติมไม่รู้จบ！"
  },
  CollectionHall_121414_Desc = {
    Text = "ความบ้าคลั่ง, นำไปสู่การทำลาย, นี่คือหลักการพื้นฐานของโลกที่มีระเบียบ.\nเขาจะถูกทำลายไหม, โลกจะถูกทำลายไหม?\nไม่มีใครทราบ.\nแต่ต่อหน้าพระเจ้าผู้สร้าง, ความบ้าคลั่งกำลังบ่มเพาะการเกิดใหม่ของพระองค์และโลก."
  },
  CollectionHall_121414_LockTip = {
    Text = "ทำสำเร็จการสืบสวนบทที่ 9-11 เปิดให้บริการ"
  },
  CollectionHall_121414_Title = {
    Text = "การประพันธ์บ้าคลั่ง"
  },
  CollectionHall_121415_Desc = {
    Text = "สิ่งที่ไร้เหตุผลที่สุดในโลกคืออะไร?\nมันไม่มีจุดหมาย ไม่เกี่ยวกับความแค้น ไม่แยกดีชั่ว\nมันแค่ต้องการทำลายทุกอย่างที่เกิดขึ้นในฝันเมื่อมันตื่นขึ้น"
  },
  CollectionHall_121415_LockTip = {
    Text = "ทำสำเร็จการสืบสวนบทที่ 9-13 เปิดให้บริการ"
  },
  CollectionHall_121415_Title = {Text = "ผง"},
  CollectionHall_121416_Desc = {
    Text = "ในฐานะชิ้นส่วนที่ไม่เหมือนใครนั้น การเป็นเทพเจ้าช่างง่ายเหลือเกิน.\nดังนั้น,      ราคาที่ต้องจ่ายคืออะไร?"
  },
  CollectionHall_121416_LockTip = {
    Text = "ทำสำเร็จการสืบสวนบทที่ 9-13 เปิดให้บริการ"
  },
  CollectionHall_121416_Title = {
    Text = "กลายเป็นพระเจ้า"
  },
  CollectionHall_121417_Desc = {
    Text = "ในอารยธรรมมนุษย์ที่ยาวนาน,      เราได้สร้างสรรค์สิ่งมากมาย.\nเกี่ยวกับวัตถุ,      เกี่ยวกับจิตวิญญาณ,      เกี่ยวกับการมีชีวิตอยู่,      ความรัก,      ควันไฟและความขัดแย้ง.\nแต่แค่นั้นมันก็เป็นเสียงรบกวนที่ไม่สำคัญในความฝันของผู้สร้างและเป็นเรื่องราวที่ไม่มีที่สิ้นสุด."
