    Text = "ผ่านด่านใดก็ได้ของการเชื่อมต่อหลายมิติ「การชำระบาปด้วยเงินและเลือด」เพื่อปลดล็อค"
  },
  CollectionHall_124224_Title = {
    Text = "บันทึกการสำรวจโลกอีกใบของโมชา"
  },
  CollectionHall_124395_Desc = {
    Text = "ในวันที่เจ็บปวดและพึงพอใจที่สุดในชีวิตของโลทัน คมดาบในมือเธอพุ่งเข้าหาเทพเจ้าตรงหน้าดั่งพายุ ดาบยักษ์และร่างกายอันยิ่งใหญ่ดั่งดาวเคราะห์ของเลวีอาธานต่างแตกสลายเป็นชิ้นเล็กชิ้นน้อยในพายุนั้น.\nหลังจากมอบมงกุฎแห่งเลือดสดให้แก่ท่านนั้นผู้เป็นทาสของอัศวิน เป็นการแลกเปลี่ยน โลทันมีเพียงข้อเรียกร้องเดียว: เธอต้องการอาวุธใหม่.\nด้วยความเกรงกลัวและเคารพต่อโลทัน กษัตริย์องค์ใหม่สั่งให้นำกระดูกของเลวีอาธานมาหล่อดาบยักษ์คู่อันไม่มีใครเทียบได้ให้เธอ ในการหล่อและชุบแข็งอย่างไม่หยุดหย่อนของช่างตีเหล็กที่ดีที่สุดจากหกอาณาจักร ซากกระดูกของเทพเจ้าผู้ล่วงลับได้รับทารกแรกเกิดอีกครั้งในมือของผู้สังหารเทพ.\nหนึ่งท่านคู่ต่อสู้ผู้ควรค่าแก่การจดจำเคยเป็นพยานต่อคมดาบคู่อันไม่ดับนั้น ค้อนยักษ์ของเขาทุบเกราะและดาบยักษ์ของโลทันแตกสลาย รอยแตกแผ่กระจายดั่งใยแมงมุมบนตัวดาบ เศษสีขาวนวลกระเด็นในอากาศสีเลือด ดั่งวันที่เธอแทงเลวีอาธาน เขาคิดว่าตนเองพบจุดอ่อนแล้ว จากนั้น เขาเห็นโลทันลุกขึ้นยืนต่อหน้าเขาอีกครั้ง ดาบยักษ์ที่ควรจะแตกสลายนั้นแทงทะลุอกเขา ดูดดื่มเนื้อและเลือดของเขา กระดูกใหม่พุ่งออกมาจากรอยแตก แหลมคมและหนาแน่นกว่าเดิม รอยหักงอกยืดออก ดั่งพุ่มหนามที่เติบโตอย่างบ้าคลั่งในป่าดงดิบ เขารับรู้ได้อย่างชัดเจนว่า HP ของตนกำลังถูกคมดาบที่หล่อจากกระดูกขาวเคี้ยวและกลืนกิน.\nแท้จริงแล้ว สัตว์ร้ายผู้เคยกลืนกินท้องฟ้าดาวนั้นไม่เคยตาย ตั้งแต่ช่วงเวลาที่สัญญาถูกลงนาม พระองค์ก็รวมเป็นหนึ่งกับเธอแล้ว ทุกครั้งที่โลทันยกดาบยักษ์ขึ้น หนามแหลมบนตัวดาบก็เริ่มผลิบาน ส่งเสียงโห่ร้องอย่างโหดร้ายไปยังคู่ต่อสู้ด้วยหนามแหลมของมัน.\nมันคืออาวุธของเธอ เธอคือสองขาของมัน เธอและมัน ตั้งแต่ต้นจนจบ ต่างจมอยู่ในความปรารถนาเดียวกัน พวกเธอไม่ตายไม่ดับ ไม่มีวันอิ่มเอม.\nสนามรบที่ไม่เคยหยุดนิ่ง คือที่พักพิงเดียวของพวกเธอ."
  },
  CollectionHall_124395_Title = {
    Text = "กระดูกหิวโหยมิรู้ดับ"
  },
  CollectionHall_124397_Desc = {
    Text = "หลายปีผ่านไป เมื่อพบหน้าของนักเดินเรือที่คุกเข่าอธิษฐาน เมอร์ฟี่: กำเนิดลวงจะรำลึกถึงบ่ายที่ไกลโพ้น ที่ 「แม่」 เล่าเรื่องราวของปลาหมึกกลมสีฟ้าให้เธอฟัง.\nสิ่งประดิษฐ์ในขวดนั้นนุ่มนวลและมีเสน่ห์ แสงสีฟ้าอัศจรรย์ลอยอยู่ในน้ำ ดึงดูดเด็กน้อยให้เข้าใกล้.\nแต่มิเรียมลูบหัวเธอด้วยแรงที่ไม่อาจปฏิเสธ ทำให้เธอมองไปที่มุมมืดของเรือ——ซากศพของนักเดินเรือคนนึงนอนอยู่บนพื้น เปล่าเปลือยเหมือนถูกพิษดูดกลืนจนหมดสิ้น.\n「จงจำไว้ว่า ความสงบในทะเลนั้นอาจเป็นสิ่งที่สวยงามที่สุด และก็อาจจะอันตรายที่สุด」.\nแสงเย็นจากขวดสะท้อนให้เห็นเงาของเธอในอาภรณ์ของเมตตา เมอร์ฟี่: กำเนิดลวงรู้สึกถึงความกลัวที่ถูกห่อหุ้มด้วยความงาม.\n\nปีผ่านไปตามจังหวะของดวงดาว เมอร์ฟี่: กำเนิดลวงยังคงเคลิบเคลิ้มดั่งแต่ก่อน แต่ก็ได้เรียนรู้การเงียบและการสังเกต.\n「เลมูเรีย,      เลมูเรีย...」\nจนกระทั่งที่แท่นบูชานั้น ใบหน้าที่เคยสงบ และอ่อนโยนเริ่มถูกคลุมด้วยความบ้าคลั่ง เธอถึงได้รู้ว่า เธอไม่เคยรู้จักมิเรียมอย่างแท้จริง\nมือที่เคยลูบหัวเธอนั้น อันอ่อนโยนของแม่ ก็จะลงโทษศัตรูของพระเจ้าอย่างที่สุด\nขณะนั้น ความกลัวที่ถูกปิดกั้นในความทรงจำของเธอได้ฟื้นคืนชีพขึ้นมาทันที และหยุดนิ่งเปลี่ยนไปเป็นการรับรู้ที่เยือกเย็น——ความมีเมตตาของเธอ ไม่ใช่สิ่งอื่นใด นอกจากการหลอกลวงอันเต็มไปด้วยสัญลักษณ์แห่งหนวด ซึ่งความลุ่มหลงในรูปลักษณ์ที่สวยงาม คือพิษที่แหลมคมทำให้เลือดเฉือน.\n\nจนกระทั่งวันนี้ พระเจ้าผู้ว่างเปล่าได้ขอพระราชทานมงกุฎแก่เมอร์ฟี่: กำเนิดลวง เธอจ้องลงไปที่นักเดินเรือที่กราบอยู่ฟากฝ่ายตรงข้ามพบกับสายตาของมิเรียมที่ยังมีแสงสว่างแห่งความเป็นไปได้ที่ไม่เคยดับมอดลง ดูเหมือนว่าเธอเห็นตัวเองที่เคยเล็กน้อย สั่นสะเทือนเมื่อจ้องมองสิ่งมีชีวิตสวยงามในขวดแก้ว."
  },
  CollectionHall_124397_Title = {
    Text = "บลูริงพิษ"
  },
  CollectionHall_124400_Desc = {
    Text = "โรคระบาดที่ไม่รู้จักกลืนกินเมืองและหมู่บ้าน ผู้คนที่หลงใหลในสงครามสังหารกันอย่างเต็มที่ท่ามกลางความวุ่นวาย บทเพลงแห่งเหล็กและเลือดเดือดพล่านอย่างบ้าคลั่ง.\nด้วยความกลัว หรือการใช้ประโยชน์จากความกลัว.\nความกลัวคือศัตรูที่มองไม่เห็น ศัตรูเก่าแก่ ศัตรูที่ร้ายแรง.\nเขาคืออัศวินที่ไม่ผ่านเกณฑ์ เขาพ่ายแพ้ต่อความกลัว.\nแต่คำสาบานที่เคยปฏิญาณไว้อย่างจริงจังยังคงก้องอยู่ในหู ปีแล้วปีเล่า ผ่านบ้านเกิดที่กลายเป็นความว่างเปล่าไปแล้ว.\n「ข้าจะปฏิบัติต่อผู้อ่อนแอด้วยความเมตตา ข้าจะเผชิญหน้าศัตรูที่เข้มแข็งด้วยความกล้าหาญ」\nราตรีซ่อนรอยเท้าของผู้กระทำความชั่ว กระแสเสียงกรีดร้องและร้องไห้ท่วมท้นถนนและตรอกซอย ฝูงชนเหมือนฝูงแกะที่ตื่นตระหนก.\n「ข้าจะต่อสู้กับคนชั่วร้ายอย่างไม่มีข้อยกเว้น ข้าจะต่อสู้เพื่อผู้ที่ไม่สามารถต่อสู้ได้」\nปลายหอกเปื้อนเลือด โล่เงินเป็นสนิม เงามืดยิ้มอย่างอิ่มเอม ฝูงกาโฉบวนเวียนเหนือศีรษะ ในดวงตามีแสงวาบของปีศาจ.\n「ข้าจะช่วยเหลือผู้ที่ต้องการความช่วยเหลือจากข้า」\n「เขานั่น เขามาแล้ว」 ผู้คนพึมพำเบาๆ ความกลัวบิดเบือนใบหน้าของพวกเขา 「อสูรกายที่ว่างเปล่า亡灵แห่งการแก้แค้น กลับมาจากห้วงลึกแห่งความตาย เพื่อลากศัตรูของเขาลงสู่หนองดำแห่งความเคียดแค้น」\nเขานั่นเอง. เขาไม่เคยลืม เขาไม่เคยลืมเลย.\nเหตุใดจึงต้องยืนหยัด？หากทุกสิ่งย่อมสูญสลายในที่สุด แม้แต่เกียรติยศและความศรัทธา.\nเหตุใดจึงต้องถอยหนี？เมื่อไม่ว่าชะตากรรมจะเยาะเย้ยอย่างไร มนุษย์ก็มีเพียงการยอมจำนนคุกเข่า.\nหรือเพียงเพื่อซื่อสัตย์ต่อความซื่อสัตย์ อุทิศตนต่อการอุทิศตน？\nอัศวินคนสุดท้ายแห่งดัชชีถามอย่างไร้ผล จิตวิญญาณรกร้างเช่นเดียวกับร่างกายที่พังทลาย มลทินแห่งความกลัวไหลเวียนอย่างไม่มีขีดจำกัด รวมตัวกันเป็นมหาสมุทรแห่งการทำลายล้าง.\nแต่ช่องอกที่ว่างเปล่ายังคงนิ่งเงียบ คำตอบที่สูญหายยังไม่รู้ว่าอยู่ที่ใด."
  },
  CollectionHall_124400_Title = {
    Text = "อดีตที่ติดตามเงา"
  },
  CollectionHall_124404_Desc = {
    Text = "นี่คือปีที่สองที่ฉันย้ายไปเมืองทะเลกับพ่อ อีฟเลนในจดหมายร้องไห้ทำให้ฉันรู้สึกไม่สบายใจ ฉันได้ตัดสินใจที่จะจากเธอไป ที่นี่เป็นที่อุดมสมบูรณ์ที่ตกแต่งด้วยผ้าไหมและไม้ดำ ทุกคนที่กินซากก็ได้กลิ่นความโกลาหลในขณะที่มันหลับอยู่ มูลค่าของธนบัตรสามารถแลกเปลี่ยนเป็นทองคำที่มีน้ำหนักเท่ากันได้ หากควบคุมเส้นทางการเดินเรือเหล่านั้น ก็สามารถใช้ต้นทุนที่ต่ำมากในการสร้างความมั่งคั่งที่มากมายมหาศาล \n แต่ อีฟเลน อาจจะมาจากสายเลือดที่แปลกประหลาดทำให้เธอมีอาการประสาท เธอเชื่อมั่นในสิ่งที่เรียกว่าข่าวสารจากบรรพบุรุษ ว่ามีเทพเจ้าที่แปลกประหลาดซึ่งสาขาข้างเคียงของพวกเขาที่เคารพนับถือในตะวันออก เหมือนกับปลาบางชนิดในทะเลลึก ที่จะยื่นเหยื่ออันแสนอร่อยลงมาเพื่อดึงดูดเหยื่อเข้าสู่การกินอย่างช้าๆ ที่ไม่สามารถสังเกตเห็นได้ \n เธอผิดแล้ว เมืองทะเลไม่มีรสเค็มจากทะเลแม้แต่น้อย \n มีเพียงดอกมะลิที่ซ้อนกันอย่างหนาแน่น หอมหวานจนทำให้หลงใหล และเกิดความกลัว \n ดอกมะลิที่ทำให้ฉันและพ่อหลงใหลพร้อมกัน \n เมื่อฉันเห็นเธอ ทันทีที่เงาของผู้หญิงที่ชื่อว่า 「ซู」 ปรากฏในสายตาของฉัน ฉันก็ไม่มีทางหนีจากแผ่นดินเก่าแก่แห่งนี้ได้อีกต่อไป \n เธอดึงดูดให้คนเข้าใกล้ เธอทำให้คนต้องการครอบครอง เธอทำให้คนต้องการ@3 \n เธอทำให้คนคนคนคนคนต้องการต้องการต้องการต้องการต้องการ \n สับตัดเปิดทำลายตลอดไปตลอดไปตลอดไปตลอดไปตลอดไป...@2@3@2!! \n อ๊ะ ทำไมฉันถึงมาที่นี่? ฉันจะนำอะไรไป? ฉันคือ...ใคร? \n ไม่สำคัญแล้ว เธอเชิญฉัน ฉันนั่งอยู่ที่โต๊ะในบ้านหลังใหญ่ \n พ่อที่บ้าไปแล้วเหมือนกับฉัน ยิ้มอย่างเชื่อฟัง ใส่จานข้างเคียงที่หลากหลายเต็มโต๊ะอาหาร ดูเหมือนจานโลหะที่มีฝาปิดไม่เข้ากัน \n ซูนั่งย้อนแสงในแสงพระอาทิตย์ตก สายตาเธอถูกล้อมด้วยกรอบทองที่นุ่มนวล และค่อยๆ เธอวางพัดสีดำลง \n เหมือนกับอีฟเลน เหมือนกับเพื่อนเล่นในวัยเด็กของฉัน เหมือนกับความรักที่ไม่ชัดเจน...เหมือนกับแม่ของฉัน \n นั่นคือใบหน้าที่สวยงามเหมือนกับรูปปั้นทองคำในวัด \n ฉันไม่ได้ยินเสียงดูดดื่ม และไม่ได้กลิ่นเลือดจากพ่อ แต่กลับหลงใหลมองไปที่ใบหน้านั้น และเจ้าของใบหน้านั้นยื่นมือขาวสะอาดออกมา เปิดจานอาหาร และหยิบเนื้อที่เหมาะสม เธอใช้ไม้สองแท่งหนีบมันขึ้นสูง \n เธอเรียกฉัน ไขมันจากสัตว์ที่ถูกอบแล้วหยดที่มุมปากของฉัน \n 「คุณหนู คุณควรกินอะไรสักหน่อย」 \n\n ฉันเปิดปากอย่างเชื่อฟังและงงงวย \n ดอกมะลิกำลังบาน มันกำลังห้อยลงมาอย่างเงียบๆ \n —— 「บันทึกของผู้ไร้ชื่อ」 \n"
  },
  CollectionHall_124404_Title = {
    Text = "เหยื่อหยกหลาน"
  },
  CollectionHall_124405_Desc = {
    Text = "「ใช้สติปัญญาเป็นประทีป ก็จะขจัดหมอกแห่งชีวิตได้」\nครั้งหนึ่ง โมชาเคยได้ยินคำพูดเช่นนี้\nบางทีอาจเป็นคำรำพึงที่หลุดออกมาจากช่างเทคนิคของบริษัทโซโรขณะปรับแต่งโคมไล่หมอก? หรือบางทีอาจเป็นคำล้อเลียนของคนเดินผ่านเมื่อไปร้านอาหารฟิลลิงเกน?\nโมชาจำไม่ได้แล้ว สิ่งที่เธอจำได้ชัดเจนคือรอยยิ้มสังคมที่เคยชินบนใบหน้าเมื่อได้ยินคำพูดนั้น และการเยาะเย้ยที่ซ่อนอยู่เบื้องหลังรอยยิ้มนั้น\n「ประทีปเหรอ? ฮ่า ของเก่าโบราณอะไรกัน สมัยนี้คนใช้ไฟฉายกันแล้ว」\nเธอไม่ใช่ไม่รู้ว่านี่เป็นเพียงอุปมา เธอแค่ไม่ยี่หระที่จะเข้าใจ\nเพราะสักวันหนึ่ง เธอจะตาย และหลังจากตายแล้ว สติปัญญาอะไร หมอกอะไร ก็ไม่มีอยู่อีกต่อไป——เธอจะหลุดพ้นจากโลกนี้โดยสิ้นเชิง\nนี่คือการคาดการณ์ที่สมเหตุสมผลและหลีกเลี่ยงไม่ได้ สิ่งที่เธอต้องทำคือเพลิดเพลินกับกระบวนการก่อนที่「ความหลีกเลี่ยงไม่ได้」จะมาถึง\nแต่ไม่เคยมีใครบอกเธอว่า「ความหลีกเลี่ยงไม่ได้」ก็อาจพบกับ「อุบัติเหตุ」ได้\nหมอกที่คล้ายกัน สถานการณ์ที่คล้ายกัน แต่ที่นี่ไม่มีโคมไล่หมอก ไม่มีทีมสืบสวน ไม่มีสิ่งใดที่เธอคุ้นเคย ขวานของเธอสามารถฟันสัตว์ประหลาดในโลกได้ แต่ฟันหมอกที่เกิดจากความโดดเดี่ยวและความสับสนของตัวเองไม่ได้\nเธอจะกลับไปได้ไหม? เธอจะกลับไปไหม? เมื่อไหร่จะกลับไปได้...\nคำถามทีละข้อลอยขึ้นมาจากใจเธอ เหมือนน้ำลึกที่มองไม่เห็น ค่อยๆ กลืนกินจิตใจเธอ ในขณะนี้ ความคิดเดียวทั้งหมดในใจเธอคือ——\nรักษาสติไว้\nอย่าบ้า! อย่าบ้า! อย่าบ้า!\nไม่ว่าจะเผชิญกับหมอกของโลกนั้น หมอกของโลกนี้ หรือหมอกในใจตัวเอง\nเพื่อที่จะ...กลับไปอีกครั้ง"
  },
  CollectionHall_124405_Title = {
    Text = "ประทีปแห่งสติ"
  },
  CollectionHall_124407_Desc = {
    Text = "ในวันเกิดอายุเจ็ดขวบ พ่อวางกี่ปั่นด้ายชื่อ「โมอิไร」ไว้บนตักเธอ ชื่อนั้นเป็นของเทพีแห่งโชคชะตาสามองค์ที่ไม่มีใครบูชาอีกต่อไป แต่ตัวกี่ปั่นด้ายนั้นเรียบลื่นและใหม่เอี่ยม แกนทองแดงเปล่งประกายโลหะ เย็นเยือกและหนักอึ้ง\nตั้งแต่นั้นมา อาราคเน่หยิบวงล้อแห่งโชคชะตาขึ้นมา ไม่ใช่จากการเลือก แต่เพราะคำพูดที่เอ่ยออกไปโดยไม่ตั้งใจมักเป็นจริงในภายหลัง เธอไม่อาจเพิกเฉยต่อความรับผิดชอบที่ถูกลิขิตไว้นี้\nตั้งแต่นั้นมา เธอทอเรื่อยมา วันแล้ววันเล่า มองเส้นด้ายแห่งโชคชะตาหมุนอย่างเงียบงันบนกี่ปั่นด้ายอันประณีต ทอให้ผู้คนได้สัมผัสความสั่นเทิ้มของจูบแรก เสียงร้องของม้าศึก เสียงร้องแรกของทารก และรอยสลักหยาบบนหลุมศพ\nตั้งแต่นั้นมา เธอเลือกเส้นทางที่「ดีกว่า」จากเส้นด้ายนับหมื่นที่พันกัน ให้โรคระบาดมืดมิดถอยร่นก่อนเวลา ให้ประวัติศาสตร์หลบพ้นไฟสงคราม ให้อารยธรรมสร้างขึ้นใหม่จากซากปรักหักพัง...และในขณะเดียวกัน เธอก็ทอเส้นด้ายที่นำไปสู่ความบ้าคลั่ง การทรยศ หรือราตรีนิรันดร์ เพียงเพื่อรักษาตาข่ายแห่งโชคชะตาที่ทอดข้ามกาลเวลาและอวกาศ\n「อะไรคือสิ่งที่ดีกว่า?」\nกี่ปั่นด้ายที่เงียบงามไม่ตอบ เพียงหมุนต่อไป ดีและเลว การเกิดใหม่หรือข่าวมรณกรรม ปรากฏสลับกันบนเส้นด้ายเดียวกัน ในตอนนั้นเธอที่ยังเยาว์ไม่รู้ว่าชะตากรรมของตนคืออะไร แต่ก็ได้มองเห็นจุดจบของโลกที่ปลายเส้นด้ายนับไม่ถ้วน\n「หากโลกไม่สามารถหนีพ้นชะตากรรมแห่งการทำลายล้าง...」\n「ไม่ ฉันรักโลกนี้」\nอาราคเน่จ้องมองกี่ปั่นด้าย ทิ้งความคิดที่ไม่ได้เอ่ยออกมา\n「แล้ว...ชะตากรรมของฉันล่ะ?」\nเธอพึมพำกับตัวเอง มีเพียงเสียงสะท้อนที่ว่างเปล่าวนเวียนอยู่ระหว่างผนังทั้งสี่\n...\nนับไม่ถ้วนว่ามีกี่อารยธรรมที่ผงาดขึ้นและล่มสลายบนตาข่ายแห่งโชคชะตา พีระมิดหลับใหลในทราย ยานอวกาศแล่นผ่านทะเลดาว ภาษาเปลี่ยนแปลงดั่งฤดูกาลหมุนเวียน ชื่อของเทพเจ้าถูกเขียนลงในพจนานุกรมที่ปิดผนึกฝุ่น...แต่เธอยังคงนั่งอยู่ที่นั่น หมุนกี่ปั่นด้ายในมือ มองมนุษย์เล่นซ้ำวงจรแห่งความหวังและการทำลายล้างครั้งแล้วครั้งเล่า\nจนกระทั่งวันหนึ่ง เสียงเรียกเบาๆ ข้ามผ่านคุกแห่งนิรันดร์และความเงียบงันแห่งกาลนาน\n「พี่สาว...」\nในที่สุดเธอก็เบนสายตาจากวันสิ้นโลก หลับตามองไปยังเนฟเรอา ตัวตนอีกด้านในร่างกายเธอ——ดวงตาที่บริสุทธิ์ดั่งทารกแรกเกิดนั้น ไม่มีการพิพากษา ไม่มีความกลัว มีเพียงความไว้วางใจอย่างเต็มเปี่ยม เหมือนกระดาษขาวที่ยังไม่มีใครเขียน\nในชั่วขณะนั้น อาราคเน่ได้รู้ในที่สุดว่า ความรักและความรับผิดชอบ ความเกลียดชังและการทำลายล้าง ทุกสิ่งไม่มีความแตกต่างต่อหน้าโชคชะตา ดังนั้น เธอจึงนำความทรงจำที่ถูกตัดขาดและทิ้งไปด้วยมือตนเอง ความเจ็บปวด ความเสียใจ และการสูญเสียที่ควรจะเกิดขึ้นแต่ไม่เคยมาถึง ทอเป็นเส้นด้ายหนึ่งเส้น เป็นของขวัญที่หนักที่สุดและอ่อนโยนที่สุด ผูกไว้ที่ข้อมือของเนฟเรอา\n「จากที่นี่ไปเถอะ เนฟเรอา」อาราคเน่ยิ้ม「เธอเป็นอิสระแล้ว」\nอาราคเน่ไม่จำเป็นต้องมองเห็นชะตากรรมของตนเองอีกต่อไป เพราะในชั่วขณะที่หยิบกี่ปั่นด้ายขึ้นมาเมื่ออายุเจ็ดขวบ เธอได้เลือกทิศทางของอนาคตแล้ว และวงล้อแห่งชะตากรรมจะหมุนอย่างเงียบงาม เป็นพยานแห่งการต่อสู้ที่ไม่มีวันปิดฉากที่เธอกำลังจะทุ่มตัวเข้าไป"
  },
  CollectionHall_124407_Title = {
    Text = "วงล้อแห่งโชคชะตา"
  },
  CollectionHall_124410_Desc = {
    Text = "กลืนกิน กลืนกิน กลืนกิน กลืนกิน...\nสะกดจิตของความฝันอันชั่วร้าย.\nบดขยี้ บดขยี้ บดขยี้ บดขยี้...\nเสียงเพรียกของทะเล.\nทำลาย! ทำลาย!! ทำลาย!!! ทำลาย！！！！\nความบ้าคลั่งที่ไม่สามารถยับยั้งได้.\n「มอสหิวมาก.」\nสาวกลืนเนื้อที่มีเลือดสดไหลหยด แต่ไม่ว่าเธอจะกินเท่าไหร่ก็ไม่สามารถบรรเทาความว่างเปล่าในท้องได้.\n「มอสกระหายน้ำ.」\nสาวกลืนกินน้ำทะเลที่มีกลิ่นคาวเน่า แต่ไม่ว่าเธอจะดื่มเท่าไหร่ก็ไม่สามารถบรรเทาคอที่แห้งได้.\n「มอสง่วงนอน.」\nสาวทุบตีตัวเองที่รู้สึกชา แต่ไม่ว่าเธอจะนอนนานเท่าไหร่ก็ไม่สามารถยับยั้งความเหนื่อยล้าของความคิดได้.\nเพราะมีเพียงการทำลายล้างอย่างแท้จริงเท่านั้นที่สามารถทำให้เธอพอใจ.\n「แต่ มอส อย่า!」\nแต่สาวปฏิเสธเสียงเพรียกของโชคชะตา เหล็กกล้าที่ถูกทำขึ้นพิเศษกลายเป็นกรงที่เธอไม่สามารถถอดออกได้.\nเธอสร้างตัวเองให้เป็นเรือนจำที่ไม่สามารถทำลายได้ โดยใช้การจำกัดที่เรียกว่าตัวเอง เพื่อขังความบ้าคลั่งที่มาจากเอควอ.\n「มอส ถูกขังแล้ว ไอ้เลว!」\nตั้งแต่นั้นมา วังวนที่กลืนกินชีวิตมากมายอย่างมัสคัส ตั้งแต่ AF 1■■ จนถึง AF 31■ ก็ได้กลับสู่ความเงียบสงบอย่างสมบูรณ์.\n\n\n\n\n"
  },
  CollectionHall_124410_Title = {
    Text = "บ้าคลั่งที่ถูกกักขัง"
  },
  CollectionHall_124413_Desc = {
    Text = "บนชั้นหนังสือนอกจากเอกสารวิจัยที่แสนน่าเบื่อแล้ว ยังมีหนังสือสำหรับเด็กที่ดูน่าสนใจอยู่หลายเล่ม\n「ซินเดอเรลล่า」,     「สโนว์ไวท์」,     「เงือกน้อย」,     「ราพันเซล」...เจ้าของหนังสือเหล่านี้เก็บมันไว้บนชั้นด้วยเหตุผลใด——บัดนี้ไม่มีทางรู้ได้อีกแล้ว\nเรื่องราวเหล่านั้นถักทอเนื้อหาที่แตกต่างจากความเป็นจริงโดยสิ้นเชิง 「เจ้าชาย」,     「เจ้าหญิง」,     「ความรัก」...คำเหล่านี้ทำให้หัวใจของเด็กสาวเต้นระรัว\nแสงนับไม่ถ้วนที่ระยิบระยับบนท้องฟ้ายามค่ำคืนหลั่งไหลลงสู่พื้นดิน ราวกับกำลังจะรวมกันเป็นแม่น้ำแห่งแสงที่ไหลรินอยู่\nท่ามกลางแสงจันทร์ที่สาดส่อง เด็กสาวเขย่งปลายเท้าอย่างเงียบๆ แกล้งทำเป็นสวมรองเท้าแก้วใสสักคู่ ราวกับว่าเธอรอคอยมาตลอด——ว่าราตรีอันยาวนาน มืดมิด และเปล่าเปลี่ยวนี้ สักวันจะต้องสว่างขึ้น..."
  },
  CollectionHall_124413_Title = {
    Text = "เทพนิยายในโคลนตม"
  },
  CollectionHall_124414_Desc = {
    Text = "แม่มดแก่ที่เดินวนเวียนระหว่างเรือสินค้า มักซ่อนร่างอยู่ในเงาของเสื้อคลุมเก่าขาดกล่าวว่า เข็มทิศจะนำพาผู้คนไปยังที่ที่พวกเขาควรไป นักเดินเรือหัวเราะล้อเลียนคำพูดไร้สาระที่มีกลิ่นสมุนไพรของเธอ โยนเลโอฟังห้าเหรียญ แลกกับของประดับทองเหลืองอันประณีตนั้นไป.\nแล้วพวกเขาก็จอดเทียบท่าที่เมืองเล็กๆ ที่ต่อมาสูญเสียชื่อของตัวเอง ปอนทอสชอบเรื่องนี้ และเจ้าของเข็มทิศก็ชอบปอนทอส.\nแน่นอน ไม่มีใครไม่ชอบปอนทอสผู้มีอารมณ์ขัน ร่าเริง และมาไปอย่างอิสระเหมือนสายวายุ.\nมันควรจะเป็นของที่ระลึกที่ดี เป็นกุญแจที่ปอนทอสส่งต่อให้หลานชายที่รักเพื่อเปิดประตูสู่การจินตนาการถึงดินแดนอันไกลโพ้น — แต่มันทำให้ปอนทอสหาเขาไม่พบ ปอนทอสไม่ยินยอม และจะไม่มีวันยอมให้ชีวิตของเขามีความเป็นไปได้อื่น.\nเมื่อหลายปีผ่านไป ปอนทอสเดินผ่านคืนมืดนับไม่ถ้วนใต้แสงจันทร์ ค้นหาร่างที่ควรจะกลับมายังเอโปยันส์ เขาคิดเช่นนั้น.\nโอ้ คาถาป้องกันที่ไร้ประโยชน์นั้นได้จากไปจากเขาแล้ว ตอนนี้ปอนทอสสามารถพาเขากลับมาได้.\nแค่ปอนทอสยังไม่รู้ว่า「เข็มทิศจะนำพาผู้คนไปยังที่ที่พวกเขาควรไป」 เหมือนกับที่เรือทุกลำมีเส้นทางของตัวเอง คนที่แตกต่างกันก็มักเลือกทิศทางที่แตกต่างกันเสมอ."
  },
  CollectionHall_124414_Title = {
    Text = "เข็มทิศชี้ทางแยก"
  },
  CollectionHall_124415_Desc = {
    Text = "「คุณต้องการซื้อไม้ขีดไฟสักอันไหมคะ?」 ในคืนฤดูหนาว เด็กหญิงที่มือเท้าแดงก่ำเพราะความหนาวกระซิบ 「อันเดียว แค่ไม้ขีดไฟอันเดียวก็พอค่ะ.」\n「ขอโทษนะคะ ฉันจะไม่ซื้อไม้ขีดไฟของเธอหรอก」 เงาสีขาวบริสุทธิ์โค้งตัวลงเล็กน้อย บดบังดวงจันทร์ฤดูหนาว 「แต่ตรงกันข้าม ฉันมีบางอย่างจะขายให้เธอด้วยซ้ำ.」\n「แต่ หนูไม่มีเงิน...」\n「ไม่เป็นไรค่ะ จงเชื่อในพรของนางฟ้าเถอะ เธอจะขายไม้ขีดไฟได้เร็วๆ นี้เอง.」\nนางฟ้าชุดขาวยัดลูกอมใส่มือเด็กหญิง แล้วเอนตัวเข้าใกล้หูของเธอ.\n「เห็นผู้หญิงวัยกลางคนที่สวมเสื้อคลุมขนสัตว์อยู่ฝั่งตรงข้ามถนนไหมคะ? จับชายเสื้อของเธอไว้ แล้วร้องไห้ให้สุดเสียง พูดว่า คุณนายใจดี อากาศหนาวมากเลยค่ะ คุณยายของหนูป่วยหนัก ถ้าไม่ได้กินข้าวอิ่มสักมื้อ ก็จะตายเพราะป่วยในไม่ช้า ขอร้องค่ะ ให้เงินหนูหน่อยได้ไหมคะ.」\n「แต่ คุณยายจากไปนานแล้วค่ะ...」\n「ยิ่งดีเลย! ก็ลองนึกถึงความรู้สึกในตอนนั้น แล้วร้องไห้ให้จริงๆ หน่อย...」\n「ถ้าเธอยังขี้เหนียวไม่ยอมควักเงิน ฉันก็ยังมีวิธีอื่นอีก คนที่ยังเดินอยู่กลางแจ้งในคืนส่งท้ายปีเช่นนี้ ชีวิตครอบครัวต้องไม่มีความสุขแน่ๆ แล้วเธอก็เติมเข้าไปว่า คุณยายเป็นญาติเดียวของหนู วันนี้เป็นคืนส่งท้ายปีใหม่ ไม่มีใครอยากอยู่คนเดียวหรอกค่ะ ขอร้องค่ะ คุณนายผู้งดงาม แค่สามเฟนนิ่ง เพื่อให้หนูขายไม้ขีดไฟได้หมดเร็วๆ แล้วกลับไปอยู่กับคุณยายได้.」\n「ไม้ขีดไฟราคาอันละหนึ่งเฟนนิ่ง...」\n「ที่เหลืออีกสองเฟนนิ่ง หนึ่งเฟนนิ่งเป็นค่านายหน้าของฉัน และอีกหนึ่งเฟนนิ่งต้องเครื่องบูชาให้มัน.」 คาราบูเขย่าไม้กายสิทธิ์ในมือ หนอนสีขาวที่หลับใหลไหลเลื่อนดั่งคลื่นน้ำ.\n「อย่าคิดมากเลย เชื่อในพรของนางฟ้าก็พอ วิธีนี้ต้องได้ผลทุกครั้งแน่นอน จำไว้นะ ก่อนที่เธอจะควักเงินออกมา อย่าปล่อยมือเด็ดขาด ถ้าล้มเหลว เราก็ไปหาคุณนายผู้มั่งมีที่โดดเดี่ยวคนต่อไปได้เลย ไม่ต้องเป็นห่วง ในโลกใบนี้ ผู้หญิงที่มีเงินเหลือเฟือมีมากพอที่จะเลี้ยงเราสองคนได้สบายๆ.」\nไม่มีใครอยากสืบหาอีกต่อไปแล้วว่าทำไมวิธีที่ได้ผลทุกครั้งถึงล้มเหลว รวมความแล้ว หลังจากอัปเดตชุดคำพูดไปหนึ่งร้อยแปดสิบสองชุด ไม้ขีดไฟของเด็กหญิงก็ขายหมดสำเร็จ.\nในเรื่องราวที่ 「นางฟ้าแม่ทูนหัว」 ตัวจริงไม่ได้ปรากฏตัว นางฟ้าปลอมก็ยังช่วยเหลือเด็กหญิงผู้น่าสงสารที่ยากจนและใกล้จะแข็งตายได้เช่นกัน.\nน่ายินดียิ่งนัก น่ายินดียิ่งนัก."
  },
  CollectionHall_124415_Title = {
    Text = "ความจริงอันแสนหวาน"
  },
  CollectionHall_124844_Desc = {
    Text = "<Title:บทนำ>\nสาวลึกลับจากไทมูราน ตามคำบรรยายของเธอ เธอเคยเป็นนักศึกษาในมหาวิทยาลัยท้องถิ่น แต่กลายเป็นแนวหน้าของคณะกรรมการสอบสวนหมอกหลังจากการพบกันที่ชะตากรรมแบบโรแมนติก\nในเหตุการณ์「ภัยหมอก」ของรุ่งอรุณแห่งดวงดาว โมช่าได้รับการอัญเชิญมายังโลกนี้โดยบังเอิญ และได้ผ่านพิธีกรรมที่มีเงินและเลือด ซึ่งทำให้เธอได้รับการชำระล้างจากมนุษย์กลายเป็นผู้ปลุกตื่น และสิ้นสุด「ภัยหมอก」\nเธออยู่ในโลกที่ไม่ใช่ของตัวเอง แต่ยังคงแสวงหาวิธีการกลับไปในขณะเดียวกัน เธอยังสนใจอนาคตของโลกนี้ และปรารถนาที่จะเป็นพยาน「จุดจบของโลก」."
  },
