  CollectionHall_126471_Desc = {
    Text = "โมช่าเคยชินกับการมีอยู่ของหมอกแล้ว\nไม่ว่าเป็นหมอกที่ยากจะจัดการแค่ไหน หรือหมอกที่อันตรายเพียงใด เธอก็สามารถเดินออกมาได้อย่างปลอดภัย\nครั้งนี้ก็เช่นกัน\nเธอจะต้องเดินออกจากหมอกในโลกใหม่ กลับไปยังมิติที่เป็นของเธอ\nไม่ว่าจะต้องจ่ายในราคาที่ต้องจ่ายใดก็ตาม."
  },
  CollectionHall_126471_LockTip = {
