  CollectionHall_126471_Title = {
    Text = "เปิดเผยหมอกแห่งโลกใหม่"
  },
  CollectionHall_126472_Desc = {
    Text = "เวลาที่หมอกสลายจะมาถึงเสมอ \n ในขณะนั้น เสียงกรีดร้องที่ดังก้องอยู่ในหมอกจะจางหายไป รอยเลือดที่ไหลอยู่บนแท่นบูชาจะถูกเช็ดออก \n วิญญาณที่หลงทางจะได้รับการปลดปล่อย และค้นพบเส้นทางที่ถูกต้อง — \n ไปยังดวงดาวที่ส่องแสง หรือคงอยู่ในโลกาอันแท้จริง."
