  },
  CollectionHall_126472_Title = {
    Text = "เวลาที่หมอกสลาย"
  },
  CollectionHall_126473_Desc = {
    Text = "จักรวาลได้ให้กำเนิดโลก โลกได้ให้กำเนิดชีวิต และชีวิตในโลกที่แตกต่างกัน ได้ให้กำเนิดกฎและแนวคิดที่แตกต่างกันออกไป \nเมื่อพวกเขาปะทะกัน การต่อสู้ไม่เคยมีเพียงแค่สองร่าง สองเจตจำนง สองชีวิต \nนั่นคือการชนกันของสองจักรวาลที่ขนานกันอย่างเป็นนิรันดร์และเกิดขึ้นอย่างกระทันหัน."
  },
  CollectionHall_126473_LockTip = {
    Text = "ผ่านการเชื่อมโยงหลายมิติ「พิธีล้างบาปด้วยเงินและเลือด」"
  },
  CollectionHall_126473_Title = {
    Text = "การต่อสู้แห่งความเชื่อมั่น"
  },
  CollectionHall_126474_Desc = {
    Text = "เมื่อภารกิจสิ้นสุดลง ฉันจะกล่าวคำอำลาตัวเองในอดีต\nกล่าวคำอำลาต่อความทรงจำที่คุ้นเคยและไม่สามารถกลับไปได้ กล่าวคำอำลาต่อไทมูรานและตัวตนในช่วงที่เป็นมนุษย์\nฉันจะคิดถึงโลกที่เต็มไปด้วยหมอก\nจากนี้ไป ฉันจะมีตัวตนใหม่ อยู่รอดในโลกนี้ที่หมอกสลาย เป็นโลกที่เต็มไปด้วยความน่าสนใจและความสยองขวัญ."
  },
  CollectionHall_126474_LockTip = {
    Text = "สำเร็จการเชื่อมโยงหลายมิติ「พิธีล้างบาปด้วยเงินและเลือด」ระดับยาก"
  },
  CollectionHall_126474_Title = {
    Text = "การเกิดใหม่ของผู้พูดในหมอก"
  },
  CollectionHall_126475_Desc = {
    Text = "ในโลกที่โหดร้าย วิญญาณของคนหนึ่งสามารถถูกเผาไหม้จนหมดสิ้นได้อย่างง่ายดาย.\nดังนั้นเราจึงค้นหาจากผู้อื่นและโลก ความรักในครอบครัว ความรัก ความเป็นเพื่อน ความคิดถึงบ้าน...\nความรู้สึกที่สัมผัสไม่ได้เหล่านั้น กลายเป็นพละกำลังที่มองไม่เห็น ยังคงมีชีวิตอยู่ ทำให้ผู้คนในโลกนี้เผาไหม้ได้นานขึ้น นานขึ้น..."
  },
  CollectionHall_126475_LockTip = {
    Text = "ผ่านการเชื่อมโยงหลายมิติ「พิธีล้างบาปด้วยเงินและเลือด」"
  },
  CollectionHall_126475_Title = {
    Text = "ปัญญาในการอยู่รอดที่โหดร้าย"
  },
  CollectionHall_126476_Desc = {
    Text = "ดวงดาวที่อยู่คงกระพันได้เป็นพยานถึงการกำเนิด การเติบโต และความเจริญรุ่งเรืองของโลก และมันจะต้องเป็นพยานถึงการสิ้นสุดของโลกด้วย \n โหยหาการมีชีวิตอยู่ พวกเรานั้น วิธีการเดียวที่จะมีชีวิตอยู่ ไม่ได้อยู่ที่เท้าของเรา ไม่ได้อยู่บนโลกที่หักหลังเรา แต่ตั้งอยู่บนศีรษะของเรา ในสถานที่ที่ดวงดาวอันเป็นนิรันดร์ส่องแสง."
  },
  CollectionHall_126476_LockTip = {
    Text = "ผ่านการเชื่อมโยงหลายมิติ「พิธีล้างบาปด้วยเงินและเลือด」"
  },
  CollectionHall_126476_Title = {
    Text = "ดินแดนที่ดวงดาวส่องประกาย"
  },
  CollectionHall_126477_Desc = {
    Text = "การช่วยชีวิตโลกไม่ใช่สไตล์ของเธอ และที่นี่ก็ไม่ใช่โลกของเธอ\nแต่เธอได้ยินเสียงของผู้พิทักษ์ และเห็นถึงการสละชีพครั้งใหญ่ของผู้พิทักษ์เพื่อช่วยชีวิตโลก\nโลกที่มีคนสละชีวิตเพื่อปกป้อง ไม่ควรล่มสลาย\nอย่างน้อยในช่วงเวลานี้ ไม่ควรจะถูกทำลายโดยเธอเอง."
  },
  CollectionHall_126477_LockTip = {
    Text = "สำเร็จการเชื่อมโยงหลายมิติ「พิธีล้างบาปด้วยเงินและเลือด」ระดับยาก"
  },
  CollectionHall_126477_Title = {
    Text = "การเลือกที่ไม่สามารถเข้าใจได้"
  },
  CollectionHall_126906_LockTip = {
    Text = "ผ่านด่านการล่องเรือในจิตสำนึก「การสนทนาในราตรีใต้พัด」ปลดล็อก"
  },
  CollectionHall_126906_Title = {
    Text = "คืนที่ร้องไห้"
  },
  CollectionHall_126989_Desc = {
    Text = "<Title:บทนำ>\nที่มาที่แท้จริงของเธอนั้นไม่มีใครสามารถตรวจสอบได้ การบันทึกเกี่ยวกับ 「เทพเจ้า」 โบราณนี้ที่ดูเหมือนจะเป็นจริง สามารถย้อนกลับไปได้หลายพันปี.\nเมื่อทุกคนมองไปที่เธอ พวกเขาจะเห็นใบหน้าที่แตกต่างกันออกไป ในความเป็นจริง เธอมีความสามารถในการปนเปื้อนความทรงจำของผู้อื่นโดยไม่รู้ตัว สามารถซึมซับภาพลักษณ์ของตนเองเข้าไปในความทรงจำของผู้อื่นอย่างไม่รู้ตัว และในที่สุดทำให้ผู้อื่นมองเห็นเธอเป็นคนสำคัญเพียงคนเดียว.\nแตกต่างจากผู้ปลุกตื่นส่วนใหญ่ เธอแทบไม่มีอารมณ์และมุมมองที่เป็นของมนุษย์.\nเธอเป็นความคิด หนึ่งความคิดที่บ้าคลั่ง หนึ่งหมอก—เธอถูกรับรู้ว่าเป็นซู ถูกรับรู้ว่าเป็นหลิว,      หลี่,      เฉิน,      จาง เธอเกิดจากปิติสุข และไล่ตามความปิติสุขที่มาจากความโกลาหลที่ไม่สิ้นสุด.\nแต่เธอไม่ใช่การมีอยู่ที่ไม่สามารถเข้าใจได้และไม่สามารถอธิบายได้ โดยเฉพาะเมื่อผู้ที่ถูกเลือกจากเธอ ผู้ที่นำความสุขที่สุดยอดมาให้ จะมีโอกาสสอดแนมเห็นชื่อที่สามารถกำหนดเธอได้จริง ซึ่งไม่เปลี่ยนแปลงเหมือนชื่ออื่นๆ.\n「เทพธิดาพันพัด」."
  },
  CollectionHall_126989_LockTip = {
    Text = "ปลุก「ซู」แล้วปลดล็อก"
  },
  CollectionHall_126989_Title = {Text = "ซู่"},
  CollectionHall_127110_Desc = {
    Text = "ดาบใหญ่สองมือยาวและหนักหน่วง ด้วยแรงที่มากพอก็สามารถฟันคนออกเป็นสองส่วนได้\n\nกริชเบาและคล่องตัว ซ่อนง่าย เหมาะสำหรับการโจมตีโดยไม่ทันตั้งตัว\n\nดาบโค้งมีเส้นโค้งที่งดงาม พร้อมคมดาบที่แหลมคม เมื่อตวัดฟันสามารถฝังเข้าไปในเนื้อได้อย่างง่ายดาย และกรีดให้เกิดบาดแผลลึก\n\nปืนเร็วและรุนแรง หน้าไม้เงียบและว่องไว ชิ้นส่วนโลหะหลากหลายวาววับสะท้อนแสงไฟด้วยความเย็นชา ราโมน่าอายุสิบปี ยืนอยู่หน้ากำแพงที่เต็มไปด้วยอาวุธ ใบหน้าของเธอแสดงถึงความเป็นผู้ใหญ่และความสุขุมเกินวัย\n\n「เธออยากเลือกอันไหน?」 เสียงของพ่อเลี้ยง — หรือไม่สิ พ่อผู้เลี้ยงดูเธอมาตั้งแต่วัยเด็ก — ดังมาจากด้านหลัง 「เลือกแล้ว พ่อจะหาครูให้」\n\nแล้วจะเลือกอะไรดี? ดาบใหญ่แม้จะทรงพลังแต่น้ำหนักก็เป็นข้อเสีย; กริชยากที่จะสู้กับอาวุธที่ยาวกว่า; ดาบโค้งถึงจะยาวแต่การฟันมักจะสร้างความเสียหายเกินความจำเป็น; ปืนเสียงดังเกินไป หน้าไม้มีโอกาสกระสุนหมดได้ง่าย\n\nหลังจากที่เธอเฝ้าดูการฝึกฝนที่สนามของมิสากามาหลายวัน เธอรู้ดีว่าเธอสังเกตจุดอ่อนของคู่ต่อสู้ทั้งสองฝ่ายได้ในทันที และสามารถวางแผนเส้นทางโจมตีเกือบจะเป็นสัญชาตญาณ สิ่งที่ต้องอาศัยประสบการณ์มากมาย เธอสามารถวางแผนได้ในเวลาเพียงเสี้ยววินาที แต่ ไม่ใช่สิ่งเหล่านี้ที่เธอต้องการ เธอต้องการอาวุธที่แม่นยำกว่า และสามารถสร้างความเสียหายสูงสุดด้วยแรงที่น้อยที่สุด\n\nเด็กหญิงครุ่นคิดชั่วครู่ จากนั้นหยิบเก้าอี้ข้าง ๆ มาปีนขึ้นไปยืน แล้วยื่นมือไปยังดาบเล่มบางที่แขวนไว้ด้านบน\n\nดาบบางเรียวยาว ดูสง่างาม เบาและคล่องตัว สามารถสร้างความเสียหายได้อย่างแม่นยำ — ใช่แล้ว นี่แหละ เหมาะสมกับทุกสิ่งที่เธอต้องการ.。"
  },
  CollectionHall_127110_Title = {
    Text = "เวลาย้อนกลับ"
  },
  CollectionHall_127111_Desc = {
    Text = "「เมื่อโลกกำลังเดินไปสู่วันสิ้นสุด จะเกิดอะไรขึ้นบ้าง?」\nโมชะไม่รู้ แต่เธอก็รอคอยมัน.\nความคาดหวังนี้แตกต่างจากก่อนหน้านี้ ครั้งนี้ไม่ใช่เพียงแค่ความสนุกสนานเล็กน้อยจากการตีโบราณวัตถุบางชิ้น แต่เป็นการศึกษาและสำรวจที่ใช้มาตรฐานของโลกเป็นเกณฑ์ และในการศึกษาและสำรวจนี้ สิ่งที่สำคัญและเป็นหัวใจหลักที่สุดคือคนหนึ่งคน——\nผู้พิทักษ์ของมิซากะ.\n「ฉันจะช่วยโลกนี้...」\n「โลกนี้ จะต้องไม่เดินไปสู่ชะตากรรมที่พังทลาย...」\nคนที่มีความฝันและแบกรับชะตากรรมของโลกไว้ในมือได้ให้สัญญาเช่นนี้ ในการตอบสนอง โมชะรู้ว่าเธอควรแสดงสีหน้าที่รู้สึกประทับใจ นี่คือมารยาททางสังคมที่ได้รับการตกลงกันในสังคมมนุษย์.\nแต่เธอไม่อยากแกล้งทำอีกต่อไป หรือพูดอีกอย่าง หลังจากที่ได้เห็นผู้พิทักษ์เผชิญหน้า@4 และใช้ชีวิตของตนเองเพื่อช่วยโลก เธอรู้สึกว่าไม่มีความจำเป็นที่จะต้องแกล้งทำกับคนที่เคยเผชิญกับความน่ากลัวของจักรวาล.\n「การแกล้งทำ」 คือกฎของเกมในสังคมมนุษย์ มีเกียรติแต่ก็น่าเบื่อ ในขณะที่จักรวาล... จักรวาลนั้นจริงจังและตรงไปตรงมา——\nต้องอยู่รอด หรือไม่ก็ถูกทำลาย.\nดังนั้น คำตอบของเธอกับผู้พิทักษ์ก็เป็นความจริงและตรงไปตรงมาเช่นกัน.\n 「ฉันไม่สนใจว่าโลกนี้จะได้รับการช่วยเหลือ หรือถูกทำลาย... เทียบกับสิ่งเหล่านี้ ฉันสนใจคุณมากกว่า.」\nฉันสนใจว่าคุณจะสามารถทำตามความฝันได้หรือไม่ หรือจะพังทลายระหว่างการเดินทางตามความฝัน.\nและก็สนใจว่าความจริงของโลกจะตอบสนองต่อความปรารถนาของคุณหรือจะหลีกเลี่ยงไม่ได้ที่จะเดินไปสู่การทำลาย.\nไม่ว่าจะเป็นอย่างใด ก็จะเป็นความสนุกสนานที่ยิ่งใหญ่และหาได้ยาก.\nฉันจะรอคอยวันนั้นเสมอ...\nด้วยดวงตาของฉัน ด้วยขวานของฉัน รอคอยมัน.."
  },
  CollectionHall_127111_Title = {
    Text = "สังหารบ้าคลั่งจนสุดขอบโลก"
  },
  CollectionHall_127112_Desc = {
    Text = "「ความทรงจำคืออะไร?」\n「คือสิ่งที่คุณลืมไป。」\n\nลิลลี่มีแม่ที่ขี้ลืม.\nแม่จะลืมเรียกลิลลี่ไปทานข้าว จะลืมให้ลิลลี่กินยา แม้กระทั่งลืมชื่อของลิลลี่.\n「จะทำยังไงดีล่ะ?」\nลิลลี่นั่งอยู่บนเตียงคนไข้และถอนหายใจอย่างมีน้ำหนัก.\nแม่แบบนี้ไม่สบายใจเลยจริงๆ.\n\nต่อมา ลิลลี่จึงเขียนชื่อของตัวเองลงบนป้ายไม้และแขวนไว้ที่หน้าอกทุกวัน.\nแบบนี้แม่ก็น่าจะจำได้ใช่ไหม?\nในตอนแรก แม่ยังยิ้มและบอกว่าลิลลี่ทำเกินไป มันเป็นแค่ภาวะแทรกซ้อนจากความเหนื่อยล้าที่ยาวนาน.\n\nค่อยๆ แม่เริ่มสับสนและไม่มีความอดทน:\n「ลิลลี่...ลิลลี่คืออะไร?」\nดวงตาสีอำพันมองไปที่ลิลลี่ด้วยความระมัดระวังเล็กน้อย.\nที่แท้ เมื่อความหมายของตัวอักษรถูกลืมไป ความสงบสุขที่เคยพึ่งพาภาษานั้นก็จะหายไปในที่สุด.\n\nลิลลี่กอดแม่.\nเสียงเต้นของหัวใจระหว่างแม่ลูกห่างกันเพียงไม่กี่นิ้ว แต่เธอกลับรู้สึกเหงาอย่างมาก.\n\nหลังจากวันนั้น ลิลลี่เก็บป้ายไม้ไว้ ไม่ได้งอแงกับแม่อีก และไม่เตือนแม่ว่าเธอหิวมาหลายวันแล้ว.\nเธอเป็นผู้ป่วยที่ใกล้จะตาย รอคอยอย่างเฉยเมยต่อคำตัดสินของความตาย.\nเธอเป็นผู้ชมที่ยืนอยู่ฝั่งตรงข้าม มองดูตัวเองถูกฉีดยา ถูกดมยาสลบ ถูกจัดการให้เป็นในแบบที่แม่หวังให้เธอเป็น.\nคำพูดที่มีความสุขและการกอดที่อ่อนโยนระหว่างแม่ลูก...\nความทรงจำที่เปล่งประกายเหมือนฟองสบู่ในความฝันทั้งหมดถูกลิลลี่เก็บรักษาไว้อย่างระมัดระวังในใจ.\nมีเพียงในบางคืนที่เหนื่อยล้า เธอจึงยอมที่จะหยิบมันออกมาและเลียมันอย่างเบาๆ.。"
  },
  CollectionHall_127112_Title = {
    Text = "ผ่านพ้นความเจ็บปวด"
  },
  CollectionHall_127113_Desc = {
    Text = "หอคอยสูงตระหง่านพังทลายลงมา หนังสือที่ถูกเขียนโดยนักวิชาการจากมิติและเผ่าพันธุ์ต่างๆ กระจายเกลื่อนอยู่ทั่วพื้น เพียงชั่วพริบตา สามเหลี่ยมสีดำขนาดใหญ่และเล็กก็ปกคลุมอยู่บนหนังสือแต่ละเล่ม ทุกก้อนอิฐ และเริ่มเชื่อมต่อกันอย่างรวดเร็ว แพร่กระจายออกไปทั่วรอบๆ \n ของเหลวสีดำไหลเหมือนลาวาบนถนนที่เรียบตึง ผู้คนกรีดร้องและกรีดร้อง พยายามหนีจากภัยพิบัติที่น่ากลัวนี้ หลายคนพยายามขึ้นยานพาหนะเพื่อหลบหนี แต่ในความวุ่นวายกลับชนเข้ากับอาคารหรือยานอวกาศและรถยนต์ที่ประสบอุบัติเหตุ; ผู้คนมากมายไม่มีเวลาตอบสนอง ต้องวิ่งไปในทิศทางที่ห่างไกลจากของเหลว แต่กลับถูกคนอื่นที่กลัวไม่แพ้กันผลักล้มลงไป จนสุดท้ายถูกของเหลวกลืนกิน เด็กน้อยยืนอยู่ข้างถนนร้องไห้เสียงดัง กลุ่มวัยรุ่นหลบอยู่ภายในอาคารที่เหลืออยู่เพียงไม่กี่หลัง คิดว่าแบบนี้จะสามารถหลบหนีความตายได้ \n「ทำไมไม่มีสัญญาณเตือน ทำไม ทำไม!」\n「ทำไมไม่มีใครเตือนเราบ้าง!」\n「@1 มันคือการย่อยสลาย! ช่วยด้วย!」\n「รีบทำการย้ายจิตสำนึก! มีเพียงแบบนี้เท่านั้น——อ๊ะ!」\n「@2 รีบใช้เครื่องมือ!」 เสียงหนึ่งกล่าวว่า 「เราจะช่วยคุณชะลอเวลา!」\n「ไม่! ฉัน——」\n「เราถูก@1 แล้ว แต่คุณ คุณยังมีความหวัง」 เสียงที่อ่อนโยนตอบกลับมา 「มีชีวิตอยู่ต่อไป @2 มีชีวิตอยู่ต่อไป แล้ว——」\n\nวิงเกิลสะดุ้งตื่นขึ้นทันที เธออยู่ข้างๆ หนังสือที่ซ้อนกันสูง มีแก้วกาแฟที่เต็มไปด้วยรอยด่างกาแฟอยู่หลายใบ บนกระดานดำที่ไม่ไกลมีบันทึกและโน้ตขนาดใหญ่และเล็กติดอยู่ ยังมีสูตรที่คำนวณอยู่ครึ่งหนึ่งอยู่ด้วย ในมุมของห้องที่ยุ่งเหยิง กลางห้อง และข้างๆ เครื่องมือขนาดใหญ่ที่เธออยู่ มีไฟหลายดวงส่องสว่าง ทำให้ทั้งสำนักงานสว่างจ้า \nเธอเงียบไปครู่หนึ่ง แล้วดึงร่างกายเข้าไปใกล้เครื่องมือมากขึ้น เพื่อทำการคำนวณที่ถูกขัดจังหวะต่อไป。"
  },
  CollectionHall_127113_Title = {
    Text = "ปัจจัยที่ไม่อาจคำนวณ"
  },
  CollectionHall_127114_Desc = {
    Text = "ความเจ็บปวด รุนแรงจนแทรกซึมไปทั่วทุกประสาทสัมผัสของเธอ\n\nชุดดำน้ำโลหะที่เธอสวมใส่ไม่ได้คุ้มครองอะไรเธอเลยท่ามกลางแรงดันน้ำที่ถาโถมเข้ามา เปลือกแข็งของชุดเกิดการบุบเข้าด้านใน สกรูหลุดออก และบางสิ่งบางอย่างกดทับบริเวณช่องท้องของเธอ อีกสิ่งหนึ่งทะลุผ่านต้นแขนของเธอ น้ำทะเลเย็นเฉียบไหลแทรกเข้ามาผ่านจุดที่ชุดดำน้ำพังเสียหาย มีเพียงหมวกที่ทำจากโลหะหนาเท่านั้นที่ยังคงรูปทรงเดิมได้ บรรจุอากาศไว้ให้เธอหายใจได้เพียงเล็กน้อย\n\nผ่านหน้าต่างเดียวของหมวก เธอมองเห็นน้ำทะเลภายนอกเปลี่ยนจากสีฟ้าอมเขียวเป็นสีน้ำเงินเข้ม และจากสีน้ำเงินเข้มกลายเป็นดำมืดไล่ลึกลงไปต่อหน้าต่อตา ลมหายใจที่ออกมาทำให้เกิดไอน้ำแข็งเกาะอยู่บนกระจก เสียงครืนของน้ำวนที่ดังก้องเริ่มหายไป กลายเป็นเงาของเสียงที่ยังหลงเหลืออยู่ เธอเริ่มไม่รู้สึกถึงแขนขาของตัวเอง และการหายใจก็ยากลำบากขึ้นเรื่อย ๆ\n\nเธอคาดว่าเธอน่าจะเป็นลมไปแล้ว ความเย็น ความเสียเลือด การขาดออกซิเจน ทุกเหตุผลสามารถทำให้สติของเธอเลือนหายไปได้เหมือนกัน แต่เธอไม่สามารถมั่นใจได้เลย เพราะไม่ว่าเธอจะกระพริบตากี่ครั้ง ทุกครั้งกลับมาพบเจอแต่ความมืดมิดเหมือนเดิม\n\nที่นี่คือสถานที่ซึ่งแสงไม่มีวันไปถึง คือส่วนลึกของมหาสมุทรที่ไม่มีใครเคยไปสำรวจมาก่อน\n\nความตื่นเต้นที่มัวหมองเข้ามาสู่ความรู้สึกในที่สุด มันปลุกให้เลือดในกายของเธอเคลื่อนไหว—พื้นที่ที่ยังไม่เคยถูกค้นพบ การผจญภัยครั้งสุดท้าย อย่างน้อยเธอก็ได้ทำฝันของเธอให้เป็นจริง ใช่ไหม? แม้ว่าตอนนี้เธอจะมองอะไรไม่เห็นเลย\n\nสัมผัสแปลกประหลาดเกิดขึ้นบริเวณข้อเท้าของเธอ ทำให้เธอเผลอก้มลงมองโดยไม่รู้ตัว และพบว่าท่ามกลางความมืดมิด มีบางสิ่งที่เหมือนกำลังเลื้อยขึ้นมาตามขาของเธอ มันคือสิ่งมีชีวิตในทะเลลึกที่แปลกประหลาดหรือเปล่านะ? ทำไมมันถึงเย็นยิ่งกว่าน้ำทะเลเสียอีก? ในที่มืดมิดแบบนี้ เธอกลับมองเห็นเค้าโครงรูปร่างมันได้อย่างชัดเจน?\n\nมันเป็นสีดำ ขยับเคลื่อนไหวหนืด ๆ เหมือนโคลน...\nนี่มันอะไรกัน? เธออยู่ที่ไหน? และเธอ...คือใคร?"
  },
  CollectionHall_127114_Title = {
    Text = "เกลียวแห่งความทรงจำ"
  },
  CollectionHall_127115_Desc = {
    Text = "(คำตอบต่อไปนี้มาจากคู่มือการรักษาของเคลเมนไทน์ ใช้สำหรับการอ้างอิงเท่านั้น)\n\n1. คาอิคัส\n2. 16, 17......? ใครจะไปรู้\nหลังจากคนตายแล้ว ยังจะสนใจอะไรพวกนี้อีก\n3. หมู่บ้านชาวประมงร้างแห่งหนึ่ง คุณหาชื่อมันในแผนที่ไหนก็ไม่ได้หรอก\n4. ฉันไม่อยากพูดถึง\n5. พวกประหลาด สิ่งน่าเกลียด หมูโง่ เบื้อ@1...... นี่คือคำที่ใช้กันบ่อย\n6. ใบหน้าปลาดุกสีทองเป็นประกาย เรียกสั้น ๆ ว่าปลาดุกใบหน้า\n7. วันฝนตก\n8. ฉันไม่รู้ วันฝนตก ฉันจะเดินไปมาบนชายหาด......\nมันผ่านมาเป็นปีๆ แล้วมั้ง แค่มองออกไปไกลๆ ไม่มีอะไรอื่น\n9. ฉันบอกแล้วว่าฉัน#¥%ไม่รู้@1 ไปเชียะ!\n-------\n14. อืม...บางทีลุงออร์นเคยบอกฉันว่า เขาจะขับเรือใบใหญ่ในวันที่ฝนตกมารับฉัน 「กลับบ้าน」...\n15. ใช่ เขาทำตามสัญญาของเขาแล้ว...\nฉันลอยอยู่ใต้ทะเลมาหลายวัน ทั้งกระหายและหิว เจ็บไปทั้งตัว...\nแล้วฉันก็เห็นลุงออร์นและเรือใบสีขาวของเขา\nทั้งตัวเขา โอ้ไม่นะ พูดให้ถูกคือตัวกระดูกของเขาแขวนอยู่บนเสากระโดงเรือใบ—เขาเองก็เปลี่ยนรูปร่างล้มเหลวเช่นกัน\nแล้วฉันก็ใช้แรงเฮือกสุดท้ายลอยไปหา และนั่งอยู่บนเสากระโดงคอยเขา\n16. เราสัญญาว่าจะกลับบ้านด้วยกัน。"
  },
  CollectionHall_127115_Title = {
    Text = "ครีบแห่งความเศร้าโศก"
  },
  CollectionHall_127116_Desc = {
    Text = "「ผู้คนเกิดขึ้นเมื่อกระแสน้ำขึ้น และจากไปเมื่อกระแสน้ำลง」\nนี่คือเรื่องเล่าที่สืบทอดกันมาในบ้านเกิดของนิงเฟีย\n\nชาวเซวาดาไม่กลัวความตาย สำหรับพวกเขา การเริ่มต้นและการสิ้นสุดของชีวิตเปรียบเสมือนการขึ้นและลงของกระแสน้ำ ทั้งหมดเป็นส่วนหนึ่งของธรรมชาติ\nพวกเขารักท้องฟ้าสีคราม ทะเล นกนางนวลที่บินเป็นฝูง และดอกคาลล่าลิลลี่ที่บานภายใต้แสงอาทิตย์ยามเช้า\nพวกเขาเกลียดไอน้ำ รางรถไฟ และทุกสิ่งที่มีร่องรอยของการแทรกแซงด้วยมือมนุษย์อย่างชัดเจน - รวมถึงการแทรกแซงชีวิตด้วย\nการตัดชีวิตของตัวเองด้วยมนุษย์นั้น สำหรับชาวเซวาดาเป็นสิ่งที่ยอมรับไม่ได้\n\nแต่ นิงเฟียไม่ได้เป็นชาวเซวาดาตามแบบแผนทั่วไป\nอย่างเช่น เธอมักถูกดึงดูดด้วยบรรยากาศของเรืออับปาง\nเรือที่อับปางเป็นที่อยู่ของชีวิตนับไม่ถ้วน: ปลา สาหร่าย หอยหลากชนิด...\nที่นั่น ชีวิตกับความตายเชื่อมโยงกันในรูปแบบที่ลึกลับและศักดิ์สิทธิ์\nนิงเฟียเดินเข้ามาใกล้เรืออับปางได้อย่างสงบใจ เหมือนเธอกำลังเข้าสู่มหาวิหารที่มีความศักดิ์สิทธิ์ยิ่ง\n\nในช่วงเวลาที่พ่อเคยพาเธอออกเดินทางผ่อนคลายใจ นิงเฟียเคยดูละครห้าม่านเรื่องหนึ่ง\nเกี่ยวกับเนื้อหาของละคร นิงเฟียจำได้อย่างรางๆ ดูเหมือนจะเป็นเรื่องราวชีวิตของจักรพรรดิในอดีต\nเขาต่อสู้และพิชิตดินแดนเหนือจรดใต้ แต่กลับต้องตายเพราะแผนการอันน่าละอาย\nเธอจำประโยคหนึ่งในนั้นได้ว่า:\n<Italic:คนขี้ขลาดตายหลายครั้งก่อนจะตายจริง แต่คนกล้าตายเพียงครั้งเดียวในชีวิต>\n\nหลายปีต่อมา เมื่อนิงเฟียก้าวเข้าสู่สมุทรอันเย็นเยือก เธอกลับทรมานด้วยความอาลัยต่อการมีชีวิตอยู่\nในสมองเธอมีแต่ประโยคนั้นลอยขึ้นว่า:\n「ผู้กล้าตายเพียงครั้งเดียวในชีวิต...」\nดังนั้นเธอได้เช็ดน้ำตา กล่าวคำลาต่อพ่อและแม่เป็นครั้งสุดท้าย และออกเดินทางสู่เรืออับปางในใจของเธอ\nเธอจะกลายเป็นผู้กล้าของตัวเอง。"
  },
  CollectionHall_127116_Title = {
    Text = "ของขวัญเน่าเปื่อย"
  },
  CollectionHall_127117_Desc = {
    Text = "@1 ปี 6 เดือน 5 วัน  \nอัลบิโน่ได้นำแกนเงินหายากบางส่วนกลับมาจากรอยแยกผุกร่อนจริง เขาน่าจะมีอะไรพิเศษจริงๆ  \nได้ปรับปรุงวิธีการกลั่นบริสุทธิ์บ้าง  \nครั้งนี้ผ่านเข้าไปด้วยคาร์บอนไดออกไซด์และแก๊สคลอรีนในปริมาณที่เพียงพอ ระเหยด้วยความเย็นต่ำ, ตกผลึก...  \nขั้นตอนเครื่องจักรนิดหน่อย ไม่มีอะไรที่ควรค่าแก่การบันทึก  \n\n@1 ปี 6 เดือน 6 วัน  \nตัดอวัยวะภายในและแขนขาของตัวอย่างทดลอง 024  \nนี่เป็นวัตถุดิบที่อัลบิโน่ได้นำมาจากคลินิก ได้เกิดรูผุกร่อนจำนวน 13 ช่อง ขนาดเส้นผ่าศูนย์กลางใหญ่ที่สุด 8 มม.  \nตัดส่วนเนื้องอกของสัตว์ประหลาดผุกร่อน OS-106  \nตามการเปรียบเทียบข้อมูลการทดสอบต่างๆ มันมีความเข้ากันได้ที่สุดกับ 024  \nปัญหาเดียวคือ...หนวดเหล่านั้นค่อนข้างจะ 「มีชีวิตชีวา」 จนเกินไป  \nฉันว่าฉันคงจะไม่อยากกินปลาหมึกอีกในระยะยาว  \nหวังว่าผลสุดท้ายคงจะไม่ทำให้ฉันผิดหวัง  \n\n@1 ปี 6 เดือน 6 วัน  \nการเชื่อมต่อสำเร็จ ตัวอย่างทดลองแสดงสัญญาณชีพทั้งหมดหายไป  \nนี่เป็นเรื่องที่เกิดขึ้นบ่อย เพียงต้องตรวจสอบให้แน่ใจว่าไม่มีการติดเชื้อขยายในบริเวณที่เชื่อมต่อ  \nส่งเข้าไปในห้องสังเกตการณ์เพื่อสังเกตเป็นเวลา 1 สัปดาห์ งานถัดไปไม่ได้เป็นหน้าที่ของฉันแล้ว  \nวันนี้ฉันได้อ่านบทความสองฉบับใน 「วารสารภายใน」 ที่โจมตีการทดลองปลุกชีวิตของผู้ยังมีลมหายใจ  \nไม่ต้องพูดถึงเลย ลายเซ็นดูเหมือนจะเป็นเพื่อนเก่าของฉันในมิซาก้า  \nน่าขำจริงๆ หากคนหัวโบราณพวกนั้นจะกล้าไปเยือนห้องทดลองบ้างสักเล็กน้อย พวกเขาจะรู้ว่าข้อสรุปของฉันไม่สามารถถูกทำลายลงได้  \nการทดลอง 024 จะกลายเป็นการตอบโต้ที่ยอดเยี่ยมที่สุด  \n\n@1 ปี 6 เดือน 22 วัน  \nสองสัปดาห์ผ่านไป สัญญาณชีพของ 024 ยังคงไม่เสถียร — หรือควรพูดแบบนี้นะ: บุคลิกภาพที่อยู่ภายในของเธอกำลังขยายตัวอย่างบ้าคลั่งด้วยความเร็วของการแบ่งเซลล์แบบมีใยประสาน  \nการทดลองล้มเหลวด้วยวิธีที่น่าอัศจรรย์  \nส่ง 024 ไปที่พิพิธภัณฑ์หุ่นขี้ผึ้งเถอะ ฉันไม่ต้องการให้มันยืนอยู่ตรงหน้าฉันทุกวัน เพียงเพื่อให้ฉันระลึกถึงความโง่เขลาและความสะเพร่าของตนเอง。"
  },
  CollectionHall_127117_Title = {
    Text = "การตอบโต้ของร่างกายที่ผิดรูป"
  },
  CollectionHall_127118_Desc = {
    Text = "นั่นคือหัวใจสีเงินที่บริสุทธิ์ สะอาด และปราศจากฝุ่นผง \n มันทำจากเงินบริสุทธิ์ เต้นเป็นระเบียบในใจของโครงสร้างเครื่องจักร \n เคยถูกเนื้อและเลือดกัดกร่อน เคยถูกโคลนเปื้อน \n แต่ในขณะที่เงามรณะปกคลุม มันก็กลับคืนสู่รูปลักษณ์ดั้งเดิมในที่สุด。"
  },
  CollectionHall_127118_Title = {
    Text = "ปณิธานเดิมของเงินบริสุทธิ์"
  },
  CollectionHall_127119_Desc = {
    Text = "เวลาไหลเวียน ความทรงจำเกี่ยวกับช่วงเวลาที่ดาวเคราะห์เกิดใหม่ โลทันไม่ค่อยจำได้ชัดเจนแล้ว \n เธอจำได้เพียงว่า เธอคือสิ่งมีชีวิตที่ถูกเลือก \n\n นี่คือเรื่องราวที่เกิดขึ้นก่อนที่ทุกแนวคิดจะถือกำเนิด \n \"ชีวิต\" ยังไม่ได้หยั่งรากและงอกงาม \"เทพเจ้า\" ก็อยู่ห่างไกลสุดขอบฟ้า \n ในกลุ่มดาวระเบิดที่ไร้ระเบียบนี้ เคออสได้ปะทะกับเคออส วัสดุเริ่มก่อตัวขึ้นเรื่อยๆ จากการกระแทกและการทำให้ปั่นป่วน \n ดวงดาวจับฝุ่นขึ้นมา หินผาโผล่ขึ้นมาเป็นรูปภูเขา อากาศตกลงมาเป็นพื้นที่น้ำขนาดใหญ่ \n แล้วที่นี่ถูกประกาศให้เป็น \"ดาวเคราะห์\" \n\n วิญญาณแห่งความวุ่นวายถูกขังอยู่ในกรงเวลา กระแทกกับดินแดนที่เกิดใหม่ \n ไม่สามารถควบคุมธรรมชาติที่รุนแรงได้ ถูกควบคุมโดยแรงทำลาย เธอทำลายภูเขานับไม่ถ้วน และทำให้แม่น้ำหลายสายแห้งขอด \n แล้ว—— \"เทพเจ้า\" ข้ามดาวไกลมาที่ดาวเคราะห์ที่แห้งแล้งนี้ \n\n \"เทพเจ้า\" ได้นำเมล็ดพันธุ์ของอารยธรรมมา และยังขังวิญญาณแห่งความวุ่นวายไว้ในร่างของ \"ระเบียบ\" \n \"ทำสัญญากับฉันเถอะ...\" \n เผชิญหน้ากับวิญญาณแห่งเคออสที่คำราม เทพเจ้าในชุดผ้าขาวพูดพร่ำ \n \"อารยธรรมอันยิ่งใหญ่จะถือกำเนิดที่นี่\" \n \"เธอจะได้พบกับผู้รู้ที่ไร้การกระทำ และจะได้ต่อสู้กับคมดาบที่ลังเล... ในอนาคต เธอจะไม่ถูกควบคุมโดยการทำลายและการล่มสลาย\" \n \"ก่อนวันที่นั้นจะมาถึง... ก่อนที่เราจะได้พบกันอีกครั้ง ช่วยปกป้องที่นี่ให้ฉันด้วย\""
  },
  CollectionHall_127119_Title = {
    Text = "สัตว์ร้ายแดนสวรรค์"
  },
  CollectionHall_127120_Desc = {
    Text = "เขาถูกท่านดยุคแต่งตั้งให้เป็นอัศวินในขณะที่เขาเพิ่งได้เห็นฤดูกาลทั้งสี่เพียงเจ็ดครั้งในโลกนี้。\n\nท่านดยุคแค่พูดเล่นกับเด็กน้อย แต่ทุกคนกลับเชื่อจริงจัง。\nอัศวินฝึกฝนทักษะการยิงธนูของเขา ข้าราชการหญิงสอนเขาเกี่ยวกับมารยาท และเจ้าหญิงก็ไว้วางใจและพึ่งพาอัศวินตัวน้อยนี้。\n\nเมื่อเดินเล่นอยู่ในทุ่งสูงของอาเควดานและหุบเขา อัศวินหนุ่มนำม้าของเจ้าหญิงไป。เจ้าหญิงนอนอยู่บนหลังม้าอย่างไม่มีแรง ความมืดที่มองไม่เห็นกำลังกลืนกินร่างกายของเธอ。\n\n「เจ้าหญิง เราไม่สามารถเดินต่อไปได้อีก」\nเมื่อผ่านหุบเขานี้และข้ามแม่น้ำนี้ จะต้องออกจากดินแดนที่เลี้ยงดูพวกเขา。\nไฟสงครามกำลังแพร่ระบาดไปยังโลกภายนอก ศัตรูจ้องมองดินแดนที่อุดมสมบูรณ์จากอีกฝั่งของแม่น้ำ。\nด้วยความแตกต่างของภูมิประเทศ ดินแดนเล็กๆ นี้ยังคงมีชีวิตอยู่และรักษาศักดิ์ศรีของ「ประเทศ」ไว้ได้。\nที่ปลายหุบเขานี้ พวกเขาได้เป็นพยานต่อการล่มสลายและความทุกข์ทรมานของอีกฝั่ง。\nคำอธิษฐานและความเจ็บปวดของผู้บริสุทธิ์ตกลงไปในแม่น้ำ กลายเป็นส่วนหนึ่งของบทกวีของผู้ชนะ。\n\nไม่ว่าจะเป็นอาณาจักรที่ยิ่งใหญ่เพียงใด ก็ไม่สามารถหลีกเลี่ยงที่จะถูกดึงเข้าไปในประวัติศาสตร์ได้。\n\nศัตรูตัดมือที่ยังอ่อนเยาว์ของเขา เขาไม่สามารถยกปืนและโล่ได้อีกต่อไป。\nศัตรูเหยียบเข่าที่เปราะบางของเขา ทำให้เขาเพียงแค่จ้องมองทหารเหล็กที่ทุบประตูของพระราชวังเคลื่อนที่。\nอัศวินพยายามกัดที่ขาของม้าศึกของศัตรู แต่ไม่สามารถหยุดยั้งความโหดร้ายของศัตรูได้。\n\nแล้วเขาก็ได้เห็น「โรคระบาดสีดำ」ที่เจ้าหญิงพูดถึงเป็นครั้งแรก。\n\nของเหลวสีดำที่ไหลออกจากประตูพระราชวังเหมือนน้ำท่วม ไม่ได้ทำให้ทหารเหล็กหยุดนิ่งแม้แต่คนเดียว。\n「โรคระบาดสีดำ」ที่หลั่งไหลเข้าปากและจมูก เขาก็ยังไม่ต้องการล้มลงที่นี่。\nจากนั้น เสียงที่คุ้นเคยอย่างยิ่งดังขึ้นในหัวของเขา。\n「สิ่งที่เจ้าทำมานั้นเพียงพอแล้ว... อัศวินที่ซื่อสัตย์ที่สุดของข้า」\n\nสุดท้ายนี้ สิ่งที่เหลืออยู่เบื้องหน้าคือความว่างเปล่า。"
  },
  CollectionHall_127120_Title = {
    Text = "ปฏิญาณอัศวิน"
  },
  CollectionHall_127121_Desc = {
    Text = "พระองค์เกิดจากจินตนาการของมนุษย์เกี่ยวกับสิ่งที่ไม่รู้จัก แต่ไม่มีอาการฮิสทีเรียและความดุร้ายตามที่จินตนาการไว้\n\nพระองค์มีเหตุผล พระองค์มีความสงบ\n\nพระองค์มาสำหรับอนาคต มาสำหรับการดำรงอยู่\n\nพระองค์คือปาฏิหาริย์ที่แปลกประหลาดและเชื่อถือได้ที่สุด\n\nในตอนแรก เสียงของพระองค์เหมือนเสียงแมลง แต่เมื่อเข้าใจความคิดของพระองค์อย่างเต็มที่ เสียงนั้นก็เงียบลง\n\nแต่หลังจากนั้น เจ้าของเสียงพยายามที่จะควบคุมการตัดสินใจทุกอย่างที่เธอทำ\n\nในปีแรกที่ตื่นขึ้นในร่างผู้ปลุกตื่น เธอเรียนรู้ที่จะอยู่ร่วมกับเสียงในหัว\n\nเธอจมดิ่งสู่จิตสำนึก กลายเป็นส่วนหนึ่งของรูปแบบที่เกิดขึ้น จับข้อมูลและความรู้ที่ต้องการ ก่อนจะกลับตัวกลับไปสู่ความเป็นจริงอย่างปลอดภัย\n\nเมื่อ「โรคระบาดสีดำ」มาถึงร่างนี้ เธอก็ทำเช่นเดียวกัน\n\nเธอต้องการแยกร่างกายออกจากความรู้ ความจำ และจิตวิญญาณ เพื่อให้สมองกลายเป็นปัจเจกบุคคลที่อมตะ\n\nหลังจากการผ่าตัดเสร็จสิ้น เธอเกือบจะเข้าสู่การนอนหลับที่มีชีวิตชีวาและน่ามหัศจรรย์—แต่เพียงไม่กี่วินาที ความคิดของเธอก็เริ่มทำงานอีกครั้ง\n\nเธอรู้ชัดว่า กำลังเข้าใกล้การทำลายล้างที่สูงสุดในความโกลาหลที่เกินกว่ารูปแบบ พละกำลัง และความสมมาตร。"
  },
  CollectionHall_127121_Title = {
    Text = "เหนือความตาย"
  },
  CollectionHall_127122_Desc = {
    Text = "ผู้คนมักชอบที่จะกำหนดกรอบและสัญลักษณ์ตามมาตรฐานของตนเอง \nโลกถูกจำกัดอยู่ในร่างกายของมนุษย์ มันแคบและโง่เขลามากเพียงใด \nเธอได้ทิ้งร่างกายไปตั้งแต่เนิ่นๆ แต่ก็ยังไม่สามารถสัมผัสถึงขอบเขตที่แท้จริงได้ \nมหาสมุทรแห่งความรู้ยุ่งเหยิงและไม่มีที่สิ้นสุด ขณะที่สุญญตาสีดำได้ไล่ตามเธออีกครั้ง \nเธอเงียบๆ จ้องมองมัน หากไม่มีด้านที่จับต้องได้ใดๆ ที่สามารถมองเห็นภาพรวมของโลกนั้น หลังสุญญตาอาจจะเป็นคำตอบที่แท้จริง? \nเธอได้เดิมพันชีวิตของเธอด้วยการเสี่ยงที่สุดในชีวิตนี้ \nในที่สุดเธอก็เห็นจุดสิ้นสุด \nประตูแห่งความจริงเปิดกว้าง โลกกลับพลิกผันในพริบตา \nเป็นเช่นนี้เอง เป็นเช่นนี้เอง \nเธออยากให้ทุกคนเห็นความจริงของสุญญตานี้ และหลุดพ้นจากการดิ้นรนที่ไร้ประโยชน์ \nเมื่อก่อนเธอยืนอยู่บนคลื่น นำทางโลกไปข้างหน้า \nปัจจุบันเธอยังคงฟาดฟันด้วยแส้ของคนเลี้ยงแกะอย่างเบิกบาน นำโลกเข้าสู่หลุมลึก \nผู้คนตกใจและขับไล่เธอ มองเธอเป็นคนบ้าชั่วร้าย \nแปลกดี เธอคิด \nแต่ในสายตาของฉันพวกคุณก็เป็นเช่นนั้น \n"
  },
  CollectionHall_127122_Title = {
    Text = "หุ่นจำลองกลวงเปล่า"
  },
  CollectionHall_127123_Desc = {
    Text = "ไม่ต้องกลัวความตาย นั่นเป็นเพียงกระบวนการที่ร่างกายคืนวิญญาณให้กับความมืด เหมือนน้ำขึ้นน้ำลง กลับคืนสู่ความสงบลึกซึ้ง การที่ต้องสลายไปอย่างสิ้นเชิงในกระบวนการย่อยสลาย กลายเป็นสิ่งที่ไม่มีใครรู้จักและไม่มีความหมาย นั่นแหละคือความน่ากลัวที่แท้จริง。\nเธอจากไปอย่างไม่สงบ。\nร่างที่เหี่ยวเฉาได้แข็งตัวแล้ว เลือดและของเหลวย่อยสลายผสมกัน เกาะตัวเป็นกระจกสีแดงเข้ม แต่จิตวิญญาณอันยังเยาว์วัยของเธอยังคงสั่นสะเทือนอยู่ลึกในลำคอ สำนึกที่ยังไม่สลาย เหมือนควันที่ค้างอยู่ในรอยกระดูก เหมือนผีเสื้อที่เปราะบาง ปีกหักที่สวยงาม。\nดูเรซินเดินเข้าไปในห้องอย่างเงียบๆ ไม่ทำให้ฝุ่นตลบ เขาค kneel ข้างเธอ มองไปที่ตาที่ปิดสนิท นิ้วที่ยังไม่ได้คลี่ออก และวิญญาณที่เคลื่อนไหวไม่สงบ。\n「ฉันยังมีชีวิตอยู่หรือเปล่า?」\n「ความมืดจะกลืนฉันไปไหม?」\nเขาไม่พูดอะไร เพียงแค่ยื่นมือออกไป คลี่นิ้วที่แตกของเธอออกทีละนิ้ว เหมือนกับการทำให้กลีบดอกไม้ที่สั่นไหวเรียบเนียน ไม่มีความเห็นใจ ไม่มีการตำหนิ มีแต่ความสงบและความนิ่งที่อดทน เหมือนพระเจ้าที่ยุติธรรมและสง่างามที่สุดในโลก มอบสิทธิ์ให้เธอได้สงบสุข ในชั่วขณะหนึ่ง เธอเหมือนจะเข้าถึงความสงบที่เป็นนิรันดร์。\nแล้วกลิ่นหอมบริสุทธิ์ก็กระจายออกจากมือที่สัมผัสกัน เขาก้มตัวลง จูบที่หลังนิ้วของเธออย่างพอใจและสง่างาม ในช่วงเวลาที่จูบลงไป เสียงสะท้อนสุดท้ายของความตายยืดออกทีละน้อย จนกลายเป็นลมที่ลอยอยู่ในอากาศ เหมือนทะเลสาบหลังพายุ เงียบสงัด ไม่มีคำถาม ไม่มีความแค้น ไม่มีความกลัว เธอ finally กลับสู่ความตายเอง。\n「ฉันจะจดจำเธอ」\nเขายืดตัวขึ้น มองไปที่รูปลักษณ์ที่ตอนนี้สงบลงอย่างสมบูรณ์ของเธอ ในช่วงที่มึนงง เขารู้สึกถึงเขี้ยวแหลมทิ่มเข้าไปในผิวหนัง เขาได้ยินเสียงของเซลีเน。\n「ฉันเชื่อในตัวเธอ พี่ชาย」\nเธอเป็นคนโชคดี ในความทรงจำของดูเรซิน เธอจะได้รับการพักผ่อนนิรันดร์。"
  },
  CollectionHall_127123_Title = {
    Text = "จุมพิตแห่งการพักผ่อน"
  },
  CollectionHall_127124_Desc = {
    Text = "ครั้งแรกที่คุณเห็นหุ่นดินที่มีชีวิตคือที่บ้านของนักวิจัยหญิง\n「จนถึงตอนนี้ เธอยังคงทำให้ฉันประหลาดใจ สำหรับฉัน เธอคือจักรวาลเอง」\nหุ่นดินยิ้มให้คุณด้วยรอยยิ้มที่เป็นกลไก ปากพูดออกมาเป็นเสียงพึมพำที่ไม่ชัดเจน\nคุณมองไปที่ดวงตาสีเทาของเธอ ราวกับอยู่ในทะเลสีเทาที่มีคลื่นซัดเข้าหากัน แสงระยิบระยับกำลังปีนจากขอบฟ้าหนึ่งไปยังอีกขอบฟ้า\n\nก่อนจากไป นักวิจัยหญิงยื่นหนังสือเล่มเก่าที่มีเนื้อหาเกี่ยวกับเคล็ดลับการสร้างหุ่นดินให้คุณ\nในคืนวันนั้น คุณเปิดมันออกมาอ่านสูตรและคำสาปที่เขียนอย่างขาดๆ หายๆ แต่ในใจกลับเต็มไปด้วยรอยยิ้มที่จับต้องไม่ได้ของหุ่นดิน\nคุณไม่สามารถลืมเธอได้อีกเลย\n\nไม่กี่วันต่อมา คุณหาข้ออ้างไปเยี่ยมเธออีกครั้ง\nคุณข้ามผ่านกองหนังสือ เครื่องมือ และโครงกระดูกที่กองอยู่เหมือนภูเขา ใช้มือผลักม่านหนาและใยแมงมุมที่พันกันอยู่ จนสุดท้ายก็นั่งยองอยู่หน้าหุ่นดิน\nนักวิจัยหญิงนั่งหดตัวอยู่ในมุมห้อง แต่เพียงไม่กี่วัน เธอกลับดูผอมแห้ง ตาไม่มีแสงสว่าง\n「คุณกลับมาแล้ว...เหมือนคนอื่นๆ」\nนักวิจัยหญิงไออย่างอ่อนแรง\n「ใช่...ฉันมาแล้ว」\nคุณยกมือของหุ่นดินขึ้นและจูบมันอย่างต่อเนื่อง\nปลายนิ้วที่เย็นเฉียบสัมผัสที่ลำคอของคุณเบาๆ พร้อมกับความเจ็บปวดเล็กน้อย คุณหลับตาลง\n\nเมื่อคุณตื่นขึ้นมา คุณอยู่ท่ามกลางแสงแดดสีขาวอันอบอุ่น ร่างกายคุณเคลื่อนไหวไปตามคลื่นทะเลที่นุ่มนวล\nคุณรู้สึกเบาสบายอย่างที่ไม่เคยรู้สึกมาก่อน ราวกับว่าจิตวิญญาณของคุณได้ทิ้งร่างกายไว้เบื้องหลัง\nคุณหันหัวไปเห็นหัวกะโหลกสีเทาเข้ม\nพวกมันส่งเสียงร้องไห้ บิดเบี้ยว เหมือนดอกไม้ป่าสีดำที่กระจายอยู่บนทะเลโอริกาลค์สีเทา\n「ไม่——」\nลำคอของคุณอาเจียนออกมาเป็นของเหลวสีดำ คุณไม่สามารถขยับตัวได้อีกต่อไป\nแท้จริงแล้ว คุณได้กลายเป็นส่วนหนึ่งของหัวกะโหลกเหล่านั้นแล้ว\n\n「@2 มิถุนายน นักเล่นแร่แปรธาตุชื่อดัง โรมารีน ลูดวิก ถูกพบว่าเสียชีวิตอย่างแปลกประหลาดในห้องทำงานของเขา โดยที่หัวกะโหลกหายไป และยังมีคู่มือการเล่นแร่แปรธาตุลึกลับที่หายไปพร้อมกัน...」\n\n(เนื้อหาข้างต้นบันทึกไว้ในห้องสมุดมิซากะ เล่มที่สองของ《เรื่องเล่าเกี่ยวกับการเล่นแร่แปรธาตุ》)"
  },
  CollectionHall_127124_Title = {
    Text = "ของสะสมล้ำค่า"
  },
  CollectionHall_127125_Desc = {
    Text = "จนถึงวันนี้ คาสเตอร์ก็ยังไม่สามารถบอกความหมายที่แท้จริงของอิสระได้\nเขามักรู้สึกว่าตนเองเป็นคนที่โง่เขลาที่สุดในคู่แฝด ตั้งแต่เด็กเขาก็ตามหลังโพลลักซ์ไปอย่างงุ่มง่าม ฟังน้องชายพูดถึงความคิดสร้างสรรค์ที่แปลกประหลาดมากมาย\nในชีวิตการฝึกฝนที่น่าเบื่อและชา เขาคิดว่าการมีสีสันที่เบาสบายเช่นนั้นคือความสุขที่สุด จนกระทั่งจูเลียตสั่งให้ทำพิธีปรับปรุงโพลลักซ์เป็นระยะๆ\nความเจ็บปวดอันไม่มีที่สิ้นสุดทั้งหมดตกอยู่ที่โพลลักซ์คนเดียว คาสเตอร์รู้สึกสับสนและไม่รู้จะทำอย่างไรอยู่ข้างๆ น้องชาย มองดูใบหน้าที่เคยสดใสของเขาหายไปพร้อมกับรอยยิ้มที่น้อยลงเรื่อยๆ ขณะที่เขาคิดไม่ออกว่าจะทำอะไรได้บ้าง\n「เธอรู้ไหมว่าอิสระหมายถึงอะไร?」ในยามค่ำคืน โพลลักซ์ถือหนังสือที่ทั้งคู่พลิกอ่านจนขาดมือ ถามคาสเตอร์อย่างเงียบๆ\nคาสเตอร์ส่ายหัว\n「ถ้าอย่างนั้น เธออยากจะออกไปดูโลกข้างนอกไหม? พี่ชาย」\nคาสเตอร์รู้สึกตัวแข็งทื่อ เขาเหมือนเข้าใจในสิ่งที่โพลลักซ์ต้องการตามหา สิ่งที่เขาไม่เคยเห็น มีอยู่ในตัวอักษรที่เหี่ยวเฉา และมีอยู่ในจินตนาการของเขา\nเขารู้สึกตกตะลึงกับความคิดที่แสนจะผิดที่ผิดทางและน่าตกใจนี้ เขานิ่งเงียบไป อาจจะนานมาก หรืออาจจะเพียงแค่ไม่กี่ลมหายใจ เขาก็พยักหน้าโดยไม่มีความกลัว\nแม้ว่ามันจะต้องต่อสู้กับทั้งโบสถ์ แม้ว่ามันจะต้องสละชีวิตของเขา\nดังนั้น นกสองตัวจึงบินออกจากกรงที่ไม่เคยออกไป แต่โชคร้ายที่พวกเขาไม่เคยคิดว่าราคาที่ต้องจ่ายของอิสระจะเป็นภาระที่รับไม่ไหว\nเสียงปืนของนักล่าส่งเสียงดังขึ้น นกจึงร่วงลงจากอากาศ\nคาสเตอร์เพิ่งจะได้ลิ้มรสอิสระ ก็เห็นน้องชายของเขาถูกถอนปีกที่บินไปสู่เสรีภาพออกอย่างรุนแรง\nเมื่อเผชิญกับความโกรธที่น่ากลัวของจูเลียต ใบหน้าที่ซีดเซียวและสั่นเทาของน้องชายหันหลังไปให้กับผู้คน แสดงให้เขาเห็นรอยยิ้มที่ไม่เคยยอมแพ้\n「อดทนไว้ เพื่ออิสระ」\nคาสเตอร์คิดถึงริมฝีปากที่ไร้เสียงของโพลลักซ์ซ้ำแล้วซ้ำเล่า จนกระทั่งเขาได้เคี้ยวคำสองคำที่เหมือนกับความเชื่อในความทรมานที่มืดมน เขาจึงได้พบกับโพลลักซ์อีกครั้ง และในเวลานั้นเขาตกใจพบว่าคนที่นำทางเขามาตลอดได้ทิ้งสองคำนี้ไปอย่างไร้ความปรานี。"
  },
  CollectionHall_127125_Title = {
    Text = "อิสรภาพอันหนักอึ้ง"
  },
  CollectionHall_127126_Desc = {
    Text = "ในคืนที่มีพายุฝนฟ้าคะนอง ลูกสาวของพระเจ้านั่งอยู่ตามลำพังใต้หน้าต่างเรือ \n แสงจันทร์เย็นยะเยือกส่องลงบนผ้าห่ม เด็กศักดิ์สิทธิ์ที่ไหลออกมาจากของเหลวสีดำกำลังหลับใหลอยู่ในนั้น \n ลูกสาวของพระเจ้าเริ่มร้องเพลงกล่อมเด็ก \n 「นอนเถอะ นอนเถอะ ลูกน้อยของทะเล」 \n 「เปลของเจ้าคือดวงจันทร์สีดำ」 \n 「ให้ดาวทั้งหมดหลับใหลไปในความฝัน」 \n เสียงเพลงก็เป็นเหมือนคำอธิษฐาน ฝูงปลาในทะเลลึกจึงรวมตัวกัน \n เรือทั้งลำเหมือนกับแท่นบูชาขนาดใหญ่ เหมือนวันนั้นที่เธอให้กำเนิดเด็กศักดิ์สิทธิ์ \n เธอตัดหน้าอกของตัวเอง เอากระดูกและเนื้อที่เปียกโชกออกไป เพื่อชดใช้ความรักที่เลี้ยงดูและชะตากรรมของเผ่าพันธุ์ \n การเสียสละของเธอไม่ได้นำมาซึ่งเสรีภาพที่เธอปรารถนา ความตายไม่ใช่การหลับใหลอย่างเป็นนิรันดร์ แต่เป็นเพียงจุดเริ่มต้นของโศกนาฏกรรม \n ตั้งแต่นั้นมา ความสงบสุขของเธอมีเพียงในยามค่ำคืน \n 「นอนเถอะ นอนเถอะ ลูกน้อยของทะเล」 \n เมื่อเพลงกล่อมเด็กนี้สิ้นสุดลง ราชอาณาจักรที่ยิ่งใหญ่จะทะลุผ่านผิวน้ำทะเล ขึ้นมาจากมหาสมุทรที่เต็มไปด้วยคลื่น \n ในอ้อมกอดของความหวังที่หลอกลวงเช่นนี้ มอร์ฟี่ก็ปิดตาลงอย่างเบาๆ."
  },
  CollectionHall_127126_Title = {
    Text = "การพักผ่อนในความมืด"
  },
  CollectionHall_127127_Desc = {
    Text = "เขาตำหนิตัวเองอยู่เสมอ และใช้การตำหนินั้นผลักไสเพื่อนร่วมทางทั้งหมด เขาคิดว่าเขาจะเดินต่อไปคนเดียวตลอดไป เพื่อไล่ตามความสมบูรณ์แบบของดนตรี\nความสูงทำให้หนาวเหน็บ เขายอมรับชะตากรรมที่ถูกกำหนดไว้\nจนกระทั่งเขาได้ยินการบรรเลงของคนคนนั้น\nการบรรเลงของคนนั้นไม่เกี่ยวข้องกับความสมบูรณ์แบบ ดนตรีที่ทำไปตามอารมณ์เหมือนกับตัวเขาเอง บางครั้งจะมีข้อผิดพลาดในการเล่นที่แตกต่างจากโน้ตเพลง และบางครั้งก็จะลืมบางส่วนไปเลย ในช่วงเวลานั้น มือของเขามักจะเล่นโน้ตที่มีชีวิตชีวาและชาญฉลาดออกมา ทำให้ผู้คนในห้องประหลาดใจและชื่นชม\nเขาจ้องมองไปที่คนนั้น ราวกับมองเห็นวิญญาณของดนตรีที่กำลังเล่นสนุกอยู่ในโน้ตเพลง\nนี่คือสิ่งที่พ่อของเขาเรียกว่าพรสวรรค์แน่นอน เขาถูกดึงดูดอย่างลึกซึ้งเช่นเดียวกับทุกคน แต่เขาไม่สามารถเปลี่ยนทิศทางของเขาได้\nเขาเป็นคนที่ธรรมดาและโง่เขลาเช่นนั้น จึงต้องเดินไปในเส้นทางที่ลำบากนี้\nทุกคนติดตามคนนั้นไป และเขาก็เริ่มห่างออกไปเรื่อยๆ\nเขาปรารถนาที่จะเข้าใกล้เขา แต่เขานอกจากจะเล่นดนตรีก็ไม่รู้จะทำอะไร\nจะพูดคุยกับเขาอย่างไร ใช้โน้ตเพลงแบบไหนถึงจะได้รับความสนใจจากเขา\nเขาจัดทำโน้ตเพลง ราวกับคิดทบทวนคำพูดเปิด\nจนกระทั่งเขาไม่มีโอกาสพูดอีกเลย\nความเสียใจอันหนักหน่วงท่วมท้นเขา ทุกสิ่งทุกอย่างทันใดนั้นก็สูญเสียความหมาย\nในสายตาของเขามีเพียงจดหมายที่ยังไม่เสร็จต้องส่งให้กับวิญญาณที่จากไป\nเขาใช้ความพยายามอย่างมาก สุดท้ายก็ล้มลงต่อหน้าบันทึกโน้ตเพลงนั้น ในความฝันก็ยังไม่ได้สัมผัสกับแสงสว่างที่อยู่ปลายทาง\nถ้าหากฉันถูกกำหนดไม่ให้เดินไปถึงปลายทางนั้น แล้วความมุ่งมั่นตลอดชีวิตของฉันมีไว้เพื่ออะไร?\nมีเสียงขลุ่ยที่ไกลโพ้นดังมาจากแสงสว่างนั้น ปลอบประโลมวิญญาณที่เต็มไปด้วยคำถามของเขา\nในความงุนงงเขาหยิบขลุ่ยขึ้นมา รู้ถึงภารกิจที่แท้จริงของเขา\nใช้การบรรเลงที่ไม่เคยหยุดนิ่งของเขา นำความสงบสุขอันเป็นนิรันดร์มาให้\n"
  },
  CollectionHall_127127_Title = {
    Text = "บทบรรเลงนิรันด์"
  },
  CollectionHall_127128_Desc = {
    Text = "แม้ว่าจะไม่มีความทรงจำในชีวิตช่วงก่อนหน้านั้น แต่จากกล้ามเนื้อที่ไม่ค่อยพัฒนา คุณก็สามารถบอกได้ว่าคุณคงไม่ใช่คนที่รักการออกกำลังกายหรือความรุนแรงมากนัก\nคุณไม่เข้าใจเลยว่าทำไมมาตรฐานการต่อสู้ที่มิซากะตั้งไว้สำหรับนักสืบถึงสูงและครอบคลุมขนาดนี้\nหรือว่านักสืบไม่ควรเน้นไปที่คำว่า \"การสอบสวน\" ไม่ใช่ที่ความฉลาดของสมอง, การคิดอย่างรอบคอบ และโชคดีที่พอเหมาะหรือ?\nทุกครั้งที่ถูกราโมน่าลากออกจากที่นอนในหอพักตรงเวลามาอยู่กลางสนามที่ว่างเปล่าเผชิญหน้ากับการโจมตีที่มาเป็นระลอกๆ คุณก็คิดถึงหลักสูตรตรรกศาสตร์ที่เต็มไปด้วยการเสียดสีของอาจารย์ดอลล์เป็นอย่างมาก แม้ว่าเนื้อหาการบ้านที่มากมายและข้อสอบที่ทำให้คุณผมร่วงจะยังดีกว่าความเจ็บปวดจากการถูกตีและล้มในระหว่างการฝึกต่อสู้\nครั้งที่ 19 คุณถูกดาบแทงที่ปิดกั้นทุกเส้นทางการเคลื่อนไหวบีบให้เสียการทรงตัวและล้มลงไปนั่งบนพื้น รู้สึกเหมือนกระดูกทั้งตัวกำลังจะแตก\nหายใจหอบ คุณเช็ดเหงื่อที่หน้าผากออกอย่างหมดแรง และไม่ยอมลุกขึ้นอีก\nราโมน่าไม่มีสีหน้าที่แปลกใจใดๆ เธอทำท่าทางสวยงามขณะเก็บดาบกลับเข้าที่ ส้นรองเท้าของเธอเสียงดังเปรี้ยงเมื่อเดินเข้ามาหาคุณ คุณหลับตาแน่น ตัดสินใจรับฟังคำตำหนิและการวิจารณ์ทั้งหมด\nอย่างไรก็ตาม ไม่มีการตีหรือด่าใดๆ เกิดขึ้น สามวินาทีต่อมา คุณเปิดตาขึ้น พบเพียงใบหน้าที่ยิ้มแย้มอยู่ใกล้ๆ\nราโมน่าก้มลงเล็กน้อย มือที่สวมถุงมือขาวสะอาดยื่นมาให้คุณ\n「จริงๆ แล้วคุณก็พยายามมากแล้ว ฉันรู้ แต่สิ่งที่เราต้องเผชิญคือความกลัวและอันตรายที่ไม่รู้จักเสมอ แม้แต่ฉันเองก็มีช่วงเวลาที่ไม่สามารถคาดการณ์ได้」\n「ถือว่าเพื่อให้ฉันสบายใจสักหน่อย มาลองอีกครั้งเถอะ คู่หู」"
  },
  CollectionHall_127128_Title = {
    Text = "การฝึกทรงพลัง"
  },
  CollectionHall_127129_Desc = {
    Text = "มนุษย์เป็นสิ่งมีชีวิตที่ชื่นชอบการร้องเพลง สำหรับชาวดาวร้างก็เช่นกัน\nท่วงทำนองพลั่งพรูออกมาจากลำคออย่างอิสระ โดยปราศจากความตั้งใจหรือเป้าหมายใด\nมันถูกสายลมพรากออกเป็นโน้ตที่กระจัดกระจาย และเหี่ยวเฉาลงพร้อมกับอารมณ์\nว่ากันว่า ในทะเลทราย ทุกเผ่าพเนจรต่างมีบทเพลงเป็นของตนเอง\nแต่ชาวดาวร้างได้ทิ้งบทเพลงของตนเองไว้\n\nพร้อมกับบทเพลงที่หล่นหายไป ชื่อก็หายไปด้วย\nไม่มีใครล่วงรู้ชื่อเดิมของดาวร้าง\nนี่คือดาวที่ถูกสาป พิษภัยแห่งความแห้งแล้ง พายุ และความอดอยาก...\nภัยพิบัติต่าง ๆ ปรากฏตัวอย่างไม่ขาดสาย จนกระทั่งดาวร้างพังทลายลงโดยสิ้นเชิง\nเหล่าผู้อยู่ระดับสูงในเสื้อผ้าหรูหราหนีไปกับเรืออพยพ ดาวร้างกลายเป็นดาวที่รกร้างสมกับชื่อ มีเพียงผู้คนชั้นล่างที่ไร้พรเท่านั้นที่หลงเหลืออยู่\nพวกเขาทั้งหมดถูกทอดทิ้ง\n\nนับแต่นั้นมา ชาวดาวร้างตัดสินใจว่าพวกเขาไม่ต้องการเสียงหัวเราะ ไม่ต้องการบทกวี และก็ไม่ต้องการบทเพลง\nพวกเขาจะจดจำความทุกข์และความเจ็บปวดของการถูกทอดทิ้ง คืบคลานไปมาทั่วทะเลทรายขาวซ้ำแล้วซ้ำเล่า จนถึงวันที่ดาวเคราะห์ถูกทำลาย。"
  },
  CollectionHall_127129_Title = {
    Text = "บัลลาดพันธนาการ"
  },
  CollectionHall_127130_Desc = {
    Text = "ส่วนใหญ่แล้ว ความตายมักมาเยือนอย่างเงียบงัน ในขณะที่จิตสำนึกของมนุษย์ยังไม่ทันได้ตอบสนอง เทพแห่งความตายก็คืบคลานเข้ามาอย่างเงียบเชียบและพรากชีวิตอันเปราะบางไป\n\nอย่างไรก็ตาม มีเรื่องเล่าขานว่าท่ามกลางทะเลทรายที่ไม่มีใครรู้จัก มีเทพแห่งความตายสีอำพันอยู่คนหนึ่ง นางจะประกาศคำทักทายก่อนที่จะนำพาความตายสีอำพันมาด้วยเปลวไฟของอำพันและปืนสีอำพัน\n\nชายคนหนึ่งยืนอยู่บนทะเลทรายใต้แสงจันทร์ มือที่ถือปืนนั้นสั่นไหวไม่หยุด ตาของเขาจ้องแน่วแน่ไปที่ร่างสีอำพันของเคทีกูล่า ไม่กล้าแม้แต่จะละสายตาแม้เพียงเสี้ยววินาที\n\nเหงื่อเย็นหยดจากหน้าผากของเขาและทำให้หัวใจของทุกคนเบื้องหลังรู้สึกสั่นไหว แม้จะเป็นคนจำนวนมากที่เขาพามา แต่ในตอนนี้กลับไม่เป็นประโยชน์เลยสักนิด\n\nเขาไม่เข้าใจ ทั้งที่การปล้นคลังสินค้าแห่งนี้ซึ่งปราศจากผู้คนก็เเค่ภารกิจธรรมดาสำหรับเขา เหตุใดถึงได้เจอกับเทพแห่งความตายที่เล่าขานในตำนานเช่นนี้\n\n「เจ้าว่าเทพแห่งความตายนั่น? เป็นแค่ข่าวลือที่น่าเบื่อก่อนหน้านั้นเอง」  \nเคทีกูล่ากล่าวอย่างไม่ใส่ใจ\n\n「ครั้งหนึ่งเคยทาสีมันเป็นสีอำพัน อาจจะยังพบคราบสีเล็กน้อยที่ยังไม่หลุดออกมาได้บ้าง」  \nนางแสดงปืนคู่ในมือของนางออกมาอย่างใจเย็น\n\n「เปลวไฟสีอำพันที่ปากกระบอกปืนนั้นเกิดจากสารพิเศษบางชนิด」  \nนิ้วของนางแทรกเข้ามาในช่องปืน หมุนหนึ่งรอบก่อนที่จะดึงผงบางอย่างที่ไม่สามารถระบุได้ออกมา\n\n「เทพแห่งความตายที่ว่า เป็นแค่ภาพที่ข้าปั้นแต่งขึ้นในอดีต」  \n「มันทั้งแกร่ง ลึกลับ และไร้ขีดจำกัด」\n\n「มันช่วยขู่พวกคนอ่อนแอไร้ค่าให้เกรงกลัวได้」  \nนางกล่าวออกมาอย่างหยิ่งผยอง ไม่สนใจสายตาอันดุดันของชายที่อยู่ตรงหน้าเลยแม้แต่น้อย\n\nนางพูดอย่างไม่แยแส โดยไม่รู้สึกถึงอันตรายที่เริ่มเข้ามาใกล้\n\nเมื่อกระสุนเริ่มพุ่งเข้าหานาง ดวงตาของนางปรากฏความตกตะลึงและสับสนขึ้น  \nทั้งหมดนั้น เพียงเพื่อปกปิดความตื่นเต้นและความบ้าคลั่งที่ฝังลึกในจิตใต้สำนึกของนางเท่านั้น\n\n…………………………\n\nเสียงปืนสงบลง ทุกอย่างเป็นไปตามที่นางคาดไว้  \nนางยืนอยู่กลางสนามรบ ทุกสิ่งรอบตัวเต็มไปด้วยร่องรอยของเปลวไฟ\n\nเคทีกูล่าทำเพียงแค่สองสิ่ง——ยกปืน เล็งยิง  \nเมื่อใดที่นางยกปืนยาวขึ้นมา เทพแห่งความตายจะเริ่มเต้นรำอยู่เบื้องหลังทุกสิ่ง และมอบหมายลางแห่งความตายมาอย่างเท่าเทียม\n\nเมื่อใดที่นางเหนี่ยวไก เปลวไฟจะลุกลามทุกสิ่ง พานำสวนดอกไม้สีอำพันมาให้โลกได้ยล\n\n「มันเคยร่วมทางกับข้ามานับปีและได้เห็นเลือดและความตายมานับไม่ถ้วน」  \n「มันเคยถูกบังคับให้สวมหน้ากากแห่งคำลวง เพื่อปกปิดความอ่อนแอของข้า」\n\n「แต่บัดนี้ มันจะไม่เป็นเพียงข่าวลืออีกต่อไปแล้ว」"
  },
  CollectionHall_127130_Title = {
    Text = "ความตายสีอำพัน"
  },
  CollectionHall_127131_Desc = {
    Text = "「คุณเสียใจไหม?」\nจากโถแก้วที่ประดับประดา เทพเจ้าผู้โบราณได้สูดดมเธออย่างแผ่วเบา ล่องลอยไปบนบ่าเธอ เปิดหน้าต่างส่งลมเย็นที่มาพร้อมกับกลิ่นหอมอ่อนๆ ในยามค่ำคืน\n「เมื่อฉันขมวดคิ้ว ไฟป่าในกำแพงเมืองก็จะลุกโพลง เมื่อฉันยิ้มแย้ม น้ำไหลรอบด้านก็จะนำของมีค่าและสัตว์แปลกมา รวมถึงน้ำผึ้งและอาหารเลิศรส ฉันคือสมบัติที่มีค่าที่สุดในราชอาณาจักรทั้งมวล ทำไมฉันจะต้องเสียใจล่ะ?」\nเธอหน้าแดงเพราะเมามายเล็กน้อย หัวเราะคิกคักและนอนอยู่บนเตียงนุ่มที่ทำจากไหมและหนังสัตว์\n...\n「คุณเสียใจไหม?」\nเทพเจ้าผู้โบราณที่ติดอยู่บนควันธูปได้สนทนากับเขา ควันบางๆ ไหลลงจากชั้นล่าง รูปทรงของดอกไม้ที่บานออกอย่างช้าๆ\n「พวกเขาต่อสู้กันจนหัวหมุน ในขณะที่ฉันนั่งเฉยๆ และได้ประโยชน์จากมัน ยิ่งปีนสูงยิ่งตกได้หนัก ใครจะเหมือนฉัน มีทุกอย่าง ไม่มีใครที่ควรจะเสียใจ」\nเขายิ้มแย้มและเติมเหล้าในขันอีกครั้ง มือกวาดไปตามกิ่งอ่อนที่อยู่ใกล้ๆ เสียงของแมลงในกรงดังสนั่น\n...\n「คุณเสียใจไหม?」\nเทพเจ้าผู้โบราณที่ปีนออกมาจากบ่อน้ำหัวเราะเบาๆ ขณะที่หมอกล้อมรอบเส้นผมของเธอ ทำให้ดอกมะลิขาวอวบตกลงจากกิ่ง\n「ฉันมีความรัก มีความผูกพัน มีข้าวต้มร้อนเมื่อกลับบ้านในยามพระอาทิตย์ลับขอบฟ้า และมีไวน์ที่ดีเมื่อรวมตัวกัน ฉันจะเสียใจได้อย่างไร ฉันแน่นอนว่าไม่เสียใจ」\nเธอหยิบดอกไม้ขึ้นมาแนบที่ขมับ แสงเทียนอุ่นๆ สั่นไปตามชายกระโปรงของเธอ สายตาของเธอติดอยู่ที่ขอบหน้าต่าง มองไปยังคนที่เธอรอคอย\n...\n「คุณเสียใจไหม?」\nกระโปรงที่หนีอย่างยุ่งเหยิงเปื้อนดินสกปรกหน้าประตูพระราชวัง เหล่าการ์ดที่เคยอ่อนน้อมเมื่อวานนี้เหมือนไม่ได้ยินเสียงร้องไห้และขอความช่วยเหลือของเธอ ดาบสองเล่มเย็นเฉียบตัดขวางลงมา ปิดกั้นเส้นทางเดียวที่เธอเหลืออยู่\nหมอกถอนหายใจอย่างเบาๆ และแล้วดอกบ๊วยสีแดงก็เบ่งบานในหิมะ จากนั้นก็ถูกหิมะอีกครั้งกลบไปอย่างสิ้นเชิง\n...\n「คุณเสียใจไหม?」\nไข่มุกจากกล่องไม้จันทน์ร่วงกระทบกับอิฐสีฟ้า เสียงที่แตกหักของของมีค่าที่ตกลงสู่พื้นกลับไพเราะกว่าทุกครั้งที่เคยได้ยินจากเครื่องดนตรี\nภาพเขียนที่เขารักมากที่สุดซึ่งเขาชื่นชมทุกวันกลิ้งตกลงมาที่พื้น มือวาดที่เก่งกาจได้ฉีกเส้นทางธรรมชาติออกไป เหมือนกับไฟสงครามที่เขามองไม่เห็นทำลายแผ่นดินและบ้านเมือง\nหมอกล้อเลียนล้อมรอบ และแล้วไฟก็ลุกโชน ทำให้เสาและเพดานประดับตกลงไปกลายเป็นเถ้าถ่านของอดีต\n...\n「คุณเสียใจไหม?」\nเจ้าของชื่อที่เธอเรียกอยู่บนลิ้นไม่กลับมาอีกแล้ว โครงกระดูกที่ริมแม่น้ำไกลออกไป บนหมอนของนางคนงาม\nเขากลายเป็นพระราชาและเจ้าสาวของเจ้าหญิง? เขาใช้เวลาสิบปีในดอกไม้โดยไม่กลับ? เขาถูกกลืนกินโดยคนจนเป็นอาหารหลังภัยพิบัติ?\nหมอกเสียงต่ำและคลุมเครือ แต่ไม่เคยให้คำตอบที่เธอถามอย่างเจ็บปวด\n\nสมบัติที่มีค่าที่สุดในช่วงรุ่งเรืองของราชอาณาจักร จะกลายเป็นสมบัติที่มีค่าที่สุดในช่วงล่มสลายของราชอาณาจักร\nลูกหลานที่มีความสุขที่สุดในช่วงรุ่งเรืองของครอบครัว จะกลายเป็นคนที่ถูกทอดทิ้งที่ดีที่สุดในช่วงตกต่ำของครอบครัว\nและเรื่องราวสุดท้าย ที่โลกนี้มีมากมายเหลือเกิน."
  },
  CollectionHall_127131_Title = {
    Text = "ขมวดคิ้วอย่างเสียเปล่า"
  },
  CollectionHall_127132_Desc = {
    Text = "เมฆมืดครอบคลุมอยู่เหนือเมืองลอนดีเนี่ยน ปิดกั้นแสงจันทร์ เสียงระฆังในยามเที่ยงคืนดังขึ้นแล้ว ปล่องควันสูงยังคงพ่นควันดำร้อนและไอน้ำออกมา หิมะที่สัมผัสกับฝุ่นในสายลม ยังไม่ถึงพื้นก็ถูกทำให้มีสีเทาอ่อน มันปลิวไปมาลงบนเสาไฟ ถนนสว่างร้อน ทำให้มันละลายแทบจะในทันที และหยดลงบนเด็กหญิงที่เดินผ่านมา\nเด็กหญิงสวมชุดสีน้ำตาล แขนเสื้อที่ใหญ่เกินไปถูกม้วนขึ้นอย่างหยาบๆ เผยให้เห็นแขนที่ผอมบาง เธอวิ่งอย่างยากลำบาก บางครั้งต้องดึงแขนเสื้อขึ้น พยายามตามผู้หญิงที่เดินอยู่ข้างหน้า\nผู้หญิงหันไปมองเด็กหญิง แล้วพูดว่า：「ทำตัวให้เร็วหน่อย อย่าคิดว่าถ้าคุณเดินช้าแล้วจะไม่ต้องไป。」\n「ค่ะ คุณแม่，」เด็กหญิงรีบวิ่งไปข้างๆ ผู้หญิง ขณะพูดหายใจหอบ，「ขอโทษค่ะ คุณแม่。」\n「อย่าชื่อเรียกฉันว่าแม่!」ผู้หญิงจับแขนเด็กหญิงแล้วดึงให้เธอเดินเร็วขึ้น，「เป็นขยะดูดเลือด ถ้าไม่ใช่เพราะคุณ ฉันจะไม่ต้องตกต่ำมาถึงที่น่าเบื่อนี้。」\n「ขอโทษค่ะ……」\n「เงียบไปเถอะ ของไม่มีค่า」 เล็บของผู้หญิงจิกลงที่แขนเด็กหญิง ทำให้เกิดรอยลึก，「ฉันบอกคุณแล้ว จากนี้ไปโรงงานจะเป็นบ้านของคุณ อย่าคิดว่าจะออกมาหาฉัน ฉันไม่อยากเห็นคุณแม้แต่ตายก็เถอะ ได้ยินไหม?」\n「ฉัน……ฉันรู้แล้ว。」เด็กหญิงก้มหน้าลง น้ำตาที่หล่นถูกเท้ากระทบหายไปกับน้ำหิมะสกปรกบนถนนหิน ด้านไกลโรงงานส่งเสียงหวูดหมดเวลาทำงาน แมวป่าตัวหนึ่งวิ่งผ่านตรอก เสียงที่เบาๆ หายไปในเสียงเท้าของทั้งสองคน พวกเธอเลี้ยวโค้งไปตามถนน ผ่านหลังบ้านที่แขวนเสื้อผ้าและมีกลิ่นชื้น สุดท้ายหยุดอยู่หน้าตึกที่มีประตูเหล็ก\n「คุณรอที่นี่ก่อน，」เสียงของผู้หญิงนิ่งมาก แม้กระทั่งมีอาการเฉยเมย，「เมื่อฟ้าสว่าง คนในนั้นจะออกมา พวกเขาจะรับคุณไว้\nอย่าตามมานะ ไม่งั้นคุณจะเห็นว่าฉันจะฆ่าคุณไหม。」\nผู้หญิงหันหลังแล้วจากไป รูปร่างที่ผอมบางและดูเหมือนจะโก่งกลับหายไปในความมืด เด็กหญิงยืนอยู่ด้วยความสิ้นหวัง กำมือของตัวเอง ขณะมองไปที่ที่ผู้หญิงจากไป ใช้แขนเสื้อเช็ดน้ำตาบนใบหน้า\nแสงไฟสีเหลืองจากด้านหลังปรากฏขึ้น ยืดประตูเหล็กและเงาของเธอออกไป มือหนึ่งตกลงบนไหล่ของเด็กหญิง ทำให้เธอตกใจ\n「เด็กน่าสงสาร ทำไมถึงอยู่คนเดียวที่นี่?」ผู้มาใหม่เป็นสตรีสาว สวมชุดที่เหมือนแม่ชี，「มาเถอะ น้องซาร่า จะพาเธอเข้าไป เดี๋ยวก็จะไม่หนาวแล้ว。」"
  },
  CollectionHall_127132_Title = {
    Text = "ความทรงจำในคืนฤดูหนาว"
  },
  CollectionHall_127133_Desc = {
    Text = "「ผลงานของฉันเหรอ? อืม——สงสัยจังเลยนะ โอเคๆ เพราะเป็นคำขอของ VVIP แต่การเล่าเรื่องธรรมดามันไม่เข้ากับชื่อเสียงของฉันในฐานะมาสเตอร์มายากลเลย ให้ฉันใช้การแสดงที่ยิ่งใหญ่มาแสดงให้คุณเห็นเถอะ! \nมา มา มา กรุณานั่งในที่นั่งวีไอพีของคุณ การแสดงความทรงจำเวทมนตร์ที่เต็มไปด้วยเงินและการทรยศกำลังจะเริ่มต้น!」\n-------\nเสียงดีดนิ้วดังขึ้น ไฟสว่างขึ้น หมวกมายากลของคาเซียห์ลอยอยู่กลางอากาศ ปากหมวกสีเหลืองเปิดปิด และมีเสียงของคาเซียห์ดังออกมา \n「ไม่นานมานี้ ในที่ที่ไม่ไกลนัก มีคณะละครสัตว์ คณะละครสัตว์ที่มีกระต่าย ตัวตลก สิงโต ช้าง——」\nขณะที่หมวกสั่น กระต่าย ตัวตลก สิงโต และช้างก็ตกลงมาจากข้างใน เสียงกลองเริ่มดังขึ้นเรื่อยๆ พร้อมกับเสียงปืนใหญ่ที่ระเบิดขึ้น คาเซียห์ในชุดละครที่หรูหราก็โผล่ออกมาจากหมวก และสวมหมวกกลับไปที่หัวของเธอ \n「สิ่งที่สำคัญที่สุดคือ มีนักเรียนมายากลที่มีพรสวรรค์และความสามารถโดดเด่น!」\n-------\nการเติบโตของนักเรียนมาพร้อมกับเสียงปรบมือ และยังสามารถดึงดูดนักลงทุนที่แต่งตัวหรูหราได้อย่างน่าประหลาดใจ แต่แปลกมาก ตั้งแต่นักลงทุนเดินทางไปกับพวกเขา กระต่าย ตัวตลก สิงโต ช้าง……หลายคนและสัตว์ก็หายไปทีละคน ทีละตัว เวทีว่างเปล่ามากกว่าครึ่ง นักเรียนกลับไม่รู้สึกอะไร เธอยังคงทำชีวิตตามปกติ จนกระทั่งนักลงทุนยื่นแก้วไวน์ให้เธอ \nนักเรียนดื่มไวน์และหมดสติไป เวทีจึงมืดสนิท และเสียงถอนหายใจเบาๆ ก็ลอยออกมาจากความมืด \n「นั่นคือครั้งแรกที่ฉันเข้าใจความเสียใจ」\n-------\n「แต่ความเสียใจมันไม่พอหรอกเหรอ? ฉันยังอยากรู้ว่าความรู้สึกเมื่อผู้สนับสนุนร้องไห้เป็นอย่างไร ความรู้สึกเมื่อผู้ชมหัวเราะเป็นอย่างไร ฉันอยากรู้มากขึ้น มากขึ้น ในตอนนั้น—— \nฉันลืมตาขึ้น」\nกระดาษฉลองแตกกระจายขึ้นในอากาศ เสี่ยงที่ลอยไปลอยมา คาเซียห์ปรากฏตัวอยู่กลางเวที เธอเคาะที่ขอบหมวก หมวกมายากลเปิดปากออก เปล่งแสงที่เจิดจ้าออกมา \n「ฉันลืมตาขึ้น แล้วพบว่า ทุกอารมณ์คือแสง ทุกอย่างสามารถเก็บไว้ในหมวกมายากลของฉันได้ \nตอนนี้โปรดผ่อนคลายเถอะ ที่รักวีไอพีของฉัน ส่วนถัดไปจะไม่เจ็บเลยสักนิด จะทำให้คุณรู้สึกชาเล็กน้อย รู้สึกว่าชีวิตมันน่าเบื่อหน่ายนิดหน่อย……」"
  },
  CollectionHall_127133_Title = {
    Text = "การแสดงกลแสนสุข"
  },
  CollectionHall_127134_Desc = {
    Text = "คลีเมนไทน์ไม่ใช่เด็กที่แข็งแกร่ง ดังนั้นเมื่อเธอป่วยเป็นโรคประหลาด ถูกความเจ็บปวดและความตายที่ใกล้เข้ามากระทำทารุณ เธอมักจะตื่นขึ้นในเวลากลางคืนและร้องไห้เงียบๆ \n และทุกครั้งที่ร้องไห้ในวันถัดไป จะมี「ของขวัญ」ปรากฏอยู่ที่หัวเตียงของเธอ \n ขนมหวานห่อหรูหราหลายชิ้น, อุปกรณ์เสริมผมสุดฮิตในขณะนั้น, หมีขนฟูที่น่ารักน่าเอ็นดู... \n แต่สิ่งที่ทำให้เธอประทับใจที่สุด คือ ตัวอย่างดักแด้ \n ในช่วงเวลานั้น เธอป่วยหนักมาก ไม่สามารถลุกจากเตียงได้ ต้องพยายามยกตัวอย่างนั้นขึ้นไปในอากาศ มองดูชีวิตที่อยู่ภายในดักแด้ที่มีแสงส่องผ่าน \n ชีวิตนั้นหลับใหลแล้ว แต่ชีวิตนั้นก็ได้รับความเป็นนิรันดร์ \n และเธอใกล้จะถึงความตายที่แท้จริง \n คิดถึงตรงนี้ น้ำตาของเธอไหลออกมาอย่างเงียบๆ แต่มีมือหนึ่งเช็ดน้ำตาให้เธอ \n 「อย่าร้องไห้ คลีเมนไทน์ สักวันหนึ่ง เธอจะเหมือนกับดักแด้เหล่านี้ ได้รับชีวิตใหม่」 \n 「ฉันจะทำให้เธอได้รับชีวิตใหม่」 \n พ่อของเธอไม่เคยโกหก อย่างน้อยก็ไม่เคยโกหกกับเธอ ดังนั้นคลีเมนไทน์จึงเชื่อมั่นในคำพูดนี้ \n เธอเชื่อมั่นในพ่อของเธอ ดังนั้นเมื่อเข้าสู่อาณาเขตของภูเขาที่ถูกดูหมิ่น เธอจึงไม่ลังเล และเมื่อเธอทนทุกข์กับความเจ็บปวดจากการละลายของเนื้อและเลือด เธอก็ไม่มีคำบ่นใดๆ \n เพราะเธอเชื่อว่าทุกสิ่งเป็นราคาที่ต้องจ่ายและกระบวนการที่จำเป็นสำหรับการได้รับชีวิตใหม่ \n เมื่อความเจ็บปวดและความสิ้นหวังทั้งหมดผ่านพ้นไป เธอจะหายดี จะกลับไปยังที่ที่เรียกว่า「บ้าน」และรวมตัวกับคนที่เป็นญาติคนเดียวของเธอ。"
  },
  CollectionHall_127134_Title = {
    Text = "ความทรมานที่เลือนหาย"
  },
  CollectionHall_127135_Desc = {
    Text = "เธอไม่เคยฝันเลย。\n\nนักเรียนประติมากรสาวเชื่อมั่นในเหตุผลและระเบียบอย่างเด็ดขาด เช่นเดียวกับผลงานที่เย็นชาของเธอ。\nตั้งแต่แรกที่เห็นมัน เธอก็ถูกดึงดูดเข้าไป。\nนุ่มนวลและบริสุทธิ์——นั่นคือวัสดุสำหรับการระบายสีที่สมบูรณ์แบบ。\nเธอทำงานอยู่ใต้แสงจันทร์ นำสารเหนียวสีดำจากสุสานกลับไปยังสตูดิโอ。\n\nสัปดาห์ต่อมา ประติมากรรมที่ชื่อว่า《@2》ถูกนำไปแสดงในงานนิทรรศการ。\nในคืนนั้น เธอได้ยินเสียงคลื่นจากทางไกล。\nนี่คือครั้งแรกที่เธอได้ฝัน。\nในแสงเช้าที่เงียบสงบ พระราชวังใต้ทะเลที่เต็มไปด้วยฝุ่นกำลังหลับใหล。\nเธอเดินผ่านแนวปะการังสีขาว หายใจเอาความเหงาและกลิ่นของการลืม。\n\nเมื่อเธอตื่นขึ้น มือของเธอกำลังหดตัวและเปลี่ยนเป็นสีดำ สุดท้ายก็มีปะการังสีขาวงอกออกมา。\nเธอได้กลิ่นซ้ำแล้วซ้ำเล่า รู้สึกถึงเสียงกระซิบจากยุคโบราณของสิ่งมีชีวิตนับไม่ถ้วน。\nนั่นคือฟอสซิลที่แท้จริงและนุ่มนวล。\nเธอหัวเราะอย่างประหม่า——นี่คือการฝันจริง ๆ นี่เอง。\nเธอขังตัวเองในสตูดิโอและเริ่มสร้างสรรค์อย่างลืมตัว。\nการหล่อ การปั้นด้วยดิน การระบายสี……\nโกลาหลและมีระเบียบ ไม่มีชีวิตชีวาและมีชีวิตชีวา。\n\nเธอจะฝันตลอดไป。"
  },
  CollectionHall_127135_Title = {
    Text = "อวสานมิสคอรัล"
  },
  CollectionHall_127136_Desc = {
    Text = "แม่。แม่。\nมอร์ฟี่ได้สูญเสียความทรงจำส่วนใหญ่ที่เกี่ยวข้องกับเธอไปแล้ว\nมีคนบอกว่า แม่ที่ใกล้ตายกำลังปกป้องเธอ เลือดไหลเข้าคอของเธอ\nจากนั้นผู้คนก็วิ่งเข้ามาและแยกพวกเธอออกอย่างหยาบคาย\nในช่วงเวลานั้น มอร์ฟี่เห็นใบหน้าของแม่ ใบหน้านั้นเต็มไปด้วยความคลั่งไคล้ แต่กลับสวยงาม\nหลังจากที่เริ่มบันทึกเรื่องราว เธอก็มี 「แม่」 คนใหม่\nอ่อนโยน ระมัดระวัง เธอจะตอบสนองความต้องการที่ไร้เหตุผลทั้งหมดของมอร์ฟี่ แต่ยังคงรักษาระยะห่างที่ไม่ใกล้ไม่ไกล\nเมื่อมอร์ฟี่คิดว่าความสัมพันธ์ของพวกเขาจะเป็นเช่นนี้ตลอดไป เช่นเดียวกับสีหน้าของมิเรียมที่ไม่เคยเปลี่ยนแปลง เธอก็ถูกยกขึ้นไปบนบัลลังก์ที่มืดมิด และในความฝันเห็น 「ไข่」 ที่เปล่งแสงฟอสฟอเรสเซนท์\nมันเปล่งประกายในความมืดเหมือนดวงตาและเหมือนดวงดาว เสียงเพลงที่ล่องลอยอยู่รอบๆ สถานที่ศักดิ์สิทธิ์:\n<Italic:จากลูกสาวของเขา @1 เทพเจ้าของ @1 ได้ปรากฏตัว@1......>\nเธอได้รับมอบหมายภารกิจอันยิ่งใหญ่ที่เกี่ยวข้องและไม่เกี่ยวข้องกับเธอ: การเป็นแม่ที่ทำให้เทพเจ้าฟื้นคืนชีพ\nแปลกจริงๆ เธอยังไม่เข้าใจว่าแม่คืออะไร ลูกสาวคืออะไร แต่ต้องเริ่มเรียนรู้การเป็น 「แม่」\nมอร์ฟี่นึกถึงใบหน้าที่สวยงามและคลั่งไคล้นั้น นึกถึงรสชาติที่หวานและขมอยู่บนปลายลิ้น\nคนสวยคนนั้นไม่ต้องการให้ฉันตกลงไปในหลุมศพเช่นนี้ใช่ไหม?"
  },
  CollectionHall_127136_Title = {
    Text = "อุบัติเร้นลับ"
  },
  CollectionHall_127137_Desc = {
    Text = "เรื่องราวเกี่ยวกับวันดามีมากมายในหมู่บ้านแคมบริอัน\n\nมีคนบอกว่าเขาเห็นวันดานั่งอยู่บนหินขนาดใหญ่ตกลงสู่ริมทะเลสาบ\nมีคนบอกว่าเธอเป็นฟาโรห์หญิงจากเลมวาฮิ ที่เขาเคยเห็นหนามสันหลังเหมือนกันจากมัมมี่\nยังมีคนบอกว่าเธอเป็นดัชเชสจากที่ราบฟราน หลังจากฆ่าสามีสี่คนติดต่อกัน จึงได้รับมรดกอันมหาศาล\n……\n\nข่าวลือกระจายไปเหมือนสายลม ชาวบ้านยังคงทำการเกษตร ทอผ้า และบดข้าว\nในช่วงเวลาที่ยากลำบากนั้น ภาษีหนักเป็นดาบคมที่แขวนอยู่เหนือศีรษะ ตัดทุกกิ่งก้านและความคิดที่เกิดขึ้น\nแต่……ทุกครั้งที่เดินผ่านบริเวณที่พระราชินีอาศัยอยู่ เสียงดนตรีที่แฝงอยู่ในป่า กลับดึงดูดใจทุกคนได้อย่างง่ายดาย\nนั่นคือทำนองที่ไม่ควรปรากฏที่นี่\nมันมีความสุขเกินไป มีความเฉื่อยชามากเกินไป จนดูเหมือนชั่วร้าย เหมือนการกระซิบของปีศาจ\n\n「มาเถอะ ทิ้งทุกสิ่งไว้」\n「พระราชาผู้มีเมตตานั่งอยู่กลางทะเลสาบ รอการรับใช้จากบ่าวตาบอด……」\n\nดังนั้น ในคืนที่ไม่มีลม ชาวบ้านที่เหนื่อยล้าจึงวางเครื่องมือการเกษตรตัดสินใจที่จะตอบสนองความอยากรู้อยากเห็นที่แอบหนี\nเขาเดินอ้อมป่า ข้ามสะพาน ถนนสองข้างเต็มไปด้วยดอกไม้บาน เขาไม่แม้แต่จะมอง\nเขาเห็นทะเลสาบสีเขียว\nมันเชื่อมต่อกับท้องฟ้าที่ต่ำลง มีปราสาทโบราณตั้งตระหง่านอยู่ที่ขอบ\n\nพระราชินีที่สวมมงกุฎหนามนั่งอยู่กลางทะเลสาบ รอคอยประชาชนที่มาแสวงบุญอย่างอดทน\nเธอยื่นมือออกไป เพลิดเพลินกับการจูบและการเคารพจากมนุษย์\nเมฆดำกระจายออกไป พระจันทร์เต็มดวงขึ้น\nพระราชินีใช้หนามสันหลังแทงเข้าไปที่หลังของเขา\nของเหลวที่ทำให้ชาไหลเวียนไปตามหลอดเลือด เขาคุกเข่าลงบนพื้น ถูกตัดแขนขาและถูกขุดตาออก\n\nจากนั้น แรงดึงดูดที่หนักหน่วงจากพื้นดินไม่สามารถดูดซับเขาได้อีกต่อไป บทกวีและความฝันทั้งหมดของเขาผูกติดอยู่กับพระราชินี\nเข finally ต้อนรับชะตากรรมของตนเอง。"
  },
  CollectionHall_127137_Title = {
    Text = "ราชโองการของราชินี"
  },
  CollectionHall_127138_Desc = {
    Text = "「ผู้ที่ทำสมาธิตลอดทั้งวัน ขอให้ของขวัญนี้ช่วยให้จิตวิญญาณของท่านอบอุ่น ขอให้ความรักของพระบิดาช่วยปลอบโยนความเจ็บปวดในใจของท่าน และนำพาความฝันอันหวานหอมมาให้ท่าน.」\nค่ำคืนที่เต็มไปด้วยน้ำค้างกำลังจะสิ้นสุดลง เปลวไฟของเทียนไขกำลังต่ำลง ซัลวาดอร์ได้วางแผ่นหินหนักที่ถูกเก็บไว้เป็นเวลานานลง และถอดเสื้อคลุมที่ดูเคร่งขรึมออก เปลี่ยนเป็นชุดขนสัตว์สีแดงที่อบอุ่น เพื่อเตรียมตัวสำหรับเทศกาลฤดูหนาวในวันพรุ่งนี้ เขาได้ไปที่ร้านของดาฟเดลเพื่อเตรียมเซอร์ไพรส์สำหรับนักเรียนของมิสซาเก้.\n「นี่คือของขวัญชิ้นสุดท้ายแล้ว...」\nซัลวาดอร์นั่งอยู่บนเก้าอี้เก่าที่มุมของวิทยาเขต และด้วยความเหนื่อยล้าเขาจึงหลับไปโดยไม่รู้ตัว.\nนั้นคือความฝันอันหวานหอม กล่องของขวัญที่อยู่ข้างเท้าไม่รู้ทำไมจึงเปิดออกอย่างเงียบๆ—ขนมปังขิงสี่ชิ้นกระโดดออกมา ดวงตาที่ถูกจุดด้วยน้ำตาลไอซิ่งเปล่งประกาย และกลิ่นของอบเชยและดอกกานพลูหมุนวนในอากาศที่เย็น.\nกลิ่นหอมทำให้ความทรงจำที่ถูกเก็บซ่อนไว้ตื่นขึ้น เขารู้สึกเหมือนกลับไปยังโถงโบสถ์ในวัยเด็ก น้ำตาลที่ละลายอยู่บนปลายลิ้นส่งสัญญาณหวานชื่นมาให้เขา บทสวดที่ถูกทำลายด้วยความเจ็บปวดและโรคระบาดกำลังฟื้นคืนชีพอย่างเงียบๆ ตามกับวงดนตรีที่หวานชื่น.\n...\nในขณะเดียวกัน สี่เงาที่แอบซ่อนเข้ามาใกล้ซัลวาดอร์ที่หลับอยู่.\n「ท่านเจ้าของ...ท่านจะมองพวกเราเป็นเด็กไม่ดีไหม...」\n「ฮ่าฮ่า—ออรีต้าสงสัยเกินไปแล้ว! เร็วเปิดกันเถอะ~ หนึ่ง สอง...ว้าว ขนมปังขิงเยอะจัง!」\n「เธอ เธอ...พูดชื่อออกมาแล้ว ถ้า...พวกเขาจะเกลียดพวกเรา...」\n「ฮิฮิ พวกเราไม่ได้คิดจะขโมยเลยนะ! เป็นความผิดของบรูนนี่ทั้งนั้น!」\nซัลวาดอร์ได้ยินเสียงขนมปังขิงพูดคุยกันอย่างมีชีวิตชีวา รู้สึกถึงขนมปังขิงชิ้นหนึ่งกระโดดขึ้นมาที่ตัก กลิ่นอบเชยสัมผัสไปที่หลังมือที่เต็มไปด้วยรอยยับของเขา.\nไม่ ไม่ใช่ขนมปังขิงในความฝัน แต่เป็นเด็กๆ ที่ซุกซนในโลกแห่งความจริง ซัลวาดอร์สามารถจินตนาการถึงรอยยิ้มแห่งความสุขที่เด็กๆ มีเมื่อพวกเขาแอบเปิดกล่องของขวัญ เพื่อช่วงเวลาที่สวยงามนี้ ความสุขและความสงบ เขายินดีที่จะรับทุกข์ทุกอย่าง.\n「โอ้...หนวดของฉัน นี่กำลังเอาหนวดไปพันกับผมอยู่หรือ?」\nซัลวาดอร์ทำเป็นหลับอยู่ต่อไป เพื่อให้เด็กๆ สามารถทำภารกิจ 「ลับ」 ที่สนุกสนานนี้ต่อไปได้."
  },
  CollectionHall_127138_Title = {
    Text = "ความสนุกในกล่อง"
  },
  CollectionHall_127139_Desc = {
    Text = "คุณและราโมน่าไม่เคยนัดพบกันอีกครั้ง.\nในขณะที่ประตูค่อยๆ ปิดลงต่อหน้าต่อตา ขีดจำกัดแห่งการจากลาที่ทั้งสองฝ่ายกำหนดไว้ในใจ ได้กลายเป็นนิรันดร์กาลที่ถูกกำหนดไว้แล้ว.\n\nดังนั้น เมื่อเธอในช่องว่างของกาลเวลา ในการพบกันที่ผ่านมาแล้วก็ผ่านไป ค่อยๆ เกี่ยวนิ้วก้อยของคุณ...\nนี่คือการพบกันอีกครั้งที่เกินความคาดหมาย โชคดีเพียงพอแล้ว.\n「คุณไม่ได้เปลี่ยนแปลงไปเลยแม้แต่น้อย.」เธอกล่าว.\n\nเพื่อคำพูดเพียงประโยคนี้ เพื่อไออุ่นอันแผ่วเบาที่ปลายนิ้ว... แม้จะห่างกันสองโลก คุณก็ยังยินดีทุ่มเทสิ่งทั้งปวง บินข้ามทางช้างเผือกเพื่อพบกับเธอ.\nวันนี้ของปีหน้า เกี่ยวนิ้วสาบาน."
  },
  CollectionHall_127139_Title = {
    Text = "เราจะได้พบกันอีกครั้งแน่นอน"
  },
  CollectionHall_127140_Desc = {
    Text = "「ถอยกลับ ถอยกลับ!」\n「ไปที่@3! ทำตัวให้เร็ว!」\n「ช่วยด้วย ช่วยฉันด้วย! อย่าทิ้งฉันไว้!」\n「อย่าหลงไปคำนึงถึงเขา รีบถอยกลับ——อัลวา!」\nทหารที่ถือปืนดาบวิ่งออกไปอย่างรวดเร็ว เสียงระเบิดดังข้างตัวเธอ เสียงต่อสู้ของทหาร เสียงกรีดร้อง และเสียงสัญญาณสงครามดังเป็นระยะๆ เลือดทำให้ดินกลายเป็นสีดำ ส่งกลิ่นคาวที่หนาแน่นจนไม่สามารถถูกกลบด้วยกลิ่นควันปืน ทหารที่ล้มลงบนพื้นมีสายตาที่ว่างเปล่า ไม่ว่าจะเป็นชุดทหารสีใด ก็ในตอนนี้กลับกลายเป็นสีแดงที่เจ็บตา\nอัลวากัดฟัน สู้กับคนที่เข้ามาหาเธอ เธอเห็นแล้ว ชายหนุ่มที่เรียกหาช่วย ถูกกดลงบนพื้น มือทั้งสองข้างพยายามอย่างหนักเพื่อป้องกันมีดจากศัตรูที่สูงใหญ่\nเสียงปืนระเบิดและความเจ็บปวดมาเยือนพร้อมกัน ศัตรูที่อยู่ไม่ไกลล้มลงอย่างช้าๆ อัลวาหันหลังกลับและฟันมีด ทนความเจ็บปวดที่ขาและพุ่งเข้าไปข้างหน้า ใช้โอกาสขณะที่ศัตรูเสียสมดุลแทงมีดเข้าที่อกของอีกฝ่าย พร้อมกับกดไกปืน\nกระสุนทะลุร่างและกระเด็นเลือด เธอเช็ดหน้าพร้อมหันกลับไปเพื่อยืนยันความปลอดภัยของชายหนุ่ม แต่พบว่าเขาไม่รู้ว่าไปไหนแล้ว\nเธอมองลงไป พบว่า มีดแทงทะลุจากเหนือเข่าซ้ายของเธอ เลือดอุ่นๆ ไหลออกมา\nเธอฉีกผ้าคลุมออกเป็นชิ้นเล็กๆ ผูกที่ขาเพื่อจำกัดการไหลของเลือด ใช้ปืนดาบเป็นไม้เท้าชั่วคราว เดินกระเผลกตามกองทัพไป。"
  },
  CollectionHall_127140_Title = {
    Text = "ความมุ่งมั่นแรงกล้า"
  },
  CollectionHall_127141_Desc = {
    Text = "ประวัติศาสตร์มักจะเป็นเสียงเดียวของผู้ชนะ ต้นไม้แม่เสื่อมสลาย ประเทศล่มสลาย ทุกสิ่งเกี่ยวกับอดีตต่างเกิดการเปลี่ยนแปลงอย่างเงียบ ๆ \nกวีขับขานเรื่องราวของสาวงามนีนะเว นักเดินทางนั่งล้อมกองไฟเอียงหูฟัง \n\n「ข้ามทะเลทรายสีเงิน สาวงามจากต่างแดนได้เข้ามายังนีนะเว \nน้ำจากสวรรค์ไหลหลั่งจากบ่าของเธอ เพชรซีนายตกลงจากดวงตาของเธอ \nในดวงตาสีทองอร่าม ส่องมองอดีตของดินแดนต่างประเทศ \nบนผิวที่มีสีเหมือนน้ำผึ้ง เขียนอนาคตของนีนะเว」\n\nแล้วหลังจากนั้นล่ะ? สาวงามนี้ได้กลายเป็นราชินีหรือไม่? \nกวีชราทำการดีดกีตาร์เจ็ดสาย ส่งเสียงถอนหายใจยาวออกมา \n\n「เธอคือยาพิษที่ทำให้ผู้คนหลงใหล \nเธอคือน้ำพิษที่แทรกซึมเข้าไปในปอดของกษัตริย์และขุนนาง \nเธอคือน้ำท่วมที่ประชาชนไม่สามารถหลบหนีได้ \nเธอคือผู้แทนของโรคระบาดสีดำ เธอนำมาซึ่งโรคภัย ฝันร้าย ความตาย และวันสิ้นสุดของนีนะเว」\n\nกีต้าร์ยังไม่ถูกวางลง มีคนหนึ่งลุกขึ้นจากโต๊ะเหล้า ดึงดูดสายตาของนักดื่มทั้งหลาย \nคนผู้นั้นปล่อยเหรียญเหล้าออกจากนิ้วที่ยาวเรียวยาว เงินทองกลิ้งลงมา เสียงดังระฆัง \nที่เธอเดินผ่าน สายตาติดตาม ไฟฟ้ากระพริบ \n\n「เวลาเดินไปอย่างรวดเร็ว… แต่ไม่เป็นไร พระองค์จะไม่ตอบสนองต่อคำพูดเหล่านี้ \nวันหนึ่งพวกคุณจะเข้าใจความเมตตาและความใจดีของพระองค์… เช่นเดียวกับที่ฉันเข้าใจ…」\nเธอผลักประตูเก่า ๆ ของโรงเหล้าออก เหมือนกับการเปิดกล่องเครื่องประดับ แสงจันทร์ตกลงบนบ่าที่เปลือยเปล่า ส่องให้เห็นประกายระยิบระยับ \nสาวงามที่ได้รับความรักจากแสงจันทร์นั้น มีผิวที่คล้ายกับน้ำผึ้งจริง ๆ。"
  },
  CollectionHall_127141_Title = {
    Text = "ฟูมฟักด้วยเมตตา"
  },
  CollectionHall_127142_Desc = {
    Text = "เมื่อเธอเปิดตาออกจากเรือนดอกไม้ ไฟใหญ่ได้ลุกลามไปทั่วทั้งสวน มายังที่ตรงหน้าของเธอแล้ว \n ประตูของเรือนดอกไม้ถูกล็อคจากข้างนอก กลิ่นแอลกอฮอล์และน้ำมันที่เข้มข้นลอยฟุ้งในอากาศ เธอเรียกชื่อโคเลตต์เสียงดัง จนเสียงของเธอแหบแห้งเพราะควัน และเสียงที่ตอบกลับมา มีเพียงเสียงเปลวไฟเห่าหอน \n เธอรู้สึกโชคดี ที่โคเลตต์ออกไปข้างนอก ไม่เช่นนั้นไฟที่ใหญ่ขนาดนี้ เธอก็อาจจะมีอันตราย \n เธอรู้สึกเศร้า ในช่วงเวลาสุดท้ายของชีวิต เธอไม่ได้พบกับเพื่อนสนิทเป็นครั้งสุดท้าย เมื่อโคเลตต์กลับมาเห็นสวนที่ถูกเผาทำลายและตัวเธอเอง คงจะรู้สึกเสียใจมากแน่ๆ \n เธอรู้สึกเสียดาย ชีวิตของพวกเธอกำลังดีขึ้น แต่เปลวไฟนี้จะทำให้พวกเธอหยุดลง \n เผาไหม้ บ้านกำลังเผาไหม้ ท้องฟ้ากำลังเผาไหม้ ใบไม้กำลังเผาไหม้ กลีบดอกไม้กำลังเผาไหม้ ฉากที่เกิดขึ้นในสวนกำลังแสดงและหมุนเวียนอยู่ตรงหน้าเธอ: เธอนำโคเลตต์มาที่สวน เธอยื่นกุหลาบให้กับโคเลตต์ เธอนำขนมปังนุ่มๆ ที่เธอทำจากการทำงานทั้งวันมาให้ \n พวกเธอเล่นสนุก ไล่จับกัน นอนอยู่ใต้แสงแดดที่เงียบสงบ ฝันถึงวันที่จะได้อยู่ในห้องของเคาน์เตส \n เผาไหม้ อดีตกำลังเผาไหม้ อนาคตกำลังเผาไหม้ สวนที่มีเรื่องราวและความรู้สึกทั้งหมด กำลังเผาไหม้อย่างบ้าคลั่ง \n น้ำตาหยดหนึ่งไหลลงมาจากใบหน้าของเธอ และในความร้อนแรงของเปลวไฟ มันก็หายไปอย่างรวดเร็ว \n เธอรู้สึกสวยงาม ในบทกวี ความเจ็บปวดและความเสียดายคือความงาม เธอค้นหาไปทั่ว และพบกระดาษและปากกาที่ถูกไฟกัดกร่อนจนหมด \n ความรู้สึกขอบคุณ ความรัก ความไม่อยากจากลา พร ความงาม เธอจะเก็บทุกสิ่งที่งดงามนี้ไว้ให้กับโคเลตต์ \n 「……ถึงโคเลตต์ ฮอร์ลา ในไฟ」 \n บทส่งท้ายของบทกวี เธอได้ทิ้งลายเซ็นสุดท้ายไว้ \n ห่างออกไปหนึ่งร้อยเมตร ที่ถนนตรงข้ามสวน โคเลตต์ดูเหมือนจะรู้สึกถึงอะไรบางอย่าง เธอเงยหน้าขึ้น แสงไฟที่รุนแรงสะท้อนบนใบหน้าของเธอ \n น้ำตาหยดหนึ่งไหลลงมาจากใบหน้าของเธอ และในความร้อนแรงของเปลวไฟ มันก็หายไปอย่างรวดเร็ว。"
  },
  CollectionHall_127142_Title = {
    Text = "บทส่งท้าย"
  },
  CollectionHall_127143_Desc = {
    Text = "พวกเขาแล่นเรืออยู่ในแม่น้ำมืดมิด ซีดเซียว เงียบสงัด และเหนื่อยล้า \n หมอกจางๆ ยืดแขนออกมา ดึงพวกเขาเข้าสู่ความมืด วนเวียนอยู่ในคืนที่ไม่มีที่สิ้นสุด \n\n ต่อมา พวกเขาเห็นแสงสว่างหนึ่งสาย \n นั่นคือแสงอาทิตย์ที่มาจากฝั่งที่ห่างไกล มันกระพริบไปมา แต่เพียงพอที่จะส่องสว่างจิตวิญญาณที่มืดมน \n ดังนั้นพวกเขาจึงตามแสงนั้น พายเรือออกจากความมืด อย่างขัดสน มาถึงหน้ารุ่งอรุณที่สว่างไสว \n และมาถึงพวกคุณ \n\n บางทีนี่อาจเป็นเพียงการพบกันชั่วคราว แต่พวกเขาก็โบกมืออย่างเต็มที่ และตะโกนสุดเสียง \n ทุกคนอาบแสงอาทิตย์อันศักดิ์สิทธิ์ ทุกคนต่างยิ้ม \n พวกเขากล่าวว่า—— \n ขอให้ทุกช่วงเวลาที่ได้พบกันมีค่าเหมือนเทศกาล \n ขอให้หัวใจที่จริงใจไม่หยุดเต้น \n ขอให้กุญแจเงินนำทางไปข้างหน้า。"
  },
  CollectionHall_127143_Title = {
    Text = "รัตติกาลและอรุณรุ่ง"
  },
  CollectionHall_127144_Desc = {
    Text = "วายุพัดเข้ามาจากทุกทิศทาง คุณถือเทียนยืนอยู่ที่ทางเข้าของเขาวงกต\nคุณรู้สึกสับสนเล็กน้อย\nเหมือนเมื่อวินาทีที่แล้ว คุณยังอยู่ในโรงอาหารของมิซากะ ฟังชาร์ล็อตต์เล่าเรื่องตำนานเกี่ยวกับเขาวงกตใต้ดินในห้องสมุด\nและตอนนี้ คุณสวมชุดนอน เดินงัวเงียอยู่ในทางเดินที่ต่อเนื่องกัน\n「ชาร์ล็อตต์ ชาร์ล็อตต์……」\nพร้อมกับเสียงกระซิบกระซาบ ฝูงแมงมุมสีขาวหลั่งไหลเข้ามา\nมันรวมตัวกันเป็นสาวผู้ขาวซีด เธอนั่งอยู่บนชิงช้าที่ทำจากเนื้อสัตว์ แกว่งไปแกว่งมา\n\n「คุณมาแล้ว」เธอกล่าว\n「ฉันมาหาชาร์ล็อตต์ เพื่อนของฉัน เธอหลงทาง ฉันต้องหาตัวเธอ……」\nคุณเกือบจะร้องไห้ออกมา\nสาวหัวเราะคิกคัก เธอกระโดดลงจากชิงช้า เดินมาหาคุณ\n「คุณลืมไปแล้วหรือ? ข้อตกลงของเรา……」\nเด็กหญิงยื่นมือไปสัมผัสที่ท้องของคุณ แล้วก็เข้าใจในทันที\n「ใช่แล้ว คุณได้เป็นบุตรของฉันแล้ว ดังนั้นจึงไม่มีอะไรที่คุณจำได้」\n「บุตร……?」\nคุณมองลงไปที่จุดที่ผิวของพวกคุณสัมผัสกัน\nความรู้สึกอบอุ่นเหมือนใยแมงมุมแทรกซึมลึกลงไปในผิวหนัง และแพร่กระจายไปถึงหลอดเลือดที่ลึกที่สุด\nสาวน้อยกระพริบตาอย่างลึกลับ แล้วเข้ามาใกล้หูคุณพูดเบาๆ ว่า\n「ชาร์ล็อตต์ อยู่ในท้องของคุณนะ」"
  },
  CollectionHall_127144_Title = {
    Text = "ทายาทขาวซีด"
  },
  CollectionHall_127145_Desc = {
    Text = "บนเวทีขนาดใหญ่ สาวน้อยคนหนึ่งกำลังเต้นรำอยู่ \n เธอรวบผมเป็นมวยอย่างแน่นหนา บนศีรษะประดับด้วยขนนกสีขาวบริสุทธิ์และมงกุฎขนาดเล็ก กระโปรงสีขาวบริสุทธิ์พลิ้วไหวตามการเคลื่อนไหวของเธอ หมุนวนไปมาท่ามกลางเสียงไวโอลินที่เศร้าสร้อย \n แขนของเธอเหยียดออก นิ้วเท้าจรดพื้น หงส์ขาวโน้มคอยาวลงเล่าเรื่องราวความเศร้าโศกและความทุกข์ใจให้กับเจ้าชายฟัง \n ลิซวัยเยาว์อ้าปากค้าง มองดูสาวน้อยที่เบาและสง่างามบนเวที นั่นคือญาติของเธอ ซึ่งมาอยู่ที่บ้านของเธอก่อนที่เธอจะเกิด และได้รับการฝึกฝนอย่างเข้มงวดใต้การดูแลของคุณยาย สาวญาติผู้ที่ปกติเรียบง่ายและเงียบสงบไม่เคยมีชีวิตชีวาเช่นวันนี้ เธอเหมือนกับหงส์ที่กำลังจะกระพือปีกออกไป และเธอ พวกเขา ทุกคนในโรงละคร ต่างหลงใหลในเงาของเธอ \n หัวใจของเธอเต้นแรงขึ้นเรื่อย ๆ เร็วขึ้นเรื่อย ๆ — ช่างน่าอิจฉาเสียจริง! เธออยากเป็นหงส์ตัวนั้น ที่จะทิ้งเงาของตนไว้บนเวทีอันเป็นนิรันดร์ เธอรู้ว่าเธอทำได้ ทำไมคุณยายถึงไม่เคยชมว่าเธอมีขาที่ยาวและตรงในขณะที่เธอไม่ทันสังเกต? ทำไมญาติสาวที่เป็นนักเต้นนำมาหลายปีถึงไม่เคยบอกว่าเธอมีพรสวรรค์ในการเต้นรำ? ใช่แล้ว เพียงแค่เธอเริ่มต้น เพียงแค่เธอสวมรองเท้าส้นสูง ผู้คนจะต้องเดินทางมาจากเมืองไกล ๆ เพื่อมาชมการแสดง เธอจะเป็นนักเต้นที่ยิ่งใหญ่ที่สุดในศตวรรษนี้ เป็นดาวรุ่งที่สุกสกาวในศิลปะบัลเลต์! \n ในเวลานั้น เธอยังไม่รู้เลย ว่าที่รอคอยเธอมีเพียงเปลวไฟที่ร้อนแรงเท่านั้น。"
  },
  CollectionHall_127145_Title = {
    Text = "ฟูเอ็ตเต้"
  },
  CollectionHall_127146_Desc = {
    Text = "นี่คือหนึ่งปีหลังจากที่คุณมาถึงมิซากะ คุณยังจำได้ว่าตัวเองตื่นขึ้นหลังจากการระเบิดครั้งนั้นและก้าวเข้าสู่โรงเรียนนี้เป็นครั้งแรก คุณได้รับชุดนักเรียนที่พอดีและเรียบร้อย มีหอพักเป็นของตัวเอง เข้าเยี่ยมชมโรงอาหารเป็นครั้งแรกและกินจานอาหารไปสองกอง ช่วงเวลาสบายๆ ทั้งหมดในวันนั้นหยุดชะงักลง ในพริบตาคุณก็ถูกบังคับให้เข้าเรียนในชั้นเตรียมการเป็นเวลาหนึ่งปีเนื่องจากความรู้ที่ขาดแคลนและเส้นทางความคิดที่เรียบง่ายเหมือนเด็กทารก การเรียนรู้ภาษา การฝึกฝนร่างกาย การทดสอบความสามารถของเงินใจ การเสริมความรู้เกี่ยวกับสิ่งมีชีวิตพิเศษ... หลังจากถูกทรมานคุณก็ได้ผลการเรียนที่ดีบ้างไม่ดีบ้าง ผลสอบในภาษาเลโอที่ไม่ผ่านและความสำเร็จที่เชื่อมต่อผู้ปลุกตื่นสามคนในครั้งเดียวทำให้คุณมีชื่อเสียงในวิทยาเขต โชคดีที่ด้วยความสามารถพิเศษและพรสวรรค์ที่โดดเด่น คุณจึงสามารถบรรลุมาตรฐานความสามารถของนักสืบได้อย่างรวดเร็ว ไม่ต้องขยายเวลาชั้นเตรียมการอีก ส่วนความอ่อนแอที่ไม่สม่ำเสมอนั้น ก็ให้เพื่อนร่วมทีมที่ค่อยๆ มีความเข้าใจกันช่วยติวและรับผิดชอบให้ อ่า ที่นี่ถึงแม้จะมีปีศาจมากมาย แต่ก็เป็นปีศาจที่เชื่อถือได้และอ่อนโยน ที่นี่มักจะมีเมฆมาก ฝนตก และมีวันที่แดดออกน้อย ผู้คนจำนวนมากที่ถูกลืมและจะถูกลืมยังคงยืนหยัด เสียสละ และก้าวไปข้างหน้าอย่างไม่หยุดหย่อน ในวันที่ทุกอย่างเป็นไปตามปกติเช่นนี้ มิซากะได้ต้อนรับวันเปิดเทอมอีกปีหนึ่ง คุณจัดระเบียบปกเสื้อชุดนักเรียนในกระจก ปรับเรียบทุกริ้วรอย แล้วผลักประตูใหญ่ของหอพักออกไป 「อ้าปากหาว สุดท้ายก็มาถึง ฉันเกือบจะหลับไปแล้ว」 「คุณนั่งเรียนอยู่ในหอพักเหรอ? ทารกแรกเกิด」 คุณยิ้มเขินให้โลทันและย่อคอหลบซ่อนอยู่หลังลามอนน่าและโอเกียร์ที่ยืนยิ้มอยู่ ขณะที่เงาห้าเงาเต้นละล่องในวิทยาเขตตอนเช้า 「ไปเถอะ คู่หู」 「ตั้งแต่วันนี้เป็นต้นไป คุณจะเป็นส่วนหนึ่งของมิซากะอย่างเป็นทางการแล้ว」"
  },
  CollectionHall_127146_Title = {
    Text = "วันเปิดภาคเรียน"
  },
  CollectionHall_127147_Desc = {
    Text = "เดินตามแม่น้ำเทมส์ไปเรื่อยๆ แล้วเลี้ยวขวาไปที่ถนนเบ็คแมน เดินต่อไปประมาณหนึ่งร้อยฟุต คุณจะเห็น 「สำนักงานนักสืบไรเกอร์」 ที่มุมที่ไม่เด่นนั้น \n\nในฐานะที่เป็นสำนักงานนักสืบที่มีอัตราการไขคดีสูงที่สุดในลอนดีเนี่ยน ที่นี่ไม่มีชั้นหนังสือใหญ่ที่เต็มไปด้วยหนังสือวิชาชีพ ไม่มีผนังที่เต็มไปด้วยข่าวตัดปะ และไม่มีน้ำชายามบ่ายที่หรูหรา \nคุณมักจะพบเพียงป้าย 「ออกไปทำธุระ」 ที่แขวนอยู่หน้าประตู และสุนัขแก่ที่นอนอยู่ข้างๆ \n\nถ้าคุณโชคดี ในวันอาทิตย์เช้าที่มีอากาศแจ่มใส คุณอาจจะรอพบกับนักสืบชื่อดังที่เพิ่งกลับมาจากการดื่มเหล้า \nในขณะที่เขาเพิ่งเสร็จสิ้นการเล่นพนันครั้งก่อน และในกระเป๋าของเขาไม่มีเงินเหลืออยู่มากนัก คุณสามารถเสนอคำร้องที่ไร้เหตุผลของคุณได้อย่างเต็มที่: หาแมว, ช่วยแม่ที่เข้าไปในลัทธิ, รวบรวมหลักฐานการนอกใจของสามี... \nขอเพียงแค่คุณมี เขาสามารถรับมันได้ \n\n 「ฉันเพลิดเพลินกับช่วงเวลาที่ใกล้ตาย ดังนั้นฉันจึงถูกกำหนดให้เป็นนักพนัน」 \n 「แล้วการเป็นนักสืบล่ะ? ขออภัยที่พูดตรงๆ ฉันไม่เห็นความสัมพันธ์ระหว่างการหาแมวกับการใกล้ตาย」 \n 「ไม่ คุณไม่เข้าใจ... กระบวนการค้นหาความจริงนั้นเองก็เพียงพอที่จะดึงดูดใจ ไม่ว่าจะเล็กหรือใหญ่ เหมือนกับ...」 \n 「เหมือนการไปนัดหมายกับความตาย」"
  },
  CollectionHall_127147_Title = {
    Text = "ช่วงเวลาแห่งโชคลาภ"
  },
  CollectionHall_127148_Desc = {
    Text = "โพลลักซ์ฝันหนึ่ง\nเขาฝันว่าเขาสวมเกราะสีเงิน รับดาบยาวที่เงางามเหมือนจันทร์จากมือของกษัตริย์ผู้มีอำนาจ\nหลังจากนั้นเขาก็ขึ้นม้าขาวสูงใหญ่ มุ่งหน้าไปยังถ้ำหนึ่ง เมื่อเขาลงลึกเข้าไปในใต้ดิน ต้นไม้บริเวณปากถ้ำก็ส่งเสียงกระซิบเบาๆ\nในความลึกของถ้ำมีเงาสีเขียวเข้มซ่อนอยู่ นั่นคือมอนสเตอร์ที่สูงใหญ่เหมือนภูเขาเนื้อ ดวงตาที่ประหลาดของมันส่องประกายสีเขียว\n「มอนสเตอร์ที่เป็นภัยต่อชาติ ข้าจะไม่อนุญาตให้เจ้าคุกคามอาณาจักรอันศักดิ์สิทธิ์ของเราได้อีก วันนี้ ข้าจะใช้ดาบแห่งความยุติธรรมนี้กำจัดเจ้า!」\nมอนสเตอร์สั่นสะเทือนเหมือนตอบสนอง ส่งเสียงคำรามที่น่ากลัว\nโพลลักซ์ไม่เข้าใจภาษาของมัน และไม่มีความตั้งใจที่จะเข้าใจคำพูดของมัน เขายกดาบวิเศษขึ้นและเริ่มต่อสู้กับมอนสเตอร์ที่มีกลิ่นอายชั่วร้าย แขนของมอนสเตอร์แผ่กระจายไปทั่วขอบเขตมืดของถ้ำ และเสียงกระทบระหว่างดาบที่เปล่งประกายกับมันดังขึ้นอย่างชัดเจน\nเหมือนกับตอนจบของทุกเรื่องราวของวีรบุรุษ อัศวินผู้กล้าหาญได้ขึ้นขี่หลังมอนสเตอร์ และในเสียงคำราม เขาได้แทงปลายดาบลงไปในอกของมัน\nมอนสเตอร์ล้มลงอย่างหมดแรง โพลลักซ์มองด้วยความงงงวยไปที่รอยที่ค่อยๆ แพร่กระจายใต้ดาบของเขา——ทำไมเลือดสดสีแดงอุ่นถึงไหลออกมาจากร่างที่น่าเกลียดและชั่วร้ายนี้?\nเขาตื่นขึ้นจากความฝันอย่างกระทันหัน ความรู้สึกเหนียวหนึบของเลือดที่เปรอะเปื้อนมือของเขารู้สึกเหมือนจะไม่หายไป เขาเหลือบไปเห็นหนังสือเก่าที่คาสเตอร์เก็บรักษาไว้อย่างระมัดระวังอยู่ในรอยแตกหลังเตียง\nเขาเปิดหนังสือเล่มนั้นอย่างสุ่มสี่สุ่มห้า และบังเอิญเจอเรื่องราวของอัศวินที่คาสเตอร์มักอ่านอยู่บ่อยๆ ในกลางหน้าเขาเห็นประโยคหนึ่งของคำทำนาย\n「เมื่อมอนสเตอร์ชั่วร้ายถูกนักรบปราบได้ ทุกคนจะเห็นปรากฏการณ์ในท้องฟ้า ดวงอาทิตย์จะกลายเป็นความมืด และดวงจันทร์จะเปลี่ยนเป็นเลือด」\nโพลลักซ์ขมวดคิ้วและไม่ใส่ใจโยนหนังสือเก่ากลับไปที่เดิม และเริ่มกระซิบสวดมนต์ภายใต้แสงจันทร์\n「ผู้รับใช้ของพระเจ้าถูกส่งมาที่นี่เพื่ออวยพรพวกท่าน ให้พวกท่านได้ล้างบาป และกลับจากความมืดสู่แสงสว่าง ร่วมกับผู้ชอบธรรมที่บริสุทธิ์เข้าไปในดินแดนบริสุทธิ์……」\nผู้ถือไฟไม่ได้ส่องสว่างให้กับเซิร์ฟแวนท์ผู้มีความเชื่อมั่นของเขา ความไม่สงบจากฝันร้ายยังคงสั่นสะเทือนอยู่ในใจของเขา นั่นคือจิตวิญญาณที่หลับใหลของเขากำลังร้องไห้อยู่ในความฝัน。"
  },
  CollectionHall_127148_Title = {
    Text = "โพลิกซ์"
  },
  CollectionHall_127149_Desc = {
    Text = "<Bold:24 มกราคม>\nตัวเหม็นมาก.\nวันนี้กลับบ้านกับคุณเทเรซ่า พนักงานบ้าน ขณะขับรถผ่านเขตนานอัมพ์.\nนี่ไม่ใช่ประสบการณ์ที่น่าพอใจ.\nที่นั่นเป็นสถานที่อันตราย@2 มีบางคนที่มีบาดแผลแปลก ๆ บนร่างกาย คล้ายกับรูสามเหลี่ยม.\nคุณเทเรซ่าบอกว่านี่คือการลงโทษของพระเจ้าสำหรับพวกนอกรีต.\n\n<Bold:22 กุมภาพันธ์>\nเป็นไข้ตลอดหนึ่งเดือน.\nวันนี้ในที่สุดก็ได้กินอะไรบางอย่าง เป็นสเต็กสดใหม่ เนื้อนุ่มและมีน้ำเยอะ...\nใช่ เนื้อมีน้ำเยอะ.\nสีแดง@2 หอมหวาน@2 อร่อย\nกระจกในบ้านทุกบานถูกเก็บไว้ ไม่มีแม้แต่โบบี้กล้าที่จะมองฉัน.\nฮิฮิ พวกเขาไม่รู้ว่าในเวลากลางคืน ฉันสามารถเห็นรูปร่างของตัวเองจากเงาที่หน้าต่าง.\nที่ใบหน้า คอ และหน้าอกของฉัน...จากบนลงล่าง เต็มไปด้วย@2 รูสามเหลี่ยมสีดำ\n<Bold:17 มีนาคม>\n\nเยื่อบุตาของฉันเหมือนถูกคลุมด้วยผ้าลายสีแดง.\nโลกกลายเป็นสีเลือด@3\nพ่อยืนอยู่ในหมอกเลือดและตะโกนใส่ฉัน นี่เป็นครั้งแรกที่เขาพูดกับฉันด้วยเสียงดังขนาดนี้.\nเขาอยู่ใกล้ฉัน แต่เสียงของเขาอยู่ห่างไกล ฉันได้กลิ่นของความสิ้นหวัง ความเกลียดชัง และเลือด.\nอย่า@2พาฉันไป อย่า..."
  },
  CollectionHall_127149_Title = {
    Text = "นิทานของปีศาจตะกละ"
  },
  CollectionHall_127150_Desc = {
    Text = "ชาวเอริวินอาศัยอยู่ในเมืองหินสีเทา ใกล้กับทะเลสาบใหญ่สีเขียว\n\nทะเลสาบใหญ่ไม่มีชื่อ มันมีอยู่ตั้งแต่ชาวเอริวินมีความทรงจำ\nมีตำนานเล่าว่าแม่มดชั่วร้ายถูกผนึกอยู่ในน้ำลึกของทะเลสาบ\nเธอเก่าแก่พอๆ กับทะเลสาบ เป็นสิ่งมีชีวิตที่น่ากลัวที่ถูกสร้างขึ้นอย่างหยาบๆ ในยุคเริ่มต้น\nชาวเอริวินที่ไร้เดียงสาและขี้ขลาดต่างกลัวแม่มด พวกเขาพยายามทำให้แม่มดพอใจ เพื่อให้แน่ใจว่าเธอจะอยู่ในก้นทะเลสาบอย่างเงียบๆ ตลอดไป\n\n「ควรทำอะไรดี?」\n「ใช่แล้ว ควรทำอะไรดี?」\n「งั้นก็เต้นรำกันเถอะ! ไม่ว่าจะอย่างไร การเต้นรำก็ดีเสมอ」\n\nดังนั้น ทุกครั้งที่พระจันทร์เต็มดวง ชาวเอริวินจะมารวมตัวกันที่ริมทะเลสาบ เต้นรำต่อหน้ารูปเคารพที่ทำจากกระดาษ\nในขณะนั้น พระจันทร์ส่องแสงและดาวน้อย ทุกอย่างสงบสุข\n\nหลายร้อยปีต่อมา ชาวเอริวินลืมประวัติศาสตร์ ลืมตำนาน และลืมรูปเคารพ\nในวันครบรอบพันปีของการก่อตั้งเมืองหิน พวกเขาหัวเราะอย่างบ้าคลั่งและดื่มสุรา\nเสียงที่อึกทึกส่งไปยังทะเลสาบ เหมือนกับหินที่ตกลงไปในน้ำ โดยกระจายออกเป็นวงกลมไม่สิ้นสุดจากกลางทะเลสาบ สุดท้ายสัมผัสกับสิ่งที่อยู่ลึก\nดังนั้น ในคืนพระจันทร์เต็มดวง ชาวเอริวินได้ยินเสียงที่อยู่นอกขอบเขตของเสียง และเห็นพระจันทร์และไฟที่อยู่นอกขอบเขตการมองเห็น\nพวกเขากลายเป็นส่วนหนึ่งของความเงียบงัน\n\nความเงียบที่ไม่มีที่สิ้นสุดในอวกาศเหล่านี้ทำให้ชาวเอริวินเต็มไปด้วยความกลัว\nพวกเขาถูกบังคับให้นั่งนิ่งเหมือนนักลึกลับ เห็นกลุ่มใหม่หัวเราะอย่างบ้าคลั่ง ดื่มสุรา มาไปซ้ำแล้วซ้ำเล่า\nดังนั้นจักรวาลจะขยายต่อไปตลอดไป กลุ่มดาวจะห่างไกลออกไป ทุกสิ่งจะหายไป\nเรื่องราวเป็นเช่นนี้\nไม่สำคัญว่าชาวเอริวินจะรู้สึกโดดเดี่ยวหรือไม่。"
  },
  CollectionHall_127150_Title = {
    Text = "งานระเริงไร้เสียง"
  },
  CollectionHall_127151_Desc = {
    Text = "เด็กหญิงเปิดตา พบว่าตัวเองอยู่ท่ามกลางความมืด\n「เฮ้!」เธอร้องออกมา「มีใครอยู่ไหม?」\nเสียงสะท้อนลอยไปในพื้นที่ที่มองไม่เห็นขอบเขต ค่อยๆ จางหายไป เด็กหญิงสูดหายใจเข้าลึกอีกครั้ง และตะโกนอีกครั้งว่า「พี่สาว บราวน์ เวสต์-เวลป์!」\n「มีใครอยู่ไหม——」\nคำถามที่ดังขึ้นกว่าครั้งก่อนลอยห่างออกไป แล้วค่อยๆ กลับมา มีแสงสีฟ้าอ่อนๆ หลายเส้นเหมือนถูกเสียงสะท้อนดึงเข้ามาใกล้ มันประกอบด้วยอนุภาคนับพันที่ลอยอยู่ในอากาศและเล็กเหมือนฝุ่น กลายเป็นงูที่เลื้อยไปในอากาศ และคล้ายคลื่นทะเลที่โคลงเคลง เส้นแสงหนึ่งต่อหนึ่งผ่านเด็กหญิงที่ยืนอยู่ไม่ไกลอย่างไม่หยุดยั้ง เปลี่ยนทั้งฟ้าและดินให้กลายเป็นทะเลดาว อนุภาคเล็กๆ ผ่านมือและเส้นผมของเด็กหญิงไป โดยไม่ทิ้งร่องรอยไว้เลย\n「นี่คือ...อะไร?」\nฝุ่นที่ส่องแสงอยู่รอบตัวเธอขยับขึ้นลงเล็กน้อย แต่ไม่ได้ตอบ\n「ฉันจำพิพิธภัณฑ์หุ่นขี้ผึ้งได้ จำพี่สาวได้ ฉัน...เหมือนจะตายแล้ว ที่นี่คือสวรรค์ไหม?」เธอมองไปทางซ้ายและขวา「ทำไมถึงไม่มีแม้แต่เทวดา จะไม่ใช่ว่านี่คือขุมนรกใช่ไหม!」\nเสียงของเธอหล่นอยู่ข้างหูครั้งนี้ แม้แต่เสียงสะท้อนก็ไม่ปรากฏขึ้นอีก\nความรู้สึกเหงาโหวงอย่างไม่รู้สาเหตุเกิดขึ้นจากใจลึกๆ ของเธอ ในช่วงเวลาที่มึนงง เธอเหมือนจะกลับไปยังช่วงที่พบกับพี่สาวและบราวน์ ก่อนหน้านั้น กลิ่นเหม็นจากท่อระบายน้ำลอยมา เธอหนาวและหิว แต่ไม่สามารถออกไปได้ เพราะมีคนผลักเธอลงไปและกดถังใหญ่ไว้ที่ด้านบนของท่อ\nเธอแตะที่ใบหน้าของตัวเองแล้วก้าวไปข้างหน้า\nฝุ่นแยกออกจากกันข้างหน้าเธอ และรวมตัวกันที่ด้านหลัง ยกขา ลงเท้า ยกขา ลงเท้า เธอเดินไปอย่างนั้นเรื่อยๆ ไม่รู้ว่าตัวเองเดินไปนานแค่ไหน หรือเดินไปไกลแค่ไหน ข้างหน้าเธอมีฝุ่นและความมืดมากขึ้น ในขณะที่ด้านหลัง ไม่ว่าจะเป็นทิศทางที่มา หรือเส้นทางที่เดินผ่านมา ต่างก็ไม่มีร่องรอยใดๆ จนกระทั่ง—\n「ปลุกตื่นสำเร็จแล้ว เจนกิน เจนกิน คุณได้ยินไหม?」"
  },
  CollectionHall_127151_Title = {
    Text = "หนทางที่หลงหาย"
  },
  CollectionHall_127152_Desc = {
    Text = "พ่อพระผู้สร้างสรรค์ชีวิตเสด็จจากดวงดาวในท้องฟ้า\nในเวลานั้นโลกเป็นดินร้อนระอุ เปลวไฟลุกโชน พ่อพระยืนอยู่บนไฟ\nพ่อพระกล่าวว่าไฟจะดับลงในที่สุด ไฟจึงทำเช่นนั้น\nดินที่หลากหลายกลายเป็นโลก พ่อพระได้เขียนพระวาจาไว้บนโลกว่า:\nโลกจะเป็นฐานของสิ่งมีชีวิต\nหุบเขาก็กลายเป็นหุบเขา ที่ราบก็กลายเป็นที่ราบ\nพระวาจามั่นคง นี่คือกระดานหินชิ้นแรก\n\nพ่อพระเห็นเมฆหนาแน่นกล่าวว่า เมฆจะตกฝนในที่สุด เมฆจึงทำเช่นนั้น\nฝนรวมตัวกันกลายเป็นน้ำไหล พ่อพระได้เขียนพระวาจาไว้ว่า:\nน้ำจะเป็นเตียงนอน\nน้ำกลายเป็นทะเลสาบ กลายเป็นทะเล และทะเลก็ท่วมโลก\nพระวาจามั่นคง นี่คือกระดานหินชิ้นที่สอง\n\nพ่อพระเห็นน้ำมืดมน กล่าวว่าควรให้แสงสว่างตกลงมา แสงจึงทำเช่นนั้น\nแสงตกลงบนผิวน้ำ พ่อพระได้เขียนพระวาจาไว้ว่า:\nแสงจะบ่มเพาะ\nแสงนำความอบอุ่นมา\nพระวาจามั่นคง นี่คือกระดานหินชิ้นที่สาม\n\nพ่อพระเห็นว่าโลก น้ำ และแสงมีอยู่แล้ว กล่าวว่าสิ่งมีชีวิตจะมาถึง\nพระองค์ทำให้เลือดของพระองค์ไหลออกมา และเขียนพระวาจาไว้ว่า:\nเลือดจะให้กำเนิดใหม่\nเลือดของพ่อพระกระจายไปกลายเป็นสิ่งมีชีวิตในทะเล\nพระวาจามั่นคง นี่คือกระดานหินชิ้นที่สี่\n\nพ่อพระเห็นว่าสิ่งมีชีวิตเกิดขึ้นแล้ว กล่าวว่าสิ่งมีชีวิตจะเปลี่ยนแปลงตลอดไป สิ่งมีชีวิตจึงทำเช่นนั้น\nสิ่งที่มองไม่เห็นปีนขึ้นไปบนดินที่น้ำลดลง\nพ่อพระได้เขียนพระวาจาไว้บนสิ่งที่เปลี่ยนแปลงว่า:\nการเปลี่ยนแปลงไม่สามารถหยุดได้\nสิ่งที่ปีนขึ้นบกมีรากและลำต้น ขา และรูปร่างต่างๆ\nพระวาจามั่นคง นี่คือกระดานหินชิ้นที่ห้า\n\nพ่อพระเห็นว่าสิ่งมีชีวิตและการเปลี่ยนแปลงเกิดขึ้นแล้ว กล่าวว่าความตายจะมาถึง ความตายจึงมา\nแก่เฒ่าก็ต้องตาย ป่วยก็ต้องตาย พ่อพระได้เขียนพระวาจาไว้บนความตายว่า:\nผู้ที่ตายจะกลับคืนสู่ต้นกำเนิด\nร่างกายของผู้ตายค่อยๆ หายไป กลับสู่การกอดของพ่อพระ\nพระวาจามั่นคง นี่คือกระดานหินชิ้นที่หก\n\nพ่อพระเห็นว่าสิ่งมีชีวิต ความตาย และการเปลี่ยนแปลงมีอยู่แล้ว กล่าวว่าสิ่งเหล่านี้คือการสร้างของฉัน ฉันจะเหลือพรไว้\nพ่อพระนำกระดูกของพระองค์ออกมา และเขียนพระวาจาไว้ว่า:\nที่ปลายทางของทุกสิ่ง สามารถใช้กระดูกของฉัน แทนที่อำนาจของฉัน\nมอบชีวิตด้วยราคาที่ต้องจ่ายเลือดและเนื้อ\nพระวาจามั่นคง นี่คือกระดานหินชิ้นที่เจ็ด\n\nพ่อพระเห็นว่าทุกสิ่งมีอยู่แล้ว จึงหยุดพัก\nน้ำห่อหุ้มพ่อพระ แสงนำความอบอุ่นให้พ่อพระ โลกปกคลุมพ่อพระ\nหลังจากนั้นพ่อพระหลับใหล ทุกสิ่งมีชีวิตอยู่ตามพระวาจาของพ่อพระ นั่นคือโลกในปัจจุบัน。"
  },
  CollectionHall_127152_Title = {
    Text = "จารึกศักดิ์สิทธิ์"
  },
  CollectionHall_127153_Desc = {
    Text = "เขาคือราชาผู้รู้แจ้งทุกสิ่ง เป็นผู้สูงสุดแห่งลิโมเรีย\nลาพิสลาซูลีคือพระที่นั่งของพระองค์ ทองคำคือมงกุฎของพระองค์ วิญญาณคืออำนาจของพระองค์ พระองค์หลับใหลอยู่ในที่สูงสุด\nเหล่าสมณะผู้รับใช้พระเจ้าก็รับใช้พระองค์ คุกเข่าต่อหน้าเขา\nพวกเขาคือข้าพระองค์ผู้ซื่อสัตย์ คือผู้ศรัทธาต่อพระองค์อย่างแท้จริง\n\nเทพเจ้าได้ส่งแสงจันทร์ในยามค่ำคืน เพื่อเชิญพระองค์ไปยังวังแห่งนิทรานิรันดร์\nที่นั่น พวกเขาแบ่งปันอาหารแห่งวิญญาณให้แก่พระองค์ มอบสติปัญญาของเทพเจ้าแก่พระองค์\nพวกเขามอบความฝันไม่รู้จบ เพื่อให้พระองค์เห็นจุดกำเนิดแห่งทุกสิ่ง และเห็นจุดจบของกาลเวลา\nพระองค์จึงรู้ว่าจุดเริ่มต้นของทุกสิ่งล้วนเกิดจากความโกลาหล ที่ซึ่งเทพเจ้าตื่นขึ้นและสร้างวังลอยในความมืด\nพระองค์จึงรู้ว่าจุดจบของกาลเวลาเป็นความมืดมิด ทุกสิ่งหวนกลับสู่ความโกลาหล\n\nราชาแห่งราชาทั้งปวง บุตรแห่งเทพเจ้า\nผู้ใดเล่าจะเทียบเคียงกับพระองค์ได้\nผู้ใดเล่าจะปกครองในฐานะผู้นำแห่งความฝันเฉกเช่นพระองค์ ผู้ใดเล่าจะทรงอำนาจดังเช่นพระองค์\nโอ้ราชาแห่งเทพเจ้า ผู้ครอบครองตั้งแต่วัยเยาว์\nขอพระองค์หลับใหลอย่างเปี่ยมสุข\nเหล่าข้าราชบริพารและผู้ศรัทธาจะเฝ้ารออย่างอดทน เพื่อให้พระองค์นำพาพยากรณ์ของเทพเจ้ามา\nโอ้เจ้าแห่งลอริญาบูชา ผู้สั่งการเจ้าของขอบเหวลึก\nโปรดเถิด ขอเรากล่าวพระนามของพระองค์ และมอบการคุ้มครองแก่เรา\nธูลู ธูลู。"
  },
  CollectionHall_127153_Title = {
    Text = "เพลงสรรเสริญเทวราชา"
  },
  CollectionHall_127154_Desc = {
    Text = "หลายปีมาแล้วที่ข้าคิดถึงยูอูฮาชิ\nแต่เพียงในซากปรักหักพังของวิหารเหล่านี้ ข้าจึงได้เห็นเขาอย่างชัดเจนเป็นครั้งแรก \nข้าเห็นโซ่หนักรอบตัวเขา และด้วยเหตุนี้ เขาต้องพุ่งตัวลง สองมือลงพื้น และยืดคอไปยังอาหารที่เสียไปนานแล้ว\nเหมือนสุนัขตัวหนึ่ง\n\nหลังจากคาลิกูลาตาย ในฐานะผู้สมรู้ร่วมคิดของทรราช เขาถูกล็อกไว้ในซากวิหารจนถึงปัจจุบัน\nข้าลากโซ่ในมือของข้า เพื่อนำทาสของทอเรสมาให้\nทันทีที่เขาตรงตัวขึ้น ดวงตาเบิกกว้าง และเสียงกลืนอย่างรวดเร็วออกจากลำคอของเขา\n\n「รอก่อน.」\nข้าชักโซ่กลับ ดึงทาสไปยังระยะที่เขาไม่สามารถเข้าถึงได้\n「ช่วยข้าฆ่าคนหนึ่ง.」\nเขายิ้มกว้าง เผยฟันสัตว์ที่คมชัด\n「เจ้าเป็นคนที่ 19 ที่บอกเช่นนี้แก่ข้า ข้าเสียใจที่จะปฏิเสธเจ้า.」\nข้าพยายามซ่อนความผิดหวังไม่ให้เขาเห็น:\n「ทำไม?」\n「หากเจ้าสั่งให้ข้าฆ่าคนพันคน ข้ายินดีอย่างยิ่ง ฆ่าคนหนึ่ง? ข้อเสนอของเจ้าไม่พอ」\n「หากคนที่เจ้าได้ฆ่าเป็นจักรพรรดิคนปัจจุบันล่ะ?」\nข้าสูดลมหายใจลึก\n「ข้อเสนอนั้นพอหรือไม่?」\nยูอูฮาชิหัวเราะเสียงดัง:\n「นี่คือปัญหาคณิตศาสตร์ สหายของข้า หนึ่งก็คือหนึ่ง พันก็คือพัน」\n\n「ไฟลุกขึ้นแล้ว พระราชวังทองลุกเป็นไฟ!」\nไฟลุกโชติช่วงจากแดนไกล\nทรราช, ทรราช...\nข้าร้องไห้อย่างสิ้นหวัง เพื่อน้ำตาถึงเซเนกา และถึงพระราชวังที่กำลังจะกลายเป็นซากปรักหักพัง\n「เศร้าเสียขนาดนี้?」\nยูอูฮาชิเข้าใกล้มา\nเขาเพิ่งกินทาสของทอเรสนั้น และกำลังดูดอย่างพอใจ\nใช่ ข้าได้สัญญากับเขา ขอเพียงฆ่าทรราช นอกจากเสรีภาพ เขายังสามารถกินชีวิตบริสุทธิ์อีกหนึ่งพันคนต่อไป\nเขาเข้าใจถึงความหมายของไฟนี้หรือไม่?\nเขาเข้าใจถึงการรับใช้ทรราชที่หมดหวังนี้หรือไม่?\nข้าเกรงว่าไม่\nเขาเป็นสัตว์ตัวหนึ่งเท่านั้น\n\n「โรมเหมือนซากปรักหักพัง」 สัตว์กล่าว\n「หรืออาจกล่าวได้ว่าประเทศของเจ้า โลกทั้งหมด...\nในสายตาของข้า มันทั้งไม่มีความหมาย และไม่มีที่สิ้นสุด\nเจ้าร้องไห้ ต่อสู้กันเอง ทำสิ่งที่ไร้ผลและไม่มีความสำคัญ...\nตรงไปตรงมา ข้าไม่เข้าใจ」\n\nข้าจ้องมองร่างกายที่มีรอยแผลเป็นของเขา\nนี่คือโกเล็มที่สร้างขึ้นจากเลือดเนื้อของคนหลายล้านคน มันถูกทำลาย และประกอบขึ้นใหม่ตลอดหลายร้อยปี เหมือนเช่นโรม\n「แล้วเจ้าเล่า? เจ้าเป็นซากปรักหักพังด้วยหรือไม่?」\n「อาจจะ」\nเขายืดตัวขึ้นแผ่ กำลังมองแสงทองคำไกล ๆ ที่ลุกขึ้น\n「แต่ข้าไม่สนใจ」"
  },
  CollectionHall_127154_Title = {
    Text = "งานสำราญเลือด"
  },
  CollectionHall_127155_Desc = {
    Text = "พระเจ้าผู้ทรงอำนาจแห่งสกรูหาย โปรดฟังคำอธิษฐานของข้าพเจ้า。\nโปรดส่งคำทำนายของท่านมาให้ข้าพเจ้า และมอบการเปิดเผยให้กับข้าพเจ้า，\nเพื่อให้ข้าสามารถฟื้นฟูอาณาจักรของท่าน。\nในดินแดนที่ไม่มีศรัทธานี้ ในผืนดินที่ถูกล้อมรอบด้วยมหาสมุทร，\nโปรดตั้งเสาหินของท่านขึ้น และสร้างวิหารของท่าน。\n\nองค์พระผู้เป็นเจ้าผู้ทรงอำนาจในหุบเหว โปรดรับของถวายนี้จากข้าพเจ้า。\nเลือดและเนื้อที่บริสุทธิ์มาจากลูกแกะในคืนพระจันทร์เต็มดวง，\nหัวใจที่แข็งแกร่งมาจากวัวผู้ที่โตเต็มที่，\nดวงตาที่เฉียบคมมาจากนกอินทรีที่บินสูง，\nกระดูกที่แข็งแกร่งมาจากปลาวาฬที่ล่องลอย。\nลาพิส ลาซูลีคือบัลลังก์ของท่าน ทองคำคือมงกุฎของท่าน，\nโปรดมอบความฝันของท่านให้กับข้า แจ้งข่าวสารจากพระวาจาของท่าน，\nเพื่อให้ข้าสามารถฟื้นฟูร่างกายของท่าน。\n\nในหุบเหวที่อยู่ใต้ธารน้ำแข็ง ในดินแดนใต้ทะเล，\nโปรดอุทิศแม่ที่เกิดในเวลาที่ถูกต้อง。\nพระราชาแห่งลีมูเรียผู้ทรงรู้ทุกสิ่ง โปรดตอบคำอธิษฐานของข้าพเจ้า。\nตั้งแต่ท่านหลับใหลในทะเล มานานนับพันปี，\nข้าทำการในนามของท่าน ประกาศชื่อเสียงอันงดงามของท่าน โดยไม่เคยหยุดพัก。\nความเชื่อมั่นของข้าคือสิ่งที่มั่นคง และหัวใจของข้าคือความเชื่อมั่น。\nท่านคือพระเจ้าเพียงองค์เดียว เป็นการรวมตัวของผู้ไม่ตาย，\nขอให้ท่านสิ้นสุดการเฝ้ารอของข้า，กลับมาอีกครั้งในโลกนี้ เพื่อให้ข้าได้ยินพระวาจาอันมีปัญญาของท่าน。"
  },
  CollectionHall_127155_Title = {
    Text = "พลังแห่งความศรัทธา"
  },
  CollectionHall_127156_Desc = {
    Text = "เมื่อออรีตาเกิดขึ้น ผลกระทบจากน้ำท่วมใหญ่ในเมืองได้ลดลงอย่างสิ้นเชิง แต่ในหมู่บ้านห่างไกล ผู้คนยังคงต่อสู้เพื่อความอยู่รอด\n\nน้ำท่วมทำให้ผู้คนเริ่มกลัวมหาสมุทรและแม่น้ำ ผู้ที่สามารถออกไปได้ก็ออกไปแล้ว ขณะนี้ผู้ที่ยังคงอยู่ในหมู่บ้านชาวประมงเล็กๆ นี้ล้วนเป็นผู้หญิงและเด็กที่หาที่ยืนในที่อื่นได้ยาก\nในสถานที่ที่เงียบเหงานี้ ออรีตาคือเด็กคนเดียว\n\nเธอเชื่อมั่นอย่างดื้อรั้นในนิทานที่คุณยายเล่า—พ่อแม่ของเธอกลับไปยังมหาสมุทรแล้ว พวกเขากำลังรอให้ออรีตาเติบโต เมื่อเธอโตขึ้น ทุกคนก็จะได้รวมตัวกันอีกครั้ง กลายเป็นครอบครัวที่มีความสุขอีกครั้ง\n\nในขณะที่เธอยังพูดไม่ได้ เธอเหมือนเคยหลับอยู่ในอ้อมกอดที่อบอุ่น แต่เรื่องราวอื่นๆ เกี่ยวกับพ่อแม่ ออรีตาก็ไม่ค่อยนึกออกแล้ว\nแต่ในฐานะเด็กที่เกิดและเติบโตในสถานที่เงียบสงบ ออรีตาไม่เข้าใจคำว่า 「เหงา」 หรือ 「โดดเดี่ยว」 เธอมีเพื่อนของเธอ\n\nแตกต่างจากผู้ใหญ่ที่กลัวน้ำท่วม ออรีตาไม่เคยกลัวมหาสมุทร\nประชาชนในอาณาจักรของมหาสมุทร ย่อมต้องเป็นมิตรกับทะเล\nออรีตาได้เรียนรู้ที่จะเล่นกับ 「เพื่อนบ้าน」\nเธอเลียนแบบการเคลื่อนไหวของหอยกาบและเต้นรำ เรียนรู้การว่ายน้ำของปลาคลาวด์ในทะเลหญ้า\nเธอคลานอยู่บนหลังของเต่าหญ้าตามกระแสคลื่นไปยังที่ห่างไกลจากแผ่นดิน\nเธอได้เล่นสนุกกับฝูงแมงกะพรุนในมหาสมุทรที่เต็มไปด้วยแสงจันทร์\n\nเธอคือความสุข เธอคือจินตนาการ เธอคือภูต\n\nเธอคือความฝัน\n"
  },
  CollectionHall_127156_Title = {
    Text = "ความฝันแห่งท้องทะเล"
  },
  CollectionHall_127157_Desc = {
    Text = "เห็นหญิงสาวชนบทคนหนึ่งแต่งตัวฟุ่มเฟือยในชุดราตรี เครื่องประดับทองเงิน และพัดขนนก แอบเข้ามาในโลกของชนชั้นสูง...\nไม่มีอะไรที่ไม่เหมาะสมไปกว่านี้อีกแล้ว การล่วงล้ำตำแหน่งที่สูงกว่า...มันช่างน่ารังเกียจจริงๆ...!\nตามที่ฉันพูด ควรบังคับให้คนชั้นต่ำสวมสัญลักษณ์และเข็มกลัดที่เหมาะสม เพื่อไม่ให้เกิดความสับสนกับเรา\n——ดยุคฟิลิป ฮาร์โรลด์\n\nหากคุณอาศัยอยู่ในลอนดีเนี่ยน คุณต้องเคยได้ยินเกี่ยวกับสิ่งที่เรียกว่า 「ผลกระทบของโซเรล」\nยังคงกังวลว่าชุดของคุณจะขายไม่ออกอยู่หรือ? คุณควรอธิษฐานให้มีเส้นสายบ้าง เพื่อที่จะได้ได้รับความโปรดปรานจากคุณนายโซเรล—ใช่แล้ว แม้แต่หมวกหางหมูที่โง่เขลาสุดๆ ถ้ามันอยู่บนหัวของคุณนายโซเรล มันก็จะขายดี\nเธอคือไอดอลของคนยุคใหม่\n—— 「การทดสอบชื่อเสียงของคุณนายโซเรล」 จาก คู่มือดามา\n\nคืนหนึ่งที่มีอากาศแจ่มใสในฤดูร้อน\nเรานั่งอยู่บนระเบียงที่ปูด้วยหินอ่อน ดื่มไวน์ขาวอายุหลายปี พูดคุยเกี่ยวกับบทกวีและสันติภาพในโลก\nแล้วเกิดเหตุการณ์บางอย่าง@4\nพูดให้ตรงประเด็น? อา ขอโทษครับ...\nโดยรวมแล้ว ผู้หญิงคนนี้หลอกฉันไปสามพันเลโอฟัง สองทรัพย์สินในซูริแลนด์ และหัวใจที่จริงใจ!\n—— ท่านอัศวินผู้ซึ่งไม่ประสงค์ออกนาม"
  },
  CollectionHall_127157_Title = {
    Text = "ในนามของกุหลาบ"
  },
  CollectionHall_127158_Desc = {
    Text = "แยกออก ประสบการณ์ หลั่งไหล เข้าสู่การรุกราน \n\n สำหรับรากคำในภาษาฟีลิสติน 「p-l-sh」 ที่แท้จริง บรรดานักวิชาการในพระคัมภีร์มักมีความคิดเห็นที่แตกต่างกันอยู่เสมอ \n ครั้งแรกในชีวิต โกลิอัทรู้สึกว่าพวกเขาเหล่านี้ยังมีความรู้จริงๆ เพราะคำสั้นๆ สี่คำนี้แทบจะสรุปชีวิตของเขาในฐานะชาวฟีลิสตินได้ \n\n ชาวฟีลิสตินเป็นชนชาติที่มีชื่อเสียงในทะเล \n พวกเขาเป็นฝูงฉลามหางยาว ที่ตามกลิ่นเลือดไปยังเกาะที่สามารถอาศัยอยู่ได้ และฆ่าชาวพื้นเมืองทั้งหมดที่นั่น \n\n ชาวฟีลิสตินไม่รู้จักเหน็ดเหนื่อย \n พวกเขาไม่เคยหยุดพัก เมื่อทุกอย่างสงบลง ยีนที่ไม่สงบของพวกเขาก็ผลักดันให้พวกเขาออกไปค้นหาสัตว์ที่ล่าใหม่ \n\n ชาวฟีลิสตินไม่สนใจวันพรุ่งนี้ \n พวกเขามักใช้จ่ายทรัพย์สินที่ปล้นมาอย่างรวดเร็ว ดื่มไวน์จนหยดสุดท้าย แล้วขยายพันธุ์ ต่อสู้ หักหลัง... \n\n เมื่อเรือออกเดินทาง โกลิอัทหันกลับไปมองเส้นทางที่เรือได้ลากผ่านผิวน้ำ \n เลือดของชาวฟีลิสติน เลือดของชาวพื้นเมือง เลือดของศัตรู เลือดของนกทะเล... \n พวกมันไหลรวมกัน เหมือนกับหมึกสีแดงเข้มที่ไหลเข้าสู่สีน้ำเงินอันไร้ขอบเขต \n\n วันถัดมา ดวงอาทิตย์ขึ้นเหมือนเดิม น้ำทะเลเคลื่อนไหวและกระพริบเหมือนทองคำที่แตกละเอียด ทุกอย่างก็หายไปไม่มีร่องรอย \n พวกเขาอยู่ในมหาสมุทร แต่มหาสมุทรกลับลืมพวกเขา。"
  },
  CollectionHall_127158_Title = {
    Text = "ดาบไททัน"
  },
  CollectionHall_127159_Desc = {
    Text = "ตำนานเกี่ยวกับอารยธรรมที่จมอยู่ใต้ทะเลถูกเล่าขานกันในหมู่ชาวคาชูเรีย\n\nตามตำนานกล่าวว่า ก่อนที่จะมีการบันทึกในประวัติศาสตร์ การเคลื่อนที่ผิดปกติของดาวฤกษ์ทำให้อารยธรรมยุคก่อนประวัติศาสตร์จมลงสู่มหาสมุทร และชาวคาชูเรียก็คือผู้สืบทอดของอารยธรรมดังกล่าว\nนอกจากการค้าขายและการประมง เป้าหมายสำคัญอย่างหนึ่งที่ชาวคาชูเรียออกทะเลก็คือการค้นหาสิ่งที่สูญหายจากบรรพบุรุษ\nพวกเขาเชื่อว่าหญิงสาวที่เกิดในช่วงตำแหน่งดาวที่เฉพาะเจาะจงจะมีการเชื่อมโยงกับอารยธรรมบรรพบุรุษ เธอจะสามารถชี้นำตำแหน่งของอารยธรรมที่จมอยู่ใต้ทะเล และยังสามารถปกป้องเรือจากพายุ\n\nฮิลีย์สเตอร์คือผู้ที่ถูกเลือกเช่นนั้น\nเธอถูกมัดอยู่บนเสาเรือที่มีใบเรือสีขาวสูงลิ่ว มองลงไปที่มนุษย์ที่ยุ่งวุ่นวายด้านล่าง\nเธอไม่สนใจและไม่แปลกใจ\n\nฮิลีย์สเตอร์สามารถรับรู้สภาพอากาศจากลมทะเลและการเคลื่อนไหวของนกทะเล บางครั้งเธอก็สามารถสัมผัสได้ถึงกลิ่นอายจากดินแดนที่หลับใหลอยู่ไกลโพ้น\nเธอเกิดมาเพื่อเป็นของทะเล เป็นของเรือเดินทะเล—ฮิลีย์สเตอร์มักจะคิดเช่นนี้ ความจริงที่เธอถูกกักขังดูเหมือนจะไม่ทำให้หัวใจของเธอสั่นสะเทือน\nบางครั้งเธอจะออกห่างจากเสาเรือ เพื่อไล่ตามนกขาวที่บินอยู่ในอากาศ ในช่วงนั้นเรือก็จะติดตามเธออย่างไม่ยอมปล่อย\nผู้คนเชื่อว่าหญิงสาวคือสัญลักษณ์ของการเดินเรือที่ราบรื่น เรือที่ได้รับพรจะสามารถกลับบ้านอย่างปลอดภัย และนำมาซึ่งความมั่งคั่งและอารยธรรมที่ก้าวหน้า\nแต่เธอกลับไม่รู้เรื่องนี้เลย。"
  },
  CollectionHall_127159_Title = {
    Text = "ใบเรือแห่งญาณสอดส่อง"
  },
  CollectionHall_127160_Desc = {
    Text = "ดึง ดึง ดึง\nเสียงก้าวเดินค่อยๆ เหยียบส่วนใกล้เข้ามา บุรุษผู้แต่งกายด้วยหมวกทรงสุภาพเดินผ่านซากปรักหักพังและมายืนอยู่ต่อหน้าผู้เฝ้ารักษาที่ใกล้หมดแรง\nบุรุษสุภาพ: คุณมาทำอะไรที่นี่?\n\n(บุรุษสุภาพมีปัญหาการพูดติดอ่างอย่างรุนแรง และผู้เฝ้ารักษามักพูดวกวน เพื่อความสะดวกในการอ่าน โปรดเราตัดบางจุดสำคัญในบทสนทนาออก)\n\nผู้เฝ้ารักษา: ฉันกำลังเฝ้าดูศูนย์ขังนักโทษ\nบุรุษสุภาพมองไปรอบๆ บริเวณท้องร้างที่ไม่มีคนและซากที่กำลังพังทลายช้าๆ จากการกัดกร่อน\nบุรุษสุภาพ: แต่ที่นี่ไม่มีทั้งศูนย์ขังและไม่มีนักโทษ อาณาจักรของคุณไม่มีอยู่นานแล้ว\nผู้เฝ้ารักษา: ฉันกำลังเฝ้าดูศูนย์ขังนักโทษ\nบุรุษสุภาพ: ทำไม?\nผู้เฝ้ารักษาเงยหน้าขึ้น ใบหน้าอ่อนวัยที่ยังไร้เดียงสาทว่าซึ่งเต็มไปด้วยความไม่เข้าใจและความมั่นใจ\nผู้เฝ้ารักษา: ฉันไม่รู้... ฉันอยากกลับบ้าน\nผู้เฝ้ารักษา: ฉันเฝ้าดูศูนย์ขังแทนท่านท่านผู้สูงไว ท่านมีความสุข ฉันก็จะกลับบ้านได้\nไม่รู้ว่าท่านผู้สูงไวคนนั้นเป็นใคร และทำไมต้องเฝ้าแทน เธอเองก็ไม่แน่ใจ\nบุรุษสุภาพไม่ถามต่อ เหมือนกับว่านี่คือเรื่องธรรมดาที่เข้าใจได้\nบุรุษสุภาพ: บ้านเกิดคุณ เป็นยังไง?\nผู้เฝ้ารักษา: บ้านเกิดฉันมีแค่ฤดูหนาวกับเวลากลางคืน และมีป่าไม้และทะเลไม่มีที่สิ้นสุด\nบุรุษสุภาพ: ฟังดูไม่เหมาะแก่การอยู่อาศัย\nผู้เฝ้ารักษา: ฉันไม่ชอบเวลากลางวัน เห็นมั้ย ฉันสร้างจากขี้ผึ้ง ถ้าฉันสัมผัสกับแสงแดด ฉันจะหายไป\nผู้เฝ้ารักษา: ดังนั้น ฉันสามารถซ่อนตัวที่นี่ ไม่สามารถกลับบ้านเองได้\nบุรุษสุภาพคิดหนักแล้วพยักหน้า เขาดูตื่นเต้นทันที\nบุรุษสุภาพ: ช่างบังเอิญเหลือเกิน คุณสร้างจากขี้ผึ้ง ส่วนฉันพอดีกับที่เป็นช่างปั้นขี้ผึ้ง\nบุรุษสุภาพ: เรามาแลกเปลี่ยนกันเถอะ — ฉันสามารถทำให้คุณเดินได้ภายใต้แสงแดด ฉันยังช่วยคุณหาทางกลับบ้าน ในการแลกเปลี่ยน คุณต้องเป็นผู้ช่วยฉัน\nผู้เฝ้ารักษา: ผู้ช่วยคืออะไร?\nบุรุษสุภาพ: คุณสามารถช่วยฉันเฝ้าพิพิธภัณฑ์ขี้ผึ้ง มันต่างจากศูนย์ขังแห่งนี้ มันคือศิลปะ และศิลปะแข็งแรง ไม่มีวันพังทลาย\nผู้เฝ้ารักษา: ศิลปะเก่งขนาดนั้นเลยเหรอ?\nบุรุษสุภาพหัวเราะอย่างมีความสุข\nบุรุษสุภาพ: ใช่ มันเก่งขนาดนั้นเลย\n\nตอนจบของเรื่อง ผู้เฝ้ารักษาเดินตามบุรุษสุภาพไปแบบไม่คิดอะไร เหมือนกับตอนที่เธอมาที่ศูนย์ขังแห่งนี้อย่างไม่คิดอะไรมาก่อน\nเธอเป็นคนที่ปรับตัวเข้ากับสภาพแวดล้อมเสมอ。"
  },
  CollectionHall_127160_Title = {
    Text = "ลอยล่องในห้วงตัณหา"
  },
  CollectionHall_127161_Desc = {
    Text = "คุณเหยียบย่างไปยังทุ่งรกร้างที่ไร้ผู้คน\nร่องรอยของกิจกรรมของมนุษย์ได้หายไปนานแล้ว สัตว์โลกที่จิตวิญญาณเหือดแห้งต้องดิ้นรนอย่างยากลำบากในเถ้าถ่านและฝุ่นละออง\nการมีชีวิตอยู่ที่นี่ไม่ควรค่าแก่การอิจฉา ไม่มีใครรู้จุดหมายปลายทางของการเดินทาง เพียงแต่วนเวียนอยู่ในภาพลักษณ์ที่ไม่มีที่สิ้นสุด\nจนกระทั่งก้าวของพวกเขาชะงักงัน ล้มลงกับพื้น มองขึ้นไปที่ฟ้า ยื่นมือออกไปเรียกหา——\n\nขอให้การเดินทางของฉันสิ้นสุดลง\nด้วยซากศพเป็นดินอุดมสมบูรณ์ เป็นอาหาร เป็นแหล่งกำเนิด ให้ต้นอ่อนที่อ่อนแอเติบโตขึ้นใหม่。"
  },
  CollectionHall_127161_Title = {
    Text = "เกิดใหม่ในดินแดนที่สูญเสีย"
  },
  CollectionHall_127162_Desc = {
    Text = "เธอเคยตั้งคำถามในกลางดึกถึงหมื่นครั้ง ว่าทำไมเธอถึงต้องทนทุกข์ทรมานอย่างไม่สิ้นสุด?\nไม่มีใครตอบ.\nเสียงกระซิบผ่านลำคอที่แหบแห้งกลายเป็นเศษซาก ไม่ได้ส่งถึงหูของเทพเจ้าใดๆ.\nความเจ็บปวดของเธอยังคงยาวนานและยากที่จะบรรเทา จนค่อยๆ หมักหมมกลายเป็นหนอง กลายเป็นความเกลียดชังที่เข้มข้นขึ้นเรื่อยๆ.\nจู่ๆ วันหนึ่ง เธอพบว่าคนรอบข้างเริ่มมีของเหลวสีดำซึมออกมา คล้ายกับเลือดที่ไหลออกจากร่างกายของเธอ.\nพวกเขาเริ่มบ้าคลั่งอย่างรวดเร็ว เหมือนกับเธอ.\nบางทีนั่นอาจเป็นความเจ็บปวดของพวกเขา เธอมองดูด้วยสายตาที่เย็นชา และรู้สึกถึงความพึงพอใจเล็กน้อย.\nแต่ถ้านั่นคือความเจ็บปวด เธอไม่ใช่ถูกกลืนกินโดยสีดำไปนานแล้วหรือ?\nเธอเข้าใกล้สีดำที่เหลือทิ้งไว้ แต่กลับได้รับอิสรภาพโดยไม่คาดคิด.\nอิสรภาพไม่ได้ให้การปลดปล่อยแก่เธอ เธอเหมือนปีศาจที่ถูกเนรเทศในนรกมานานพันปี ความปรารถนาในใจของเธอถูกกัดกร่อนโดยความเกลียดชังจนหมดสิ้น.\nร่างกายของเธอติดอยู่ในโซ่ตรวน จิตใจของเธอเต็มไปด้วยน้ำหนัก.\nมีเพียงเสียงร้องที่เศร้าสร้อยเท่านั้นที่จะล้างบาปให้กับจิตวิญญาณที่หนักหน่วงของเธอ ทำให้เธอหายใจได้อย่างสะดวก.\nมาเถอะ ลิ้มรสที่ฉันเคยลิ้มรส ให้เธอกลายเป็นฉัน.\nเธอค้นพบว่าภาสีแดงเป็นสีที่สวยงามเพียงใด.\nเธอ finally เข้าใจว่า ความเจ็บปวดไม่มีเหตุผล.\nไม่ว่าจะดื่มเองหรือชวนคนอื่นมาลิ้มลอง.\nคืนนี้เธอเทเหล้าขม เตรียมเชิญชวนทั้งเมือง.\n"
  },
  CollectionHall_127162_Title = {
    Text = "จมสู่สีชาด"
  },
  CollectionHall_127163_Desc = {
    Text = "เรือของฉันถูกสิ่งใดบางอย่างพันรัดแน่น ใบพัดพยายามดิ้นรนอย่างยากลำบาก เสียงนั้นน่าหวาดกลัว。\nเมฆฝนกำลังรวมตัวอยู่เหนือศีรษะเรา เมฆสีดำม้วนตัวพร้อมฟ้าผ่า。\nเสียงฟ้าร้องฟาดลงมาที่เสาเรือในทันที ใบพัดหลุดจากการพันรัดและเริ่มหมุนอีกครั้ง。\nฉันถอนหายใจออกมา แต่หัวหน้าช่างเครื่องกลับเริ่มกรีดร้อง。\n\nน้ำทะเลผสมกับของเหลวเหนียวหนืดชนิดหนึ่ง ในพายุที่รุนแรง กลิ่นหอมถูกพัดไปไกลตามลม ฉันได้กลิ่นเพียงแต่ความตาย。\nแต่ฉันตระหนักว่า ของเหลวที่เปล่งแสงเรืองรองนั้นคือเลือดชนิดหนึ่ง。\nเพื่อนที่รักที่สุดของฉัน เรือที่ฉันไว้วางใจที่สุด ได้ใช้กำลังทั้งหมดก่อนที่จะจม—ใบมีดที่ควรจะตัดน้ำทะเลได้ได้ตัดเข้าที่หนวดของมอนสเตอร์อย่างรุนแรง。\n\nนี่คือสัญญาณแห่งโชคดี! เราจะสามารถออกจากพายุได้ในไม่ช้า!\nฉันกำลังคิดที่จะปลอบลูกเรือของฉัน แต่ในขณะที่ฉันเงยหน้าขึ้น มีแสงสว่างปรากฏอยู่กลางทะเลมืด。\nนั่นคือประภาคารใช่ไหม? จะเป็นไปได้อย่างไร? ไม่ ไม่สามารถเป็นไปได้。\nที่นี่คือกลางมหาสมุทร ดินแดนที่ใกล้ที่สุดอยู่ห่างออกไปหลายร้อยไมล์ทะเล จะมีใครอยู่ และจะมีใครสามารถสร้างประภาคารที่นี่ได้?\n\nลูกเรือของฉันเริ่มร้องไห้ เริ่มสวดมนต์ เริ่มร้องเพลงบ้านเกิดด้วยเสียงประสานกัน。\nแล้วประภาคารนั้นก็ดับลงอย่างกะทันหัน。\nแสงทั้งหมดหายไปและพายุที่คำรามก็กลายเป็นฝนเล็กน้อยตกลงบนดาดฟ้า。\nลูกเรือสรรเสริญพระเจ้าผู้มีเมตตา ยินดีในความรอดชีวิตจากภัยพิบัติ。\nแต่ฉันกลับเห็นสิ่งที่ชัดเจน。\n\nสิ่งที่หายไปในแสงสว่างนั้น คือผู้หญิงที่มีรูปร่างงดงามคนหนึ่ง。"
  },
  CollectionHall_127163_Title = {
    Text = "ท่ามกลางพายุฝน"
  },
  CollectionHall_127164_Desc = {
    Text = "เมื่อวีรบุรุษสิ้นสุดการเดินทางอันยิ่งใหญ่ของเขา ผู้คนก็ปิดหน้าสุดท้ายของหนังสือภาพและหลับไปอย่างหนักหน่วง。\n\nค่ำคืนที่ยาวนานกำลังจะมาถึง เรื่องราวของเฮลอตเพิ่งเริ่มต้นขึ้น。\n\nเธอเดินตามแนวชายฝั่งที่ยาวเหยียดไปทางเหนือ ข้ามลำธาร ปีนภูเขา จนถึงสุดขอบดินแดนที่หนาวเย็นจัด。\nผ่านไปหลายปีนับตั้งแต่การต่อต้านที่ทำให้โลกตกตะลึง เฮลอตไปถึงที่ไหนก็ตาม สภาพอากาศก็เป็นใจ ทุกสิ่งล้วนเป็นไปด้วยดี ความสัมพันธ์ระหว่างทาสและนายยังคงรักษาสมดุลที่ละเอียดอ่อน การต่อต้านอย่างรุนแรงกลับดูน่าอึดอัดและน่าขำ。\nเธอถูกตั้งคำถาม ถูกเย้ยหยัน และในที่สุดก็ถูกลืม。\nแต่เธอไม่เคยโต้แย้ง。\n\nนักรบเฮลอตมาที่ไปอย่างไร้ร่องรอย เธอได้ฝังเมล็ดพันธุ์แห่งเสรีภาพลึกลงไปในกลางแผ่นดินระหว่างทะเล。ห้าปี สิบปี หนึ่งร้อยปี...\nวันหนึ่งมันจะงอกงามทะลุพื้นดิน เติบโตอย่างแข็งแกร่ง。\n\nไม่มีใครรู้ว่าที่ฝังศพสุดท้ายของนักฆ่าสปาร์ตานั้นอยู่ที่ไหน มีข่าวลือว่าอดีตเพื่อนสนิทของเธอ อิบามิณดา ได้เก็บศพของเธอไว้。\nหลายปีต่อมา เมื่อคุณเดินผ่านเนินหญ้าที่มีดอกมะลิบานสะพรั่ง อาจจะเห็นหลุมศพเล็กๆ แห่งหนึ่ง ที่เขียนไว้ว่า：\n\nที่หญ้ากลุ่มนี้ฝังศพของนักรบ หรือจะกล่าวว่า\nเธอเคยเป็นนักรบ\nเธอคือบุตรสาวของเบอริคลีส และเป็นความภูมิใจของเกาะทีโล\nกวีฟลาคัสสรรเสริญเธอว่ามีความกล้าหาญในการต่อสู้\nสปาร์ตานผมดำรู้ดีถึงความสำเร็จของเธอ"
  },
  CollectionHall_127164_Title = {
    Text = "ทลายโซ่ตรวน"
  },
  CollectionHall_127165_Desc = {
    Text = "A. F.@1ปี@1เดือน@1วัน\n\n08:00\n\nทำการประกอบชิ้นส่วนหมายเลข 107 ถึง 133\n\nชิ้นส่วนประเภท C เหลืออีกแค่นิดเดียว เมื่อเสร็จแล้วจะนำไปใช้เป็นแกนพลังงานของหุ่นยนต์กลไก 「ติ๊กต็อก」\n\nเดิมทีฉันตั้งใจจะประกอบเอง แต่@2บอกว่า หัวหน้าต้องเรียนรู้ที่จะไว้วางใจเพื่อนร่วมงานของตัวเอง\n\nพูดได้ดีจริงนะ ทั้งที่เธอเองนั่นแหละที่ตรวจสอบชิ้นส่วนจนดึกดื่น\n\n-------\n\nA. F.@1ปี@1เดือน@1วัน\n\n00:21\n\nมอเตอร์ MF311000 ประกอบเสร็จสมบูรณ์ เฟืองขบกันสนิท ท่อส่งไม่มีอุดตัน ขณะนี้ระบบทุกอย่างทำงานปกติ กำลังจะทำการปรับแก้ขั้นสุดท้าย\n\n13:07\n\nเชื่อมต่อพลังงานพิเศษ S แล้ว มอเตอร์ MF311000 ทำงานได้ดี เข้ากันได้ดีกับร่างสังเคราะห์หมายเลข EA307850 ร่างสังเคราะห์ทำงานเป็นปกติ\n\n@2มองโลกในแง่ดี เธอคิดว่าครั้งนี้เราจะไปได้ไกลกว่าครั้งก่อน ฉันเตือนเธอว่าอย่าลืมสิ่งที่เกิดขึ้นตอนพยายามปลุกครั้งที่ห้า เธอก็อุดหูแล้วบอกว่าไม่ได้ยิน ครั้งนั้นถ้าไม่ใช่เพราะฉันตอบสนองเร็ว เปลวไฟจากแกนพลังงานที่ลุกไหม้เองคงเผาผมเธอหมดหัวไปแล้ว\n\nน่าจะให้เธอลองเป็นหัวโล้นดูสักครั้ง บางทีเธออาจจะเรียนรู้ที่จะระมัดระวังมากขึ้นก็ได้\n\n-------\n\nA. F.@1ปี@1เดือน@1วัน\n\n14:55\n\nการเตรียมการขั้นสุดท้ายเสร็จสิ้น พลังงานพร้อม อุปกรณ์ยึดตรึงเปิดใช้งานแล้ว สถานะการยึดตรึง: ดี ลำตัวจะทำการติดตั้งหลังจากการปลุกเสร็จสมบูรณ์\n\n15:00\n\nเริ่มการทดลองเปิดใช้งาน 「ติ๊กต็อก」 ครั้งที่ 13\n\n15:05\n\nลำตัว EA307853 ทำงานปกติ มอเตอร์ MF311000 ทำงานปกติ ข้อต่อคอของ 「ติ๊กต็อก」 เคลื่อนไหวปกติ ชิ้นส่วนศีรษะของ 「ติ๊กต็อก」 ทำงานปกติ\n\n15:15\n\n「ติ๊กต็อก」 ดำเนินคำสั่งกะพริบตา ติดตามสายตา และอ้าปากได้สำเร็จ มอเตอร์มีอาการร้อน แต่ยังอยู่ในเกณฑ์ที่ยอมรับได้\n\nกำลังจะทำการติดตั้งชิ้นส่วนแขนขา ขอให้สวรรค์คุ้มครองให้ครั้งนี้ราบรื่น\n\n18:07\n\nขณะดำเนินคำสั่งเดิน แกนมอเตอร์หลอมละลาย วงจรไหม้ พลังงานพิเศษ S ไม่ได้รับความเสียหาย\n\n@2ปกป้องพลังงานพิเศษนี้มาก แม้แต่ฉันก็ถูกห้ามไม่ให้แตะต้อง ฉันคิดว่าฉันเข้าใจได้ มันเป็นวัตถุลึกลับจริงๆ ดูเหมือนเงินโลหะธรรมดา ไม่เหมือนจะมีความสามารถในการกักเก็บพลังงานเลย แต่กลับสามารถจ่ายพลังงานให้หุ่นยนต์กลไกได้จริงๆ แถมอุณหภูมิสูงขนาดนั้นก็ไม่ได้ทำให้มันเสียหาย มันเหลือเชื่อจริงๆ\n\nถ้าสิ่งนี้สามารถผลิตเป็นจำนวนมาก หรือขุดได้ในปริมาณมาก...\n\nบางทีฉันควรหาวันไปถามเธออีกครั้ง ก็ไม่รู้ว่าเธอจะทุ่มเวลาให้กับหุ่นตัวนี้อีกนานแค่ไหน วันไหนที่เธอกลายเป็นหุ่นเสียเอง ฉันก็คงไม่แปลกใจ\n"
  },
  CollectionHall_127165_Title = {
    Text = "แกนกลางที่มลาย"
  },
  CollectionHall_127166_Desc = {
    Text = "\"พวกเราใช้ทองเหลืองและเหล็กกล้าธรรมดา วัดเส้นทางของดวงดาว แต่ห้วงลึกที่ไม่มีสิ้นสุดนั้นมีอัลกอริทึมของตัวมันเอง ความไม่แน่นอนที่ไม่อาจคาดเดาได้\"\n ท่ามกลางเรือเดินสมุทรที่ค่อยๆ จมลง โคปเปอร์แซนท์ได้เริ่มบทสวด \"เพลงไว้อาลัยของนักเดินเรือ\"\n เธอรู้อยู่แล้วถึงชะตากรรมของตัวเอง และได้เลือกชะตากรรมนั้นแล้ว ดังนั้นเมื่อเผชิญหน้ากับความตาย เธอไม่มีความหวาดกลัว มีเพียงแต่ความสงบ—สงบอย่างที่เผาไหม้ สงบอย่างที่ทำภารกิจนำทางครั้งสุดท้ายให้สำเร็จ\n แต่แสงไฟที่ลุกไหม้ช่างร้อนแรงเกินไป เธอไม่สามารถมองเห็นทางข้างหน้า ไม่สามารถเปล่งเสียงออกมาได้ และไม่สามารถโบกธงนำทางได้ ภายใต้การนำทางที่บกพร่องเช่นนี้ เรือจะสามารถเดินทางได้ถูกต้องหรือไม่?\n เธอไม่รู้ และนั่นทำให้เกิดความกลัวและความกังวลในใจเธอ\n ขณะนั้น \"เพลงไว้อาลัยของนักเดินเรือ\" ได้เสนอคำแนะนำขึ้นมา: \"โอ้เจ้าหนุ่มสาวผู้นำทางทั้งหลาย ในท้ายที่สุดเจ้าจะถูกทะเลเค็มโอบกอด กลายเป็นแสงไฟฟอสฟอรัสที่นำทาง\"\n แสงไฟฟอสฟอรัส? โคปเปอร์แซนท์นิ่งเงียบ เธอเคยได้ฟังตำนานเกี่ยวกับแสงเซนต์เอ็ลโมในหมู่ชาวเรือมาแล้ว แต่ร่างมนุษย์ธรรมดานั้นจะสามารถกลายเป็นแสงศักดิ์สิทธิ์ที่ส่องสว่างโลกได้อย่างไร?\n แต่ถึงแม้จะปราศจากความหวัง โคปเปอร์แซนท์ยังคงสวดภาวนาในใจของเธออย่างไม่หยุดยั้ง: สวดภาวนาให้เธอสามารถปฏิบัติหน้าที่ให้สำเร็จลุล่วงในครั้งสุดท้าย\n ไม่มีใครได้ยินคำสวดภาวนานี้นอกจากตัวโคปเปอร์แซนท์เอง แต่นั่นก็เพียงพอแล้ว—\n ในความมืด หัวใจสีเงินได้ใช้มวลสารละลายเป็นเชื้อเพลิง ระเบิดแสงสว่างอันแรงกล้า และเติมเต็มความปรารถนาชิ้นสุดท้ายของเธอ\n \"บัญชีดำแห่งกระแสน้ำจะจารึกชื่อของเจ้า ให้คลื่นที่โหมกระหน่ำบรรเลงเพลงไว้อาลัยนิรันดร์เพื่อเจ้า\"\n สุดท้าย เธอก็ได้ตายลงเช่นเดียวกับที่ \"เพลงไว้อาลัยของนักเดินเรือ\" ได้กล่าว\n แต่เธอก็ได้ก้าวข้าม \"เพลงไว้อาลัยของนักเดินเรือ\" ไปอีกขั้นแล้ว\n นั่นเป็นความทะนงตนและคำเตือนของมนุษย์ที่เผชิญหน้ากับทะเล แต่ในเวลานี้ เธอได้กลายเป็นแสงเซนต์เอ็ลโม แสงสว่างนิรันดร์ที่นำทางเรือต่อไป。"
  },
  CollectionHall_127166_Title = {
    Text = "การชี้นำของไฟศักดิ์สิทธิ์"
  },
  CollectionHall_127167_Desc = {
    Text = "เธอถูกเรียกว่าบุตรแห่งคำสาปผู้เกิดมาพร้อมกับความตาย เป็นบุตรสาวไร้พรแห่งโชคชะตา\n\"ผ้าห่อตัว\" ของเธอกับน้องสาวเพิ่งแตกออก แสงสีสันเจิดจรัสพวยพุ่งผ่านช่องว่างออกมาและแตะพื้นดิน ในชั่วพริบตา หญ้าเขียวเหี่ยวเฉา ดอกไม้แหลกสลาย แม้แต่ต้นไม้ใหญ่ที่ไกลออกไปหรือปลาที่ว่ายอยู่ในทะเลสาบก็ถูกดูดชีวิตจนกลายเป็นร่างไร้จิตวิญญาณ\nเผ่าพันธุ์ของเธอตกใจกลัว รีบย้าย \"ผ้าห่อตัว\" ทั้งหมดออกไปให้ไกล เธอต่อสู้ดิ้นรนเพื่อฉีกขาดห่อตัวนั้นออก เหมือนนกที่เพิ่งฟักไข่พยายามทะลุกระดอง แต่มือที่เธอยื่นออกไปกลับถูกหลีกเลี่ยงด้วยความรังเกียจ ทุกสิ่งที่พบเห็นมีเพียงใบหน้าที่แสดงความเกลียดชัง\nมีแค่น้องสาวของเธอเท่านั้น ที่เกิดในคืนเดียวกับเธอ แต่เติบโตเร็วกว่าเธอเสมอ ผู้ถือเธอไว้ในอ้อมแขนและร้องเพลงกล่อมด้วยเสียงที่ราวกับนกแห่งวิญญาณ\n\"หลับเถอะ หลับเถอะ พี่ที่รักของฉัน\nหลับเถอะ หลับเถอะ ฝันดีจะมาถึงในที่สุด\"\n\nเธอไม่ควรมีอยู่ ถ้าเธอไม่มีอยู่ น้องสาวที่เปล่งประกายของเธอก็จะไม่ได้รับเงาแห่งความบาป\nโอ้ น้องสาวที่น่าสงสารของฉัน เธอมักคิดว่า\n\"ความอยู่รอดนั้นเธอแบกรับไว้ในสิ่งที่ไม่ควรต้องแบกรับ\"\nโอ้ น้องสาวที่น่าสงสารของฉัน เธอมักคิดว่า\n\"พี่จะทำให้เต็มที่เพื่อเธอ\"\n\"หลับเถอะ หลับเถอะ น้องสาวที่รักของฉัน\nหลับเถอะ หลับเถอะ พี่ก็รักเธอ แม้ในความฝัน\"。"
  },
  CollectionHall_127167_Title = {
    Text = "กลืนกินเพลงบรรเลงกล่อม"
  },
  CollectionHall_127168_Desc = {
    Text = "เขาเห็นยอดแหลมของโบสถ์ละลายเหมือนเทียนไข หยดลงบนปีกขาวบริสุทธิ์ของพระ สีสันที่อยู่บนกระจกสีของนักบุญสลายตัวเป็นโครงกระดูกด้วยความรวดเร็ว จากนั้นในชั่วพริบตาก็ถอยกลับกลายเป็นทารก รูปทรงเรขาคณิตที่แหลมคมและกลมมนสวดมนต์ออกมาจากปากของผู้ศรัทธา เต็มไปทั่วทั้งห้องโถง\nเขาเห็นพื้นที่ของสถานีรถไฟพับทบซ้ำไปซ้ำมาเป็นพื้นที่ที่ไม่ใช่ยูคลิด ชานชาลาในระยะไกลอยู่ใกล้แค่เอื้อม ขณะที่จุดตรวจบัตรอยู่ห่างไกลออกไป นาฬิกาในห้องโถงหมุนทวนเข็มนาฬิกา ฝูงชนที่เหมือนกระดูกแห้ง ๆ ดูเหมือนจะถูกเส้นสายที่มองไม่เห็นดึงให้ถอยหลังเดินไป ขี้เถ้าสีม่วงข้นลอยจากก้อนเมฆเข้าสู่ปล่องควันของรถไฟ\nเขาเห็น 「ความว่าง」 ในป่าแปรสภาพเป็นรูปร่าง ต้นไม้ หิน และเถาวัลย์เป็นเพียงเส้นขอบของ 「ความว่าง」 ที่ถูกขีดเขียนเป็นเส้นขอบโปร่งแสง ขนของหงส์เป็นสีโมเสคที่เปลี่ยนแปลงตลอดเวลา ในที่ที่พวกมันว่ายน้ำ น้ำในทะเลสาบแข็งตัวเป็นกระจกสีโปร่ง\nใต้ม้านั่งที่คู่รักนั่งอยู่ เงาสีส้มสดใสพยายามกัดกร่อนข้อเท้าของเจ้าของ\nเขาเห็นโน้ตเพลงในโรงอุปรากรตกลงมาดั่งฝน เขาเห็นสุสานขยับขึ้นลงเล็กน้อย ราวกับผิวหนังของสัตว์ประหลาดที่หายใจอยู่...\nเขาเห็นมากมาย มากมาย เขาบอกสิ่งที่เขาเห็นให้แม่ ครู และเพื่อน ๆ ของเขา เขาวาดสิ่งที่เขาเห็นลงในภาพ เขาต้องการนำโลกในสายตามาให้ผู้คนเห็น แต่คนรอบข้างเขากลับน้อยลง โลกหนึ่งกำลังห่างไกลจากเขามากขึ้น\nแต่ทำไมล่ะ? เขาเพียงแค่บันทึกสิ่งที่เขาเห็นไว้ พิคแมนไม่เข้าใจเลย\nพิคแมนที่เศร้าโศกยืนอยู่หน้ากระจก เขาเห็นซอมบี้ยิ้มให้เขาโดยมีฟันแหลมคมเต็มปาก\n「ไม่มีอะไรสำคัญไปกว่าการได้เห็นความจริงที่เกิดขึ้น ความบ้าคลั่ง ความเคออส ความโลภ... คุณอยากไปดูไหม พิคแมน?」\nพิคแมนผู้สำแดงเดชยิ้มให้เขาแล้วก้าวเข้าสู่กระจก\nเขาเพียงแค่ต้องการเห็นความจริงที่บ้าคลั่งที่สุดด้วยตนเอง แล้ววาดมันลงบนผืนผ้าใบของเขาอย่างซื่อสัตย์\nเขาไม่ใช่มนุษย์และไม่ใช่ซอมบี้\nเขาเป็นเพียงจิตรกรผู้มีลักษณะเหมือนจริง พิคแมน。"
  },
  CollectionHall_127168_Title = {
    Text = "ความขัดแย้งของลัทธิความจริง"
  },
  CollectionHall_127169_Desc = {
    Text = "เมื่อคนคนหนึ่งสามารถรับรู้ถึงอดีตและอนาคตทั้งหมด สิ่งที่รอเขาอยู่ไม่ใช่ความสุขที่รู้ทุกอย่าง แต่เป็นความเศร้าโศกและความสิ้นหวังที่ไม่มีที่สิ้นสุด \nดวงตาของเธอสามารถมองเห็นเส้นด้ายที่อยู่เบื้องหลังทุกสิ่งทุกอย่าง เส้นด้ายข้างหนึ่งเชื่อมต่อกับอดีต และอีกข้างเชื่อมต่อกับอนาคต \nเส้นด้ายนี้ถูกเรียกว่า ชะตากรรม \nเธอมองคนที่ติดตามอยู่ข้างๆ อย่างไร? \nผู้คนมีความดีและความเมตตา ผู้คนมีความหยิ่งและความสงสัย \nแต่ชะตากรรมของคนเหล่านั้นและชะตากรรมของมนุษย์ถูกกำหนดไว้ตั้งแต่เริ่มต้นการพบกันในแต่ละครั้ง \nเธอแน่นอนว่ารักพวกเขา มิฉะนั้นทำไมเธอถึงยื่นมือออกไปช่วยเหลือและให้ประกายไฟอยู่เสมอ \nเธอแน่นอนว่าคาดหวังพวกเขา มิฉะนั้นทำไมเธอถึงเดินเข้าสู่เงาของการเกิดใหม่อย่างมั่นคงในความพินาศ \nเพราะความรัก เธอจึงเต็มไปด้วยความเศร้า \nเพราะความคาดหวัง เธอจึงผิดหวังอยู่บ่อยครั้ง \nเธอติดอยู่ในบึงสีดำ และคอยจัดการกับเส้นด้ายสีดำมากมายอย่างไม่รู้จักเหน็ดเหนื่อย \nวงล้อของชะตากรรมหมุนวนไปเรื่อยๆ \nเธอเห็นเปลวไฟแห่งความโลภกลืนกินท้องฟ้า \nเธอเห็นความหลงผิดที่มืดบอดนำไปสู่การทำร้ายตัวเอง \nเธอเห็นความคิดที่บ้าคลั่งเร่งทำลาย \nความเคออสที่ไร้ระเบียบจะมาถึงเสมอ \nความหวังและความสิ้นหวังหมุนวนไปอย่างไร้ประโยชน์ ตลอดไปไม่มีที่สิ้นสุด \nจนกระทั่งเธอเห็นแสงดาวในความมืดในช่วงเวลาหนึ่ง \nแสงนั้นอ่อนแอ แต่เธออยู่ในความมืดมานานเกินไป \nในขณะที่เธอจ้องมอง น้ำตาก็ไหลออกมา \n"
  },
  CollectionHall_127169_Title = {
    Text = "กรงล้อหลีกเร้น"
  },
  CollectionHall_127170_Desc = {
    Text = "ปีใหม่ที่กำลังจะมาถึง คุณตัดสินใจจัดพิธีที่ไม่เคยมีมาก่อน เพื่อเฉลิมฉลองการเปลี่ยนแปลงของเวลาอย่างสุดยิ่งใหญ่ \n เพื่อสิ่งนี้ คุณได้เตรียมการมาอย่างยาวนาน จุดเทียนให้แสงอบอุ่นส่องสว่างในคืนฤดูหนาวของวิทยาเขต; สร้างแท่นกลางสนามฝึกซ้อม ปูพรมแดงเข้มที่เต็มไปด้วยลวดลาย คุณถึงขั้นตัดริบบิ้นทองคำและผ้าซาตินเงินนับไม่ถ้วนด้วยมือของคุณเอง เพียงเพื่อให้ช่วงเวลานับถอยหลังนี้เกินกว่าความเศร้าสำหรับการจากลา กลายเป็นรอยตราตลอดกาลที่ไม่จางหายเมื่อปีเก่ากับปีใหม่โอบกอดกัน \n แต่... ยังขาดอะไรอยู่ \n คุณเดินเข้าไปในส่วนลึกของโกดังเก่า ปัดฝุ่นออกจนหมด จนในที่สุดพบกับนาฬิกาโบราณเรือนนั้น เปลือกนอกของมันมีรอยขีดข่วน ตัวเข็มได้แตกและหลุดออกไปนานแล้ว แสดงว่ามันไม่สามารถใช้งานได้ \n ในขณะที่คุณรู้สึกสิ้นหวัง ไทอีสก็ปรากฏตัวขึ้น พร้อมกับนาฬิกาเรือนใหม่ที่ยืนอยู่ข้างหลัง \n นาฬิกาเรือนนั้นคุ้นเคยมาก เธอยังคงยิ้มอย่างหยอกล้อ แต่ในดวงตาของเธอซ่อนความอ่อนโยนที่แน่นอน \n 「เป็นไงบ้าง นาฬิกานี้ถ้าคู่กับการเต้นของฉัน จะต้องเป็นพิธีที่ยิ่งใหญ่ที่สุดแน่ๆ」 \n 「นี่... จะไม่ใช่นาฬิกาของทาวิลใช่ไหม?」 \n 「โอ้ คุณก็รู้ว่าเธอเหงาอยู่ในน้ำ มันน่าเบื่อเกินไป」 \n 「ถ้าเราให้เธอเข้าร่วมพิธีของเรา เพื่อรับรู้ความรักของฉัน อาจจะทำให้เธอรู้สึกสนใจขึ้นมาบ้างนะ～」 \n เที่ยงคืนค่อยๆ มาถึง ไทอีสยืนอยู่หน้านาฬิกาขนาดใหญ่ ราวกับเป็นของขวัญที่เวลาได้ห่อหุ้มไว้ \n ริบบิ้นพันรอบร่างของเธอเหมือนดอกไม้ไฟที่ยังไม่ดับ ในแสงไฟที่หมุนวน สร้างคลื่นสีทองแดงและเงินน้ำเงิน ริบบิ้นโบว์ที่อวบอิ่มรอบเอวของเธอ เป็นเชือกสุดท้ายที่ผูกขึ้นโดยปีใหม่—เธอคือของขวัญที่ยิ่งใหญ่ที่สุดของปีเก่า ห่อหุ้มด้วยผ้าซาตินแห่งความสุข รอคอยให้เวลาได้แกะออก \n แขนของเธอค่อยๆ ยกขึ้น นิ้วมือของเธอไล่ตามแสงและเงา สุดท้ายชี้ไปยังนาฬิกาที่แขวนอยู่ข้างหลัง ตัวเลขสิบสองบนหน้าปัดเชื่อมต่อกันกลายเป็นแสงที่กระจายออกไป กระโดดไปตามนิ้วของเธอ \n ผู้คนที่มารวมตัวกันมองไปที่การเต้นรำของไทอีสด้วยความสนุกสนาน ราวกับได้รับอิทธิพลจากบรรยากาศที่มีความสุข เริ่มขยับตามจังหวะของเธอ \n และเมื่อเสียงระฆังดังขึ้น เธอก็กดนิ้วเบาๆ สัมผัสกับจุดเริ่มต้นของความเป็นนิรันดร์ ของขวัญที่ถูกมัดไว้เปิดแขนออก นำเอาความสุขทั้งหมดที่เก็บไว้ในตอนสิ้นปีแปรเปลี่ยนเป็นคำอวยพรที่ลอยฟุ้งกระจายไปทั่วโลก."
  },
  CollectionHall_127170_Title = {
    Text = "ช่วงเวลานับถอยหลัง"
  },
  CollectionHall_127237_Title = {
    Text = "เรื่องเก่าแก่ของเมืองทะเล"
  },
  CollectionHall_127239_Title = {
    Text = "อาณาจักรฟานหลงโบราณ"
  },
  CollectionHall_129601_Desc = {
    Text = "<Title:แนะนำ>\nเด็กสาวที่ใช้ชีวิตอยู่บนเกาะที่โดดเดี่ยว ร่าเริงและเต็มไปด้วยความดุร้าย.\nด้วยบุคลิกที่กระตือรือร้นและพลังที่มีมาแต่กำเนิด หลายคนมักจะปรับตัวไม่ทันเมื่อได้สัมผัสกับความใกล้ชิดที่มากเกินไปของเธอในครั้งแรก แต่เมื่อใช้เวลากับเธอสักระยะหนึ่ง จะพบว่าเธอแค่ต้องการช่วยเหลือเพื่อนๆ อย่างสุดความสามารถ.\nแม้ว่าบางครั้งวิธีการช่วยเหลือของเธอจะแปลกแยกจากคนทั่วไป แต่โดยรวมแล้ว ผลลัพธ์มักจะช่วยให้ผู้ที่ได้รับความช่วยเหลือแก้ปัญหาได้ดีทีเดียว?\nในสภาพที่ไม่สามารถควบคุมพลังของตนเองได้ จะทำให้ห้องทดลองมักเกิดการระเบิดอยู่เสมอ.\nเนื่องจากขาดการศึกษาอย่างจำเป็น บางครั้งมอสจึงต้องใช้ท่าทางอธิบายเป็นเวลานานกว่าจะทำให้ผู้สนทนาเข้าใจความหมายของตน แน่นอนว่ามอสไม่ต้องการให้ฝ่ายตรงข้ามใช้เวลานานในการชี้ให้เข้าใจ เพราะสัญชาตญาณที่ยอดเยี่ยมของเธอสามารถแก้ปัญหานี้ได้ดี.\nสนิทสนมกับนอติลาและผู้พิทักษ์ ตามที่เธอกล่าว สามคนมีข้อตกลงที่จะออกผจญภัยร่วมกัน แต่สำหรับนอติลาแล้ว ไม่มีความทรงจำเกี่ยวกับเรื่องนี้เลย ขณะที่ผู้พิทักษ์กลับไม่พูดถึงประสบการณ์นั้น.\nบางครั้งสามารถเห็นนากทะเลที่สวมหมวกมิซากะอยู่ข้างๆ มอส มอสตั้งชื่อมันว่า「ลูกถ่านขนาดเล็กที่สอง」 ทุกครั้งที่เป็นแบบนี้ งานบางอย่างที่ควรจะเสร็จสิ้นจะหายไปอย่างไร้เหตุผล.."
  },
  CollectionHall_129601_LockTip = {
    Text = "ปลุก「มอส」แล้วปลดล็อก"
  },
  CollectionHall_129601_Title = {Text = "มอส"},
  CollectionHall_129803_LockTip = {
    Text = "ต้องผ่านด่านกิจกรรมจำกัดเวลา「รถไฟความสุขที่วิ่งอย่างรวดเร็ว：ออกเดินทาง」ในด่านใดก็ได้"
  },
  CollectionHall_129803_Title = {
    Text = "รถไฟความสุขที่วิ่งอย่างรวดเร็ว：ออกเดินทาง"
  },
  CollectionHall_129810_Desc = {
    Text = "ในวนลูปที่ไม่สามารถบันทึกได้ ฮวนนิ่ง·รามอน่าก้าวข้ามสวนดอกไม้หลังหอระฆัง \n เธอเหลือบเห็นในสวนกุหลาบ ดอกไม้หลากหลายกำลังบานสะพรั่งอย่างสวยงาม \n หลังจากหยุดพักที่หายาก เธอจึงทิ้งความคิดที่ไร้สาระทั้งหมดและเดินทางต่อไปยังสนามรบสุดท้าย \n โคลนกระเด็นไปยังกลีบกุหลาบสีเลือด ทันใดนั้นก็ถูกเมือก D สีดำกลืนกินไป เหลือไว้เพียงเงาร่างที่โดดเด่นในสายลม."
  },
  CollectionHall_129810_Title = {
    Text = "กุหลาบที่เหยียบย่ำในโคลน"
  },
  CollectionHall_130218_LockTip = {
    Text = "ต้องผ่านด่านใดก็ได้ของกิจกรรมจำกัดเวลา「การเกิดใหม่ที่พลิกกลับ: บันทึกห้องมืด」"
  },
  CollectionHall_130218_Title = {
    Text = "การเกิดใหม่ที่พลิกกลับ: บันทึกห้องมืด"
  },
  CollectionHall_130219_Desc = {
    Text = "นี่คือเกาะที่ไม่มีบันทึกในแผนที่ทะเลใดๆ ตั้งแต่เริ่มมีชีวิต เกาะนี้ไม่มีไวรัสที่เรียกว่า「อารยธรรม」เหยียบย่างลงมาเลย ที่นี่มีเพียงชายหาด ป่าเขา ทะเลที่มองไม่เห็นขอบเขต และ...สาวน้อยคนหนึ่ง................ 「พ่อ แม่ ปลา！」 「อ๊า~~」ปลาโลมาสองตัวว่ายมาที่ขาของสาวน้อยอย่างช้าๆ ส่งเสียงร้องที่ไพเราะและชัดเจน หนึ่งในนั้นแบกสาวน้อยขึ้น อีกตัวหนึ่งรับปลาที่สาวน้อยเพิ่งตีสลบในมือมา แล้วกลืนเข้าไปทั้งตัว 「อ๊า~~」 「เฮ้ เฮ้ มอส! เก่งมาก！」เหมือนเด็กที่ไม่รู้เรื่องรู้ราว สาวน้อยทำท่าทางที่มีพลังเพื่อตอบรับคำชมจาก「พ่อ」และ「แม่」 「วันนี้ พระอาทิตย์! ดีมาก！」 「มอส! พ่อ! แม่! ไปเดินเล่นกัน！」ได้ยินคำพูดของสาวน้อย ปลาโลมาที่แบกสาวน้อยอยู่ส่งเสียงร้องเบาๆ แล้วเริ่มว่ายรอบเกาะอย่างช้าๆ แสงแดดอบอุ่นสาดส่องลงมาที่สาวน้อย ขับไล่ความชื้นเย็นที่ไม่หายไปตั้งแต่หลายวันก่อน ลมอ่อนๆ ปลิวผ่านเส้นผมของสาวน้อย นำพาหายใจอันขี้เกียจของมหาสมุทร เสียงหัวเราะ เสียงน้ำกระทบ เสียงเล่นสนุก ที่เกาะที่แยกตัวออกจากโลก ไม่มีความกังวลจาก「อารยธรรม」เหลือไว้ มีเพียงเสียงหัวเราะที่ดั้งเดิมและบริสุทธิ์ สองสัตว์และหนึ่งคนใช้ชีวิตอย่างไม่มีความกังวลในวันธรรมดาเช่นเคย................ จนกระทั่งเสียงเรียกที่ไม่มีที่สิ้นสุดได้กลืนกินความเงียบนี้หมดสิ้น 「กลับมาเถอะ...กลับมาเถอะ...」 「@1ต้องการคุณ...@2...@4...ต้องการคุณ...」"
  },
  CollectionHall_130219_Title = {
    Text = "สวนอีเดนที่ห่างไกล"
  },
  CollectionHall_130220_Desc = {
    Text = "ดอกแดนดิไลออน เล็กกว่านก เบากว่าสายลม\n\nเมื่อดอกแดนดิไลออนผ่านทุ่งร้างแห่งแรก มันถามหญ้าลมที่กระจัดกระจายอยู่ที่นี่ว่า: พวกเธอขยายพันธุ์อย่างไร?\nหญ้าลมตอบว่า: 「พวกเราปล่อยเมล็ดพันธุ์ล่องลอยไปทุกสารทิศ จนกว่าจะพบดินที่สามารถหยั่งรากได้」\nนักเดินทางผู้พเนจรนั้นไร้บ้าน ดอกแดนดิไลออนถอนหายใจเช่นนั้นแล้วโดยสารสายลมอีกสายบินจากไป\n\nเมื่อดอกแดนดิไลออนผ่านทะเลทรายแห่งที่สอง มันถามกระบองเพชรที่กระจายอยู่ประปรายที่นี่ว่า: พวกเธอมีชีวิตรอดอย่างไร?\nกระบองเพชรตอบว่า: 「พวกเราฝังรากลึกลงใต้ดิน ดูดซับน้ำอันหายาก」\nแม้ในสภาพแวดล้อมที่โหดร้ายก็ยังมีชีวิตอยู่อย่างเข้มแข็ง ดอกแดนดิไลออนครุ่นคิดเช่นนั้นแล้วจากไป\n\nไม่นานหลังจากนั้น ดอกแดนดิไลออนผ่านเหนือเมือง\nแสงไฟทั่วเมืองที่ปรากฏในค่ำคืนอันมืดมิด คือร่องรอยแห่งชีวิตของมนุษย์\nเมื่อถึงจุดสิ้นสุดของการเดินทางอันยาวนาน เมล็ดพันธุ์ของดอกแดนดิไลออนก็จะร่วงหล่นลงสู่ผืนแผ่นดินนั้นในที่สุด"
  },
  CollectionHall_130220_Title = {
    Text = "ขอให้โลกเปลี่ยนเป็นกลิ่นหอม"
  },
  CollectionHall_130221_Desc = {
    Text = "อารัคเนรู้ดีว่า เธอกำลังทำสิ่งที่ถูกกำหนดให้ล้มเหลว.\nเธอหมุนจักรไหมอย่างเบา ๆ วันแล้ววันเล่า นำความเศร้าโศกและความสุขของมนุษย์ ความรุ่งเรืองและความเสื่อมถอยของราชวงศ์ รวมถึงบทกวีและความรักที่เหมือนประกายดาว ทอเป็นตาข่ายขนาดใหญ่ที่ข้ามกาลเวลา.\nเธอทำได้ดีมาก แม่นยำ ยับยั้ง และอ่อนโยน. ปฏิเสธสิ่งที่ 「ผิด」 และเลือกสิ่งที่ 「ถูกต้อง」.\nผู้คนรุ่นแล้วรุ่นเล่าที่แสดงให้เห็นรอยยิ้มแห่งการเกิดใหม่ อารยธรรมมากมายได้เขียนประวัติศาสตร์ใหม่ในเถ้าถ่าน. และความสุขที่เกิดจากการทอ ความเหนื่อยล้าที่เกิดจากการทอ รวมถึงอารมณ์อ่อนโยนทั้งหมด ได้ค่อย ๆ จางหายไปในความเจ็บปวดตลอดกาล. เธอได้ตัดขาดความเปราะบางด้วยมือของตัวเอง เหลือไว้เพียงเจตจำนงที่ชัดเจน เพื่อให้แน่ใจว่าทุกการเลือกนั้นมาจากความรับผิดชอบ ไม่ใช่จากความอ่อนแอ.\nแต่โศกนาฏกรรมที่ลึกซึ้งที่สุด ไม่ใช่ตัวการลงโทษเอง แต่เป็นสิ่งที่เธอรู้ชัดเจนว่า ไม่ว่าเธอจะแก้ไขหรือทออย่างไร โลกก็ยังคงมุ่งไปสู่ความว่างเปล่าที่เงียบสงบ. อารยธรรมเปรียบเสมือนปราสาททรายที่เปราะบาง น้ำขึ้นจะมาถึง. ความพยายามของเธอ เป็นการแสดงที่ไม่มีผู้ชม การเฝ้ารอที่ไม่มีเสียงสะท้อน.\n「ชะตากรรมได้ตัดสินเราสู่ความโดดเดี่ยวที่เป็นนิรันดร์แล้ว ทำไมเราจึงต้องยอมรับการลงโทษที่โหดร้ายนี้?」\n「ฉีกมัน ทำลายมัน... คุณจะสามารถหลบหนีจากการลงโทษนี้ได้...」\nเธอเหลือบตามอง ตัดความคิดที่เกินความจำเป็นออกอย่างเบา ๆ และกลับไปทออย่างน่าเบื่อหน่าย มุ่งมั่น น้ำตาไหล ทนทุกข์...\nทุกการดิ้นรนที่ไร้ค่า ทุกชะตากรรมที่ไม่มีทางออก ได้ถูกทออยู่ในตาข่ายนี้แล้ว.\nและในใจกลางของตาข่าย เธอเห็นตัวเอง."
  },
  CollectionHall_130221_Title = {
    Text = "ใยถักทอแห่งนิรันดร์"
  },
  CollectionHall_131000_LockTip = {
    Text = "จำเป็นต้องผ่านกิจกรรมจำกัดเวลา「เสียงเพรียกของเมอร์สคัส：มอสกับทะเล」บางด่าน"
  },
  CollectionHall_131000_Title = {
    Text = "เสียงเพรียกจากเมอซคัส：มอสกับทะเล"
  },
  CollectionHall_131388_Desc = {
    Text = "ที่หน้าประตูคลับหรูหราสีทอง ชายต้อนรับที่สวมเสื้อเชิ้ตสีขาวยกมือขึ้นหยุดไรเกอร์อย่างสุภาพ\n「คุณครับ คุณไม่มีคำเชิญและไม่ใช่สมาชิกของเรา จึงไม่สามารถเข้าได้」\n「จริงเหรอ... นี่มันยุ่งยากแล้วสิ...」\nไรเกอร์ใช้มือสัมผัสคาง แกล้งทำเป็นคิดอยู่จริงๆ เขากำลังรอ\nรอผู้ต้องสงสัยในคดีที่อยู่ในมือ\nรอการมาของโชคชะตาที่กำหนดไว้\nแน่นอนว่าเขารอจนได้——\n「นี่ไม่ใช่นักสืบโชคดีที่มีชื่อเสียงจากลอนดีเนี่ยนเหรอ! มาๆ ผมยินดีที่จะเป็นผู้แนะนำให้」\n「ผมตั้งใจอยากเห็นโชคที่มีตำนานของคุณแล้ว อย่าทำให้ผมผิดหวังนะ...」\nสุภาพบุรุษพูดพร้อมกับยิ้มที่ดูเหมือนจะอ่อนโยนแต่เต็มไปด้วยความชั่วร้าย\nสีหน้าที่เป็นเช่นนี้พบเห็นได้บ่อยในคลับ เพราะคุณไม่สามารถคาดหวังให้เหล่านักพนันที่มุ่งมั่นสู่ความสนุกปฏิบัติตามกฎได้\nดังนั้นเมื่อรู้ว่าตนเองถูกวางแผน ไรเกอร์จึงไม่ใส่ใจ เพียงแค่ยิ้มมุมปากและเก็บไพ่ฮวีกัสอย่างใจเย็น\nไม่ต้องรีบ เกมเพิ่งเริ่มต้น ไม่ใช่หรือ?\nดังนั้น รอบแรก รอบสอง รอบสาม... เกมหนึ่งต่ออีกเกม\nจนกระทั่งไรเกอร์สูญเสียชิปทั้งหมด\n「นักสืบโชคดี ดูเหมือนวันนี้คุณจะโชคไม่ดีเลย จริงอยู่ ไม่มีใครสามารถได้รับการดูแลจากโชคชะตาตลอดไป...」\n「ยังจะเล่นต่อไหม? นักสืบ น่าเสียดายที่คุณไม่มีอะไรเหลือแล้ว」\n「ไม่มีอะไรเลย? ไม่จริง」นักสืบที่แพ้ยิ้มและชี้ไปที่ตัวเอง「ผมยังมีชุดสูทที่เหมาะสมนี้ มีไม้เท้าราคาแพงนี้ และยัง...」\nนักสืบหยุดชั่วครู่แล้วหยิบอุปกรณ์ขนาดเล็กออกจากกระเป๋าเสื้อสูท กดเสียงต่ำและยิ้มขณะเล่นมัน「ผมยอมรับว่าคุณมีวิธีโกงที่ชาญฉลาดมาก แม้แต่เจ้าของคลับนี้ก็ไม่สามารถแก้ไขได้ ต้องขอความช่วยเหลือจากผม แต่ไม่ว่าจะเป็นวิธีไหนก็ต้องใช้เวลา ต้องใช้การปฏิบัติ ต้องมีการประสานกัน」\n「น่าเสียดาย อุปกรณ์ชิ้นนี้ที่ผลิตโดยมิซากะ ได้บันทึกหลักฐานเกี่ยวกับคุณและพรรคพวกของคุณที่โกงในคลับได้อย่างชัดเจน」\nสุภาพบุรุษตกใจและโกรธจัด ขณะที่พรรคพวกของเขาก็โกรธแค้นและต้องการให้กับนักสืบ แต่ท่ามกลางสายตาของคนมากมาย สุภาพบุรุษไม่กล้าทำอะไรเกินเลย และยิ่งไปกว่านั้น นักสืบได้มอบทางเลือกให้เขา ทางเลือกที่เขาไม่สามารถปฏิเสธได้\n「มาลองเดิมพันอีกครั้งไหม? ถ้าคุณชนะ อุปกรณ์ชิ้นนี้และชีวิตของผม จะเป็นของคุณ คุณเข้าใจที่ผมหมายถึง」\n「แล้วถ้าผมแพ้ล่ะ?」\n「แพ้ก็ต้องให้คุณไปมอบตัว」ไรเกอร์ยิ้มและยักไหล่ แสดงให้เห็นถึงเขี้ยวที่แวววาว「คุณคิดว่าคุณจะแพ้เหรอ? นักพนันที่แท้จริงเชื่อว่าเขาจะชนะ」\nใช่ ทุกคนที่เป็นนักพนันคิดว่าตนจะชนะ ดังนั้นไม่ว่าใครก็ไม่สามารถปฏิเสธเกมนี้ได้\nดังนั้น ไพ่ฮวีกัสจึงถูกแจกอีกครั้ง วางไพ่ วางไพ่ และสุดท้าย ตัดสินผลแพ้ชนะ\n「โชคดี~」\nไรเกอร์ไม่มองผู้แพ้แม้แต่ครั้งเดียว ยิ้มและยกมือขึ้นโยนเงินที่ชนะขึ้นไปในอากาศ\nดังนั้น คลับที่เสียงดังอยู่แล้วกลับยิ่งคึกคัก เต็มไปด้วยเสียงเรียกร้องของผู้คน เสียงกรีดร้องแห่งความมั่งคั่งและเสียงหัวเราะ\nและในเสียงเรียกร้อง เสียงกรีดร้อง และเสียงหัวเราะนั้น ไรเกอร์จึงเก็บเครื่องประดับที่มิซากะมอบให้กลับเข้าไปในกระเป๋าเสื้อ สูบลมเข้าไปในหมวกและยิ้มมุมปาก\nนักพนันที่แท้จริงเชื่อว่าเขาจะชนะ\nเพราะเขามั่นใจว่าไม่ว่าเขาจะทำอะไร การดูแลของโชคชะตายังคงอยู่กับเขาเสมอ\n"
  },
