  },
  CollectionHall_132222_Desc = {
    Text = "หากความปรารถนาสามารถเป็นจริงได้ ปอนทอสหวังว่าการจากลาจะมาทักทายก่อนที่มันจะมาถึง\nพ่อแม่ของเขาหายไปอย่างเงียบงัน ในบ่ายอันสงบ พี่สาวเลซ่าจ้างรถลากมาคันหนึ่ง แล้วก็มีสิ่งประหลาดเหล็กยาวๆ ที่เขายังไม่รู้จักในตอนนั้น ท่ามกลางกลิ่นน้ำมันดีเซลและเสียงดังกึกก้อง เขาก็มาถึงเมืองชายทะเลแห่งนั้น\nเกี่ยวกับที่ไปของพ่อแม่ เลซ่าไม่เปิดเผยแม้แต่คำเดียว หลังจากทะเลาะกันอย่างรุนแรง เขาก็วิ่งออกไปยังท่าเรือที่เต็มไปด้วยกลิ่นคาวเค็ม\nชาวทะเลที่มีดวงตาห่างกันมากกำลังขายปลาที่มีรูปร่างแปลกประหลาด มาจากห้วงลึกที่มนุษย์ไม่อาจไปถึงได้\n「เฮ้ อยู่ห่างๆ ไว้ ปลาพวกนี้อาจสาปแช่งเหมือนกับสิ่งที่จับมันมาก็ได้.」\nคนเดินผ่านพูดเบาๆ ไม่มีใครอยากเห็นหนุ่มหน้าตาดีที่เพิ่งมาถึงต้องยุ่งเกี่ยวกับเรื่องวุ่นวาย\nเขายิ้มให้อีกฝ่ายตามนิสัย แต่สายตากลับตกไปที่เหยื่อล่อที่มืดหม่นและเน่าเปื่อยนั้นโดยไม่รู้ตัว มันมีปากที่อ้ากว้างเต็มไปด้วยฟันแหลมคม น่าเกลียด, บิดเบือน, โอ้อวด และเสียงในจินตนาการบางอย่างก็เล่าถึงชีวิตของสิ่งที่ตายแล้วนั้น\nในห้วงลึกอันมืดมิดไร้แสง มันล่อลวง, ช่วงชิง, ใช้ทุกวิถีทาง ร่างกายของมันคือกรงขังอันแข็งแกร่ง กักขังลูกหลาน, คนรัก, ศัตรู, และเหยื่อของมัน\nสิ่งดีงามในชีวิตของมันควรจะผ่านไปอย่างรวดเร็ว แต่มันกักเก็บพวกเขาทั้งหมดไว้ พวกเขาใช้ร่างกายของมันเป็นพาหนะ พึ่งพาอาศัยกันอย่างแนบแน่น ไม่แยกตัวจากกัน\nปอนทอสสะบัดหัวอย่างรุนแรง มองไปรอบๆ ด้วยความตกใจท่ามกลางเสียงกึกก้องที่แหลมคมในหู\nเสียงนั้นหายไปเหมือนคลื่น เขาถือว่าทุกอย่างเป็นแค่ช่วงเวลาที่ใจลอย และเยาะเย้ยความประสาทของตัวเองในใจ\nแล้วก็ตกดิ่งลงสู่โชคชะตาที่กำหนดไว้โดยไม่รู้ตัว."
  },
  CollectionHall_132222_Title = {
    Text = "กรงขังมีชีวิต"
  },
  CollectionHall_133709_Desc = {
    Text = "การขี่ม้ายามเช้าต้องควบเคียงข้างเหล่าสุภาพบุรุษในเขตเพื่อหยั่งเชิงจุดยืนต่อร่างกฎหมายปฏิรูป งานเลี้ยงอาหารเย็นต้องแลกเปลี่ยนคำชมอย่างสุภาพกับบรรดาสุภาพสตรีจากตระกูลต่างๆ งานเลี้ยงอาหารค่ำที่โต๊ะยาวต้องนั่งฟังคำอธิษฐานก่อนอาหารอันยืดยาวและเสแสร้งท่ามกลางแสงเทียนเงินระยิบระยับ และหลังจากโอเปร่าเลิก ยังต้องรับมือกับการทักทายสังสรรค์ไม่รู้จบตามทางเดินหน้าห้องส่วนตัว\n\n「มีเพียงน้ำชายามบ่ายบนสนามหญ้าหลังบ้านเท่านั้น ที่เป็นเวลาของตัวฉันเองอย่างแท้จริง」\n「นี่เป็นครั้งแรกที่ฉันเชิญแขกมาร่วมน้ำชายามบ่าย ฉันจะมอบสิทธิ์ในการเลือกหัวข้อสนทนาให้แก่คุณ」\n\nโซเลลยกถ้วยชาแดงที่เพิ่งรินเต็มขึ้นมา\n「คุณอยากรู้จุดยืนของเคานต์เดอ·เครเมในร่างกฎหมายปฏิรูปสภาฉบับล่าสุดที่เสนอไปหรือเปล่า? หรือว่าการวางเดิมพันอันแยบยลของตระกูลโบมอนนาระหว่างสองพรรค? หรือแค่สนใจความลับของคุณหนูไวเคานต์คนไหนสักคน?」\n「ไม่ต้องเลยหรือ? คุณแค่อยากรู้รสชาติของขนมหวานสีชมพูบนโต๊ะของฉัน?」\nเธอจิบชาเบาๆ สายตาที่เคยมองไปไกลๆ กลับมาตกลงที่ตัวคุณ\n「งั้นก็ลิ้มลองดูสิคะ」\n「รสชาติบางอย่างน่ะ ต้องลงมือทำเองถึงจะเข้าใจได้อย่างแท้จริง」\n「คุณว่าจริงไหมคะ ท่านผู้เป็นที่เคารพ——ท่านนั้น?」\n\nหมอกดำทะลักออกจากปกเสื้อและข้อมือของแขกผู้สวมชุดนักเรียนมิซาเกะ หมอกนั้นรวมตัวกลายเป็นกลุ่มความโกลาหลสีดำทึบอย่างรวดเร็ว\n「ฮิฮิฮิ เธอคิดจริงๆ หรือว่าตัวเองจะหนีพ้นจากชะตากรรม?」\n「แดดกำลังดี ฉันอยากเพลิดเพลินกับเวลาว่างอันหายากของฉันก่อน อยากชิมชาแดงและสปันจ์เค้กที่กำลังฮิตก็เชิญตามสะดวก เรื่องอื่นๆ รบกวนมาใหม่หลังหมดเวลาพักกลางวันนะคะ」"
  },
  CollectionHall_133709_Title = {
    Text = "เวลาพักกลางวันส่วนตัว"
  },
  CollectionHall_133710_Desc = {
    Text = "ในฐานะนักเรียนดีเด่นของมิซากะ ราโมน่าสามารถยึดสติและเหตุผลเป็นตรรกะสูงสุดในการดำเนินชีวิตได้สำเร็จ รักษาความสงบ รักษาอารมณ์ขัน และรักษาความน่าเชื่อถืออันหาที่เปรียบมิได้\nแต่บางครั้ง ราโมน่าเช่นนี้ก็จมดิ่งในห้วงครุ่นคิด เมื่อเผชิญกับความสยองขวัญอันสุดขีดของโลก หรือความงดงามอันสุดขีด——\nจ้องมองสีชมพูอันไร้ขอบเขตที่เต็มสายตา ราโมน่าเงียบงันไร้เสียง\nเท่าที่เธอรู้ ไม่เกินสามสัปดาห์ ดอกซากุระจะเปลี่ยนจากเริ่มบานสู่ร่วงโรยจนหมด ดังนั้นดอกไม้ที่หนักอึ้งเต็มกิ่งก้าน กิ่งใบที่แผ่ขยายอย่างเขียวชอุ่ม ในไม่ช้าก็จะเหี่ยวเฉา จมดิ่งสู่ความเวิ้งว้างและเงียบเหงา\nแต่ชีวิตที่คาดหมายได้ของมนุษย์นั้น ยาวนานกว่าสามสัปดาห์ ยาวนานกว่าสามปี ยาวนานกว่าสามสิบปี แต่ก็เหมือนต้นซากุระเหล่านี้ มีเพียงครั้งเดียว\nภาพหลอนที่ยิ่งใหญ่ที่สุดของมนุษย์ คือการเชื่อว่าตนจะมีชีวิตอยู่ตลอดไป\nราโมน่าเข้าใจ\nดอกไม้บานแล้วร่วง เป็นกฎธรรมชาติที่ธรรมดาที่สุด และความเป็นความตายของมนุษย์ ท้ายที่สุดแล้วก็เป็นเพียงปรากฏการณ์ทางธรรมชาติเท่านั้น\nราโมน่าก็เข้าใจเช่นกัน\nแต่เกิดมาเป็นมนุษย์ ย่อมอยากมอบความหมายให้กับการมีอยู่ของตน ทุกทารกแรกเกิดก็เพื่อสิ่งนี้ จึงก้าวเข้าสู่ประตูของมิซากะ\nพวกเขาคือผู้บุกเบิกในการต่อสู้กับการย่อยสลาย คือแนวป้องกันสำคัญที่เฝ้ามองอนาคตของมนุษยชาติ\nชีวิตของพวกเขาไม่ใช่เพียงปรากฏการณ์ทางธรรมชาติอันเป็นกลาง แม้ถูกกำหนดให้ดับสูญ ก็ยังเปลี่ยนแปลงเส้นทางของโลกนี้อย่างแท้จริง\nและในระหว่างนั้น พวกเขาสู้เคียงบ่าเคียงไหล่ ร่วมฝ่าฟันทุกพายุ\nเหมือนดอกไม้ดอกหนึ่งบนต้นไม้ต้นเดียวกัน ซบเคียงข้างดอกไม้อีกดอก ร่วมเป็นดอกตูม ร่วมโบกสะบัดร่วงหล่น ร่วมบานสะพรั่งและเหี่ยวเฉา\nตอนนี้ ได้เวลากลับแล้ว\nดอกไม้ที่เธอพึ่งพาได้ และคู่ควรให้เธอพึ่งพา ยังคงรอเธออยู่"
  },
