  CollectionHall_133769_Desc = {
    Text = "จมลง จมลง จมลง\nจมลงสู่วังวนแห่งความมืดมิด\nเป็นราคาที่ต้องจ่าย พระองค์จะไม่สามารถกลืนกินกุ้งฝอยได้อีกแม้แต่ตัวเดียว"
