  CollectionHall_133769_Title = {
    Text = "จมลง"
  },
  CollectionHall_133770_Desc = {
    Text = "ผู้โดยสารทุกท่าน, สวัสดีครับ/ค่ะ!\nเทศกาลปีใหม่กำลังจะมาถึง, ในช่วงเวลาอันงดงามแห่งการรวมครอบครัวและส่งท้ายปีเก่าต้อนรับปีใหม่นี้, เจ้าหน้าที่ประจำขบวนรถทุกท่าน, ขอส่งพรอันจริงใจที่สุดมายังคุณผู้เดินทางกลับบ้านเกิดไกลและเหน็ดเหนื่อยจากการเดินทาง——\nขอให้คุณมีความสุขในเทศกาลปีใหม่, ครอบครัวอบอุ่นเต็มด้วยปิติสุข, ควบแล่นตลอดทาง, สมหวังทุกประการ! <(￣︶￣)↗[GO!]"
  },
  CollectionHall_133770_LockTip = {
    Text = "เสร็จสิ้นบันทึกพิเศษ「รถไฟที่มุ่งสู่เทศกาลปีใหม่」"
  },
  CollectionHall_133770_Title = {
    Text = "ควบแล่น：ขบวนรถแห่งปิติสุข"
  },
  CollectionHall_133771_Desc = {
    Text = "ผู้โดยสารทุกท่าน สวัสดีครับ/ค่ะ ต้องขออภัยเป็นอย่างยิ่งที่ต้องแจ้งให้ทราบว่า เนื่องจากอารมณ์ส่วนตัวของนายสถานี ขบวนรถไฟปิติสุขพิเศษจะหยุดจอดชั่วคราว ณ ที่นี้ กำหนดการออกเดินทาง เราจะประกาศแจ้งให้ทราบทันทีหลังจากการสังหารกันเองสิ้นสุดลง\nระหว่างจอดรถ ระบบปรับอากาศ, แสงสว่าง และห้องน้ำของขบวนรถสามารถใช้งานได้ตามปกติ กรุณาใช้บริการตามความจำเป็นในการสังหาร เพื่อป้องกันมิให้เกิดอันตราย\nท้ายที่สุด หน้าที่ของขบวนรถไฟปิติสุข คือการนำรอยยิ้มมาสู่ผู้โดยสารทุกท่าน～(￣▽￣～)(～￣▽￣)～"
  },
  CollectionHall_133771_LockTip = {
    Text = "เสร็จสิ้นบันทึกพิเศษ「รถไฟที่มุ่งสู่เทศกาลปีใหม่」"
  },
  CollectionHall_133771_Title = {
    Text = "หยุดฉุกเฉิน!"
