  CollectionHall_133772_Desc = {
    Text = "กรุณาทราบ: ขบวนรถไฟกำลังจะถึงสถานีถัดไป อาณาจักรฟานหลงโบราณ ผู้โดยสารที่ต้องการลงที่อาณาจักรฟานหลงโบราณ กรุณาศึกษาเทคนิคการร้องเพลง «ดอกมะลิงามเอย» ล่วงหน้า\nเพราะว่า พวกคุณไม่มีโอกาสลงรถแล้ว φ(≧ω≦*)♪"
