  CollectionHall_133773_Title = {
    Text = "สีน้ำเงินและน้ำเงินที่ลึกกว่า"
  },
  CollectionHall_134293_Desc = {
    Text = "<Title:แนะนำ>\nเจ้าของโรงละครแห่งโชคชะตา นักเขียนบท นักแสดง ผู้ถักทอชะตากรรมนิรันดร์และนักโทษแห่งนิรันดร์...\nตั้งแต่เกิดมา อาแรคเน่ก็มีความสามารถในการมองเห็นเส้นด้ายแห่งโชคชะตา ด้วยกี่ปั่นด้ายที่มีชื่อว่า 「มอยไร」 เธอถักทอโชคชะตาให้โลกอยู่ทุกขณะจิต รักษาสมดุลอันเปราะบางของชะตากรรมไว้ เพื่อสิ่งนี้ เธอจึงขับไล่ความงดงามและความเปราะบางทั้งหมดออกจากตัวเอง ตัดสินใจอย่างถูกต้องที่สุดเพื่อชะตากรรมทั้งมวล แบกรับบาปแห่งโชคชะตาทั้งปวงไว้เพียงลำพัง\nเธอรู้มานานแล้วว่า ณ จุดสิ้นสุดของใยแห่งโชคชะตา ความพินาศนั้นไม่อาจหลีกหนีได้ แต่เธอยังคงถักทอไม่หยุดหย่อนตลอดกาล มองดูทุกสิ่งที่เธอรักค่อยๆ ตกลงสู่จุดจบที่ทำลายล้างทุกสิ่ง\nเธอถักทอ รอคอย รอคอยเส้นด้ายที่เธอไม่เคยคาดการณ์ไว้ ที่จะกอบกู้ใยแห่งโชคชะตาจากห้วงเหว"
  },
  CollectionHall_134293_LockTip = {
    Text = "ปลุกตื่น「อารัคเน」หลังปลดล็อก"
  },
  CollectionHall_134293_Title = {
