  CollectionHall_141453_LockTip = {
    Text = "ผ่านด่านการเชื่อมโยงหลายมิติ「เมล็ดพันธุ์แห่งรักที่ถูกลืม：血ﾝ肉ｲw世ｮ」เพื่อปลดล็อก"
  },
  CollectionHall_141453_Title = {
    Text = "ลำนำเร่ร่อนนิรันดร์"
  },
  CollectionHall_141528_Desc = {
    Text = "ตำนานเล่าว่าตราบใดที่เด็กวิ่งไล่ตามกระต่ายป่าในพงพนา ก็มีอัตราความน่าจะเป็นที่จะตกลงไปในโพรงไม้ที่นำสู่โลกอื่น. เท้าเล็กๆ เนียนนุ่มของลิลลี่เหยียบลงบนทางเดินหินกรวด. 「ลิลลี่ชอบที่นี่... บนพื้นไม่มีเศษแก้ว และในอากาศก็ไม่มีกลิ่นน้ำยาฆ่าเชื้อ.」 ลิลลี่สูดอากาศบริสุทธิ์เข้าลึกๆ วายุที่พัดผ่านพงพนาพัดพาเอากลิ่นหอมแปลกๆ ของดอกไม้มาด้วย. ยอดไม้เหนือหัวสานกันเป็นโดมเหมือนกระจกสี แสงแดดที่ส่องลงมาเป็นชิ้นๆ เหมือนอัญมณีที่กระโดดโลดเต้นอยู่ทั่วพื้น ทิวทัศน์อันงดงามและมหัศจรรย์ทำให้ลิลลี่เกือบไม่รู้ว่าควรมองไปทางไหน. 「อ้า คุณกระต่ายเมื่อกี้!」 หูยาวสีเทาคู่หนึ่งที่คุ้นเคยโผล่ขึ้นมาจากพุ่มหญ้า ลิลลี่รีบวิ่งไล่ตาม. ตะไคร่น้ำใต้เท้าบานออกเป็นดอกเงินเล็กๆ ทุกครั้งที่เหยียบ แต่ลิลลี่ก็ไม่มีเวลาสนใจ เธอมีเรื่องสำคัญกว่าที่ต้องพูดกับคุณกระต่าย. ลุยข้ามลำธารที่ไหลเป็นแสงสีน้ำผึ้ง ผ่านกอกกที่ร้องเพลงได้. ลิลลี่ที่หอบแฮ่กๆ ในที่สุดก็จับหางฟูฟ่องเหมือนลูกบอลของคุณกระต่ายได้. 「คุณกระต่าย คุณยินดีเป็นเพื่อนกับลิซ่าไหม?」 「ลิซ่าเป็นเพื่อนของหนู แต่ตอนนี้คนอื่นๆ กลัวเธอมาก... ถ้าเป็นคุณกระต่าย ต้องสามารถเป็นเพื่อนกับเธอได้แน่!」 ในขณะที่คุณกระต่ายหันหลังกลับมา หิ่งห้อยนับพันก็ลอยขึ้นเต็มท้องฟ้า. 「แน่นอน @2เป็นเพื่อนของทุกคน. แต่ตอนนี้ ถึงเวลาพักผ่อนแล้ว.」 ดังนั้น ลิลลี่จึงอุ้มคุณกระต่ายที่กลายเป็นเพื่อนแล้ว คลานไปยังต้นไม้ใหญ่สูงตระหง่านในส่วนลึกของพงพนา. ท่ามกลางความอบอุ่นของหิ่งห้อยที่ล่องลอยอยู่รอบๆ ลิลลี่พิงรากของต้นไม้ใหญ่และหลับไปอย่างสงบ. 「ผู้รับการทดสอบ: ลิลลี่. อาการทางคลินิก: การหายใจสม่ำเสมอ, ความเร็วการเคลื่อนไหวของลูกตาปกติ. การทดลองแทรกแซงจิตสำนึกครั้งที่ 359, สำเร็จ.」 นั่นคือโลกแฟนตาซีอันงดงามเหมือนความฝัน."
  },
