  CollectionHall_142155_Desc = {
    Text = "เมื่อถูกสิ่งผิดรูปที่เข้าใจไม่ได้ จดจำไม่ได้ และน่าขยะแขยงเข้ามาประชิด การโจมตีเพื่อการป้องกันตนเองคือสัญชาตญาณของสิ่งมีชีวิต.\nดังนั้น สิ่งนี้จึงไม่อาจถือเป็นบาปได้."
