  },
  CollectionHall_142156_Desc = {
    Text = "「ได้ยินเสียงของฉันไหม? แม้ร่างกายจะการละลายหายไปในวายุ.」\nเสียงเพรียกจากที่ไกลโพ้นลอยมาตามสายลม นั่นคือเสียงค้นหาที่ข้ามผ่านกาลเวลาอันยาวนาน มาจากคืนฤดูหนาวอันกว้างใหญ่และหนาวเหน็บ จากฝั่งตรงข้ามของการลืมเลือน."
