  CollectionHall_142156_Title = {
    Text = "忘却の彼方"
  },
  CollectionHall_142157_Desc = {
    Text = "ความทรงจำกระพริบซ้อนทับกัน ความจริงและความเท็จของบทสรุปยังไม่ชัดเจน.\nแต่สิ่งนี้สำคัญจริงๆ หรือ?\nท้ายที่สุด ไม่ใช่ทุกเรื่องราวที่จะเริ่มต้นด้วยความรัก แต่ทุกเรื่องล้วนจบลงด้วยความตาย."
