  CollectionHall_142157_LockTip = {
    Text = "เคลียร์การเชื่อมต่อหลายมิติ 「เมล็ดพันธุ์แห่งรักที่ถูกลืม」"
  },
  CollectionHall_142157_Title = {
    Text = "ความทรงจำสี่ชั้น"
  },
  CollectionHall_142158_Desc = {
    Text = "หากสักวันหนึ่ง เธอก็เหมือนกับฉัน จมอยู่กับภาพที่คาโรเละเทะ เน่าเปื่อยผุพัง.\nแล้วเธอก็จะต้องเข้าใจ——\nช่วงขณะที่ปลายนิ้วเล็กๆ ของเธอสัมผัสกัน คือปาฏิหาริย์อันหาได้ยากในโลกมนุษย์."
