  CollectionHall_142158_Title = {
    Text = "ปาฏิหาริย์"
  },
  CollectionHall_142159_Desc = {
    Text = "เธอเบื่อหน่ายกับชีวิตธรรมดา วนซ้ำ น่าเบื่อ วันแล้ววันเล่าบ้างไหม?\nลองสิ่งใหม่ดูสิ มีอีกมิติหนึ่งกำลังอ้าปากกว้างต้อนรับ ส่งคำเชิญชวนมาหาเธอ."
