  CollectionHall_142160_Desc = {
    Text = "ความรักคือความสูงส่ง ความรักคือความโลภ; ความรักคือพร ความรักคือสาปแช่ง.\nความรักเกิดขึ้นพร้อมกับน้ำ และจะจากไปพร้อมกับน้ำเช่นกัน.\nแต่ฤดูฝนจะไม่กลับมาอีก."
