  CollectionHall_142161_Desc = {
    Text = "สรรพชีวิตทั้งหลายถือกำเนิดมาพร้อมกับความไม่รู้ ดูดซับสารอาหารจากสรรพสิ่ง ปรับเปลี่ยนสภาพแวดล้อม ช่วงชิงทรัพยากร และอุปการะตนเอง.\nนี่คือบาปกำเนิดที่ไม่อาจหลีกเลี่ยงได้."
