  CollectionHall_142161_Title = {
    Text = "บาปดั้งเดิม"
  },
  CollectionHall_142162_Desc = {
    Text = "มีพืชชนิดหนึ่งชื่อดอกแดนดิไลออน ที่ปล่อยให้เมล็ดพันธุ์ล่องลอยไปกับวายุ.\nเมล็ดนุ่มฟูเร่ร่อนตามสายลม ห่างไกลจากบ้านเกิดไกลแสนไกล.\nมันโดดเดี่ยวอยู่คนเดียว จะตัดสินใจหาที่พักพิงของตนเองเมื่อใดกัน?\nนั่นก็คือ เมื่อมีคนเพียงคนเดียวในทะเลทรายที่รักดอกแดนดิไลออนต้นนั้น."
  },
  CollectionHall_142162_LockTip = {
    Text = "เคลียร์การเชื่อมต่อหลายมิติ 「เมล็ดพันธุ์แห่งรักที่ถูกลืม」"
  },
  CollectionHall_142162_Title = {
    Text = "ดอก민들레จะไปที่ไหน"
  },
  CollectionHall_142163_Desc = {
    Text = "ท้องฟ้ากว้างใหญ่ ทะเลทรายไพศาล.\nนั่นคือดินแดนที่มีแต่เธอและฉัน ไร้ผู้คน.\nนั่นคือการท่องเที่ยวแห่งความรักที่เสรีชั่วนิรันดร์."
  },
  CollectionHall_142163_LockTip = {
    Text = "เคลียร์การเชื่อมต่อหลายมิติ 「เมล็ดพันธุ์แห่งรักที่ถูกลืม」"
  },
  CollectionHall_142163_Title = {
    Text = "การท่องเที่ยวในทะเลทราย"
  },
  CollectionHall_142164_Desc = {
    Text = "ฉันจะอัญเชิญชื่อของเธอได้ไหม? แม้โลกจะสูญสลายไป.」\nหากความทรงจำทั้งหมดจะถูกทำลายล้างและกระจัดกระจาย ความมืดมิดแห่งการลืมเลือนจะกลืนกินเรื่องราวในอดีตที่ยังไม่ทันได้รำลึกถึงทั้งหมด.\nงั้นก็จับมือกันเถิด ให้แสงสีเงินเชื่อมโยงเธอและฉัน.\nในความฝันอันใหม่สด ในฤดูใบไม้ผลิยามที่เมล็ดอ่อนนุ่มเริ่มงอกงาม."
  },
