  },
  CollectionHall_142868_Desc = {
    Text = "<Title:บทนำ>\nปอนทอสจำความรู้สึกในวันที่ได้รู้ประวัติศาสตร์ของตระกูลได้เสมอ ก่อนหน้านั้น เขาไม่เคยเตรียมพร้อมรับผิดชอบสิ่งใดเลย ทุกคนชื่นชอบเขา เขาหล่อเหลา สนุกสนาน และไร้กังวล\n@1เรือที่แล่นผ่านท่าเรือหลวงตลอดทั้งปีทำให้เขาไม่ต้องเผชิญกับความจำเจของชีวิตประจำวัน เขาได้ยินเรื่องราวมากมาย หลายคนบอกว่าเขาช่ำชองโลก จนเขาไม่ยอมรับว่าตัวเองอาจเป็นแค่คนธรรมดาคนหนึ่ง\nดังนั้น เขาจึงถูกกลืนหายไปในความปีติยินดีอันยิ่งใหญ่ที่ไม่คาดคิดแต่ก็สมเหตุสมผล ยิ่งไปกว่านั้น การมีอยู่อันยิ่งใหญ่ลึกลับที่อยู่เบื้องหลังฝันร้ายที่ขับเคลื่อนตระกูลมาหลายชั่วอายุคนยังยอมรับเขา — เขาเกิดมาแตกต่างจากคนอื่น\nทว่าเพียงคำพูดเล่นๆ ของ「N」 ทำให้พวกคลั่งศรัทธาทำลายหมู่บ้านทั้งหมดในการโจมตีชายฝั่งโดยไม่เลือกหน้า\nไม่อาจเผชิญกับหายนะที่มาโดยไม่ทันตั้งตัว เพื่อให้ได้มาซึ่งพละกำลังจากห้วงลึก ปอนทอสเลือกที่จะบูชายัญร่างกายของตนแด่@3 และบูชายัญความเป็นไปได้ทั้งหมดของตนเองด้วย\nแต่นั่นสำคัญอะไร ไม่มีสิ่งใดจะเกินการควบคุมของเขาอีกต่อไป\nเขาจะไม่สูญเสียสิ่งใดอีกแล้ว."
  },
  CollectionHall_142868_LockTip = {
    Text = "ปลดล็อกหลังจากปลุกตื่น「ปอนทอส」"
  },
  CollectionHall_142868_Title = {
    Text = "พอนทอส"
  },
  CollectionHall_142901_Title = {
    Text = "เอโปยานส์นิรันดร์"
  },
  CollectionHall_143468_Desc = {
    Text = "ระฆังมรณะได้ดังขึ้นแล้ว ผู้ทรยศนำเสนอการแสดงที่บ้าคลั่งที่สุด.\nเส้นด้ายนับไม่ถ้วน จะถักทอเป็นบทสรุปเช่นใด——\nขึ้นอยู่กับคุณ."
  },
  CollectionHall_143468_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ·ยาก บทของดวงดาว5-11 เพื่อปลดล็อก"
  },
  CollectionHall_143468_Title = {
    Text = "ร่วมถักทอบทสุดท้าย"
  },
  CollectionHall_143469_Desc = {
    Text = "มาเร็วๆ เถิด, มาเร็วๆ เถิด, ทุกคนกำลังรอคุณอยู่.\nเดินผ่านทางเดินอันยาวนาน, ก้าวขึ้นสู่เวทีนิรันดร์.\nคุณคือทั้งบทละคร, ตัวเอกเพียงหนึ่งเดียว."
  },
  CollectionHall_143469_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ บทของดวงดาว 5-16 เพื่อปลดล็อก"
  },
  CollectionHall_143469_Title = {
    Text = "เกลียวคลื่นไม่สิ้นสุด"
  },
  CollectionHall_143470_Desc = {
    Text = "พวกเขาร้องเพลงร่วมกัน, พวกเขาต่างทำหน้าที่ของตน.\nแต่พวกเขาทั้งหมดคือเธอ.\nนี่คือละครเดี่ยวที่ไม่มีวันการโค้งคำนับ อันเป็นของเธอ."
  },
  CollectionHall_143470_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ บทของดวงดาว 5-16 เพื่อปลดล็อก"
  },
  CollectionHall_143470_Title = {
    Text = "ละครเดี่ยว"
  },
  CollectionHall_143471_Desc = {
    Text = "Act I: ปั่นด้าย\nAct II: ชั่งน้ำหนัก\nAct III: ตัดสิน\nวนซ้ำเช่นนี้, วนซ้ำเช่นนี้......"
  },
  CollectionHall_143471_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ·ยาก บทของดวงดาว5-11 เพื่อปลดล็อก"
  },
  CollectionHall_143471_Title = {
    Text = "ละครสามองก์"
  },
  CollectionHall_143472_Desc = {
    Text = "ไม่ใช่อะไรอื่น นอกจากชายหนุ่มผู้มีความคลั่งไคล้คนหนึ่ง, ยิงปืนที่มุมถนนธรรมดาแห่งหนึ่ง.\nอย่างน้อยในเวลานั้น, ทุกคนต่างคิดเช่นนั้น."
  },
  CollectionHall_143472_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ บทของดวงดาว 5-16 เพื่อปลดล็อก"
  },
  CollectionHall_143472_Title = {
    Text = "อารัมภบทแห่งไฟสงคราม"
  },
  CollectionHall_143473_Desc = {
    Text = "เอี๊ยด เอี๊ยด.\nชะตากรรมเอย วงล้อของเจ้าหมุนไม่หยุด.\nทั้งความยากจนและอำนาจถูกเจ้าละลายดั่งน้ำแข็ง.\nเจ้าปิดบังตัวเอง และซ่อนเร้นใบหน้า\nแต่ก็ยังส่องแสงมาหาฉัน......"
  },
  CollectionHall_143473_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ·ยาก บทของดวงดาว5-11 เพื่อปลดล็อก"
  },
  CollectionHall_143473_Title = {
    Text = "ชะตากรรมเอย เจ้าช่างโหดร้ายเหลือเกิน"
  },
  CollectionHall_143474_Desc = {
    Text = "ลาก่อนเถิด ในท่วงทำนองสุดท้าย.\nลาก่อนเถิด ภายใต้สายตาของชะตากรรม.\nตัวเอกของเรื่องราว จะก้าวออกสู่การเดินทางใหม่."
  },
  CollectionHall_143474_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ·ยาก บทของดวงดาว5-11 เพื่อปลดล็อก"
  },
  CollectionHall_143474_Title = {
    Text = "และฉันยังคงร้องเพลง"
  },
  CollectionHall_143475_Desc = {
    Text = "ที่รัก, ให้เราอาศัยความสนุกจากแอลกอฮอล์, ร่วมเต้นรำอีกสักครั้งเถิด."
  },
  CollectionHall_143475_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ บทของดวงดาว 5-16 เพื่อปลดล็อก"
  },
  CollectionHall_143475_Title = {
    Text = "งานเต้นรำยามเมามายเล็กน้อย"
  },
  CollectionHall_143476_Desc = {
    Text = "ผู้ชมหลั่งน้ำตาเพื่อการจากลา และหลั่งน้ำตาเพื่อการพบกันอีกครั้ง.\nส่วนนักโทษที่อยู่กลางเวที ก็ควรมอบเสียงปรบมือให้แก่กันและกัน."
  },
  CollectionHall_143476_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ·ยาก บทของดวงดาว5-11 เพื่อปลดล็อก"
  },
  CollectionHall_143476_Title = {
    Text = "นักโทษกำลังโค้งลา"
  },
  CollectionHall_143477_Desc = {
    Text = "ผู้คนในโลกชอบโยนความผิดของสงครามให้กับชั่วขณะที่เสียงปืนดังขึ้น.\nแต่ชะตากรรมจะหัวเราะเยาะ, นี่คือการหลอกตัวเองของมวลมนุษยชาติ."
  },
  CollectionHall_143477_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ บทของดวงดาว 5-16 เพื่อปลดล็อก"
  },
  CollectionHall_143477_Title = {
    Text = "เมื่อผีเสื้อกระพือปีก"
  },
  CollectionHall_143478_Desc = {
    Text = "การแสดงที่ไม่มีบทส่งท้ายนั้นไม่สมบูรณ์.\nเปลี่ยนบทพูดเล็กน้อย ปรับฉากหลัง สลับนักแสดง——ทุกครั้งที่กลับมา คือฉากใหม่ที่สดใหม่."
  },
  CollectionHall_143478_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ·ยาก บทของดวงดาว5-11 เพื่อปลดล็อก"
  },
  CollectionHall_143478_Title = {
    Text = "การแสดงรอบพิเศษแบบแปรผัน"
  },
  CollectionHall_143479_Desc = {
    Text = "ปลายปากกาวิ่งพล่านบนกระดาษขาว ไล่ตามตัวอักษร และตัวอักษรนำไปสู่บทสรุปที่ถูกกำหนดไว้แล้ว.\nทุกสิ่ง, ล้วนเกิดขึ้นก่อนที่คุณจะพลิกหนังสือแต่ละเล่ม."
  },
  CollectionHall_143479_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ บทของดวงดาว 5-16 เพื่อปลดล็อก"
  },
  CollectionHall_143479_Title = {
    Text = "สิ่งที่กำลังจะถูกกำหนด, สิ่งที่ถูกกำหนดแล้ว"
  },
  CollectionHall_143480_Desc = {
    Text = "บิตเตอร์เล็กน้อย, เวอร์มุตหวาน 20ml, เชอร์รี่ไวน์นิดหน่อย, เติมน้ำแข็งให้เต็มแล้วคนให้เข้ากัน——นี่คือเครื่องดื่มเรียกน้ำย่อยชั้นเลิศ, และยังเป็นละครที่แสดงมาแล้วห้าร้อยครั้ง."
  },
  CollectionHall_143480_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ บทของดวงดาว 5-16 เพื่อปลดล็อก"
  },
  CollectionHall_143480_Title = {
    Text = "อะโดนิส"
  },
  CollectionHall_143481_Desc = {
    Text = "คุณมองชะตากรรมเป็นตัวตลก, คุณก็จะไม่ถูกชะตากรรมเป็นทาส.\nจงต้อนรับพระองค์ด้วยเสียงหัวเราะที่ไม่มีวันหยุด, ให้เราร่วมกันเรียกขานพระนามของพระองค์ ——\nปิติสุข."
  },
  CollectionHall_143481_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ·ยาก บทของดวงดาว5-11 เพื่อปลดล็อก"
  },
  CollectionHall_143481_Title = {
    Text = "ตัวตลกเสด็จมาเยือน"
  },
  CollectionHall_143482_Desc = {
    Text = "“ฉันเกลียดคุณ เกลียดที่คุณสร้างรังไหมขังตัวเอง เกลียดที่คุณไม่มีความสามารถ เกลียดที่คุณทอดทิ้งตัวเอง”\n“...แต่ความเกลียดชังนี้ก็เผาไหม้ตัวฉันเองเช่นกัน เพราะ ฉันก็รักคุณ”"
  },
  CollectionHall_143482_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ·ยาก บทของดวงดาว5-11 เพื่อปลดล็อก"
  },
  CollectionHall_143482_Title = {
    Text = "บทเพลงโศกเศร้าของวิญญาณแก้แค้น"
  },
  CollectionHall_143483_Desc = {
    Text = "โลกมอบทางแยกนับไม่ถ้วนให้คุณเลือก แต่ทุกเส้นทางรวมสู่จุดเดียวกัน — ชื่อว่าล่มสลาย, ชื่อว่าบทอวสาน."
  },
  CollectionHall_143483_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ บทของดวงดาว 5-16 เพื่อปลดล็อก"
  },
  CollectionHall_143483_Title = {
    Text = "สำเนาของโลก"
  },
  CollectionHall_143484_Desc = {
    Text = "ม่านขึ้นลง, ละครสลับเปลี่ยน, เธอยังคงอยู่ในโรงละคร——เธอคือนักเขียนบท, ผู้ชม, และยังเป็นนักแสดง.\nโอ้ เจ้าของชะตากรรม, เจ้าช่างโหดร้ายนัก, เงียบงันตลอดกาล, แล้วเหตุใดจึงหลั่งน้ำตา?"
  },
  CollectionHall_143484_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ บทของดวงดาว 5-16 เพื่อปลดล็อก"
  },
  CollectionHall_143484_Title = {
    Text = "ละครแห่งชะตากรรมที่ถักทอร่วมกัน"
  },
  CollectionHall_143485_Desc = {
    Text = "หากการล่มสลายนั้นไม่อาจหลีกเลี่ยงได้ในที่สุด, การฉีกทำลายใยแห่งชะตากรรมจะนำมาซึ่งการไถ่บาปที่แท้จริงหรือไม่?\nไม่มีใครตอบได้, ไม่มีเทพองค์ใดตอบได้.\nแต่อย่างน้อย, ความทุกข์ทรมานอันไม่มีขอบเขตก็จะดับสูญไปพร้อมกัน."
  },
  CollectionHall_143485_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ บทของดวงดาว 5-16 เพื่อปลดล็อก"
  },
  CollectionHall_143485_Title = {
    Text = "การแสดงที่ดูหมิ่นชะตากรรม"
  },
  CollectionHall_143486_Desc = {
    Text = "ใบหน้าเหล่านั้นที่ดำเนินอยู่ในโลก, จริงอย่างยิ่ง, ดูเหมือนเป็นอิสระ, ล้วนเป็นเพียงอุปกรณ์ประจำที่บนเวที.\nทุกการเคลื่อนไหว, ล้วนถูกเส้นด้ายแห่งชะตากรรมชักนำ."
  },
  CollectionHall_143486_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ บทของดวงดาว 5-16 เพื่อปลดล็อก"
  },
  CollectionHall_143486_Title = {
    Text = "เส้นด้ายของสรรพสัตว์"
  },
  CollectionHall_143487_Desc = {
    Text = "หลังจากตื่นจากความฝัน, ทุกสิ่งจะหายไป, ถูกลืมเลือนอย่างสิ้นเชิง — คฤหาสน์, แปลงดอกไม้, บทเพลง, ภาพวาด......\nนั่นคือผลิบานที่ไม่มีอยู่จริง."
  },
  CollectionHall_143487_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ บทของดวงดาว 5-16 เพื่อปลดล็อก"
  },
  CollectionHall_143487_Title = {
    Text = "ความฝันแห่งการปั่นผลิบาน"
  },
  CollectionHall_143488_Desc = {
    Text = "เสียงเครื่องสายค่อยๆ ดังขึ้น, เมยด์ขับขาน.\nผู้อยู่เบื้องหลังม่านก้าวออกมาสู่เวที, เธอโค้งคำนับต่อคุณ, เชิญคุณเป็นพยานต่อวิถีชะตาที่ถูกกำหนดไว้."
  },
  CollectionHall_143488_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ บทของดวงดาว 5-16 เพื่อปลดล็อก"
  },
  CollectionHall_143488_Title = {
    Text = "เปิดเผยผ้าคลุมหน้าของเธอ"
  },
  CollectionHall_143489_Desc = {
    Text = "นี่คือการเต้นรำด้นสดที่สามารถแสดงได้เพียงครั้งเดียวในชีวิต.\nแต่ไม่เป็นไร, มันจะได้รับเกียรติกลายเป็นตัวอย่าง, หยุดนิ่งอยู่ชั่วนิรันดร์."
  },
  CollectionHall_143489_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ บทของดวงดาว 5-16 เพื่อปลดล็อก"
  },
  CollectionHall_143489_Title = {
    Text = "ละครเต้นรำ：«ความตายของหงส์»"
  },
  CollectionHall_143490_Desc = {
    Text = "ม่านเปิดออก, ตัวละครไร้สาระทยอยปรากฏตัว.\nพวกเขาร้องเพลง, เธอทั้งหลายเต้นรำ, ก่อนที่ชะตากรรมจะมาถึง, ยังคงมุ่งมั่นนำเสนอบทละครบนเวที, แม้ว่าบทสรุปจะถูกเขียนไว้แล้ว."
  },
  CollectionHall_143490_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ บทของดวงดาว 5-16 เพื่อปลดล็อก"
  },
  CollectionHall_143490_Title = {
    Text = "บทเพลงคู่เมื่อม่านเปิด"
  },
  CollectionHall_143491_Desc = {
    Text = "เพื่อให้ทุกสิ่งอยู่ในเส้นทางที่ถูกต้อง, ย่อมมีสิ่งที่ต้องถูกคัดออก, ถูกละทิ้ง.\nการมีอยู่ที่ไม่ได้รับการเลือก, ล้วนตกหล่นสู่ห้วงเหวมืดมิด, เสียงคร่ำครวญและการด่าของพวกมัน, ท้ายที่สุดไม่มีใครได้ยิน."
  },
  CollectionHall_143491_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ บทของดวงดาว 5-16 เพื่อปลดล็อก"
  },
  CollectionHall_143491_Title = {
    Text = "ฉันที่ถูกทอดทิ้ง"
  },
  CollectionHall_143492_Desc = {
    Text = "ตายอย่างนี้ช่างงดงามจริงๆ. เธอคิด."
  },
  CollectionHall_143492_LockTip = {
    Text = "ทำการสอบสวนดำเนินการ บทของดวงดาว 5-16 เพื่อปลดล็อก"
