  CollectionHall_144448_Desc = {
    Text = "คุณได้รับคำสัญญาถึงดินแดนแห่งความว่างเปล่าที่ไม่อาจเข้าถึงได้ตลอดกาล, ที่นั่นบรรจุวิญญาณเก่าอันคุ้นเคยทั้งหมดในความทรงจำของคุณ."
