  CollectionHall_144450_Desc = {
    Text = "สุริยันได้จมลงสู่ผิวมหาสมุทรแล้ว, แสงสุดท้ายซ่อนตัวอยู่เบื้องหลังเขา.\nรุ่งอรุณและยามเย็นจะสลับกันในอีกไม่นาน, เขาจะทำให้ทุกอย่างเป็นปกติ ณ ที่แห่งนี้."
