  },
  CollectionHall_144453_Title = {
    Text = "ติดอยู่ในมหาสมุทร"
  },
  CollectionHall_144454_Desc = {
    Text = "ผู้โดดเดี่ยวที่โง่เขลา, ตื้นเขิน, หยิ่งยโส, และแข็งแกร่งแต่เปราะบางภายในได้สร้างอาณาจักรของตนเอง.\nเปลือกเปล่าที่ไม่เคยเปลี่ยนแปลงจะไม่เปิดเผยความจริง, เพราะไม่มีสิ่งใด, ที่จะสามารถปะติดปะต่อหัวใจที่กลัวการเปลี่ยนแปลงจนแตกสลายก่อนเวลาอันควรขึ้นมาจากห้วงเหวได้อีก."
  },
  CollectionHall_144454_LockTip = {
    Text = "เสร็จสิ้นการล่องเรือในจิตสำนึก「เอโปยานส์นิรันดร์」"
  },
  CollectionHall_144454_Title = {
    Text = "ชัยชนะไม่รู้จบ"
  },
  CollectionHall_144476_Desc = {
    Text = "ขอให้การเต้นรำอันสั้นนี้กลายเป็นนิรันดร์ในสายธารแห่งกาลเวลาเถิด\nในคืนแห่งคำอธิษฐานครั้งต่อไป เราจะได้การพบกันอีกครั้งใต้แสงจันทร์\n*ความรักระหว่างพ่อและลูกสาว ซาบซึ้งตรึงใจ (ノへ￣、)"
  },
  CollectionHall_144476_LockTip = {
    Text = "เสร็จสิ้นบันทึกพิเศษ「รถไฟที่มุ่งสู่เทศกาลปีใหม่」"
  },
  CollectionHall_144476_Title = {
    Text = "พลุแห่งคำอธิษฐาน"
  },
  CollectionHall_145434_LockTip = {
    Text = "ต้องผ่านด่านใดด่านหนึ่งในกิจกรรมจำกัดเวลา「เกมของเลวีอาธาน：การประลองแห่งการสังหาร」"
  },
  CollectionHall_145434_Title = {
    Text = "เกมของเลวีอาธาน：การประลองแห่งการสังหาร"
  },
  CollectionHall_145460_Desc = {
    Text = "นับตั้งแต่วันที่ถือกำเนิด พระองค์ก็ตกอยู่ในความหิวโหยอันนิรันดร์\nซากกระดูกของดาวฤกษ์แตกสลายระหว่างฟันของพระองค์ ซากเดนของอารยธรรมเน่าเปื่อยในท้องของพระองค์ ความหิวโหยของพระองค์คือสาปแช่งที่เก่าแก่กว่ากาลเวลา พระองค์กลืนกิน STR ครั้งแล้วครั้งเล่า ขับเคลื่อนบรรดาทาสให้แสดงเกมแห่งอำนาจและความโลภ แต่พระองค์ไม่เคยเข้าใจว่าความหมายที่แท้จริงของพระองค์คืออะไร\nจนกระทั่งนักรบที่ชื่อโลทันมาปรากฏตัวต่อหน้าพระองค์\n「เลวีอาธาน.」\nพระองค์จำไม่ได้ว่าครั้งสุดท้ายที่ได้ยินชื่อของตนเองนั้นคือเมื่อใด บรรดากษัตริย์ที่คุกเข่าไม่กล้าเอ่ยมัน นักบวชผู้คลั่งไคล้ใช้เพลงสรรเสริญแทน\nแต่เธอเรียกพระองค์ได้อย่างง่ายดาย ราวกับอัญเชิญคู่ต่อสู้ที่รอคอยมานาน\n「ถึงเวลาที่คุณต้องออกมาแล้ว!」\nพระองค์ดำรงอยู่มาหนึ่งหมื่นสองพันปี ในความนิรันดร์อันยาวนานนั้น ดาวเคราะห์คืออาหาร สรรพสัตว์คือมดปลวก บรรดาผู้แข็งแกร่งนับไม่ถ้วนล้วนเป็นเพียงความบันเทิงชั่วคราว ไม่มีสิ่งใดทำให้พระองค์รู้สึกอิ่ม และไม่มีสิ่งใดทำให้พระองค์รู้สึกถึงความกลัว จนกระทั่งวันนี้\nมนุษย์ธรรมดาคนนี้ นักรบคนนี้ ยกดาบยักษ์ขึ้น พุ่งเข้าใส่พระองค์ดุจพายุ\nดาบยักษ์ฉีกขาดเกล็ดเกราะ ข้างหูของพระองค์ดังขึ้นด้วยเสียงคำรามที่เปล่งออกมาเมื่อครั้งถือกำเนิดจากเคออส ความโกรธของพระองค์ทำลายดาวเคราะห์ ความหิวโหยของพระองค์กลืนกินเนบิวลา\nดาบยักษ์ตัดเล็บงอขาด พระองค์นึกถึงเทพเจ้าองค์นั้นที่สวมผ้าขาวมาปรากฏต่อหน้าพระองค์ แยกตัว STR และเจตจำนงของพระองค์ออกจากกัน\nในขณะที่ดาบยักษ์แทงทะลุหัวใจ เลวีอาธานก็หัวเราะขึ้น\nหนึ่งหมื่นสองพันปี เจตจำนงที่สูญหายไปนั้น ในที่สุดก็กลับมาต่อหน้าพระองค์อีกครั้ง ฉีกพระองค์เป็นชิ้นเล็กชิ้นน้อย พิชิตพระองค์ กลืนกินพระองค์ เธอจะนำพระองค์ก้าวข้ามทุกดินแดน มุ่งสู่ห้วงดาวที่ไกลออกไป พิชิตทุกสิ่งมีชีวิตที่เข้มแข็ง\nในวันนั้น อสูรโกลาหลโบราณได้ทารกแรกเกิด ในขณะที่กลับสู่เธอ พระองค์เข้าใจอย่างถ่องแท้ว่า พระองค์และเธอ ถือกำเนิดมาจาก STR อันบริสุทธิ์และสมบูรณ์\n STR เอง คือความหมายทั้งหมดทั้งมวล."
  },
  CollectionHall_145460_Title = {
    Text = "อวสานเทพอสูรวาฬ"
  },
  CollectionHall_146400_Desc = {
    Text = "<Title:บทนำ>\nเทพเจ้าโบราณไม่อาจดับความพิโรธอันนิรันดร์ของวาฬแห่งท้องฟ้าดาวได้ จึงได้แยกวิญญาณและร่างกายของพระองค์ออกจากกัน เจตจำนงของพระองค์ตกลงสู่แผ่นดินรกร้าง กลายเป็นนักรบที่มีนามว่าโลธัน: เทพวาฬเวหา\nเธอมีนิสัยชอบสู้รบโดยธรรมชาติ มองการแสวงหาพละกำลังอันสูงสุดเป็นสัญชาตญาณและเกียรติยศเดียวที่มี ด้วยเหตุนี้ เธอจึงก้าวเข้าสู่การคัดเลือกของวาฬแห่งท้องฟ้าดาว ทำสัญญากับมัน และเมื่อพละกำลังถึงจุดสูงสุด เธอก็ใช้ดาบยักษ์สังหารดอมิเนียนของตนเอง นำอำนาจของอสูรกลืนดาวมาเป็นของตน\nกระดูกวาฬอันแหลมคมแทงทะลุคาโร กระดองกระดูกอันมืดมิดปกคลุมร่างกาย ดวงตาคู่นั้นที่บรรจุห้วงดาวไว้เหลือเพียงสายตาเย็นชาที่มองศัตรู\nเธอไม่ได้สนุกกับการล่มสลาย และไม่ยอมลดตัวลงสังหารอย่างไร้ความหมาย สิ่งที่เธอปรารถนาคือเพียงศัตรูที่น่าตื่นเต้นยิ่งกว่า และพละกำลังที่เข้มแข็งยิ่งกว่า\nนักรบผู้บริสุทธิ์ที่สุดนั้น ไล่ตามเงาของคู่ต่อสู้ที่แข็งแกร่ง เหยียบย่ำทุกมุมของห้วงดาว จนกว่าผู้แข็งแกร่งทั้งปวงจะล้มลงใต้คมดาบ จนกว่าทุกทางจะถึงจุดสิ้นสุด"
  },
  CollectionHall_146400_LockTip = {
