  },
  CollectionHall_147989_Desc = {
    Text = "ในยามนั้น ข้ายังเป็นเพียงบ่าวรับใช้ชั้นต่ำสุด ได้เป็นประจักษ์พยานแก่การเดินทางอันโหดร้ายที่ควรค่าแก่การจดจำ.\nเจ้านายผู้เป็นตำนานนั้น พลังหล่อหลอมเป็นเลือดเนื้อของเธอ เลือดร้อนเดือดกลายเป็นเปลวไฟที่ไม่มีวันดับ และแสงเพลิงก็จุดประกายในดวงตาของเธอ——\nโปรดจดจำเรื่องราวในอดีตนี้แทนข้าด้วย ลูกของข้า. ...ในที่สุดเธอได้รับชัยชนะ และพิชิตท้องฟ้าเต็มไปด้วยดวงดาว."
