  },
  CollectionHall_148138_Desc = {
    Text = "ในห้องปฏิบัติการอันกว้างขวาง อุปกรณ์ที่ละเอียดอ่อนนานาชนิดถูกจัดวางอย่างเป็นระเบียบ มีเพียงท่อและสายไฟนับไม่ถ้วนที่พันกันยุ่งเหยิง ดั่งงูที่ขดเลื้อย ทอดตัวอยู่บนพื้น แขวนอยู่กลางอากาศ.\nสัญญาณของความคิดเปรียบดั่งแม่น้ำที่ไม่มีใครมองเห็น แต่อัจฉริยะผู้นั้นคุ้นเคยกับมันมานานแล้ว สมองคือต้นกำเนิดของมัน ไหลผ่านท่อกลไก และในที่สุดก็รวมตัวกันในร่างกายที่สร้างขึ้นใหม่นี้.\nขณะที่จิตสำนึกถูกถ่ายทอด ความทรงจำที่ถูกเก็บฝังมานานก็ถูกขุดขึ้นมาอีกครั้ง ครอบครัว, มิซากะ, การทดลองที่ยังไม่เสร็จสิ้น... ในความมึนงง อัจฉริยะนึกถึงหลายปีก่อน เมื่อเธอยังไม่หลุดพ้นจากพันธนาการของร่างกายดั้งเดิม เคยมีนักเรียนคนหนึ่งที่น่าเบื่อ วนเวียนอยู่รอบๆ เธออย่างสนใจใคร่รู้ ดวงตาเปล่งประกายด้วยแสงที่ชื่อว่าความอยากรู้อยากเห็น.\n「ท่านคิดว่าร่างกายที่สร้างขึ้นโดยมนุษย์สามารถบรรจุวิญญาณที่แท้จริงได้ไหมครับ/ค่ะ?」\nมนุษย์ธรรมดามักชอบจินตนาการถึงสิ่งที่เกินกว่าสายตาของพวกเขา นี่เป็นคำถามที่ธรรมดาสามัญ แต่ในฐานะครู เธอก็ยังตอบสักสองสามคำ แม้จะไม่ยอมเงยหน้าขึ้นมองเลย.\n「ร่างกายของเจ้าก็ไม่ต่างจากสิ่งที่มนุษย์สร้างขึ้น การทำงานของหัวใจ แขนขา และประสาทสัมผัสทั้งห้านั้นแตกต่างจากกลไกอย่างไร?」\n「พอแล้ว แทนที่จะเพ้อฝันเรื่องไร้สาระเหล่านี้ ไม่ดีกว่าหรือที่จะเอาเวลาไปฝึกฝนสมองที่เป็นสนิมของเจ้า มิฉะนั้น ร่างกายที่มีเลือดไหลเวียนของเจ้าก็จะยิ่งไร้ประโยชน์มากขึ้นไปอีก.」\nบัดนี้ ผู้ที่ตั้งคำถามนั้นถูกกาลเวลาฝังกลบไปนานแล้ว ไม่มีอยู่อีกต่อไป มีเพียงถังสมองที่บรรจุปัญญาเท่านั้นที่ยังคงคิด และจะคิดต่อไปตลอดกาล.\nสิ่งที่ชาวโลกเรียกว่าวิญญาณนั้นไม่ใช่อะไรอื่น นอกจากกิจกรรมทางเคมีไฟฟ้าที่เกิดจากการเชื่อมต่อของเซลล์ประสาท 86,000 ล้านเซลล์ ไม่ว่าจะเป็นเนื้อหนังหรือกลไก ความแตกต่างของวัตถุดิบก็ไม่อาจเปลี่ยนแปลงสาระสำคัญที่ว่าพวกมันเป็นเพียงสื่อกลาง.\nใช่แล้ว มนุษย์ธรรมดาทำไม่ได้ แต่เธอในฐานะอัจฉริยะทำได้ และได้ทำสำเร็จแล้ว——มีเพียงเช่นนี้เท่านั้น จึงจะสามารถไขความจริงของโลก และบรรลุถึงยอดสูงสุดแห่งความรู้ได้.\nการมองเห็น ไม่ใช่อะไรอื่น นอกจากแสงที่ผ่านลูกตา และโฟกัสเป็นภาพบนจอประสาทตา.\nการได้กลิ่น ไม่ใช่อะไรอื่น นอกจากโมเลกุลกลิ่นที่จับกับตัวรับ ผ่านเส้นทางการรับรู้ทางเคมีของเส้นประสาท.\nการได้ยิน ไม่ใช่อะไรอื่น นอกจากคลื่นเสียงที่ถูกแปลงโดยหูชั้นใน กลายเป็นสัญญาณไฟฟ้าที่ส่งขึ้นไปยังเปลือกสมอง.\nสถานที่ที่หุ่นอยู่นั้นมืดมากเกินไป แสงไฟริบหรี่สั่นไหว แม้แต่เงาก็ไม่อาจปรากฏ เธอหลับตาลงเบาๆ เพราะรู้ดีว่าแม้จะลืมตาขึ้น สิ่งที่เห็นก็ไม่ใช่อะไรนอกจากภาพที่ไม่เคยเปลี่ยนแปลง.\nห้องถูกทำความสะอาดจนไม่มีฝุ่นแม้แต่เม็ดเดียว ยาในขวดก็ถูกปิดผนึกอย่างแน่นหนา กลไกไม่จำเป็นต้องหายใจ และยิ่งไม่จำเป็นต้องสูดอากาศไร้กลิ่นนี้เพื่อทดสอบประสาทสัมผัส.\nมีเพียงเสียงแจ้งเตือนจากกลไกที่เย็นชา ก้องอยู่ในห้องปฏิบัติการอันกว้างขวาง:\n「การซิงโครไนซ์จิตสำนึกเสร็จสมบูรณ์ ยืนยันการเปิดใช้งานกลไก.」\nเพียงพอแล้ว.\nแม้จะเป็นเสียงไร้ชีวิต แต่ฟังดูคุ้นเคย ราวกับยึดโยงความเป็นจริงของโลกวัตถุ และเหมือนเป็นเพียงการเตือนอย่างเรียบง่ายว่า การพักผ่อนชั่วคราวสิ้นสุดลงแล้ว ถึงเวลาที่จะอุทิศตนให้กับการวิจัยรอบใหม่อีกครั้ง."
  },
  CollectionHall_148138_Title = {
    Text = "จิตวิญญาณสอดประสาน"
  },
  CollectionHall_148140_Desc = {
    Text = "<Title:บทนำ>\nคืนหิมะที่ลมหนาวแทงกระดูก เด็กหญิงเท้าเปล่าได้มอบวิญญาณให้แก่หนอน.\nหากการขายสิ่งของราคาถูกเช่นนี้สามารถแลกมาซึ่งความสุขที่คนมากมายปรารถนาไม่ถึง เธอก็ไม่มีอะไรต้องลังเลเสียดาย.\nนับแต่นั้น เธอเปรียบดั่งเงาสีขาว ล่องลอยอยู่ในโลกที่แห้งแล้ง ถักทอวิหารด้วยคำโกหก ปลอมแปลงพรด้วยลูกอม เพื่อแลกกับเครื่องบูชาประทังชีวิต.\nเธอกับหนอน เปรียบดั่งคู่หูที่ดีที่สุด.\nจนกระทั่งข่าวสารใหม่ส่งมาจากยอดเขา ประกาศแก่ชาวโลกถึงดินแดนศักดิ์สิทธิ์ที่สามารถเติมเต็มทุกความปรารถนา.\nไม้ขีดไฟนั้นถูกขีดให้ลุกโชน.\nเธอจะใช้มันละลายภูเขาหิมะทั้งลูก."
  },
  CollectionHall_148140_LockTip = {
    Text = "ผ่านด่านการสอบสวนดำเนินการบทของดวงดาวบทที่ 6 「ยามขุนเขาเริงสำราญ」เพื่อปลดล็อก"
  },
  CollectionHall_148140_Title = {
    Text = "คาราบู"
  },
  CollectionHall_148143_Title = {
    Text = "ทวีปเหนือสุด"
  },
  CollectionHall_148163_Title = {
    Text = "ยามขุนเขาเริงสำราญ"
  },
  CollectionHall_149045_Desc = {
    Text = "「สวมพวงหรีดให้ดีๆ นี่คือพิธีมอบเกียรติยศของเจ้าแล้ว อัศวินน้อยที่รัก」\nเมื่อดอกเดซี่บานสะพรั่งทั่วทุ่งกว้าง มักมีทหารขี้เกียจอ้างชื่อการคุ้มกัน พาเด็กหนุ่มมาเตร็ดเตร่ที่นี่เสมอ.\nเครื่องประดับที่ถักจากดอกไม้ที่พบเห็นได้ทั่วไปที่สุดในดัชชีอากีตาน ถูกวางลงอย่างเบามือบนผมสีทอง.\n「ท่าน บางที... เราควรฝึกซ้อมแล้วหรือเปล่า？」\nเด็กหนุ่มพูดเช่นนั้น แต่ก็สวมพวงหรีดดอกไม้สีขาวให้ตรงอย่างว่าง่าย.\nพืชเล็กๆ นี้ มักอาบอยู่ในแสงสว่างเสมอ และในดินแดนของเด็กหนุ่ม มันยังเป็นสัญลักษณ์แห่งความหวัง.\nเมื่อลืมตาขึ้นอีกครั้ง ภาพอันสดใสเหล่านั้นก็ไม่หลงเหลืออยู่อีกต่อไป.\nม้าศึกร้องเสียงดัง ศัตรูรุมกันเข้ามาอย่างดูถูก ท่ามกลางกองทัพนับพัน เขามีเพียงตัวคนเดียว.\nแล้ว เสียงอึกทึกที่แสบหูก็หยุดลงอย่างกะทันหัน——\nกระแสน้ำสีดำหลั่งไหลเข้าสู่จิตวิญญาณของเขา.\nตามมาด้วยเสียงฉีกขาดของหอกที่แทงทะลุเนื้อหนัง เสียงเลือดที่พุ่งออกมา และเสียงคร่ำครวญของศัตรู.\nความดูถูกบนใบหน้าเหล่านั้นสูญสิ้นไปหมดสิ้น แทนที่ด้วยความหวาดกลัวและการถอยหนีที่ท่วมท้น.\nแต่เด็กหนุ่มก็เพียงยกมือขึ้นอย่างเป็นกลไก แทง ดึงออก แล้วยกขึ้นอีกครั้ง.\nจนกระทั่งทหารคนสุดท้ายล้มลง.\nควันฝุ่นปกคลุมใบหน้านับไม่ถ้วน ซากของผู้พิชิตและผู้ถูกพิชิตกองทับถมกันบนพื้นดิน ไม่มีความแตกต่างอีกต่อไป.\nเงามืดเลื้อยขึ้นหลังของเขา หัวเราะเยาะว่า：「ทำต่อไปสิ. วางหอกลง แล้วทำอีกครั้ง」\n「ระหว่างผู้พิทักษ์และผู้ทำลาย มีเพียงเส้นบางๆ กั้นอยู่เท่านั้น. บัดนี้ เจ้าได้เลือกแล้ว」\nความมืดปกคลุมท้องฟ้า เลือดซึมซาบแผ่นดิน.\nเขามองไปยังทุ่งกว้างในระยะไกล——เพียงคืนเดียวสั้นๆ ที่นั่นก็สูญเสียสีสันในอดีตไปตลอดกาล.\nสายลมพัดชายเสื้อของเด็กหนุ่ม และพัดผ่านผืนหญ้าที่รอดมาได้อย่างหวุดหวิดนั้น.\nในความเงียบงันของราตรี ในมุมที่แม้แต่ปีศาจก็ไม่รู้จัก ความขาวบริสุทธิ์ที่แทบมองไม่เห็นยังคงอยู่ในดวงตาของเขา.\nนั่นคือดอกเดซี่ดอกสุดท้ายของดินแดนแห่งนี้ เติบโตอย่างเงียบๆ ในที่ที่ไม่มีใครสนใจ.\nแม้จะเปื้อนสีแดง ก้านดอกงอ แต่ก็ยังไม่ล้มลง."
  },
  CollectionHall_149045_Title = {
    Text = "และดอกเดซี่ยังคงบานสะพรั่ง"
  },
  CollectionHall_149759_Desc = {
    Text = "<Title:บทนำ>\nในที่สุด โอเกียร์ก็ยอมรับว่า ด้วยวัยและพลังของเขา ยังไม่เพียงพอที่จะเป็นอัศวินผู้พิทักษ์แผ่นดิน.\nในโลกนี้ เขาไม่ได้รับคำสนับสนุนอันสำคัญนั้น.\nดังนั้น ภายใต้การชักจูงของเจ้าหญิง เขาจึงกลับไปยังดินแดนของบิดา และใช้ชีวิตเยี่ยงขุนนางหนุ่มสามัญ.\n\nเมื่อเปลวสงครามโหมกระหน่ำ โอเกียร์ผู้ไม่อาจละทิ้งตัวตนของอัศวินได้รีบรุดกลับสู่ราชวัง แต่ก็สายเกินไปเสียแล้ว.\nเจ้าหญิงทำลายตนเองด้วยวิธีอันโหดร้ายที่สุด; เพื่อนร่วมรบที่คุ้นเคยไม่มีใครรอดชีวิต——พวกเขายืนหยัดอยู่จนถึงนาทีสุดท้าย.\nเมื่อกองทัพศัตรูบุกเข้าสู่ราชวังที่พังทลายไปแล้ว ต้องการปล้นสะดมทุกสิ่ง เขาไม่อาจระงับความโกรธและความเจ็บปวด จึงเลือกมอบร่างกายให้แก่พลังแห่งความมืดอันเย้ายวนนั้น.\nศัตรูไม่ทันได้ตั้งแถวใหม่ ล้มตายสิ้นโดยน้ำมือเขา แต่หลังจากการแก้แค้น หนุ่มน้อยกลับไม่รู้สึกโล่งใจแม้แต่น้อย.\n\nเงาสีดำครอบครองร่างกายของเขา แทรกซึมเข้าสู่จิตวิญญาณของเขา ในช่วงวันเวลาอันมึนงงนั้น เขาได้ก่อความผิดพลาดมากมาย.\n\n——การสังหาร การทำลาย การกระทำทุกสิ่งที่ขัดต่อคำสาบาน......จนกระทั่งแสงสว่างเพียงแสงเดียวได้ปลุกตื่นเขาจากความว่างเปล่าอันไม่มีที่สิ้นสุด.\n\nบางที การเริ่มต้นสำนึกผิดตั้งแต่ตอนนี้ยังไม่สายเกินไป.\nเขายังมีโอกาสที่จะหยิบหอกและโล่ขึ้นมาอีกครั้ง และต่อสู้เพื่อปกป้องคุณธรรม."
  },
  CollectionHall_149759_LockTip = {
