  },
  CollectionHall_48611_Desc = {
    Text = "<Title:มิติวัตถุ>\nมิติที่วัตถุดำรงอยู่ เป็น 「โลกแห่งความเป็นจริง」 ที่มนุษย์ใช้ชีวิตประจำวันอยู่ในนั้น \nในมิติวัตถุ พื้นที่จะปรากฏในสามมิติ เวลาเป็นเส้นตรง วัตถุสามารถสัมผัสได้ อารมณ์และจิตใจเป็นนามธรรมมองไม่เห็น \nทุกอย่างดูลงตัวราวกับว่าสิ่งที่ไม่อาจเข้าใจได้ไม่เคยมีอยู่จริง \n\n<Title:มิติจิตวิญญาณ>\nมิติที่จิตวิญญาณดำรงอยู่ หรือที่เรียกอีกอย่างว่า 「มิติแห่งความฝันลวง」 \nในมิติจิตวิญญาณ อารมณ์,     ความทรงจำ,     และความยึดมั่น อาจก่อตัวเป็นบุคคลที่แตกต่างกันออกไป \nนอกจากจิตใจของบุคคลจากมิติวัตถุแล้ว ที่นี่ยังเป็นที่อยู่อาศัยของสิ่งมีชีวิตหลากหลายในมิติจิตวิญญาณ สิ่งมีชีวิตเหล่านี้ยากที่จะสังเกตเห็นด้วยตาเปล่า ต้องพึ่งพาเครื่องมือพิเศษในการรับรู้ หรือแอบมองในดินแดนลับแล"
  },
  CollectionHall_48611_Title = {
    Text = "มิติ"
  },
  CollectionHall_48612_Desc = {
    Text = "<Title:คำนิยามและความลักษณะเฉพาะ>\nปรากฏการณ์การหลอมกร่อนและการสลายตัวของสารบางชนิด.\nยกเว้นบุคคลเพียงไม่กี่คน ส่วนใหญ่ของมนุษย์ไม่สามารถสังเกตเห็นปรากฏการณ์หลอมละลายได้ด้วยตาเปล่า.\nเมื่อการหลอมกร่อนดำเนินไป การดำรงอยู่ของผู้ที่ถูกหลอมกร่อนจะถูกลบเลือน ร่องรอยชีวิต บันทึกเป็นลายลักษณ์อักษร และความทรงจำที่เกี่ยวข้องกับพวกเขาจะหายไปทั้งหมด.\nพวกเขาจะค่อยๆ ถูกลืมโดยโลกทั้งใบ.\n\n<Title:การแพร่กระจายของการหลอมกร่อน>\nไม่มีวิธีการแพร่กระจายที่สามารถตรวจสอบได้.\nการปรากฏและการหายไปของการหลอมกร่อนดูเหมือนจะสุ่มสนิท ไม่สามารถทำนายหรือติดตามได้. ในปัจจุบันสามารถทำให้การหลอมกร่อนแพร่กระจายได้ผ่านวิธีการและเครื่องมือเฉพาะ เช่น พิธีกรรมพิเศษหรือวัตถุโบราณ เป็นต้น.\n\n<Title:การแทรกแซงการหลอมกร่อน>\nสามารถแทรกแซงและทำการรักษาได้เฉพาะด้วยเงินใจและผลิตภัณฑ์เงินแท่งเท่านั้น.\nคนส่วนใหญ่มีแนวโน้มที่จะถูกการหลอมกร่อนเข้าครอบงำ แต่สามารถแทรกแซงได้ด้วยผลิตภัณฑ์เงินแท่งก่อนที่จะถูกทำลายอย่างสมบูรณ์.\nบุคคลเพียงไม่กี่คนที่มีความต้านทานต่อการหลอมกร่อนในระดับหนึ่ง แต่สภาพจิตใจของพวกเขาจะได้รับความเสียหายถาวรที่ไม่สามารถแก้ไขได้ด้วยผลิตภัณฑ์เงินแท่ง และยังไม่พบวิธีการแทรกแซงที่มีประสิทธิภาพในปัจจุบัน."
  },
  CollectionHall_48612_Title = {
    Text = "การย่อยสลาย"
  },
  CollectionHall_48614_Title = {
    Text = "ประตู"
  },
  CollectionHall_48616_Desc = {
    Text = "<Title:วันที่ก่อตั้ง>\nA.F.187 โดยมีสถาบันมิซาเกะเป็นต้นกำเนิด ก่อตั้งเมื่อ A.F.90\n\n<Title:ผู้ก่อตั้ง>\nวอร์ด·ฟิลลิปส์, เคลาร์คช์, ทาวี\n\n<Title:ภาพรวม>\nมหาวิทยาลัยพิเศษที่มีภารกิจในการต่อต้านการกัดกร่อน\nเป็นองค์กรอิสระที่เป็นกลางโดยสมบูรณ์จากรัฐบาลทุกประเทศ ไม่เข้าร่วมการต่อสู้ทางการเมืองใดๆ และไม่สังกัดฝ่ายใด\nคณาจารย์ นักศึกษา และบุคลากรทั้งหมดมีเพียงกว่าหนึ่งพันคน นอกจากหลักสูตรทั่วไปด้านเศรษฐศาสตร์ มนุษยศาสตร์ และวิทยาศาสตร์แล้ว ยังเปิดหลักสูตรพิเศษสำหรับนักสืบสวน ผู้พิทักษ์ความลับ และผู้ตื่นรู้\nวิทยาเขตหลักตั้งอยู่ในราชอาณาจักรเลโอ เมื่อเกิดปรากฏการณ์กัดกร่อนขึ้นทั่วโลก จะส่งทีมสืบสวนพร้อมนักสืบสวนและผู้พิทักษ์ความลับไปแก้ไขสถานการณ์\nเป็นองค์กรพิเศษที่ให้ความสำคัญทั้งทฤษฎีและการปฏิบัติ ผลของการสอบตกก็ร้ายแรงไม่แพ้กัน"
  },
  CollectionHall_48616_LockTip = {
    Text = "ผ่านด่านบทนำเพื่อเปิดใช้งาน"
  },
  CollectionHall_48616_Title = {
    Text = "มหาวิทยาลัยมีธาก"
  },
  CollectionHall_48618_Title = {
    Text = "บทนำ"
  },
  CollectionHall_48619_Desc = {
    Text = "<Title:วันก่อตั้ง>\nA. F. 186\n\n<Title:ผู้ก่อตั้ง>\nประเทศที่ลงนามใน«ข้อตกลงมิสเดีย»\n\n<Title:ภาพรวม>\nองค์กรระดับโลกที่ประกอบด้วยมนุษย์ทั่วไป\nได้รับการจัดตั้งขึ้นโดยการสนับสนุนทางการเงินจากหลายประเทศ เป็นอิสระจากรัฐบาล ทำหน้าที่เป็นผู้จัดการอย่างเป็นทางการและผู้ตอบสนองแรกต่อปรากฏการณ์หลอมละลาย\nสมาชิกส่วนใหญ่เป็นคนธรรมดาที่ไม่มีพื้นฐานทางลึกลับหรือความสามารถเหนือธรรมชาติ โดยมีเป้าหมายและภารกิจสำคัญเพียงอย่างเดียวคือการต่อสู้กับการหลอมกร่อน\nมีสำนักงานหลายแห่งในประเทศต่างๆ ทั่วโลก แต่ละแห่งรับผิดชอบพื้นที่เฉพาะของตนเอง\nความเคร่งครัดและการยึดมั่นในกฎคือความประทับใจแรกของทุกคนที่มีต่อองค์กรนี้ เครื่องแบบสีขาวที่ซักจนแข็งสะท้อนบุคลิกที่ตั้งตรงและจริงจังของพวกเขา"
  },
