  CollectionHall_48631_Desc = {
    Text = "หอยโข่งตัวน้อยสีเหลืองนี้มีต้นกำเนิดที่สูงส่ง พร้อมกับแหล่งที่มาที่สมบูรณ์แบบและไร้ที่ติ"
