  },
  CollectionHall_48631_Title = {
    Text = "<WhiteQuality: หอยโข่งเหลือง>"
  },
  CollectionHall_48635_Desc = {
    Text = "<Title:คำแนะนำ>\nมิซากะ รักษาการณ์คณบดี.\nเป็นศิษย์ของโครว์ลี่·แมคคินนอน และเป็นรุ่นน้องโดยตรงของเฮอร์เบิร์ต.\nเป็นหนึ่งในผู้เห็นเหตุการณ์ที่เฮอร์เบิร์ตลอบสังหารอาจารย์ของตน หลังจากที่อาจารย์เสียชีวิตก็ได้จัดการเรื่องของสถาบันแทนมาโดยตลอด.\nเป็นผู้ที่ให้ความสำคัญกับประสิทธิภาพสูงสุดอย่างแท้จริง ไม่เคยมาสาย ผมสั้นเพราะสามารถประหยัดเวลาในการหวีผมได้.\nอพยพจากบ้านเกิดเอลค์มาที่เลโอเนียเพราะสงคราม.\nนิ้วชี้ขวาไม่สามารถงอได้ตามปกติ มีข่าวลือว่าเป็นหลักฐานจากการถูกทารุณกรรมในค่ายกักกัน."
  },
  CollectionHall_48635_LockTip = {
    Text = "ผ่านด่านบทนำเพื่อเปิดใช้งาน"
  },
  CollectionHall_48635_Title = {
    Text = "ชอร์ท"
  },
  CollectionHall_48636_Desc = {
    Text = "<Title:คำแนะนำ>\nหนึ่งในสามผู้ก่อตั้ง ร่วมกับวอลด์ ฟิลลิปส์ และเคราลค์ช์ ได้ก่อตั้งสถาบันมิซากะ ซึ่งเป็นต้นแบบของมหาวิทยาลัยมิซากะ\nเป็น「ร่างกายที่ตื่นขึ้น」ลำดับแรก และเป็นผู้ให้เทคโนโลยีร่างกายที่ตื่นขึ้น\nปกติประจำการอยู่ที่สระดำ คนที่เคยเห็นใบหน้าของเธอสามารถนับได้ไม่เกินสองมือ เป็นหนึ่งในความลับสูงสุดของมหาวิทยาลัยมิซากะ\n「ชู่...อย่าทดสอบ@2ของคุณ」"
  },
