  },
  CollectionHall_48950_Desc = {
    Text = "นั่นคือแวบหนึ่งของความจริงอันนิรันดร์และไร้ตำหนิ."
  },
  CollectionHall_48950_Title = {
    Text = "สไลม์หวาน"
  },
  CollectionHall_48968_Desc = {
    Text = "เกี่ยวกับไม้เท้าของลอร์ดเดกสเตอร์ มีการคาดเดามากมายในวิทยาเขตของมิซากะ。\n\n「ไม่มีข้อสงสัยเลยว่า ไม้เท้าของลอร์ดและรอยยิ้มของเขาก็ซ่อนความลับไว้เช่นกัน。\nมันมีเพชรเงินที่สามารถเรียกพลังของผู้ปลุกตื่นได้หรือไม่ หรือซ่อนดินปืนไว้เพื่อเปลี่ยนเป็นอาวุธได้ทุกเมื่อ? \nให้ลอร์ดเดกสเตอร์เป็นผู้เปิดเผยให้เราทราบกันเถอะ!」\n\nขณะที่อ่านและจดบันทึกบทนำ ฮันนาก็ชี้กล้องไปที่ลอร์ดเดกสเตอร์ หวังว่าจะได้ฟังคำพูดจากเจ้าของเอง。\n\n「มันเหรอ? ไม่มีอะไรพิเศษเลย แค่ไม้เท้าที่ใช้ในชีวิตประจำวันที่สั่งทำจากตระกูลเดกสเตอร์เท่านั้น。\nอัญมณีที่ใช้บนไม้เท้านี้ ยังไม่เท่ากับความมีค่าของพี่ชายของฉัน。\nถ้าต้องพูดว่ามันมีความพิเศษอะไร...\nมันเคยมีเลือดของพ่อแม่และพี่ชายของฉันติดอยู่ นี่ถือเป็นความพิเศษไหม?」"
  },
  CollectionHall_48968_Title = {
    Text = "ไม้เท้าของลอร์ด"
  },
  CollectionHall_48969_Desc = {
    Text = "มีเรื่องเล่าหนึ่งที่เล่าขานกันในโลกใต้ดินของลอนดีเนี่ยน。\n\nที่ท่าเรือที่วุ่นวาย,ในซอยที่เงียบสงบ,ในบาร์ที่เสียงดัง……\nคุณไม่รู้ว่าเมื่อไหร่,ที่ไหนจะพบสาวน้อยที่ถือกล้อง,สวมแว่น,และใส่เครื่องแบบ แต่ขอแค่คุณพบเธอ คุณก็จะสามารถซื้อข้อมูลที่คุณต้องการได้ทุกอย่าง โดยมีค่าใช้จ่ายเพียงหนึ่งเดียว—\n\nนั่นคือการให้ความลับที่มีเพียงคุณเท่านั้นที่รู้。\n\nมีคนแลกความจริงที่ได้ยินจากบาร์มาสำหรับจุดอ่อนที่ร้ายแรงของคู่ต่อสู้。\nมีคนแลกจุดอ่อนของตนเองเพื่อให้คนรักไม่พูดถึงอดีต。\nสาวน้อยถือข้อมูลมากมาย แต่มีเพียงเรื่องเดียวที่ไม่สามารถแลกเปลี่ยนด้วยความลับใดๆ ได้。\n\n「เกี่ยวกับเรื่องของฉันเหรอ? ขอโทษนะ นี่คือของที่ไม่ขายนะ」"
  },
  CollectionHall_48969_Title = {
    Text = "ข้อมูลคือชีวิต"
  },
  CollectionHall_48970_Desc = {
    Text = "ในมหาวิทยาลัยมิสซาก้า คนที่ไม่สามารถไปกวนได้มากที่สุด หากดอร์ลเป็นคนที่สองแล้ว คนแรกที่แน่นอนเลยก็คือคุณซิลเวีย\n\nในฐานะนักจิตวิทยาเพียงคนเดียวในมหาวิทยาลัยมิสซาก้า คุณซิลเวียผู้ลึกลับนี้ ไม่เพียงแต่ดูแลจิตวิทยาของนักสืบที่ตกใจกับภารกิจ แต่ยังมีหน้าที่ช่วยปรับอารมณ์ของผู้ที่ตื่นตัว\n\nไม่เพียงแค่ไม่เกรงกลัวผู้ที่ตื่นตัว แต่ก็ยังสามารถต่อสู้กับพวกเขาทางจิตใจได้อย่างทัดเทียม - ผู้ยิ่งใหญ่ที่ยอดเยี่ยมเช่นนี้เธอเป็นอย่างไรกันนะ?\n\nด้วยความอยากรู้เกี่ยวกับสิ่งที่ไม่รู้จัก น้องใหม่ที่ขาดความยำเกรงเล็กน้อยแอบเข้าไปในห้องตรวจสอบของคุณซิลเวียในคืนดึก\n\nจากนั้นพวกเขาก็หมดสติ\n\nพอตื่นขึ้นมาในตอนเช้าบริเวณลานมหาวิทยาลัย พวกเขาปวดหัวอย่างหนัก แต่ในใจกลับรู้สึกปลอดโปร่งมากกว่าที่เคยเป็น\n\nมีคนหนึ่งหยิบกระดาษที่ลอยออกมาจากกระเป๋าของพวกเขาขึ้นมา แล้วพบข้อความว่า:\n\n「หากต้องการคำปรึกษาทางจิตวิทยา กรุณาขอนัดล่วงหน้ากับคุณอิริกาก่อนนะคะ— ซิลเวีย」"
  },
  CollectionHall_48970_Title = {
    Text = "กำแพงแห่งจิตใจ"
  },
  CollectionHall_48971_Desc = {
    Text = "เมื่อคุณหญิงผู้สูงศักดิ์ใช้ผ้าเช็ดหน้าปิดจมูกด้วยความสงสารและความรังเกียจ และสั่งให้คนรับใช้ส่งเครื่องประดับที่ไม่ต้องการให้เธอ เธอก็นึกในใจว่า \nจะดีแค่ไหนถ้าเด็ก ๆ ในบ้านคนจนได้กินเนื้อสักมื้อหนึ่ง \n\nเมื่อเธอแบ่งอาหารของตัวเองให้เด็ก ๆ จนตัวเองเป็นลมล้มลงในทางเดินเพราะความหิวโหยที่ยาวนาน เธอก็พูดว่า \nไม่เป็นไร ไม่ต้องเรียกหมอนะ ค่ารักษาพยาบาลสามารถซื้อขนมปังได้หลายก้อนเลย \n\nเมื่อศิลปินใจดีพาหมอที่รู้จักมาเยี่ยมและเสนอความร่วมมือระยะยาวให้เธอ เธอก็นึกในใจว่า \nต้องให้พวกเขาทดลองกับฉันก่อน ไม่อย่างนั้นฉันไม่สบายใจที่จะให้เด็ก ๆ มารับการรักษาของพวกเขา \n\nซาร่าสามารถทนทุกอย่างได้ แต่สิ่งเดียวที่เธอไม่สามารถทนได้คือสิ่งที่ทำไปทั้งหมดกลับนำไปสู่ผลลัพธ์ที่น่าเศร้า。"
  },
  CollectionHall_48971_Title = {
    Text = "จุดวิกฤต"
  },
  CollectionHall_48972_Desc = {
    Text = "มือกำลังหมุนวนในความมืด ค้นหาผู้เป็นเจ้าของของมัน \n\n ในคืนที่เต็มไปด้วยเลือดนั้น มันถูกฉีกออกจากเจ้าของอย่างโหดร้าย \n ในขณะนี้ ผู้ที่นำมันไปกำลังไหลเวียนรอบตัวมัน ส่งเสียงหวีดหวิวแปลกประหลาด \n \n 「ปล่อยไปเถอะ มาอยู่กับเรา ช่างทำหุ่นขี้ผึ้งจะทำให้คุณถูกลืม」 \n\n มือไม่สนใจ มันเคลื่อนย้ายไปยังนิ้วมือที่ยาวเรียวซึ่งมันภูมิใจ \n\n 「เจ้าของจะไม่ลืมฉัน \n ฉันคือทางเดียวที่เขาจะทำศิลปะให้เป็นจริง—— \n พวกคุณไม่เข้าใจว่าฉันหมายถึงอะไรสำหรับเขา」 \n\n 「เหมือนกับที่คนจะลืมคนรัก ลืมเวลา แต่จะไม่ลืมตัวเอง」 \n\n เสียงหัวเราะที่เห็นอกเห็นใจดังมาจากความมืด \n 「ตรงกันข้าม คนมักจะลืมตัวเองเป็นคนแรกเสมอ \n แต่ไม่เป็นไร——」 \n\n เวลาอธิบายทุกอย่าง มือจะเข้าใจความจริงนี้ในไม่ช้า: \n ไม่มีอะไรที่ไม่สามารถถูกลืมได้ \n มันไหลผ่านศตวรรษแล้วศตวรรษเล่า เรื่องราวในโลกเกิดขึ้นรอบๆ มัน และพรุ่งนี้จะถูกลืม \n แต่พวกมันยังคงไหลต่อไปไม่หยุด。"
  },
  CollectionHall_48972_Title = {
    Text = "มือที่ถูกลืม"
  },
  CollectionHall_48973_Desc = {
    Text = "ตั้งแต่ได้รับการอุปการะจากคุณวอร์ด ฟิลลิปส์ อลิสเตอร์ได้เข้าร่วมการประชุมระดับสูงของมิซากะหลายครั้ง。\n\nพูดถึงระดับสูง จริงๆ แล้วมันก็เหมือนการแข่งขันอภิปรายที่จัดขึ้นเดือนละครั้ง：\nคุณฟิลลิปส์มีน้ำเสียงที่อ่อนโยนและชี้แนะอย่างใจเย็น；\nเคลาร์คัสพูดจาเฉียบขาดและไม่ยอมให้ใครก้าวข้าม。\nพวกเขาสลับกันเป็นฝ่ายสนับสนุนหรือฝ่ายค้าน เพื่ออนาคตของมิซากะหรือการจัดสรรทรัพยากรของระบบการตื่นรู้ในเดือนหน้าอย่างไม่รู้จักเหน็ดเหนื่อย。\nคุณทาวิลเป็นผู้ชมที่เงียบ ไม่เคยให้คำแนะนำอย่างง่ายดาย。\nเขาพยายามทำตัวให้เป็นกรรมการที่ตรงไปตรงมา บางครั้งก็ทำหน้าที่เป็นผู้ตัดสิน และถึงขั้นต้องใช้ทักษะการต่อสู้ในบางครั้ง เพื่อหลีกเลี่ยงไม่ให้โต๊ะประชุมเล็กๆ ประสบอุบัติเหตุ。\n\nณ ตอนนี้ สมาชิกในการประชุมเหลือเพียงสองคน หนึ่งคนไม่สามารถออกจากสระดำได้ตลอดไป อีกคนก็ไม่สามารถออกจากใต้ดินได้เพื่อหวังจะได้ 「อนาคต」 ที่อาจเกิดขึ้น。\nส่วนโต๊ะนั้น หาไม่เจออีกตั้งแต่เหตุการณ์ครั้งนั้น。"
  },
  CollectionHall_48973_Title = {
    Text = "เวลาพบกัน"
  },
  CollectionHall_48974_Desc = {
    Text = "ทาวีหลับใหลอยู่ที่ก้นสระดำ\n\nที่นั่นไม่มีเสียงและแสงตลอดทั้งปี มีเพียงความมืดที่ทำให้สิ้นหวัง\nไม่เคยมีแขกคนใดมาเยือนที่นี่ ไม่เคยมีเสียงใดถึงที่นี่\nที่นี่คือดินแดนที่การทำลายล้างไม่สามารถเข้าถึงได้——\n\nเพราะภัยพิบัติได้มาถึงแล้ว\n\nในฐานะผู้ควบคุมลำดับกาลเวลา เธอได้เห็นจุดจบที่เจ็บปวดมากมาย\nในฐานะส่วนหนึ่งของกฎ เธอจึงไม่สามารถหยุดยั้งความมืดที่กำลังมาถึงได้\nหากเป็นเช่นนั้น เธอจึงต้องจำศีลอยู่ในดินแดนที่ไม่มีอยู่ โดยรอคอยผู้ที่เรียกว่า「ตัวแปร」มาถึงในรูปแบบที่ไม่มีอยู่\n\nวันหนึ่ง ผู้นั้นจะมาถึง"
  },
