  },
  CollectionHall_48984_Title = {
    Text = "แอนตินอมี"
  },
  CollectionHall_48985_Desc = {
    Text = "ตัวแทนคณบดีเป็นบุคคลแปลกประหลาดในวิทยาเขตมิสซาก้า。\n\nในหมู่ผู้สืบสวนของมิสซาก้าที่มีความสามารถพิเศษและมอนสเตอร์ที่แพร่ระบาด มีเพียงส่วนน้อยที่ไม่มีความสามารถเกินกว่าพื้นฐานมนุษย์ และตัวแทนคณบดีคือหนึ่งในนั้น แต่เธอกลับได้รับตำแหน่งหน้าที่สำคัญในบทบาทนี้\nเกิดในครอบครัวธรรมดาแห่งอาณาจักรเอลค์ เธอเติบโตภายใต้วัฒนธรรมท้องถิ่นที่หล่อหลอมให้เธอมีบุคลิกรุนแรงและกล้าหาญ\n\nต่อมา เพื่อนร่วมค่ายเชลยโซเฟียได้จุดประกายความสนใจในงานวิจัยทางวิชาการให้เธอ\nความสำเร็จที่โดดเด่นทางวิชาการ ทำให้เธอได้รับการยอมรับจากอาจารย์ที่ปรึกษา และเป็นลูกศิษย์ที่ได้รับการยอมรับมากที่สุดของอดีตคณบดีคณะชีววิทยาแห่งมหาวิทยาลัยมิสซาก้า\nดังนั้น เมื่ออาจารย์ที่ปรึกษาหายตัวไป เธอจึงเข้ามารับหน้าที่ตำแหน่งคณบดีชั่วคราวโดยธรรมชาติเหมาะสม\nด้วยการยืนหยัดของเธอ งานวิจัยของคณะชีววิทยาจึงดำเนินไปอย่างเป็นระเบียบเรียบร้อย\n\n「ไม่หวาดกลัวต่อความรุนแรง ไม่หวาดกลัวต่ออำนาจเผด็จการ และแน่นอนว่าไม่หวาดกลัวต่อหน้าที่ที่ได้รับ」"
  },
  CollectionHall_48985_Title = {
    Text = "หน้าที่"
  },
  CollectionHall_48986_Desc = {
    Text = "มีข้อกำหนดที่ไม่เป็นลายลักษณ์อักษรระหว่างนักสืบว่า \n\nในคืนหลังพิธีกรรมสุสานกุญแจ นักสืบที่มีประสบการณ์มากกว่าจะนำพานักสืบหน้าใหม่ไปจัดงานเลี้ยงที่สวนหลังหอพัก \nพวกเขาจะจุดเทียน นั่งเป็นวงรอบกุญแจเงินของตัวเอง \nนักสืบที่มีประสบการณ์จะเล่าเรื่องราวเกี่ยวกับกุญแจที่มีหมายเลขเฉพาะตัวนี้ให้กับนักสืบหน้าใหม่แต่ละคน \n\nกิจกรรมแบบนี้จะกลายเป็นงานเล่าเรื่อง และกุญแจเงินหมายเลข I-0001 และ K-0001 ซึ่งเป็นตัวแทนของ 「รุ่นแรก」 ก็จะกลายเป็นจุดสนใจในการสนทนา \nมีน้อยคนที่รู้ว่า กุญแจเงิน K-0001 ที่ทำขึ้นด้วยมือโดยผู้พิทักษ์รุ่นแรกนั้น ปัจจุบันอยู่ร่วมกับเจ้าของในใต้ดิน ตลอดการรอคอยที่ไม่มีการแยกวันคืน ฟังเสียงกระซิบจากผู้ที่จากไปแล้ว \n\n 「เธอรู้ไหมว่าเขาไม่ได้อยู่ที่นี่จริงๆ ใช่ไหม อลิสเตอร์」 ดอลล์กล่าว 「มันอาจจะทำจากเงินใจของอาจารย์เธอ แต่ไม่สามารถมองว่าเป็นวิญญาณของเขา」 \n 「นี่เป็นเพียงวิธีการของจิตใจที่มุ่งมั่นเท่านั้น ดอลล์」 อลิสเตอร์ยิ้ม 「ไม่ต้องห่วง ฉันมั่นคง ไม่สามารถล้มลงก่อนที่ผู้พิทักษ์หน้าใหม่ของเราจะเติบโตขึ้นได้ เธอพูดถูกไหม?」"
  },
  CollectionHall_48986_Title = {
    Text = "จิตใจที่มุ่งมั่น"
  },
  CollectionHall_48987_Desc = {
    Text = "ช่วงชีวิตครึ่งแรกของเขาเต็มไปด้วยเคออส ความมืด และเลือด\n\nกินแล้วนอน นอนแล้วกิน......ต่อมา เขาลืมตาขึ้นและมีสติ\n\nพวกเขาบอกว่าเขากินพี่น้องของเขาทั้งหมด เป็นผู้รอดชีวิตคนเดียว\nพวกเขายังบอกว่าเขาคือบุตรของเทพเจ้าผู้ยิ่งใหญ่ที่ผสมกับมนุษย์\nที่ลำคอของเขามีวงเวทย์สีดำพันธนาการ ซึ่งรักษาชีวิตของเขาและควบคุมเขา ทำให้เขาไม่สามารถขัดขืนโบสถ์ได้ในชีวิตนี้\nเขามีความสงสัยและความอยากรู้อยากเห็นเกี่ยวกับโลกใบนี้ แต่ตั้งแต่เกิดเขาถูกพรากโอกาสอื่นๆ ทั้งหมดออกไป\n\nงดงามและอันตราย ซ่อนเร้นและโดดเด่น นี่คือเขา\nน่าเสียดายที่คำบรรยายข้างต้นยังไม่ถึงหนึ่งในสิบของแก่นแท้ของเขา\nความเห็นใจใดๆ ที่เกิดจากคำบรรยายนี้ต่ออัลบิโนจะทำให้คุณตกนรกไม่รู้จบ。"
  },
  CollectionHall_48987_Title = {
    Text = "การผูกคำสาปขมขื่น"
  },
  CollectionHall_48988_Desc = {
    Text = "หน้าที่ของหมอคือการรักษาผู้ป่วย\n\nแต่มีวิธีการรักษาหนึ่งที่ต้องใช้มีดที่คมที่สุดกรีดผิวหนัง เจาะเข้าไปในเนื้อเยื่อ เปิดอกออกมา เพื่อนำเอาโรคออกไป แล้วอวยพรให้ร่างกายมีความสามารถในการฟื้นฟูตนเอง\n\nนี่ไม่ควรจะเป็นความผิดของเธอ\nแต่ทุกครั้งหลังจากการผ่าตัดเสร็จสิ้น เธอก็อดไม่ได้ที่จะเล่าเรื่องราวให้กับเด็กหญิงฟังเหมือนเป็นการชดเชย\nเธอไม่ใช่นักเล่าเรื่องที่ดี คำพูดของเธอขาดๆ เกินๆ แต่เรื่องราวที่เธอแต่งขึ้นยังทำให้เด็กหญิงตั้งใจฟังอย่างจริงจัง\nบริเวณที่เธอตัดดูเหมือนจะค่อยๆ ดูดซับพลังของคำพูดเหล่านั้นอย่างช้าๆ และแข็งแกร่ง และเริ่มฟื้นฟูอย่างเป็นธรรมชาติ……"
  },
  CollectionHall_48988_Title = {
    Text = "การเฉือนและรอยแผล"
  },
  CollectionHall_48989_Desc = {
    Text = "สัตว์ยักษ์ซ่อนตัวอยู่ในความมืดของคืน \n\nภายในกระท่อม เสียงร่ำไห้จากการสูญเสียลูกสาวที่รักจึงดังขึ้นในทุกๆ เที่ยงคืน ทำลายความอดทนและความกดดันของช่วงกลางวันอย่างไม่มีการปิดบังและรุนแรง \nจากการสะอื้นไปจนถึงเสียงร้องทุกข์ สุดท้ายก็พูดถึงชื่อที่ไม่เป็นของสัตว์ยักษ์อีกต่อไป ด้วยเสียงเรียกที่เจ็บปวดทะลวงเข้าไปในหัวใจที่เหมือนมนุษย์ของสัตว์ยักษ์ \n\nกลับบ้านเถอะ ลิซ่า \nโอ้ ลิซ่าของฉัน \nสัตว์ยักษ์เงียบอยู่ ซ่อนตัวอยู่ในความมืดของคืน หดตัวลงและหลับลึก \nวันหนึ่งเธอจะกลับไป กลับไปยังสถานที่ที่เรียกว่า 「บ้าน」"
  },
  CollectionHall_48989_Title = {
    Text = "ซ่อนตัวในความมืด"
  },
  CollectionHall_48990_Desc = {
    Text = "ไม่มีใครเกิดมาเป็นกัปตันโดยตรง อย่างน้อยเอลตันก็ไม่ใช่ \n\n ก่อนที่จะเป็นกัปตัน เขาได้เปลี่ยนแปลงระหว่างกองทัพเรือและเรือพาณิชย์หลายครั้ง จนเกือบจะกลายเป็นโจรสลัดหลายครั้ง โชคดีที่ในที่สุดเขาก็ได้ตั้งหลักอยู่บนเรือสำรวจลำหนึ่ง \n\n เรือสำรวจล่องรอบทวีปขั้วโลก ทุกครั้งที่ขึ้นฝั่งหมายถึงการผจญภัยครั้งใหม่ \n หน้าที่ของเขาคือการแบกสัมภาระให้กับนักวิทยาศาสตร์ที่อ่อนแอ เขาเคยรู้สึกภูมิใจในเรื่องนี้—สัมภาระที่บรรจุอยู่ อาจจะเป็นสิ่งที่สามารถเปลี่ยนแปลงโลกได้ \n และพวกเขาอาจจะเป็นผู้ที่จะเขียนประวัติศาสตร์ใหม่ \n\n ก่อนที่พายุหิมะจะทำให้พวกเขาติดอยู่ในถ้ำน้ำแข็ง ก่อนที่กลุ่มลัทธิลึกลับจะโจมตีพวกเขาในตอนกลางคืน เอลตันเคยคิดเช่นนี้อยู่เสมอ。"
  },
  CollectionHall_48990_Title = {
    Text = "กระเป๋าสะพายหลังผจญภัย"
  },
  CollectionHall_48991_Desc = {
    Text = "เขาเป็นนักเรียนที่เงียบขรึมและขยันมาตลอด \n\nตอนเช้า 8 โมง เมื่อเหล่านักวิจัยคนอื่นรีบเดินทางมาพร้อมกับขนมปังอยู่ในปาก เขาได้เขียนรายงานการทดลองเสร็จเรียบร้อยแล้ว \nตอนเที่ยงคืน เมื่อไฟในอาคารทดลองดับสนิท เขาจึงค่อยๆ เก็บของแล้วออกไป \n\nอ้อ เขายังให้อาหารแมวจรจัดตัวเล็กๆ ในละแวกใกล้เคียงทุกวัน \nต่อมาแมวจรจัดเหล่านั้นหายไป ไม่มีใครรู้ว่าพวกมันไปไหน \n\nอาจารย์ครอว์ลีย์กำลังวิเคราะห์บันทึกการทดลองและรายงานของเขา \nกระชับและละเอียด ไม่มีจุดเด่นใดๆ — แต่ก็ไม่มีจุดอ่อนใดๆ \nนักเรียนคนนี้ทำให้เขาสงสัย \nแต่ความสงสัยนั้นเป็นสิ่งที่ดี มันมักจะเป็นสวิตช์ที่นำไปสู่ความอยากรู้ \n\nแน่นอน ในตอนนั้นครอว์ลีย์ไม่ได้คาดคิดว่า: มันอาจจะเป็นสวิตช์ที่นำไปสู่ความตายได้เช่นกัน。"
  },
  CollectionHall_48991_Title = {
    Text = "กายวิภาคความตาย"
  },
  CollectionHall_48992_Desc = {
    Text = "「ไม่รู้ตัวเลย คุณหายไปนานขนาดนี้แล้ว。\n\nฉันยังคงกลับไปที่วันนั้นในความฝันอยู่บ่อยครั้ง ความเจ็บปวดจากบาดแผลที่แขนซ้าย ความมึนงงที่เกิดจากการเสียเลือด การไล่ล่าจากหนูที่โกลาหล…\nในความโกลาหลนั้น คุณในชุดนักเรียนมิซากะปรากฏตัวขึ้น พาฉันหนีออกจากปราสาทเก่าที่เต็มไปด้วยความไม่ดีงาม。\n\nในความฝันครั้งสุดท้าย คุณยืนอยู่หน้าหมอน ฉันถูกเตือนว่า สำหรับนักสืบ ความตายมักจะติดตามอยู่เสมอ。\nฉันไม่สามารถตัดสินใจได้ว่า นั่นคือความจริงหรือจินตนาการของฉัน。\nทุกครั้งที่เป็นแบบนี้ ฉันจะไปสัมผัสที่แขนซ้ายของฉัน หากฉันสามารถสัมผัสกับพื้นผิวโลหะที่เย็นเฉียบและประณีตได้ นั่นคือความจริง。\n\nแต่ในความฝันอีกมากมาย ฉันกลับจับเพียงแค่ความว่างเปล่าเท่านั้น。」"
  },
  CollectionHall_48992_Title = {
    Text = "แด่เพื่อนรัก"
  },
  CollectionHall_48993_Desc = {
    Text = "ครอว์ลีย์ในระหว่างที่สอนยังคงได้รับรางวัล \"อาจารย์ที่ได้รับความนิยมสูงสุด\" อย่างต่อเนื่อง\n\nสำเนียงคอนสแตนตินที่ดูเหมือนจะขัดแย้งและรอยยิ้มที่จริงใจของเขาทำให้เขาได้รับความชื่นชอบจากนักเรียนจำนวนมาก รวมถึงเฮอร์เบิร์ตด้วย\n\nในปี A.F.2@1 ครอว์ลีย์ได้ตัดสินใจอย่างเด็ดเดี่ยวที่จะรับเฮอร์เบิร์ตที่ดูไม่เด่นเป็นนักเรียนของเขา\nเฮอร์เบิร์ตได้เดินทางร่วมกับเขาข้ามภูเขา ข้ามลำธาร และผ่านทะเลทราย ทิ้งรอยเท้าไว้ที่รอยแยกการหลอมละลายทีละแห่ง\nเขายังจำความรู้สึกตกตะลึงในครั้งแรกที่เห็นรอยแยกการหลอมละลายได้\n\nครอว์ลีย์ยืนอยู่หน้าหมอกสีดำที่พวยพุ่งออกมา ร่างของเขาดูเล็กน้อยมาก\n“ชูว์—คุณได้ยินไหม?”\nเฮอร์เบิร์ตจึงหลับตาและได้ยินเสียงของมหาสมุทรที่เงียบสงบกำลังโหมกระหน่ำ โลกดูเหมือนจะห่างไกลจากเขา\nครอว์ลีย์ตื่นเต้นมาก เขาพูดว่า\n“นี่คือบทกวี บทกวีที่ลึกลับและลึกซึ้งที่สุดในจักรวาล”\n\nหลายปีต่อมา ความทรงจำของเฮอร์เบิร์ตเกี่ยวกับครอว์ลีย์ได้จางหายไปแล้ว\nเช่นเดียวกับที่พวกเขาทำงานร่วมกันและมีข้อขัดแย้งกัน เช่นเดียวกับที่เขา \"พลาด\" ทำให้เขาเสียชีวิต\nแต่เขาจะจำรอยยิ้มใต้หมอกสีดำนั้นได้ตลอดไป\nในช่วงเวลานั้น เขาเห็นบทกวี。"
  },
