  },
  CollectionHall_49015_Desc = {
    Text = "เมื่อภัยพิบัติลอยหายไป วิกฤตก็ประกาศยุติชั่วคราว ทีมปฏิบัติการพิเศษจากมิซากะได้ออกจากอาร์คต์พร้อมกับ「โชคหล่นทับ」\nคุณเดกสเตอร์หันกลับไปมองหลุมขนาดใหญ่ที่เกิดจากการระเบิด ไม่รู้พืชที่ไม่รู้จักนั้นงอกขึ้นมาเมื่อไหร่\nเธอถอนหายใจอย่างโล่งอก รู้สึกมีความสุข\nฤดูใบไม้ผลิจะมาถึงในอาร์คต์ลินด์\nต้นหลิวจะเริ่มแตกใบเมื่อฤดูใบไม้ผลิหน้ามาถึง ดอกลิลลี่แห่งหุบเขาจะบานสะพรั่งในฤดูฝนถัดไป ทุกชีวิตจะได้เริ่มต้นใหม่\nและการเดินทางต่อสู้กับสิ่งที่ไม่รู้จักของพวกเขาก็จะเริ่มต้นขึ้นใหม่อีกครั้ง\n"
  },
  CollectionHall_49015_Title = {
    Text = "ฤดูใบไม้ผลิในอาคูชเน็ท"
  },
  CollectionHall_49018_Desc = {
    Text = "A.F. 314 ในคืนฤดูหนาวที่มืดมิด เสียงระเบิดดังกึกก้องไปทั่วอาร์คต์ลินดา \n โลกาเริ่มสั่นสะเทือน ป่าไม้สว่างไสวราวกับกลางวัน \n พร้อมกับเสียงแผดเสียงร่ำร้องของชีวิตและเสียงร้องไห้ของธรรมชาติ หมู่บ้านถูกทำลายจนราบเป็นหน้ากลอง \n ตามคำกล่าวของเดกสเตอร์ นักเรียนระดับปริญญาตรีของระบบการตื่นรู้ที่เข้าร่วมในการ 「สอบสวนภัยพิบัติอาร์คต์」 ในคืนนั้น เปลวไฟที่พุ่งขึ้นสู่ท้องฟ้าส่องประกายด้วยสีดำและเงิน。"
  },
