  CollectionHall_49030_Desc = {
    Text = "แพร่พันธุ์เถอะ แพร่พันธุ์เถอะ ให้วิญญาณที่ไหลไปด้วยเลือดของต้นแม่แผ่ขยายไปทั่วโลก。"
