  },
  CollectionHall_49105_Title = {
    Text = "ผู้เลี้ยงวิญญาณ"
  },
  CollectionHall_49740_LockTip = {
    Text = "ผ่านด่านการสอบสวนดำเนินการ 7-0 เพื่อเปิดใช้งาน"
  },
  CollectionHall_49740_Title = {
    Text = "มารดาของหมื่นลูกหลาน"
  },
  CollectionHall_49747_Desc = {
    Text = "เนื้องอกที่เติบโตขึ้นจากรอยแผลกัดกร่อน\nจนถึงปัจจุบัน ยังไม่สามารถสรุปกฎเกณฑ์ใดๆ เกี่ยวกับการเจริญเติบโตของเนื้องอก รวมถึงการกระจายตัวของเนื้องอกแต่ละประเภทได้\nอาจเป็นแขนขาส่วนเกิน หนวดรยางค์ หรืออาจเป็นสิ่งอนินทรีย์อย่างฟันเฟือง โลหะ ก็เป็นได้"
  },
  CollectionHall_49747_Title = {
    Text = "การเจริญเติบโตผิดปกติ d"
  },
  CollectionHall_49748_Desc = {
    Text = "<Title:คำนิยามและลักษณะเฉพาะ>\nมีเส้นผ่านศูนย์กลางมากกว่า 5 เมตร และยังมีความเป็นไปได้ที่จะขยายตัวต่อไป รอยละลายขนาดใหญ่ที่เกิดจากการหลอมกร่อน \nรอยแยกการหลอมละลายสามารถแบ่งออกเป็นประเภท C, B, A, S, SS, SSS ตามขนาดของรอยแยก \nเมื่อเวลาผ่านไปจะขยายตัวอย่างต่อเนื่อง นอกจากการแพร่กระจายของการหลอมกร่อนปกติแล้ว ยังอาจทำให้เกิดปรากฏการณ์ธรรมชาติที่ผิดปกติ เช่น สึนามิ พายุเฮอริเคน เป็นต้น \n\n<Title:วิธีรับมือ>\nกุญแจเงินที่ทำจากเงินใจสามารถระงับหรือแม้กระทั่ง「ปิด」รอยแยกได้ในระดับหนึ่ง \nผู้พิทักษ์ใช้กุญแจเงินเพื่อขยายพลังจิตใจของตนเอง ทำให้เกิดการสะท้อนกับมิติจิตวิญญาณ และสร้างบาเรียในมิติที่สูงขึ้นบนรอยแยกการหลอมละลาย เพื่อให้มัน「ปิด」ชั่วคราว"
  },
  CollectionHall_49748_Title = {
    Text = "รอยแยก d"
  },
  CollectionHall_49749_Desc = {
    Text = "แกนกลางของรอยแยกการหลอมละลาย มักเป็นศัตรูหลักที่ผู้พิทักษ์ต้องจัดการในภารกิจภาคสนาม \n ปรากฏการณ์หลอมละลายสามารถแพร่กระจายและจะส่งผลกระทบต่อปรากฏการณ์หลอมละลายใกล้เคียง ทำให้มีลักษณะเชิงพื้นที่"
  },
  CollectionHall_49749_Title = {
    Text = "เผ่าพันธุ์"
  },
  CollectionHall_49750_Desc = {
    Text = "<Title:คำนิยามและลักษณะสำคัญ>\nปรากฏการณ์หลอมกร่อนเป็นสาเหตุให้เกิดการเปลี่ยนแปลงผิดรูป การละลาย และการเสียชีวิตในบุคคล\nสามารถเกิดขึ้นได้ทั้งในสิ่งมีชีวิตอินทรีย์ เช่น มนุษย์ สัตว์ และพืช รวมถึงสิ่งอนินทรีย์ เช่น แร่ธาตุและโลหะ ความเป็นไปได้ที่จะเกิดการหลอมกร่อนเพิ่มขึ้นในบุคคลที่อยู่ใกล้รอยแยกการหลอมกร่อน\nปัจจุบันยังไม่พบสารใดที่สามารถทนทานต่อปรากฏการณ์หลอมกร่อนได้\n\n<Title:ลักษณะในแต่ละระยะ>\nระยะเริ่มต้น: มีรอยหลอมกร่อนรูปสามเหลี่ยมกลับด้านสีดำบนผิวหนัง พร้อมกับการหลั่งลาวาหลอมละลายออกมา\nระยะกลาง: รอยหลอมกร่อนขยายใหญ่ขึ้น ลาวาหลอมละลายหลั่งออกมาอย่างต่อเนื่อง จิตใจของบุคคลได้รับความเสียหาย อาจเกิดสิ่งเจริญเติบโตที่ถูกหลอมละลาย\nระยะปลาย: รอยหลอมกร่อนขยายอย่างรวดเร็ว ลาวาหลอมละลายหลั่งออกมามากขึ้น ส่วนใหญ่ของบุคคลจะสูญเสียสติสมบูรณ์ในระยะนี้\nระยะสุดท้าย: ร่างกายของบุคคลล่มสลาย ทางสรีรวิทยาถือว่าเสียชีวิต แต่จิตใจยังคงถูกทำลาย เมื่อจิตใจถูกทำลายจนหมดสิ้น บุคคลจะหายไปโดยสิ้นเชิง โดยไม่มีโอกาสฟื้นคืนสติอีก\n\n<Title:กรณีพิเศษ>\nกรณีพิเศษประเภทร่างกาย: บุคคลที่ถูกหลอมกร่อนแสดงถึงการเสริมสร้างร่างกายและการรับรู้ทั้งห้า นอกจากนี้ยังมีบุคคลที่ได้รับผลกระทบจากสิ่งเจริญเติบโตที่ถูกหลอมละลายหรือภัยพิบัติ ซึ่งมีความสามารถพิเศษ เช่น การบิน การควบคุมจิตใจ และการควบคุมความคิด\nกรณีพิเศษประเภทจิตใจ: จิตใจของบุคคลที่ถูกหลอมกร่อนได้รับผลกระทบน้อยกว่า ยังคงรักษาความมีสติพื้นฐานไว้ได้ บางบุคคลแสดงพฤติกรรมปกติ เหมือนกับบุคคลที่ไม่ได้ถูกหลอมกร่อน"
  },
  CollectionHall_49750_Title = {
    Text = "การหลอมกร่อนและการกร่อน"
  },
  CollectionHall_49751_Desc = {
    Text = "<Title:นิยามและคุณลักษณะ>\nบุคคลสูญเสียร่างกายเนื่องจากการหลอมกร่อน และกลายเป็นลาวาหลอมละลายและผงละลาย เป็นปรากฏการณ์ดังกล่าว\nหลังจากถูกทำให้สลาย ตัวตนของบุคคลนั้นจะถูกลบไปจากโลกโดยสิ้นเชิง\n\n<Title:ลักษณะในแต่ละช่วงระยะ>\nระยะเริ่มต้น: คนที่ไม่สนิทกับบุคคลที่ถูกหลอมกร่อนจะลืมการมีอยู่ของพวกเขา\nระยะกลาง: คนที่สนิทกับบุคคลที่ถูกหลอมกร่อนจะเริ่มสูญเสียความทรงจำเกี่ยวกับพวกเขา และเอกสารที่เกี่ยวข้องเริ่มปรากฏรอยละลาย พร้อมทั้งข้อมูลพร่าเลือน\nระยะปลาย: คนที่สนิทกับบุคคลที่ถูกหลอมกร่อนจะสูญเสียความทรงจำจนเหลือเพียงความทรงจำที่เลือนลาง จนกระทั่งลืมบุคคลนั้นไปโดยสมบูรณ์\n\n<Title:การลบล้างการดำรงอยู่>\nเมื่อกระบวนการสลายพัฒนาจนถึงจุดสุดท้าย การดำรงอยู่ของบุคคลที่ถูกหลอมกร่อน รวมถึงร่องรอยการดำรงอยู่ จะถูกลบออกไปอย่างสิ้นเชิง\nไม่มีสิ่งใดสามารถพิสูจน์ได้ว่าพวกเขาเคยดำรงอยู่ในโลก ดังเช่นคนส่วนใหญ่"
  },
  CollectionHall_49751_Title = {
    Text = "การคลี่คลาย"
  },
  CollectionHall_49752_Desc = {
    Text = "แกนเงินอาจจะเป็นจุดสิ้นสุดของการละลายหรือการกัดกร่อน：มันคือชีวิตที่ถูกการกัดกร่อนและการทำลายล้าง,     วัสดุคล้ายเงินที่เกิดจากการแยกตัวตามความน่าจะเป็น.มันไม่เพียงแต่มีพลังงานฟิสิกส์มหาศาล,     ยังสามารถเชื่อมโยงกับมิติจิตใจได้ในระดับหนึ่ง.บางกรณี,     การติดต่อเชื่อมโยงนี้สามารถทำได้แม้กระทั่ง「มิติจิตวิญญาณ」เกิดการรบกวน.แกนเงินเป็นหนึ่งในกุญแจสำคัญในการต่อสู้ของมนุษย์กับการหลอมกร่อน.แต่เนื่องจากวิธีการก่อตัวที่พิเศษ,     แกนเงินไม่เพียงแค่จำนวนที่น้อย,     คุณค่าก็มีความสำคัญอย่างยิ่ง."
  },
  CollectionHall_49752_Title = {
    Text = "เงิน"
  },
  CollectionHall_49753_Desc = {
    Text = "<Title:ภาพรวม>\nเทคโนโลยีทั้งหมดที่ใช้ประโยชน์จากแกนเงินเรียกรวมกันว่าเทคโนโลยีแกนเงิน\nคนส่วนใหญ่ในโลกไม่รู้ถึงการมีอยู่ของแกนเงิน มีเพียงมหาวิทยาลัยมิซาเกะเท่านั้นที่ครอบครองเทคโนโลยีแกนเงิน โดยมีสาขาวิชาวิจัยและประยุกต์ใช้แกนเงินโดยเฉพาะ เพื่อทำการวิจัยและพัฒนาแกนเงินอย่างต่อเนื่อง\nตามข้อตกลงมิสทีเรีย มหาวิทยาลัยมิซาเกะจะจัดหาเทคโนโลยีแกนเงินให้แก่คณะกรรมการตรวจสอบข้อตกลงมิสทีเรีย เพื่อร่วมกันต่อต้านการกัดกร่อนและรับมือกับวิกฤต\n\n<Title:ร่างตื่นรู้?>\nในเทคโนโลยีร่างตื่นรู้ของมหาวิทยาลัยมิซาเกะ การขึ้นรูปร่างตื่นรู้จำเป็นต้องดำเนินการโดยมีแกนเงินเป็นศูนย์กลาง\nแม้ว่าการขึ้นรูปร่างตื่นรู้จะไม่ได้ถูกบันทึกไว้ในคู่มือแนะนำเทคโนโลยีแกนเงิน แต่ร่างตื่นรู้จำนวนไม่น้อยมักพูดเย้ยตัวเองว่า:\n「เฮ้ พวกเราก็ถือเป็นเทคโนโลยีแกนเงินประเภทหนึ่งใช่ไหมล่ะ?」\n\n<Title:อุปกรณ์สังเกตการณ์การกัดกร่อน>\nมีหลายรูปแบบ เช่น แว่นตา หน้ากาก เป็นต้น ผลิตจากแกนเงิน ช่วยให้ผู้สวมใส่สามารถสังเกตมิติลับและมองเห็นการกัดกร่อนได้\n\n<Title:เครื่องสื่อสารมหาวิทยาลัยมิซาเกะ>\nรูปแบบที่พบบ่อยที่สุดคือเข็มกลัดรูปตราสัญลักษณ์ของมหาวิทยาลัย แกนกลางเป็นแกนเงินที่ผ่านการประมวลผลพิเศษ เครื่องสื่อสารไม่เพียงสามารถเชื่อมต่อถึงกันได้ แต่ยังสามารถสื่อสารระยะไกลมากกับภายในมหาวิทยาลัยมิซาเกะได้อีกด้วย สัญญาณมีความเสถียร <Italic:ในสถานการณ์ปกติ>ไม่ได้รับผลกระทบจากปรากฏการณ์ทางธรรมชาติ\n\n<Title:บัตรอนุญาตเข้ามิซาเกะ>\nบัตรอนุญาตพิเศษที่มีแกนเงินอยู่ภายใน มีเพียงผู้ที่ถือบัตรอนุญาตเท่านั้นที่สามารถหลีกเลี่ยงการหลงทางในม่านหมอกของมหาวิทยาลัยมิซาเกะได้\nผู้ที่ไม่มีบัตรอนุญาตจะตกอยู่ในสภาวะสูญเสียการรับรู้อย่างไม่สิ้นสุดในป่าด้านนอกมหาวิทยาลัย รอคอยการขับไล่จากผู้ตรวจสอบเวรประจำ"
  },
  CollectionHall_49753_Title = {
    Text = "เทคโนโลยีเศษเงิน"
  },
  CollectionHall_49754_Desc = {
    Text = "<Title:หลักการ>\nหรือจะถูกปลุกจากเงินใจ หรือได้รับการดัดแปลงจากทดลอง หรือเกิดจากอุบัติเหตุ...\nพวกเขาทั้งโบราณและใหม่. โบราณ เพราะว่าตั้งแต่หลายสิบศตวรรษที่แล้วในหนังสือสมุดกระดาษสา พวกพ่อมดได้บันทึกอย่างลับๆ เกี่ยวกับการเดินทางของร่างกายที่ตื่นขึ้นในโลก.\nพวกเขาใหม่ เพราะเรายังไม่เข้าใจถึงแก่นแท้ของร่างกายที่ตื่นขึ้น ก็ต้องร่วมมือกับพวกเขาเพื่อช่วยเหลือโลก.\nนอกจากให้ความเชื่อมั่นกับพวกเขาแล้ว จงจำไว้ว่า: อย่าไร้การป้องกัน.\n\n<Title:คุณสมบัติ>\nร่างกายที่ตื่นขึ้นมีบุคลิกภาพที่สมบูรณ์ และยังคงมีความทรงจำจาก「ก่อนหน้า」 แต่เนื่องจากความสามารถพิเศษที่พวกเขามี พวกเขาเคยถูกมองว่าเป็นอาวุธที่มีลักษณะเหมือนมนุษย์.\nเพื่อรักษาเสถียรภาพของสังคมทั่วไป การดำรงอยู่ของร่างกายที่ตื่นขึ้นเป็นความลับสูงสุดในประเทศต่างๆ.\nปัจจุบัน，《ข้อตกลง》ยอมรับเฉพาะร่างกายที่ตื่นขึ้นจากมหาวิทยาลัยมิซากะเท่านั้น ร่างกายที่ตื่นขึ้นที่ไม่ได้ถูกปลุกโดยมหาวิทยาลัยมิซากะ จะถือว่าละเมิด《ข้อตกลง》และจำเป็นต้องให้ทางการบันทึกและกักกัน.\n\n<Title:ขอบเขต>\nร่างกายที่ตื่นขึ้นมีความสามารถหลากหลาย แต่นักวิจัยสามารถหาความคล้ายคลึงกันระหว่างความสามารถต่างๆ ได้เสมอ.\nตามความคล้ายคลึงเหล่านี้ มหาวิทยาลัยมิซากะได้แบ่งขอบเขตของร่างกายที่ตื่นขึ้นออกเป็นหลายหมวดหมู่.\nร่างกายที่ตื่นขึ้นในขอบเขตเดียวกันสามารถประสานงานกันได้ดีกว่า ระหว่างขอบเขตที่แตกต่างกันอาจมีการปฏิเสธกันได้ ยกเว้นขอบเขตแห่งความวุ่นวายที่ไม่มีปรากฏการณ์นี้.\nสาเหตุของการปฏิเสธระหว่างขอบเขตไม่เป็นที่ทราบแน่ชัด ตามการวิเคราะห์ของศาสตราจารย์ดอร์แห่งภาควิชาการปลุกของมหาวิทยาลัยมิซากะ อาจเกี่ยวข้องกับผลกระทบต่อมิติจิตวิญญาณจากบางสิ่งที่ไม่อาจรู้ได้ แต่ปัจจุบันยังไม่มีหลักฐานยืนยันสมมติฐานนี้."
  },
  CollectionHall_49754_Title = {
    Text = "ร่างกายที่ตื่นขึ้น: พื้นฐานการรับรู้"
  },
  CollectionHall_49755_Desc = {
    Text = "<Title:ภาพรวม>\nเป็นไอเทมรูปกุญแจที่ทำจากเงินใจล้วน มีความสามารถในการขยายและโฟกัสพลังจิตของผู้ใช้ ช่วยให้สามารถเชื่อมต่อและส่งผลต่อมิติจิตวิญญาณได้ \nกุญแจเงินเป็นสัญลักษณ์ของนักสืบและผู้พิทักษ์แห่งมิซากะ ทุกกุญแจเงินจะมีหมายเลขประจำตัวที่ไม่ซ้ำกัน กุญแจของนักสืบทั่วไปจะเริ่มต้นด้วยตัวอักษร I ส่วนของผู้พิทักษ์จะเริ่มต้นด้วย K \nหากนักสืบไม่สามารถปฏิบัติภารกิจภาคสนามได้อีกต่อไป ทางโรงเรียนมิซากะจะทำการยึดกุญแจเงินคืน และจะนำมาแจกจ่ายให้กับนักสืบคนอื่นในอนาคต \nแต่น่าเสียดายที่รายงานการยึดคืนแสดงให้เห็นว่า ในช่วงร้อยปีที่ผ่านมา มีกุญแจเงินที่ยังคงใช้งานได้ปกติถูกยึดคืนกลับมาไม่ถึงสิบดอกเท่านั้น ส่วนใหญ่ของกุญแจเงินถูกทำลายพร้อมกับการจากไปของเจ้าของ \n\n<Title:การสร้างและการได้มา>\n■■ เอกสารลับลำดับที่ ■■■ \nการหล่อขึ้นรูปกุญแจเงินต้องดำเนินการในสระดำ โดย ■■■■■ \nหลังจากที่ ■■■ ถูกหล่อขึ้น จะมีการแกะหมายเลขลงบนกุญแจ และมอบให้กับผู้ใช้ที่เหมาะสมในพิธีโยธาสถาน"
  },
  CollectionHall_49755_Title = {
    Text = "กุญแจเงิน"
  },
  CollectionHall_49756_Desc = {
    Text = "<Title:ภาพรวม>\nดินแดนลับแล เป็นพื้นที่พิเศษที่สร้างขึ้นร่วมกันโดยโลกแห่งความเป็นจริงและมิติจิตวิญญาณ\nนายฟิลลิปส์จากมหาวิทยาลัยมิซากะเคยเขียนไว้ในบันทึกของเขาว่า ความผิดปกติทั้งหมดในโลกนี้ หากไม่ได้มาจากจิตใจของมนุษย์ ก็เกิดขึ้นจากดินแดนลับแล\nที่นี่เป็นการประสานกันของชีวิตและความตาย ความจริงและฝัน มันปฏิเสธความจริง และซ่อนเร้นความจริงไว้อย่างแนบเนียน\n\n<Title:คำจำกัดความและคุณลักษณะ>\nดินแดนลับแลคือพื้นที่ที่ใกล้เคียงกับมิติจิตวิญญาณมากที่สุดที่มนุษย์สามารถเข้าไปได้ด้วยเนื้อหนัง แต่ผู้คนยังคงรู้จักมันเพียงเล็กน้อย เช่นเดียวกับที่พวกเขายังไม่เข้าใจการหลอมกร่อนอย่างถ่องแท้\nแต่สิ่งที่แน่นอนคือ การหลอมกร่อนและดินแดนลับแลมักปรากฏพร้อมกันเสมอ: ปรากฏการณ์หลอมละลายยิ่งรุนแรงมากเท่าไหร่ ขอบเขตของมิติดินแดนลับแผลก็จะยิ่งขยายมากขึ้นเท่านั้น\n\n<Title:สิ่งต่างๆ ในดินแดนลับแล>\nในฐานะเขตแดนที่เปราะบาง ดินแดนลับแผลจึงได้รับผลกระทบได้ง่าย\nสิ่งมีอยู่พิเศษที่ปรากฏในดินแดนลับแผล เช่น ภาพลวง รอยละลาย และหมอก ถือว่าเป็นการสะท้อนของอารมณ์และความคิด โดยอาศัยกลไกการฉายภาพพิเศษนี้ มิซากะจึงสามารถสร้างจุดติดต่อบางส่วนในดินแดนลับแผล เพื่อทำให้สภาพจิตใจของนักสืบมั่นคงและเยียวยาบาดแผลของร่างกายที่ตื่นขึ้น\nอย่างไรก็ตาม สิ่งที่มีอยู่จริงในโลกความจริง เช่น พื้นดินและอาคาร มักจะไม่ได้รับผลกระทบในดินแดนลับแผล (ไม่ต้องกังวล ถนนในดินแดนลับแผล <Italic:ส่วนใหญ่> มีความปลอดภัย)"
  },
  CollectionHall_49756_Title = {
    Text = "เขตแดน"
  },
  CollectionHall_49757_Desc = {
    Text = "<Title:วันก่อตั้ง>\nก่อนยุคหินใหม่\n\n<Title:ผู้ก่อตั้ง>\nไม่ปรากฏ\n\n<Title:ภาพรวม>\nศาสนาที่มีผู้ศรัทธามากที่สุดในทวีปพานลอราเชีย\nมีผู้ติดตามจำนวนมากและมีขนาดใหญ่โต ในช่วงเวลาเฉพาะของแต่ละปีจะมีการเฉลิมฉลองในท้องถิ่นต่างๆ โดยงานเฉลิมฉลองที่แพร่หลายที่สุดคือ 「ราตรีเงินเย็น」 และ 「เทศกาลดวงข้ามหนาว」\nเจ้าหน้าที่ทางศาสนาในองค์กรเรียกตนเองว่า 「ผู้แทนของพระบิดา」 ซึ่งหมายถึงผู้ที่ปฏิบัติตามพระประสงค์ของพระบิดา เพื่อกำจัดความทุกข์ยากของโลก\nพวกเขาเชื่อว่าหลังจากมนุษย์เสียชีวิตแล้วจะสามารถกลับคืนสู่อ้อมกอดของพระบิดา อยู่ในดินแดนแห่งสุขอย่างไม่สิ้นสุด และหลุดพ้นจากความทุกข์ของโลก\nด้วยคำสอนที่เป็นสากลเช่นนี้ มันจึงกลายเป็นศาสนาที่ได้รับความนิยมอย่างหลีกเลี่ยงไม่ได้"
  },
  CollectionHall_49757_LockTip = {
    Text = "เคลียร์ด่านพิเศษ「สีของเลือด：การไถ่โทษ」ปลดล็อก"
  },
  CollectionHall_49757_Title = {
    Text = "สันติวิหารแห่งชีวิต"
  },
  CollectionHall_49758_Desc = {
    Text = "<Title:วันก่อตั้ง>\nก่อนยุคหินใหม่\n\n<Title:ผู้ก่อตั้ง>\nมิลียาห์ม\n\n<Title:ภาพรวม>\nองค์กรโบราณที่สืบทอดมาจากดินแดนเก่า\nสมาชิกมักแสดงลักษณะครึ่งบนเป็นปลาและครึ่งล่างเป็นมนุษย์ พวกเขาหลักๆ ทำกิจกรรมในทะเลและพื้นที่ชายฝั่ง ไม่เคยเข้าไปลึกในแผ่นดิน\nกล่าวกันว่า พวกเขาลงไปในทะเลเพื่อตามหาเส้นทางของพระราชา และกลับมาพร้อมกับความหวังที่จะนำพาอาณาจักรของพระราชา\nการเสียสละทั้งหมดนี้ เพื่ออาณาจักรที่สาบสูญ — ลีมูเรีย และกษัตริย์ผู้เหนื่อยล้าของมัน"
  },
  CollectionHall_49758_LockTip = {
    Text = "ปลดล็อกหลังผ่านด่านการสอบสวนดำเนินการ บทที่ 5 「ตาพายุ」"
  },
  CollectionHall_49758_Title = {
    Text = "ผู้เหยียบทะเล"
  },
  CollectionHall_49759_Desc = {
    Text = "<Title:วันก่อตั้ง>\nยุคหายนะน้ำท่วม\n\n<Title:ผู้ก่อตั้ง>\nไม่ทราบ\n\n<Title:ภาพรวม>\nองค์กรศาสนาลับ\nถือว่าการหลอมกร่อนเป็นของขวัญจากพระเจ้า และเงินใจเป็นร่างกายของพระเจ้า เชื่อว่าการหลอมกร่อนสามารถชำระล้างบาป นำพาผู้คนสู่ดินแดนบริสุทธิ์ที่ปราศจากบาป\nแม้มีสมาชิกจำนวนมาก แต่ดำเนินการอย่างลับๆ มักพบเห็นเงาของพวกเขาในสถานที่ที่มีการหลอมกร่อน\nกล่าวกันว่ามีต้นกำเนิดมาจากตระกูลชั้นสูงโบราณ การหายตัวไปพร้อมเพรียงของสมาชิกตระกูลนี้ยังคงเป็นประเด็นถกเถียงของนักประวัติศาสตร์จนถึงปัจจุบัน"
  },
  CollectionHall_49759_LockTip = {
    Text = "ผ่านด่านการสอบสวนดำเนินการ บทที่ 4 「ในที่เงียบงัน」 เพื่อปลดล็อก"
  },
  CollectionHall_49759_Title = {
    Text = "โบสถ์แห่งตะเกียง"
  },
  CollectionHall_49760_Desc = {
    Text = "<Title:ดัชนีนอร์ส>\nค่าที่ใช้วัดความเสถียรของชิ้นส่วนจิตใจในเงินใจ \nร่างกายที่ตื่นขึ้นที่มีดัชนีนอร์สสูงจะมีความเสถียรของชิ้นส่วนจิตใจที่แข็งแกร่ง มีระดับความบ้าคลั่งต่ำกว่า และไม่ค่อยเกิดการสูญเสียการควบคุม หลังจากสูญเสียการควบคุมก็อาจก่อให้เกิดการบาดเจ็บหรือเสียชีวิตน้อยลง \nร่างกายที่ตื่นขึ้นมีดัชนีนอร์สแตกต่างกันไป บางรายอาจมีดัชนีนอร์สวูบไหวหรือไม่สามารถวัดได้อย่างแม่นยำเนื่องจากสถานการณ์เฉพาะบุคคล \n\n<Title:การสูญเสียการควบคุมของร่างกายที่ตื่นขึ้น>\nในฐานะแกนหลัก เงินใจมอบพละกำลังที่ไม่ควรปรากฏในโลกนี้ให้กับร่างกายที่ตื่นขึ้น แต่ก็เป็นเมล็ดพันธุ์แห่งความบ้าคลั่งเช่นกัน \nเมื่อร่างกายที่ตื่นขึ้นถูกสร้างขึ้น ส่วนใหญ่มักอยู่ในสภาพบ้าคลั่งที่ควบคุมยาก หากไม่มีนักสืบที่ทำการลิงก์ทันเวลา การสูญเสียการควบคุมของพวกเขาจะทำลายล้างโลกอย่างเหลือเชื่อ ดังนั้น ลิงก์ไม่เพียงแต่เป็น \"เครื่องขยาย\" แต่ยังเป็น \"ตัวทำให้มั่นคง\" ที่ขาดไม่ได้อีกด้วย \nตามบันทึกของมหาวิทยาลัยมิซากะ ปัจจุบันมีเพียงดอร์·@2 เท่านั้นที่สามารถรักษาความมีสติไว้ได้ในช่วงแรกของการกลายเป็นร่างกายที่ตื่นขึ้น \nนอกจากนี้ ทาวี ผู้อยู่ภายในประตู และอลิสเตอร์ ผู้พิทักษ์คนแรก ได้ร่วมกันรักษาเสถียรภาพของเงินใจขนาดใหญ่ใต้รอยแยกการหลอมละลาย L-01 ทำให้ร่างกายที่ตื่นขึ้นในมหาวิทยาลัยมิซากะสามารถรักษาสติไว้ได้นาน แม้จะตัดลิงก์ออก ก็จะไม่สูญเสียการควบคุม \n\n<Title:การตายของร่างกายที่ตื่นขึ้น>\nร่างกายที่ตื่นขึ้นมีสมรรถนะทางร่างกายเหนือกว่ามนุษย์มาก แต่เมื่อเผชิญกับภัยคุกคามจากสิ่งมีชีวิตกลายพันธุ์ ภัยพิบัติ รวมถึงรอยแยกการหลอมละลายและการหลอมกร่อนเอง ก็ยังอาจได้รับความเสียหายและร่างกายของพวกเขาก็มีโอกาสถูกทำลาย \nนักวิจัยเชื่อว่าหลังจากร่างกายของร่างกายที่ตื่นขึ้นถูกทำลาย จิตสำนึกในเงินใจจะกลับไปยังมิติจิตวิญญาณ เพื่อรอการปลุกครั้งที่สอง \nการเสียหายของเงินใจอาจหมายถึง \"ความตาย\" อย่างแท้จริง \n\n<Title:การปลุกครั้งที่สอง>\nหลังจากการปลุกครั้งที่สอง รูปลักษณ์ บุคลิก ความชอบ และความสามารถของร่างกายที่ตื่นขึ้นมักจะไม่เปลี่ยนแปลง ความทรงจำก็จะได้รับการเก็บรักษาไว้ แต่บางร่างกายที่ตื่นขึ้นอาจมองว่าตนเองเป็นบุคคลที่แยกจากกันสองคน มหาวิทยาลัยมิซากะยังคงสงวนท่าทีต่อเสียงเหล่านี้"
  },
  CollectionHall_49760_Title = {
    Text = "ปลุกการรับรู้ขั้นสูง"
  },
  CollectionHall_49761_Desc = {
    Text = "<Title:ภาพรวม>\nร่างกายที่ตื่นขึ้นบางส่วนแสดงความเหมือนกันอย่างมากในด้านความสามารถและลักษณะการเปลี่ยนแปลงทางรูปร่าง นักวิจัยได้สรุปว่าระหว่างกระบวนการปลุกมีบางสิ่งที่ไม่รู้จัก (บางคนเชื่อว่าเป็นมลภาวะ) ส่งผลต่อจิตใจของร่างกายที่ตื่นขึ้น และมอบพละกำลังอันมหาศาลให้แก่พวกเขา \nปัจจุบัน นักวิจัยเรียกพลังที่ส่งผลต่อการดำรงอยู่ของร่างกายที่ตื่นขึ้นว่า 「ต้นกำเนิด」\n\n<Title:ร่างกายต้นกำเนิดที่ตื่นขึ้น>\nร่างกายต้นกำเนิดที่ตื่นขึ้นคือ 「ตัวเองอีกด้าน」ของร่างกายที่ตื่นขึ้นชื่อเดียวกัน \nพวกเขามีลักษณะคล้ายกัน แต่มีประสบการณ์ชีวิตที่อาจแตกต่างกันอย่างสิ้นเชิง บุคลิก ความชอบ การแสดงออก และแม้กระทั่งพละกำลัง มีลักษณะของ 「ต้นกำเนิด」มากกว่า \nข้อมูลเกี่ยวกับร่างกายต้นกำเนิดที่ตื่นขึ้นมีจำกัดมาก มิซากะมีความรู้น้อยมากเกี่ยวกับสาเหตุของปรากฏการณ์นี้ นักวิจัยบางคนได้เสนอทฤษฎีและพัฒนาแนวคิดเรื่อง 「โลกคู่ขนาน」จากการปรากฏตัวของร่างกายต้นกำเนิดที่ตื่นขึ้น แต่ทฤษฎีนี้ยังไม่ได้รับการเผยแพร่และการวิจัยเพิ่มเติมในขณะนี้"
  },
  CollectionHall_49761_Title = {
    Text = "ปฐมกาล"
  },
  CollectionHall_49762_Desc = {
    Text = "<Title:แกนกลาง>\nแกนกลางของร่างกายที่ตื่นขึ้นคือเงินใจ แม้ว่าร่างกายจะแยกชิ้นส่วนไปทั้งหมด ตราบใดที่เงินใจยังคงอยู่ ก็สามารถทำการปลุกร่างกายที่ตื่นขึ้นครั้งที่สองได้\n\n<Title:ร่างกาย>\nร่างกายของร่างกายที่ตื่นขึ้นอาจประกอบด้วยวัสดุหลายประเภท วัสดุและโครงสร้างที่แน่นอนเกี่ยวข้องกับความชอบและลักษณะเฉพาะของร่างกายที่ตื่นขึ้น\nร่างกายของร่างกายที่ตื่นขึ้นไม่ได้จัดเตรียมไว้ล่วงหน้าโดยเจ้าหน้าที่ของมหาวิทยาลัยมิซากะ แต่จะถูกหลอมรวมจากพลังงานจิตใจในเงินใจระหว่างพิธีปลุก ดังนั้นในการพิธีปลุก นอกจากเงินใจและกุญแจเงินที่จำเป็นแล้ว ยังต้องเตรียมวัสดุจำนวนมากเพื่อให้ร่างกายที่ตื่นขึ้นใช้ในการสังเคราะห์ร่างกาย วัสดุที่พบบ่อยสามารถดูได้ในภาคผนวกหมายเลข 3\nนอกจากนี้ มหาวิทยาลัยมิซากะมีแผนกและนักวิจัยมืออาชีพที่รับผิดชอบในการซ่อมแซมความเสียหายของร่างกายของร่างกายที่ตื่นขึ้น"
  },
  CollectionHall_49762_Title = {
    Text = "องค์ประกอบของร่างกายที่ตื่นขึ้น"
  },
  CollectionHall_49763_Desc = {
    Text = "<Title:ประจำวัน>\nร่างกายที่ตื่นขึ้นในมหาวิทยาลัยมิซากะมีสิทธิ์เทียบเท่ากับคณาจารย์และเจ้าหน้าที่ พวกเขาสามารถใช้สิ่งอำนวยความสะดวกภายในมหาวิทยาลัยและได้รับสิทธิ์ในการรับค่าตอบแทนจากการสอบสวน \nเมื่อนักสืบคู่หูไม่มีภารกิจภาคสนาม ร่างกายที่ตื่นขึ้นสามารถเคลื่อนไหวอย่างอิสระในเขตพื้นที่ของมหาวิทยาลัยได้ ส่วนใหญ่จะทำตามความชอบและนิสัยจากชีวิตในอดีตเพื่อค้นหาสิ่งที่อยากทำ บางส่วนเลือกเข้าเรียนในชั้นเรียน เพื่อทำความเข้าใจยุคสมัยนี้หรือสร้างมิตรภาพกับนักสืบ \nยกเว้นในกรณีพิเศษบางประการ โดยหลักการแล้วร่างกายที่ตื่นขึ้นไม่จำเป็นต้องรับประทานอาหารหรือนอนหลับ แต่หากเลือกทำก็จะไม่ก่อให้เกิดผลกระทบใดๆ \n\n<Title:ปฏิบัติการ>\nเพื่อสร้างสมดุลระหว่างการสั่งการและคงสภาพลิงก์ มหาวิทยาลัยมิซากะได้พัฒนาเครื่องมือพิเศษที่เรียกว่า「เครื่องถ่ายทอดพลังจิต」\n「เครื่องถ่ายทอดพลังจิต」ที่ติดตั้งในกล่องอุปกรณ์ภาคสนาม สามารถถ่ายทอดความสามารถของร่างกายที่ตื่นขึ้นในรูปแบบของไพ่ เพื่อให้สามารถสั่งการร่างกายที่ตื่นขึ้นได้"
  },
  CollectionHall_49763_Title = {
    Text = "พฤติกรรมการปลุกร่างกาย"
  },
  CollectionHall_49764_Desc = {
    Text = "<Title:วันก่อตั้ง>\nA.F.306\n\n<Title:ผู้ก่อตั้ง>\nเฮอร์เบิร์ต โรเซนทาล\n\n<Title:ภาพรวม>\nองค์กรวิจัยเอกชนที่มีแนวคิดสุดโต่ง\nพยายามนำมนุษย์มาผสมกับผลผลิตจากการหลอมกร่อนเพื่อพัฒนาวิวัฒนาการและเอาชีวิตรอดในโลกที่เต็มไปด้วยภัยพิบัติ\nประกอบด้วยสมาชิกหัวรุนแรงกว่า 20 คน พวกเขาใช้วิธีการโหดร้ายและมองว่าผู้บริสุทธิ์เป็นเพียงวัสดุทดลอง\nผู้ก่อตั้งคือ เฮอร์เบิร์ต โรเซนทาล อดีตอาจารย์มหาวิทยาลัยมิซากะที่ถูกตราหน้าว่าเป็นผู้ทรยศ และมีความเกี่ยวข้องใกล้ชิดกับโบสถ์แห่งตะเกียง\nสัญลักษณ์ขององค์กรคือมีดแกะสลักปลายแบน โดยมีข่าวลือว่าเป็นการแสดงความเคารพต่อกษัตริย์ไซปรัสผู้หลงรักในรูปปั้น"
  },
  CollectionHall_49764_LockTip = {
    Text = "ผ่านด่านการสอบสวน บทที่ 3 「ระวังสุนัขดุ」 เพื่อปลดล็อก"
  },
  CollectionHall_49764_Title = {
    Text = "สมาคมนักประติมากรรม"
  },
  CollectionHall_49765_Desc = {
    Text = "<Title:ภาพรวม>\nบุคคลากรเฉพาะทางที่ได้รับการคัดเลือกและฝึกอบรมผ่านกระบวนการพิเศษของมหาวิทยาลัยมิซากะ มีพลังจิตที่แข็งแกร่ง สามารถทนต่อการใช้จากการเชื่อมโยงร่างกายที่ตื่นขึ้น และสั่งการด้วยคำสั่งจิตใจได้\nพวกเขาเผชิญหน้ากับการหลอมกร่อน เพื่อต่อสู้เพื่อการอยู่รอดของมนุษยชาติ แต่กลับไม่เป็นที่รู้จัก นักสืบที่เสียชีวิตจากการหลอมกร่อน แม้แต่ชื่อและประวัติก็ไม่สามารถเหลือไว้ได้อย่างสมบูรณ์\nชื่อของพวกเขาไม่มีใครรู้ แต่หวังว่าผลงานของพวกเขาจะคงอยู่ตลอดไป\n\n<Title:การคัดเลือก>\nจากฐานทฤษฎีเรื่อง \"การประกอบสร้างจิตใจของนักสืบและความสามารถในการพัฒนาศักยภาพ\" มิซากะทำการคัดเลือกบุคคลที่มีพลังจิตที่แข็งแกร่ง โดยสังเกตความเข้มข้นของการสะท้อนระหว่างบุคคลกับกุญแจเงิน\n\n<Title:การฝึกอบรม>\nหลังจากผ่านการคัดเลือกแล้ว นักสืบจะต้องเข้าสู่ชั้นปีเตรียมการเพื่อรับการฝึกอบรมเป็นเวลาหนึ่งปี\nเนื้อหาการฝึกอบรมรวมถึงทฤษฎีพื้นฐานของการหลอมกร่อน การแนะนำเทคโนโลยีซิลเวอร์คอร์ ทฤษฎีร่างกายที่ตื่นขึ้น และการฝึกฝนที่เกี่ยวข้องกับการต่อสู้ เช่น พื้นฐานการออกกำลังกาย การเชื่อมโยงการปลุก และการควบคุมร่างกายที่ตื่นขึ้น\n\n<Title:พิธีหลุมศพกุญแจ>\nหลังจากเรียนหนึ่งปีและผ่านการประเมิน นักสืบจะเข้าร่วมในพิธีหลุมศพกุญแจที่จัดขึ้นในวันเฉลิมฉลองของโรงเรียน\nในพิธี นักสืบจะกล่าวคำสาบาน และสลักชื่อของตนเองบนแผ่นหลุมศพ\nจากนั้น นักสืบแต่ละคนจะได้รับกุญแจเงินที่มีหมายเลขเฉพาะเจาะจง โดยตัวอักษรตัวแรกคือ「I」\nจากจุดนี้ พวกเขาจะอำลาตัวตนในฐานะคนธรรมดา เมื่อพวกเขาเสียชีวิต แผ่นหินที่บรรจุชื่อของพวกเขาจะกลายเป็นหลักฐานของการดำรงอยู่ของพวกเขา\n\n<Title:การปลด>\nหากนักสืบไม่สามารถปฏิบัติภารกิจภาคสนามได้ด้วยเหตุผลหลายประการ มิซากะจะให้ความเคารพและย้ายพวกเขาไปทำงานในแผนกสนับสนุนหรือแผนกข้อมูลที่ปลอดภัยกว่า\nถึงอย่างนั้น นักสืบที่ปลดจากตำแหน่งก็มักจะทนทุกข์ทางกายและใจอย่างมาก\nสำหรับผู้ที่เคยมองเห็นความจริงของโลก การใช้ชีวิตอย่างสงบสุขเป็นเพียงภาพลวงตาที่ฟุ่มเฟือย"
  },
  CollectionHall_49765_Title = {
    Text = "นักสืบ"
  },
  CollectionHall_49766_Desc = {
    Text = "<Title:ภาพรวม>\nนักสืบพิเศษที่มีพลังจิตแข็งแกร่งกว่านักสืบทั่วไป\nพวกเขามีสิทธิ์เข้าถึงข้อมูลลับมากกว่านักสืบปกติ ทำให้สามารถสัมผัสความลับที่ซ่อนเร้นได้ลึกซึ้งยิ่งขึ้น ภารกิจที่พวกเขาได้รับมักจะเป็นงานที่ซับซ้อนและยากที่สุด\nในสงครามที่ยืดเยื้อกับการหลอมกร่อน พวกเขาคือแนวหน้าของมนุษยชาติทั้งมวล\n\n<Title:การคัดเลือก>\nโดยปกติแล้ว มิซากะจะทำการคัดเลือกบุคคลพิเศษระหว่างกระบวนการตรวจสอบนักสืบ\nเมื่อพบบุคคลที่ตอบสนองต่อกุญแจเงินอย่างรุนแรงเป็นพิเศษ เจ้าหน้าที่คัดเลือกจะใช้คำอธิบายและรายการจากเอกสาร《องค์ประกอบทางจิตใจและการประเมินศักยภาพของผู้พิทักษ์》ร่วมกับการสังเกตเป็นระยะเวลาหนึ่ง ก่อนจะตัดสินว่าบุคคลนั้นสามารถพัฒนาเป็นผู้พิทักษ์ได้หรือไม่\n\n<Title:การฝึกฝน>\nนอกเหนือจากหลักสูตรทฤษฎีพื้นฐานและการฝึกปฏิบัติการรบ ผู้พิทักษ์จะได้รับการฝึกฝนพละกำลังจิตเพิ่มเติม\nพวกเขาจะได้สัมผัสร่างกายที่ตื่นขึ้นและปฏิบัติภารกิจภาคสนามเร็วกว่านักสืบทั่วไป เพื่อฝึกฝนความสามารถของตนเอง\n\n<Title:พิธีกรรมหลุมกุญแจ>\nหลังจากผ่านการประเมิน ผู้พิทักษ์จะเข้าร่วมพิธีกรรมหลุมกุญแจกับนักสืบทั่วไป เพื่อรับกุญแจเงินของตนเอง\nแตกต่างจากนักสืบ เลขรหัสของกุญแจเงินสำหรับผู้พิทักษ์จะขึ้นต้นด้วย「K」\nจากนี้ไป กุญแจเงินจะกลายเป็นสัญลักษณ์ประจำตัวของผู้พิทักษ์ และมอบความช่วยเหลือที่ทรงพลังสำหรับภารกิจภาคสนามในอนาคต\n\n<Title:ผู้พิทักษ์กับร่างกายที่ตื่นขึ้น>\nผู้พิทักษ์สามารถใช้พลังจากร่างกายที่ตื่นขึ้นในการต่อสู้กับการหลอมกร่อน ดังนั้น ความสามารถในการควบคุมร่างกายที่ตื่นขึ้นจึงมีความสำคัญอย่างยิ่ง\nพวกเขาจะได้รับการฝึกฝนการควบคุมการรบอย่างเข้มงวดในช่วงเตรียมตัว และหลังจากพิธีกรรมหลุมกุญแจ จะต้องปฏิบัติภารกิจภาคสนามภายใต้การดูแลของครูร่วมกับร่างกายที่ตื่นขึ้นที่พวกเขาจับคู่ เพื่อให้แน่ใจว่ามีความสามารถในการปฏิบัติภารกิจภาคสนามอย่างอิสระในอนาคต\n\n<Title:การปลดจากตำแหน่ง>\nหากผู้พิทักษ์ไม่สามารถปฏิบัติภารกิจภาคสนามได้ด้วยเหตุผลใดก็ตาม มิซากะจะเคารพการตัดสินใจและย้ายพวกเขาไปทำงานในแผนกที่ปลอดภัยกว่า เช่น แผนกสนับสนุนด้านหลังหรือแผนกสนับสนุนข้อมูล\nผู้พิทักษ์สามารถลาออกจากการปฏิบัติหน้าที่โดยคืนกุญแจ เก็บบันทึกลับ และลงนามในข้อตกลงรักษาความลับ แต่จนถึงปัจจุบันแทบน้อยคนนักที่เลือกทำเช่นนั้น"
  },
  CollectionHall_49766_Title = {
    Text = "ผู้พิทักษ์"
  },
  CollectionHall_49767_Desc = {
    Text = "<Title:การเชื่อมโยงการปลุก>\nร่างกายที่ตื่นขึ้นในกระบวนการสร้างจะได้รับมลพิษที่ไม่ทราบสาเหตุ พวกเขาจะหลุดเข้าสู่ความบ้าคลั่งได้ง่าย ดังนั้นจึงจำเป็นต้องให้นักสืบทำการเชื่อมโยงจิตวิญญาณเพื่อทำให้จิตใจมั่นคง และสำหรับนักสืบส่วนใหญ่ การเชื่อมโยงกับร่างกายที่ตื่นขึ้นจำเป็นต้องอาศัยพลังของกุญแจเงิน \nกุญแจเงินสามารถเสริมสร้างพลังจิตของผู้ถือครอง ทำให้สามารถเชื่อมโยงกับร่างกายที่ตื่นขึ้นได้นานขึ้น สั่งการร่างกายที่ตื่นขึ้นในการต่อสู้ และมอบความช่วยเหลือทางพลังจิตแก่ผู้ถือครอง นอกจากนี้ ผู้ถือครองยังสามารถใช้กุญแจเงินเพื่อช่วยเหลือร่างกายที่ตื่นขึ้นได้ในระดับหนึ่ง \nตามทฤษฎีแล้ว พลังจิตของผู้ถือครองยิ่งมากเท่าไหร่ ก็ยิ่งสามารถเชื่อมโยงกับร่างกายที่ตื่นขึ้นได้มากขึ้นเท่านั้น แต่อย่างไรก็ตาม จนถึงขณะนี้ คนที่สามารถทนต่อภาระทางจิตใจจากการเชื่อมโยงกับร่างกายที่ตื่นขึ้นหลายตัวพร้อมกันได้มีเพียงคนเดียวเท่านั้น \n\n<Title:พิธีปลุก>\nพิธีปลุกที่ดำเนินการโดยใช้กุญแจเงิน เป็นบทเรียนบังคับสำหรับนักสืบทุกคน \nในระหว่างพิธีปลุก กุญแจเงินสามารถขยายการรับรู้ระหว่างผู้ใช้และเงินใจ เป็นการช่วยเสริมสร้างการหล่อหลอมเงินใจ ทำให้ในที่สุดกลายเป็นร่างกายที่ตื่นขึ้นที่มีความสามารถพิเศษ \n\n<Title:การติดตามและการระบุตำแหน่งทางจิตใจ>\nเมื่อแยกจากกันกับร่างกายที่ตื่นขึ้น ผู้ถือครองสามารถใช้กุญแจเงินผ่าน「การติดตามทางจิตใจ」เพื่อระบุตำแหน่งโดยประมาณของจิตใจที่ตรงกับลักษณะของร่างกายที่ตื่นขึ้น \nแต่นั่นไม่ได้หมายความว่าทุกจิตใจที่พบจะเป็นเพื่อนของคุณ ดังนั้นเมื่อทำการ「การติดตามทางจิตใจ」โปรดอย่าลืมรักษาความสงบ \n\n<Title:การปิดรอยแยกการหลอมละลาย>\nผู้ถือครองสามารถใช้กุญแจเงินเพื่อปิดรอยแยกการหลอมละลาย ดูรายละเอียดเพิ่มเติมได้ที่ การหลอมกร่อน-วิธีการรับมือ"
  },
  CollectionHall_49767_Title = {
    Text = "ใช้งานกุญแจเงิน"
  },
  CollectionHall_49768_Desc = {
    Text = "<Title:ภาพรวม>\nผู้พิทักษ์แต่ละคนมีความสามารถพิเศษที่ไม่เหมือนกัน.\nตามบันทึกของมิซากะ ความสามารถที่เป็นที่รู้จักของผู้พิทักษ์ในปัจจุบันได้แก่ การอ่านความทรงจำ,      การแบ่งปันอารมณ์,      และการรับรู้ทางจิต เป็นต้น.\n\n<Title:ผู้พิทักษ์รุ่นแรก>\nผู้พิทักษ์รุ่นแรกคือ อลิสเตอร์ โอเวนส์.\nสำหรับคนส่วนใหญ่ เขาเป็นเพียงเงาบางๆ ในช่องว่างของประวัติศาสตร์ มีเพียงไม่กี่คนที่รู้ว่าเขายังคงปฏิบัติหน้าที่อยู่ใต้ดินของมิซากะ.\nเขาไม่สามารถเดินได้ตามปกติ ซึ่งเป็น 「การเสียสละที่จำเป็น」 เพื่อมิซากะ.\nเครื่องมือที่ประหยัดและมีประสิทธิภาพสูงของมิซากะ — กระเพาะอาหารของเขาถูกตัดออกทั้งหมดแล้ว ไม่จำเป็นต้องกินหรือดื่ม ประหยัดค่าใช้จ่ายด้านอาหารไปได้อย่างมาก.\n\n<Title:ผู้พิทักษ์คนใหม่>\nความสามารถของผู้พิทักษ์คนใหม่นั้นโดดเด่นและแตกต่างอย่างไม่ต้องสงสัย.\nTA สามารถปลุกพลังใหม่ของกุญแจเงินผ่านวัตถุ,      อารมณ์,      หรือความทรงจำ ซึ่งเปลี่ยนแปลงความเข้าใจของนักวิชาการและนักประวัติศาสตร์มืออาชีพโดยสิ้นเชิง.\nทุกคนรู้ว่าผู้พิทักษ์คนนี้จะสร้างพายุครั้งใหม่อย่างแน่นอน.\nคำถามคือ พายุครั้งนี้จะพาพวกเขาไปทางไหน?"
  },
