  CollectionHall_51019_Desc = {
    Text = "<Title:วันก่อตั้ง>\nก่อนยุคหินใหม่ (Pleistocene)\n\n<Title:ผู้ก่อตั้ง>\nไม่ปรากฏ\n\n<Title:ภาพรวม>\nชนชาติเร่ร่อนที่แยกตัวออกมาจากราชอาณาจักรอัสซีเรีย\nซ่อนตัวอยู่ในพายุที่โหมกระหน่ำตลอดปีของทะเลทรายเลมวาฮ์ วิถีชีวิตของพวกเขาค่อนข้างดั้งเดิม และแทบไม่มีการติดต่อกับคนภายนอก ชาวอัลลันนับถือ「ต้นแม่พันธุ์แห่งความอุดมสมบูรณ์」และอาศัยความสามารถในการสืบพันธุ์ที่ผิดปกติของต้นแม่พันธุ์แห่งความอุดมสมบูรณ์และน้ำแห่งแม่น้ำศักดิ์สิทธิ์ เพื่อรักษาขนาดประชากรของพวกเขา\nหลังจากการ「ปฏิบัติการเลมวาฮ์」ชนชาติอัลลันก็หายสาบสูญไปโดยไม่มีข่าวคราวอีกเลย"
  },
  CollectionHall_51019_LockTip = {
    Text = "ผ่านบทที่ 7 「แม่น้ำแห่งความปรารถนา」เพื่อปลดล็อก"
  },
  CollectionHall_51019_Title = {
    Text = "ชนเผ่าอาลัน"
  },
  CollectionHall_51038_Title = {
    Text = "07 แม่น้ำแห่งราคะ"
  },
  CollectionHall_51373_Title = {
    Text = "วัตถุที่ไม่สามารถคาดการณ์ได้"
  },
  CollectionHall_51374_Desc = {
    Text = "<Title:ข้อมูลพื้นฐาน>\nศาสตราจารย์แห่งมหาวิทยาลัยมิซากะ นักกิจกรรมสังคม และขุนนาง\nเคยเป็นเพลย์บอยที่ใช้เงินอย่างฟุ่มเฟือยและก่อคดีเล็กน้อยที่ไม่ร้ายแรง เป็นที่รู้จักทั้งในแวดวงใต้ดินและสังคมชั้นสูง\nต่อมาครอบครัวถูกพวกบูชาลัทธิชั่วร้ายสังหารจนหมด เขาเป็นผู้รอดชีวิตเพียงคนเดียว ส่วนเรื่องที่เกิดขึ้นหลังจากนั้นมีเพียงเขาเท่านั้นที่สามารถอธิบายได้\nแม้จะเป็นบิดาบุญธรรมของรามอน่า แต่กลับปิดปากเงียบเกี่ยวกับที่มาของรามอน่า\nตอนหนุ่มๆ สอบตกทุกวิชา แต่กลับกลายเป็นศาสตราจารย์แห่งมิซากะได้\nเป็นพวกเพลย์บอยไม่สนใจกฎเกณฑ์ แต่ไม่เคยมีข่าวลือเรื่องชู้สาวกับใครทั้งหญิงหรือชาย\nโดยรวมแล้วเขาเป็นคนที่ซับซ้อนและเต็มไปด้วยความขัดแย้ง"
  },
  CollectionHall_51374_LockTip = {
    Text = "ผ่านด่านบทนำเพื่อเปิดใช้งาน"
  },
  CollectionHall_51374_Title = {
    Text = "เด็กซ์เตอร์"
  },
  CollectionHall_51375_Desc = {
    Text = "<Title:คำแนะนำ>\nรามอน่า ลูกสาวบุญธรรมของเดกซ์เตอร์ และเป็นคู่หูในการสอบสวนที่เชื่อถือได้ที่สุดของตัวละครเอก \nเธอเติบโตมาในห้องเรียนของแต่ละภาควิชาในสถาบันการศึกษา และมีความรู้เกี่ยวกับปรากฏการณ์หลอมกร่อนและร่างกายที่ตื่นขึ้นอย่างลึกซึ้ง \n\nเมื่อยังเด็ก รามอน่าเคยใฝ่ฝันถึง「พ่อแม่ที่แท้จริง」ของเธอ แต่ภายใต้การดูแลและความรักของเดกซ์เตอร์และคุณครู เธอได้ถือว่าสถาบันการศึกษานี้เป็นบ้านที่แท้จริงของเธอแล้ว \n\nความเยือกเย็น ความเป็นเหตุผล และความดีที่พอเหมาะพอดี ทำให้ไม่มี「ความแปลกประหลาด」ใดๆ ในตัวเธอ — ในกลุ่มคนแปลกๆ ของมิซากะ ความ「ปกติ」ของเธอกลับโดดเด่นออกมา \nแม้ว่าเธอจะมักจะมีใบหน้าที่เย็นชา แต่ผู้ที่คุ้นเคยกับเธอก็รู้ดีว่านั่นเป็นเพียงเพราะความเหนื่อยล้าของ「อัจฉริยะ」เท่านั้น"
  },
