  CollectionHall_51603_Desc = {
    Text = "แมวขนสั้นสีดำที่สง่างามและลึกลับ มีคำกล่าวว่าในดินแดนทะเลทรายอันไกลโพ้นแห่งหนึ่ง มันได้รับการเคารพในฐานะตัวแทนของเทพเจ้า แต่นามของเทพองค์นั้น ปัจจุบันไม่มีใครรู้อีกแล้ว \nได้รับการบูชา ได้รับการยกย่อง ได้รับการลืมเลือน บางทีนี่อาจเป็นชะตากรรมของเทพเจ้า"
