  },
  CollectionHall_57597_Desc = {
    Text = "<Title:คำแนะนำ>\nบิชอปคนปัจจุบันของเขตลอนดีเนี่ยน และเป็นร่างกายที่ตื่นขึ้นซึ่งถูกปลุกโดยบิชอปคนก่อนอย่างไม่คาดคิด \nเขาเป็นสาวกผู้ศรัทธาในเทพผู้สร้างโลกอย่างแรงกล้า ปฏิบัติตามคำสอนของพระบิดาด้วยชีวิต ปฏิบัติต่อสรรพสิ่งด้วยความเมตตาและใจกว้าง มีชื่อเสียงสูงในหมู่ประชาชน และถูกเรียกโดยบรรดาผู้ศรัทธาว่า “นักบุญแห่งลอนดีเนี่ยน” \nแต่น่าเสียดายที่ความรักและความกรุณาต่อสรรพสิ่งนี้เองที่พรากชีวิตของเขาไปในขณะที่ยังเป็นมนุษย์ \nเมื่อครั้งยังมีชีวิต เขาเคยพยายามรักษาการหลอมกร่อน โดยไม่ลังเลที่จะมอบเนื้อและเลือดของตนให้กับกระดานหินแห่งชีวิต เพื่อบรรเทาความทุกข์และยืดอายุของ “ผู้ป่วย” ในเขตปกครองของเขา หลังจากเขาเสียชีวิต กระดานหินก็หายสาบสูญไป—จนกระทั่งเขาฟื้นคืนชีพอีกครั้งในฐานะร่างกายที่ตื่นขึ้น \nดวงตาที่ถูกปกคลุมด้วยผ้าพันแผลสามารถมองเห็นแสงแห่งวิญญาณได้ ดังนั้นเมื่อเขาพบกับผู้พิทักษ์ เขาจึงมั่นใจว่าผู้พิทักษ์คือทูตซีดเซียวที่ถูกทำนายโดยพระบิดา ผู้ที่จะสามารถช่วยโลกจากการจมดิ่งสู่ความมืดได้"
  },
  CollectionHall_57597_LockTip = {
    Text = "ผ่านด่านพิเศษบันทึก「สีของเลือด」ปลดล็อค"
  },
  CollectionHall_57597_Title = {
    Text = "ซัลวาดอร์"
  },
  CollectionHall_57598_Desc = {
    Text = "<Title:บทนำ>\nราชาหนุ่มที่สุดแห่งอารยธรรมลีมูเรียในยุคก่อนประวัติศาสตร์\nตั้งแต่วัยเยาว์ได้แสดงความสามารถพิเศษออกมา โดยหลับวันละกว่า 20 ชั่วโมง และเมื่อตื่นก็ยังคงดูเหนื่อยล้าอยู่เสมอ\nบางครั้งสามารถรับรู้ถึงความรู้สึกชอบหรือไม่ชอบของเหล่าเทพ และฝันเห็นเศษเสี้ยวของกาลเวลาต่างๆ จึงได้รับการเคารพ เกรงกลัว และยกย่องให้เป็นกษัตริย์\nแต่ราชาน้อยไม่ใส่ใจ เขาเพียงหลีกเลี่ยงการสำแดงและการพยากรณ์ของเทพอย่างเฉื่อยแฉะ\n\nในที่สุดก็ได้ล่วงรู้ถึงชะตากรรมการทำลายของลีมูเรีย แต่ไม่รู้จะเปลี่ยนแปลงอย่างไร จึงได้แต่เก็บไว้เงียบ\nจนกระทั่งวันที่หายนะมาถึง ผู้คนต่างหมดหวัง เพื่อตอบสนองความคาดหวังของประชาชน เขาจึงสร้างคำพยากรณ์ปลอมขึ้นมา\nเกี่ยวกับกษัตริย์ผู้เป็นอมตะ และการปรากฏตัวของเขาอีกครั้ง\nในที่สุดโลกใบเก่าก็ถูกน้ำท่วม ผ่านกาลเวลา คนใหม่ๆ ก็เริ่มขยายเผ่าพันธุ์บนแผ่นดินอีกครั้ง เรื่องราวในยุคก่อนประวัติศาสตร์ก็ไม่มีใครรู้อีกเลย\nอาจเป็นไปได้ว่าเขาเองก็ไม่คาดคิดว่าคำพยากรณ์ที่เขาไม่ได้ตั้งใจจะถูกถ่ายทอดและขยายความต่อไป\nเขากลับประเมินพลังแห่งศรัทธาต่ำไป"
  },
  CollectionHall_57598_LockTip = {
    Text = "ปลุก「ตูรู」แล้วปลดล็อก"
  },
  CollectionHall_57598_Title = {
    Text = "ธูลู"
  },
  CollectionHall_57599_Desc = {
    Text = "<Title:คำแนะนำ>\nทูตจากชนเผ่าอาลัน ผู้อ้างว่ามาถึงเลมวาห์ตามคำแนะนำของความฝัน \nนำทีมของชนเผ่าอาลันเดินทางวนเวียนอยู่นอกกำแพงพายุเป็นเวลานาน เพื่อแสวงหาความเป็นไปได้ในการฟื้นฟูต้นแม่พันธุ์แห่งความอุดมสมบูรณ์ ซึ่งเป็นต้นศักดิ์สิทธิ์ของชนเผ่าอาลัน \nในความเป็นจริงแล้ว สังกัดโบสถ์แห่งตะเกียง ยังไม่มีใครรู้ถึงแรงจูงใจที่แท้จริงเบื้องหลังรอยยิ้มที่เต็มไปด้วยความเมตตาอันไม่เสื่อมคลายของเธอ บางทีเมื่อการเดินทางดำเนินต่อไป อาจสามารถเผยความจริงบางส่วนได้"
  },
  CollectionHall_57599_LockTip = {
    Text = "ผ่านบทที่ 7 「แม่น้ำแห่งความปรารถนา」เพื่อปลดล็อก"
  },
  CollectionHall_57599_Title = {
    Text = "จูเลียต"
  },
  CollectionHall_57600_Desc = {
    Text = "<Title:แนะนำ>\nอาศัยอยู่ในอารยธรรมยุคก่อนประวัติศาสตร์เลมูเรีย ทั้งครอบครัวเป็นผู้บำเพ็ญจิตวิญญาณที่เคารพศรัทธาในเทพเจ้าอย่างเคร่งครัด\nเธอขยันหมั่นเพียรในการบำเพ็ญตั้งแต่เด็ก เมื่อเติบโตขึ้นก็ได้เข้าสู่วิหารในเมืองหลวงตามที่ปรารถนา กลายเป็นนักบวช\nเธอโหยหาปาฏิหาริย์ โหยหาประสบการณ์เหนือธรรมชาติ แต่สิ่งเหล่านั้นไม่เคยมาถึง\n\nเมื่อทูรูขึ้นครองราชย์ เธอได้กลายเป็นมหาปุโรหิตที่รับใช้เบื้องพระยุคลบาท\nครั้งแรกที่ได้พบกษัตริย์องค์ใหม่ เธอรู้สึกเคลิบเคลิ้มและปีติอย่างสุดขีด เธอเข้าใจทันทีว่านี่คือสิ่งที่เธอโหยหา — อวตารของเทพเจ้าบนโลกมนุษย์\nใช่แล้ว ความหมายแห่งการดำรงอยู่ของเธอคือการรับใช้กษัตริย์น้อยพระองค์นี้\n\nแม้น้ำท่วมจะกลืนทวีปและอารยธรรมเลมูเรียจมลงสู่ก้นทะเล เธอก็ไม่เคยสั่นคลอนในศรัทธานี้แม้แต่น้อย"
  },
  CollectionHall_57600_LockTip = {
    Text = "ผ่านด่านโลกแห่งความฝันประหลาด「การลบหลู่」เพื่อปลดล็อก"
  },
  CollectionHall_57600_Title = {
    Text = "มิเรียม"
  },
  CollectionHall_57601_Desc = {
    Text = "<Title:แนะนำ>\nเพื่อแพร่กระจายเมล็ดพันธุ์ข้ามกำแพงมิติ แต่กลับสละสัญชาตญาณการสืบพันธุ์ของเผ่าพันธุ์เพราะ 「ความรัก」\nซายะที่หลงทางมายังจักรวาลนี้โดยบังเอิญ ถูกทิงค์เตอร์ผู้เดินทางข้ามดวงดาวปลุกขึ้นจากแกนกลางเงิน เธอเสาะหาทิศทางอย่างสับสน และค้างอยู่บนดาวเคราะห์รกร้างแห่งหนึ่ง จนกระทั่งได้พบกับผู้พิทักษ์ความลับแห่งมิซาเกะ\nในการค้นหา ในการสนทนาลึกซึ้ง สิ่งมีชีวิตสองตนที่แตกต่างกัน ได้ข้อสรุปที่คล้ายคลึงกันเกี่ยวกับนิยามของ 「ความรัก」\nความทรงจำอาจเลือนราง แต่สายสัมพันธ์ที่เคยเกิดขึ้นกับผู้สำคัญ จะนำทางเธออีกครั้ง\nในโลกที่เต็มไปด้วยการหลงลืมนี้ เธอยึดมั่นในโรคที่เรียกว่าความรัก"
  },
  CollectionHall_57601_LockTip = {
    Text = "ปลดล็อกหลังปลุก 「ซายะ」"
  },
  CollectionHall_57601_Title = {
    Text = "ซายะ"
  },
  CollectionHall_57602_Desc = {
    Text = "<Title:คำแนะนำ>\nในตำนานโบราณ มีสัตว์ประหลาดยักษ์สองตัวอยู่ในโลก ซึ่งอาศัยอยู่ในห้วงน้ำลึกและทิศตะวันออกของเอเดนตามลำดับ\nสัตว์ประหลาดทั้งสองนี้จะพบกันได้ก็ต่อเมื่อเวลาสิ้นสุดลงเท่านั้น พวกมันจะถูกถวายเป็นเครื่องบูชาแด่ทิอาแมท พระมารดาแห่งชีวิต เพื่อแลกกับการเวียนว่ายตายเกิดของชีวิต\n\nโรแทนคือ「สัตว์」ที่ซ่อนเร้นอยู่เบื้องหลังตำนาน\nเธอเป็นผลผลิตจากธรรมชาติของดาวเคราะห์ แต่แตกต่างจากตำนาน เธอคือทั้งน้ำในเหวและจิตวิญญาณแห่งเอเดน\nเธอคือพลังแห่งความวุ่นวายบริสุทธิ์ เป็นวิญญาณแห่งเสรีภาพที่ไม่อาจควบคุมได้ และเป็นระเบียบที่ยังไม่ถูกกำหนด\nการทำลายล้างและการปกครองคืออำนาจที่โลกมอบให้กับเธอ สองสัญชาตญาณที่ตรงข้ามกันปะทะกันภายในตัวโรแทน เพื่อสร้างสมดุลให้กับพละกำลังที่อาจฉีกเธอออก เธอจำเป็นต้องใช้การต่อสู้เพื่อปลดปล่อยความปรารถนาในการทำลายล้าง\nโรแทนได้รับมอบหมายจากดาวเคราะห์ให้ปกป้องประวัติศาสตร์ 「หน้าที่」ของเธอคือการทำตามเจตจำนงของดาวเคราะห์ กำจัดและลงโทษผู้ที่ส่งผลกระทบต่อชะตากรรมของดาวเคราะห์ แต่คนเช่นนั้นยากจะปรากฏแม้เพียงหนึ่งในหลายพันปี\nในความน่าเบื่อของการรอคอยภารกิจที่ไม่มีที่สิ้นสุด โรแทนปรารถนาที่จะพบคู่ต่อสู้\n\nด้วยเหตุนี้ เธอจึงเคยมองไปที่กษัตริย์หนุ่มผู้เยาว์ กระทั่งเรียกหายนะให้ตกลงมา\nอย่างไรก็ตาม ไม่มีอะไรสามารถลดทอนความตั้งใจในการต่อสู้อันเชี่ยวกรากของเธอได้ มันจะทวีความรุนแรงขึ้นจากการฟื้นคืนชีพของเธอ"
  },
  CollectionHall_57602_LockTip = {
    Text = "ปลุก「โรแทน」หลังจากปลดล็อก"
  },
  CollectionHall_57602_Title = {
    Text = "โลทัน"
  },
  CollectionHall_57603_Desc = {
    Text = "<Title:บทนำ>\nพระราชาที่เคยปกครองเมืองศพ ตอนนี้กลายเป็นราชาแห่งซอมบี้ที่ถูกเคารพเป็นพระเจ้า.\nเขาเป็นหนุ่มที่ฉลาดและยุติธรรม แต่เพราะ「รสนิยม」การบริโภคที่ยูนีคของเขา—การกินศพ จึงทำให้ราชสำนักหวาดกลัว.\nก่อนคืนที่เขาจะสละราชสมบัติ พระบิดาของเขาได้ทำการวางยาฆ่าดุลเลเซ.ในระหว่างที่เขาโดนย่อยสลายและถูกกลืนกิน สติของเขาก็หลอมรวมกับพระเจ้าที่ประดิษฐานอยู่ในวิหาร ทำให้ได้ลิ้มรสความหวานอันน่าอัศจรรย์ของเนื้อกายของตน.\nเขามองการบริโภคเป็นศิลปะแห่งความโรแมนติก นี่ไม่ใช่เพียงการตอบสนองทางรสชาติ ยังเป็นการจดจำสิ่งที่ถูกลืม.\nการย่อยสลายจะทำลายทุกอย่าง ทำให้เรื่องราวในอดีตลอยไปตามลม แต่ดุลเลเซจะเป็นพยานแห่งตำนานและความธรรมดาของทุกผู้คน ทำให้เลือดและเนื้ออยู่ในความทรงจำของตนจวบจนกาลนิรันดร์."
  },
  CollectionHall_57603_LockTip = {
    Text = "ปลุก「ดูเลเซย์อิน」แล้วปลดล็อก"
  },
  CollectionHall_57603_Title = {
    Text = "ดูเรซิน"
  },
  CollectionHall_57604_Desc = {
    Text = "<Title:บทนำ>\nครั้งหนึ่งเคยเป็นเจ้าของที่ดินผู้ปกครองพื้นที่แถบหนึ่ง.\nมีคำกล่าวว่า หลังจากดาวเคราะห์แม่ถูกการทำลายโดยการหลอมกร่อนแล้ว ได้ตกลงสู่หุบเขาแม่น้ำแคมบริอันพร้อมกับหินอุกกาบาตขนาดใหญ่.\nเชี่ยวชาญในการจัดการปศุสัตว์ การรวมที่ดิน และการจัดการการลงทุนที่มีความเสี่ยง.\nทุกครั้งที่ออกไปข้างนอก จะมีผู้ติดตามที่ไม่มีวันตายจำนวนมากมายตามหลังเสมอ.\n1 คนใช้นั่งเป็นเก้าอี้เหยียบ, 2 คนเล่นดนตรีและร้องเพลงเพื่อสร้างความบันเทิง, อีก 4 คนช่วยดูแลรถม้า...\nขนาดพระสันตะปาปาก็ยังต้องละอายในความเรียบง่ายของขบวนตนเอง."
  },
  CollectionHall_57604_LockTip = {
    Text = "ปลดล็อกหลังจากผ่านด่าน การล่องเรือในจิตสำนึก 「งานเลี้ยงหมู่ที่ลุกโชน」"
  },
  CollectionHall_57604_Title = {
    Text = "วานด้า"
  },
  CollectionHall_57605_Desc = {
    Text = "<Title:แนะนำ>\nพี่สาวฝาแฝดที่ทิงค์เทอร์รักยิ่ง\nตั้งแต่เริ่มฟักออกมา เธอก็แสดง「พรสวรรค์」ที่แตกต่างออกไป เนื่องจากพลังที่ควบคุมไม่ได้ ฟีนเทอร์จึงทำได้เพียงขดตัวอยู่ใน「ผ้าอ้อม」ตลอดกาล ไม่สามารถเติบโตได้\nถูกมองว่าเป็นบุคคลที่จะนำความโชคร้ายมาสู่เผ่าพันธุ์ จึงถูกขับไล่ออกจากถิ่นที่อยู่เดิมพร้อมกับทิงค์เทอร์\n\nน้องสาวอาศัยของบริจาคจากชนชั้นสูงเพื่อแลกกับเสบียงที่จำเป็นต่อการดำรงชีวิต เธอใช้ทรัพยากรส่วนใหญ่เพื่อเลี้ยงดูฟีนเทอร์\nหลังจากภัยพิบัติครั้งหนึ่ง เธอหา「ตั๋ว」ได้เพียงใบเดียว จึงหลอกล่อฟีนเทอร์ให้ขึ้นเที่ยวบินออกจากดาวเคราะห์รกร้าง\nขณะที่ยานกำลังจะขึ้นบิน ฟีนเทอร์ได้ทำการต่อต้านเป็นครั้งแรกและครั้งสุดท้าย:\nเธอขู่บังคับทิงค์เทอร์ให้ไปด้วย โดยแลกกับการออกจากผ้าอ้อมและดูดซับพลังชีวิตของทุกคน...\nเพราะตัวเองเป็น「ผู้มีข้อบกพร่อง」 จึงรู้สึกด้อยค่าในตัวเองอย่างมาก\n\nเคยปฏิเสธการกินอาหารอยู่ช่วงหนึ่ง หวังว่าตัวเองจะอดตายเร็วๆ เพื่อจะได้ไม่เป็นภาระของทิงค์เทอร์\nเป็นเช่นนี้มานาน จนกลายเป็นนิสัยเลือกกินที่แก้ไม่หาย\n\nชอบมุมมืดๆ โดยปกติต้องไปตามที่อย่างห้องใต้ดินถึงจะพบฟีนเทอร์ได้"
  },
  CollectionHall_57605_LockTip = {
    Text = "ปลุก「ฟีนต์」หลังจากปลดล็อก"
  },
  CollectionHall_57605_Title = {
    Text = "เฟนท์"
  },
  CollectionHall_57606_Desc = {
    Text = "<Title:บทนำ>\nเคทีกุร่า เป็นเด็กกำพร้าที่เกิดในภูมิภาคทะเลทราย เมื่อเธอยังเป็นสาวน้อย เธอได้ช่วยเหลือเด็ก ๆ ที่มีชะตาชีวิตอันน่าสงสารในท้องถิ่นหลายคน\nเพื่อพาเด็กเหล่านี้ผ่านการต่อสู้ดิ้นรนในชีวิตไปเธอได้สร้างกระเป๋าลวงให้เหมือนเธอมีชีวิตอยู่ เพื่อป้องกันอันตรายจากความชั่วร้าย\nในสายตาของหลายคน เธอเป็นตัวแทนของความโหดร้ายและบ้า\nไม่ว่าการต่อสู้จะเกิดขึ้นที่ไหน เธอจะตอบสนองต่อศัตรูที่กล้าหาญยืนอยู่ข้างหน้ากระบอกปืนของเธอด้วยความร้อนแรงและวิธีการอันโหดเหี้ยมที่สุด\nเมื่อเวลาผ่านไป แม้แต่เด็ก ๆ ที่พูดไม่ชัดในท้องถิ่น ก็รู้ว่าบนทะเลทรายกว้างใหญ่ มีเทพเจ้าแห่งความตายสีเหลืองอำพันอยู่\nในการต่อสู้กับ N เธอแพ้ในการแข่งขันนั้นอย่างไม่คาดคิด และจึงสูญเสียทุกอย่าง\nแม้แต่ N ก็ไม่รู้ว่า เธอได้ถูกสังเกตโดยบางคนในหมู่ดวงดาวแล้ว\nหลังจากประสบความตายที่กำหนดไว้แล้ว เธอได้รับพลังของเขาและภารกิจที่เขาตั้งให้เธอ\nในร่างกายของเธอนั้นมีการรวมกลุ่มของดวงดาวทำให้เธอสามารถเป็นหนึ่งในนั้นได้\nหากช่วงเวลาสุดท้ายไม่สามารถหยุดยั้งได้ เขาจะละทิ้งทุกอย่าง และกลับไปสู่นภา กลายเป็นท่าเรือที่เริ่มแรกและสุดท้าย"
  },
  CollectionHall_57606_LockTip = {
    Text = "ผ่านผู้พเนจร「กลางวันอมตะ」แล้วปลดล็อก"
  },
  CollectionHall_57606_Title = {
    Text = "เคธี่กูลา"
  },
  CollectionHall_57607_Desc = {
    Text = "<Title:บทนำ>\nการหลอมละลาย·ดอร์ เดิมเป็นความภาคภูมิใจของมิซากะและวิทยาศาสตร์มนุษยชาติ ในระหว่างการต่อสู้อันยาวนานกับปรากฏการณ์หลอมละลาย เธอตระหนักว่า ขณะที่ปรากฏการณ์นี้กำลังทำลายร่างกาย มันก็ได้ปูทางไปสู่ความจริงเช่นกัน \nหลังจากบังเอิญสัมผัสกระดานหินโบราณที่สลักด้วยคัมภีร์ลึกลับ เธอตัดสินใจเดินบนเส้นทางอันดำมืดไร้ขอบเขต ยอมให้การหลอมกร่อนกัดกร่อนสมองโดยไม่เปลี่ยนร่างหุ่นเพื่อยืดชีวิต \nในที่สุดเธอก็ได้บรรลุตามปรารถนา มองเห็นแก่นแท้ของการหลอมละลาย แต่ก็ได้พังทลายสู่การทำลายและความว่างเปล่าอย่างสิ้นเชิง \nหลังจากแสงสว่างแห่งศรัทธาและเหตุผลที่เคยนำทางทุกคนหายไป การหลอมละลาย·ดอร์เริ่มเผยพฤติกรรมการทำลายล้างในที่ที่อาจารย์และนักเรียนในโรงเรียนไม่สามารถมองเห็นได้ “ช่วย” ก่อให้เกิดเหตุการณ์สูญเสียชีวิตหลายครั้งก่อนที่จะถูกมิซากะค้นพบ และถูกควบคุมด้วยการเฝ้าระวังและปราบปรามขั้นสูงสุด \nแต่เบื้องหลังหุ่นที่พังทลาย วิญญาณอันเปี่ยมไปด้วยพรสวรรค์ของเธอดูเหมือนจะยังคงส่งเสียงสะท้อนอยู่ในสถานที่ที่ลึกซึ้งและมืดมิดกว่าเดิมของโลก"
  },
  CollectionHall_57607_LockTip = {
    Text = "ปลุก「เมลต์·ดอร์」แล้วปลดล็อก"
  },
  CollectionHall_57607_Title = {
    Text = "ดอลล์: มลายทราม"
  },
  CollectionHall_57608_Desc = {
    Text = "<Title:คำอธิบาย>\nเกิดในครอบครัวต่ำต้อย แต่ได้รับความนิยมจากความงามของเธอ เป็นนักร้องที่พยายามเอาตัวรอดในสังคมชั้นสูงอย่างยากลำบาก\n\nในช่วงเวลาแห่งภัยพิบัติ เธอได้รับตั๋วเดียวสำหรับการหนีชีวิตด้วยความเมตตาและบุญคุณเล็กๆ น้อยๆ\n\nทุกคนถือว่าตำแหน่งนี้ควรเป็นของเธอเอง แต่เธอกลับตัดสินใจอย่างลับๆ ว่าจะปกป้องและส่งฟีนต์ พี่สาวของเธอขึ้นไปบนเที่ยวบิน\n\nอย่างไรก็ตาม ในช่วงเวลาสุดท้าย พี่สาวใช้พละกำลังที่หลุดจากการโอบอุ้ม และบังคับให้เธอขึ้นนั่งบนที่นั่ง เพื่อส่งตัวเธอออกจากดาวร้าง\n\n\nหลังจากถูกปลุกขึ้นมาโดยไม่คาดคิด ทิงค์เทตรู้สึกผิดและเสียใจอย่างไม่สิ้นสุด เธอเชื่อว่าพี่สาวของเธอไม่ได้ตาย หรืออาจฟื้นคืนชีพในรูปแบบใดรูปแบบหนึ่งเหมือนกับตัวเธอ\n\nตั้งแต่นั้นมา เธอได้ทุ่มเททุกอย่างเพื่อค้นหาสถานที่ของพี่สาว โดยไม่คำนึงถึงต้นทุน"
  },
  CollectionHall_57608_LockTip = {
    Text = "ปลุก「ทิงค์เทต」แล้วปลดล็อก"
  },
  CollectionHall_57608_Title = {
    Text = "ทิงค์"
  },
  CollectionHall_57609_Desc = {
    Text = "<Title:บทนำ>\nนักวิชาการอัจฉริยะที่ได้รับฉายาว่า 「สมองแห่งมิซากะ」 หนึ่งในที่ปรึกษาภาคสนามของมิซากะ\nเข้าเรียนที่มิซากะเมื่ออายุ 14 ปี เคยเป็นผู้นำในการปรับปรุงอุปกรณ์ช่วยชีวิตของอลิสเตอร์\nติดเชื้อการหลอมกร่อนระหว่างการเดินทางออกนอกพื้นที่ครั้งหนึ่ง เขียนคำอธิบายขั้นตอนการปลุกยาวถึงแปดสิบหน้าอย่างสงบ ก่อนจะจากไปอย่างสงบ\nหลังความตาย เพื่อนร่วมงานปฏิบัติตามคำอธิบาย นำเงินใจของเธอใส่ลงในเครื่องมือปลุก สร้าง 「ดอร์ ร่างกายที่ตื่นขึ้น」\nหลังถูกปลุกให้ฟื้นคืนชีพ เธอลุกขึ้นอย่างสงบ แต่งตัวอย่างสงบ และเดินเข้าห้องทดลองอย่างสงบเพื่อดำเนินการวิจัยที่ค้างคาต่อ\nเห็นไหม โลกของอัจฉริยะก็น่าเบื่อและจืดชืดเช่นนี้แหละ"
  },
  CollectionHall_57609_LockTip = {
    Text = "ปลุก「ดอร์」แล้วปลดล็อก"
  },
  CollectionHall_57609_Title = {
    Text = "ดอลล์"
  },
  CollectionHall_57610_Desc = {
    Text = "<Title:คำอธิบาย>\nวิญญาณของเผ่าพันธุ์ต่างดาวที่หนีออกมาจากดาวเคราะห์ซึ่งถูกการหลอมกร่อนกลืนกิน ได้เข้าสิงร่างของเด็กสาวที่เพิ่งเสียชีวิต หลีกเลี่ยงชะตากรรมเดียวกับพ่อแม่ที่ต้องตายไป\nแต่ไม่นานหลังจากร่างมนุษย์นี้เริ่มแสดงอาการของการหลอมกร่อน วิญญาณของเธอก็ถูกตรึงไว้ภายในร่างเช่นกัน ไม่สามารถหนีออกไปได้อีก\nด้วยความหวาดกลัวจากการแพร่กระจายของการหลอมกร่อน เธอเกิดภาวะจิตใจล่มสลายและติดต่อมิซากะโดยตรง เพื่อขอให้เปลี่ยนตนเองเป็นร่างกายที่ตื่นขึ้น โดยเสนอแลกเปลี่ยนด้วยความรู้และเทคโนโลยีของเผ่าพันธุ์ตนเองเป็นการตอบแทน\nหลังจากกลายเป็นร่างกายที่ตื่นขึ้น เธอทำการวิจัยเกี่ยวกับเครื่องจักร ไฟฟ้า และจิตใจในสถาบันการศึกษา อย่างไรก็ตาม เนื่องจากความกลัวอย่างยิ่งต่อการหลอมกร่อนทำให้เธอไม่สามารถทำการวิจัยเกี่ยวกับการหลอมกร่อนได้ อีกทั้งยังเกิดความกลัวต่อความมืดเพราะเงาทางจิตใจ จนไม่กล้าหลับนอน ใช้ชีวิตอยู่ทุกวันด้วยความอ่อนไหวและประสาทตึงเครียด"
  },
  CollectionHall_57610_LockTip = {
    Text = "ปลุก「เวินเค่อ」แล้วปลดล็อก"
  },
  CollectionHall_57610_Title = {
    Text = "วิงเกิล"
  },
  CollectionHall_57611_Desc = {
    Text = "<Title:คำแนะนำ>\nวิญญาณที่เกิดในมิติจิตใจ เดิมทีลอยเคว้งอยู่ในมหาสมุทรสีเทาอันกว้างใหญ่และว่างเปล่า ตามนักเดินทางจิตใจที่มาเป็นครั้งคราวมายังโลก เพื่อสัมผัสความปรารถนาที่แตกต่าง และตัดศีรษะของพวกเขาเพื่อรวบรวมไว้ในมหาสมุทร ดูดซึมปัญญาและอารมณ์ของพวกเขา \nถูกปลุกให้ตื่นเมื่อกว่าหนึ่งพันหกร้อยปีก่อน และเข้าสิงผู้ที่ปลุกเธอแล้วตัดศีรษะของเธอเอง เนื่องจากลักษณะการดูดซึมพลังจิต ยังคงคงอยู่ด้วยการรวบรวมศีรษะ และเพื่อความบันเทิงได้ล่าศีรษะมากเกินความจำเป็น จนกระทั่งได้พบกับเจ้าของร้านจริงๆ ถูกปราบและทำข้อตกลง ติดตามเจ้าของร้านในฐานะผู้ช่วยจนกว่าชีวิตของเธอจะสิ้นสุด \nสัตว์ประหลาดที่ได้สร้างมิตรภาพที่แท้จริงกับเจ้าของร้านเข้าใจความปรารถนาที่แท้จริงของตัวเอง ตัดศีรษะของเจ้าของร้าน และรับช่วงต่อทั้งรูปลักษณ์และร้านค้าของเธอ จากนั้นไม่ได้ล่าศีรษะอย่างสุ่มสี่สุ่มห้าอีกต่อไป แต่เปลี่ยนเป็นวิธีการแลกเปลี่ยนร้านค้าเพื่อรับมือกับงานสัญญาลึกลับและแลกเปลี่ยนศีรษะ โดยผ่านการสนทนากับลูกค้าเพื่อบรรเทาความเหงาจากการสูญเสียเจ้าของร้าน \nความปรารถนาในปัจจุบันคือปกป้องร้านค้าและเมืองที่เจ้าของร้านรัก"
  },
  CollectionHall_57611_LockTip = {
    Text = "ผ่านด่านบันทึกพิเศษ「เมืองฝนเงาลึกลับ」เพื่อปลดล็อก"
  },
  CollectionHall_57611_Title = {
    Text = "ดาฟโฟดิล"
  },
  CollectionHall_57612_Desc = {
    Text = "<Title:คำแนะนำ>\nเมื่อยังมีชีวิตอยู่ เธอเคยเป็นนักมายากลที่ท่องเที่ยวไปทั่วโลก\nเติบโตมาในคณะละครสัตว์ ชีวิตของเธอรายล้อมไปด้วย「คนแปลกแยก」 โจร นักโทษหลบหนี เด็กถูกทอดทิ้ง คนพิการ และคนที่มีร่างกายผิดปกติ...\nคาเซียก็เป็น「คนแปลกแยก」เช่นกัน: เธอไม่สามารถรับรู้หรือแสดงอารมณ์ได้\nแต่เธอกลับเป็นอัจฉริยะในการแสดง สามารถคว้าเสียงปรบมือจากผู้ชมได้เสมอ\nแม้ภายหลังจะเผชิญกับ @2 และกลายเป็นวิญญาณเหยื่อของพวกต้องสาป เธอก็ยังคงทำการแสดงมายากลเหมือนตอนที่ยังมีชีวิต พร้อมเชิญชวนผู้ชมเข้าสู่「โลกแห่งความมหัศจรรย์เหมือนดินแดนเทพนิยาย」\nทว่า สิ่งที่แปลกคือ หลังจากชมการแสดงมายากลเสร็จ ผู้ชมทุกคนกลับรู้สึกว่า「มันขาดอะไรบางอย่าง」และชีวิตก็เริ่มไร้รสชาติมากขึ้น\nพวกเขาสับสน เฉื่อยชา และบางคนถึงขั้นฆ่าตัวตาย\nแล้วนักมายากลสาวของเราล่ะ? เธอซ่อนตัวอยู่หลังม่าน ดื่มด่ำกับ「รางวัล」อันหอมหวานที่เธอเก็บเกี่ยวมาได้อย่างเบิกบาน\nการแสดงอันหรูหราต้องใช้ต้นทุนสูง และเธอก็เพียงแค่ต้องการให้มันดำเนินต่อไปอย่างยั่งยืน"
  },
  CollectionHall_57612_LockTip = {
    Text = "ปลุก「คาเซีย」แล้วปลดล็อก"
  },
  CollectionHall_57612_Title = {
    Text = "คาเซียห์"
  },
  CollectionHall_57613_Desc = {
    Text = "<Title:การแนะนำ>\nบุคคลลึกลับที่ข้ามเส้นกั้นของไลน์ที่อยู่ในโลกด้วยความบังเอิญ เป็นอีกสิ่งหนึ่งของราโมนา.\nใน「เหตุการณ์นั้น」เนื่องจากความปลอดภัยของผู้พิทักษ์ ต้องปล่อยให้พลังของผู้ปลุกเสกควบคุมร่างกาย.\n\nหลังจากเหตุการณ์ สิ่งที่@2ทิ้งไว้บนราโมนาไม่หายไป.\nจิตสำนึกของ@2ยังคงอยู่ในร่างกายเธอ บีบคั้นพื้นที่ของการมีอยู่ของจิตสำนึก(\n\nอย่างไรก็ตาม เธอไม่ได้ต้องการให้คนรู้สึกเป็นกังวล ทำหน้าตาให้ดูเหมือนว่าไม่มีปัญหาใด ๆ\nการง่ายดูแลผมและชีวิตของเธอให้มีระเบียบสืบต่อ \nบางครั้งที่สติจะหลงหายไป ทำให้เธอมีสถานะว่างเปล่า\nนอกจากนี้การพูดจะใช้คำเสียงที่ต่าง(\nดังนั้นไม่ต้องกังวล แม้ว่าทางมาจะแตกต่างการกระทำจะเพื่อผู้พิทักษ์และสันติของโลกนี้."
  },
  CollectionHall_57613_LockTip = {
    Text = "ผ่านด่าน 「เพียงก้าวเดียว」 ในโหมดการล่องเรือในจิตสำนึก เพื่อปลดล็อก"
  },
  CollectionHall_57613_Title = {
    Text = "ราโมน่า: วัฏกาล"
  },
  CollectionHall_57614_Desc = {
    Text = "<Title:คำแนะนำ>\nเธอเกิดในดินแดนแห่งบทกวีและกุหลาบ เธอคือภูตแห่งบทกวี\nภูตล่องลอยอยู่ในความฝันที่ถักทอโดยคำศัพท์ ยินดีกับการผลิบานของแสงแดดแต่ละรำไร และหลั่งน้ำตาให้กับการเฉาของดอกไม้แต่ละดอก\nเธอครุ่นคิด เธอเศร้าสร้อย และปรารถนาการมาอยู่เคียงข้างของวิญญาณอีกดวง\n\nต่อมา ในสวนที่ดอกไม้บานสะพรั่ง ช่างดอกไม้หนุ่มได้วางดอกกุหลาบหนึ่งดอกไว้ตรงหน้าเธอ\nแล้วเธอก็ยิ้มอย่างเขินอาย พร้อมรับดอกไม้นั้นเบาๆ\n「ในที่สุดก็ไม่ต้องอยู่คนเดียวอีกแล้ว」\nนั่นคือสิ่งที่เธอเชื่อมั่นในเวลานั้น"
  },
  CollectionHall_57614_LockTip = {
    Text = "ผ่านด่านพิเศษบันทึก「ที่อยู่ของดอกกุหลาบ」ปลดล็อก"
  },
  CollectionHall_57614_Title = {
    Text = "ฮอร์ลา"
  },
  CollectionHall_57615_Desc = {
    Text = "<Title:คำแนะนำ>\nตั้งแต่ยุคโบราณ กษัตริย์องค์เดียวของเผ่าอาลัน.\nเมื่อยังเยาว์วัย เธอได้รับการถวายให้เป็นผู้ส่งสารแห่งต้นไม้ เพื่อส่งสาส์นจากพระมหากษัตริย์ หลังจากการต่อต้านครั้งแรก เธอถูกมองว่าเป็นเครื่องบูชายัญและถูกโยนลงไปในแม่น้ำศักดิ์สิทธิ์ของเผ่าอาลัน แต่กลับตื่นรู้ถึงเจตจำนงแห่งต้นไม้.\nน้ำนมแห่งต้นไม้ได้หลอมรวมเข้ากับเนื้อและเลือดของเธอ และระบบรากของต้นไม้มีเลือดของเธอไหลเวียนอยู่ เธอคือต้นแม่พันธุ์แห่งความอุดมสมบูรณ์ และต้นแม่พันธุ์แห่งความอุดมสมบูรณ์ก็คือเธอ.\nอย่างไรก็ตาม พลังแห่งการหลอมกร่อนได้ปนเปื้อนสายเลือดของเผ่าอาลัน เธอจึงใช้ร่างกายของตนเองแทนต้นแม่เพื่อรับมลพิษ เพื่อหวังว่าจะช่วยให้เผ่าอาลันมีโอกาสในการอยู่รอด.\nในวันนี้ที่เผ่าอาลันได้สูญหายไปในกระแสแห่งประวัติศาสตร์ มีเพียงต้นแม่พันธุ์แห่งความอุดมสมบูรณ์ที่เคยตั้งตระหง่านและพังทลายลงมา ที่ยังคงเป็นพยานถึงเรื่องราวที่เกี่ยวข้องกับเธอ."
  },
  CollectionHall_57615_LockTip = {
    Text = "ปลุก「ไทอีส」หลังจากปลดล็อก"
  },
  CollectionHall_57615_Title = {
    Text = "ทาอิส"
  },
  CollectionHall_57616_Title = {
    Text = "ระหว่างดวงดาว"
  },
  CollectionHall_57617_Desc = {
    Text = "<Title:คำแนะนำ>\nอาจารย์ด้านจิตวิทยาของมหาวิทยาลัยมิซากะ รับผิดชอบในการให้คำปรึกษาทางจิตใจแก่ผู้ตรวจสอบ\nอ่อนโยนและใจดี ได้รับความรักจากคณาจารย์และนักเรียนในมหาวิทยาลัยอย่างกว้างขวาง แต่สมาชิกบางคนของมิซากะกลับรู้สึกหวาดกลัวเธอ\nยังไม่ต้องพูดถึงชาดำที่มีส่วนผสมไม่ชัดเจน——ไม่มีใครเคยเห็นเธอในขณะที่ไม่ยิ้ม แค่ข้อนี้ก็เพียงพอที่จะทำให้คนขนลุกได้แล้ว"
  },
  CollectionHall_57617_LockTip = {
    Text = "ผ่านด่านบทนำเพื่อเปิดใช้งาน"
  },
  CollectionHall_57617_Title = {
    Text = "ซิลเวีย"
  },
  CollectionHall_57618_Title = {
    Text = "คนโง่"
  },
  CollectionHall_57619_Title = {
    Text = "ฮีบริด"
  },
  CollectionHall_57620_LockTip = {
    Text = "ตื่น「ปิ๊คมัน」หลังการปลดล็อก"
  },
  CollectionHall_57620_Title = {
    Text = "คนต่างถิ่น"
  },
  CollectionHall_57621_Desc = {
    Text = "<Title:คำแนะนำ>\nนักสืบอาวุโสของมิซากะ ผู้ที่ได้รับการเคารพจากผู้พิทักษ์เรียกว่า 「รุ่นพี่」\nเคยกลัวการออกจากบ้านด้วยเหตุผลบางอย่างที่ไม่สามารถพูดได้ ในขณะที่ศึกษาอยู่ในโรงเรียนก็ทำงานเป็นเจ้าหน้าที่ฝ่ายข่าวกรองไปด้วย\nหลังจากเพื่อนสนิทเสียชีวิต ได้เปลี่ยนสไตล์จากเดิมมาสู่แนวหน้า โดยการทำ 「สิ่งที่เขาเคยทำ」 เพื่อรำลึกถึงเพื่อนที่จากไป\nพกพากุญแจเงินที่แตกหักติดตัวเสมอ เพื่อรักษาความทรงจำที่ค่อยๆ เลือนลางเหล่านั้นอย่างยากลำบาก"
  },
  CollectionHall_57621_LockTip = {
    Text = "ผ่านด่านบทนำเพื่อเปิดใช้งาน"
  },
  CollectionHall_57621_Title = {
    Text = "วิลเลียม"
  },
  CollectionHall_57622_Desc = {
    Text = "<Title:ประวัติย่อ>\nคนทำสวนของสีไค และเป็นเพื่อนวัยเด็กของออร์ล่า \nในช่วงเวลาที่ออร์ล่าหมดหนทางที่สุด เธอได้มอบความสุขที่ยากจะลืมเลือนให้กับออร์ล่าผ่านสวนดอกไม้แห่งหนึ่ง \nเมื่อความสามารถของออร์ล่าเริ่มเติบโตและเบ่งบาน โคลเล็ตกลับใช้ไฟป่าครั้งใหญ่พรากเอาความมั่งคั่ง เกียรติยศ และชีวิตของออร์ล่าไป \nเธอได้ร่วมมือกับเฮอร์เบิร์ต สร้างโลกจากบทกวีโดยใช้รวมบทกวีของออร์ล่า อาจเป็นเพราะระลึกถึงความทรงจำ หรืออาจเป็นเพราะต้องการควบคุม ไม่มีใครรู้ \nโคลเล็ตมักจะกล่าวเสมอว่า ในบทกวีที่งดงามเหล่านั้น สิ่งเดียวที่เธอเข้าใจคือความปรารถนา \nเธอกำลังเจ็บปวดจากสิ่งนั้น แต่เธอก็ภูมิใจในสิ่งนั้นเช่นกัน"
  },
  CollectionHall_57622_LockTip = {
    Text = "ผ่านด่านพิเศษบันทึก「ที่อยู่ของดอกกุหลาบ」ปลดล็อก"
  },
  CollectionHall_57622_Title = {
    Text = "โคเล็ตต์"
  },
  CollectionHall_57623_Desc = {
    Text = "<Title:บทนำ>\nมิลียาห์มเคยพบเดโบราห์สองคน: คนหนึ่งเป็นนักบวชแห่งลีมูเรีย อีกคนเป็นสาวใช้ของตระกูลโอเนอร์ คนหนึ่งเป็นเพื่อนสนิทของเธอ อีกคนก็เป็นเพื่อนสนิทของเธอเช่นกัน \nสองยุคสมัยที่ห่างกันนับหมื่นปี สองคนที่แตกต่างกัน แต่มีชื่อเดียวกัน ใบหน้าเหมือนกัน และความดีงามเหมือนกัน นี่เป็นความบังเอิญที่หาได้ยาก สำหรับมิลียาห์มแล้ว นี่คือลางบอกเหตุที่เต็มไปด้วยความศักดิ์สิทธิ์ \nมิลียาห์มได้เห็นจุดจบของเดโบราห์ทั้งสองคน: คนหนึ่งจมลงสู่ก้นทะเลพร้อมกับลีมูเรีย อีกคนถูกเธอส่งขึ้นแท่นบูชายัญด้วยมือของเธอเอง ถูกผ่าท้องจนเสียชีวิต \nในเรื่องราวอันยิ่งใหญ่เกี่ยวกับสวรรค์ เรื่องราวของเดโบราห์เป็นเพียงคำอธิบายสั้นๆ สีแดงสดสองบรรทัด"
  },
  CollectionHall_57623_LockTip = {
    Text = "ผ่านด่านโลกแห่งความฝันประหลาด「การลบหลู่」เพื่อปลดล็อก"
  },
  CollectionHall_57623_Title = {
    Text = "เดโบรา"
  },
  CollectionHall_57624_Desc = {
    Text = "<Title:คำแนะนำ>\nสมาชิกคนสำคัญของสมาคมนักสืบมหาวิทยาลัยมิซากะ และเป็นนักขุดคุ้ยข้อมูลอันดับหนึ่งของมหาวิทยาลัยมิซากะ\nมีความสามารถในการรวบรวมและขุดค้นข้อมูลอย่างหาตัวจับยาก จนได้รับชื่อเสียงเลื่องลือไปทั่วลอนดีเนี่ยน\nเดิมทีเธอเป็นชาวสาธารณรัฐอาร์เจนโต แต่หลังจากเหตุการณ์ในครอบครัวทำให้เธอมาที่ลอนดีเนี่ยน และใช้ความลับของมิซากะที่เธอมีอยู่ในมือเพื่อเข้าศึกษาในมหาวิทยาลัยแห่งนี้\nอย่าได้หลงกลกับรอยยิ้มแจ่มใสของเธอ — การที่เธอเข้าใจเรื่องราวของมิซากะนั้นลึกซึ้งกว่าที่ใครหลายคนคิดไว้มาก"
  },
  CollectionHall_57624_LockTip = {
    Text = "เพื่อปลดล็อก ผ่านด่านการสอบสวนดำเนินการ บทที่ 1 「เรื่องลับของเขตตะวันออก」"
  },
  CollectionHall_57624_Title = {
    Text = "ฮันนา"
  },
  CollectionHall_57625_Desc = {
    Text = "<Title:ประวัติย่อ>\nอดีตนักวิจัยของมูลนิธิกรีนแห่งก่อน ผู้อำนวยการโรงพยาบาลรักษาโรคไร\nหลังจากสามีและลูกสาวเสียชีวิต เธอได้ทุ่มเทเวลาเพื่อตามหาวิธีฟื้นคืนชีพให้ลูกสาว\nในระหว่างการเดินทางอันยาวนาน เธอลืมใบหน้าของลูกสาวไป และความรักและความอบอุ่นที่เคยเป็นแรงผลักดันให้เธอสู้ต่อ\nเหลือเพียงความเจ็บปวดที่ฝังลึกอยู่ในใจ"
  },
  CollectionHall_57625_LockTip = {
    Text = "ผ่านด่านการสอบสวนดำเนินการ บทที่ 4 「ในที่เงียบงัน」 เพื่อปลดล็อก"
  },
  CollectionHall_57625_Title = {
    Text = "ฟรานซิส"
  },
  CollectionHall_57626_Desc = {
    Text = "<Title:บทนำ>\nกัปตันแห่งเรือโสนาเนียร์.\nบ้านเกิดของเขาจางหายไปในความทรงจำของผู้คนเพราะการย่อยสลาย,      มีเพียงเขาที่จำทุกสิ่งได้. ดังนั้นผู้คนจึงเรียกเขาว่าคนบ้า.\nชุมชนเล็ก ๆ ริมทะเล,      ญาติ,      พี่น้อง... สิ่งเหล่านี้คืออดีตที่คนบ้าพยายามหวนคืน.\nเขาได้ทำข้อตกลงกับมิรียำ,      ส่งมอบสินค้าที่เธอต้องการ,      เป็นการตอบแทน,      เธอจะช่วยเขาตื่นความทรงจำที่หลับใหลมายาวนาน.\nดังนั้น,      เขาได้เห็นเด็กหญิงที่ถูกล้อมรอบด้วยลมเย็นและนกเขาน.\n\n「ชื่อของฉันคือเซเลสเต,      ตราบใดที่เธอต้องการฉัน,      ฉันก็จะอยู่ที่นี่.」\nเธอคือร่องรอยที่ครั้งหนึ่งเคยมีอยู่ของบ้านเกิด,      เป็นเทพนิยายที่เขาเคยได้ยินจากปากของผู้สูงอายุเมื่อเขายังเด็ก.\n\nปรากฏว่าที่ผ่านมาที่ดึงวิญญาณให้หวนคือความจริงที่มีอยู่จริง."
  },
  CollectionHall_57626_LockTip = {
    Text = "ผ่านด่านการสอบสวนปฏิบัติการ บทที่ 6 「ดวงดาวที่ผิดเพี้ยน」 เพื่อปลดล็อก"
  },
  CollectionHall_57626_Title = {
    Text = "เอลตัน"
  },
  CollectionHall_57627_Desc = {
    Text = "<Title:บทนำ>\nพนักงานของโบสถ์ลอนดินีอุมแห่งพรนิรันดร์ของบิดา,      รับผิดชอบในการช่วยบิชอปและนักบวชท่านอื่นในการรักษาการดำเนินการในโบสถ์ให้ราบรื่น.\nหลังการเสียชีวิตของพ่อ,      พี่สาวที่เก่งกาจได้ยึดกิจการขึ้นมา,      กลายเป็นพ่อค้าเล็กมีชื่อเสียง,      ทุกอย่างดูเหมือนจะดีและราบรื่นนครั้นการหลอกลวงที่มีการวางแผนไว้อย่างดีนั้น.\nภายในคืนเดียว,      สามแม่ลูกต้องไร้สิ้นทุกสิ่ง. แต่เรื่องนี้ไม่ใช่เรื่องใหญ่,      บิชอปแห่งลอนเดเนียมได้ยื่นมือเข้าช่วยเหลือเธอ,      เพียงแค่มีครอบครัวอยู่ด้วยกัน,      เธอไม่กลัวปัญหาใด ๆ.\nต่อมาพี่สาวเธอเสียชีวิต.\nแม่เธอได้ทุกข์ทรุดและเสียชีวิตไปอย่างเศร้าหมอง.\nในขณะเดียวกัน,      บุคคลที่ไร้ยางอายที่เข้าครอบครองบ้านตระกูลของเธอก็จัดกิจกรรมศิลปะและสรวลเสพสุข.\nความสับสน,      ความโกรธ,      ความเข้าใจผิด... อารมณ์มากมายบีบอัดที่หน้าอกของเธอ,      แปรเปลี่ยนเป็นความเกลียดที่ต้องบดขยี้เธอเป็นฝุ่น. แต่เธอไม่ควรเป็นเช่นนี้,      บิชอปเคยกล่าวเอาไว้,      ผู้ที่ติดอยู่ในอดีตจะไม่มีทางก้าวไปข้างหน้าได้,      มีแต่การให้อภัยเท่านั้นที่จะทำให้พ้น.\nเธอทำไม่ได้.\n「อย่าบังคับตัวเองให้ทน,     」 ผู้หญิงที่เรียกตัวเองว่าเลดี้แสงในโคมให้คำแนะนำข้างหูเธอ,      「การให้อภัยคือการปล่อยปละละเลย. ผู้ดีเท่านั้นจึงควรได้รับการอภัย,      คนเลว — คนเลวทุกคนควรได้รับการลงโทษที่สมควร.」\nดังนั้นเธอจึงรับกระจกจากมือหญิงนั้น,      เริ่มพิธีการตัดสิน."
  },
  CollectionHall_57627_LockTip = {
    Text = "ผ่านด่านพิเศษบันทึก「สีของเลือด」ปลดล็อค"
  },
  CollectionHall_57627_Title = {
    Text = "โซเฟีย"
  },
  CollectionHall_57628_Desc = {
    Text = "<Title:ประวัติโดยย่อ>\nทาสไร้ที่มา เคยขึ้นดำรงตำแหน่งหัวหน้าเผ่าแทนโกลิอัท\nสังหารเจ้านายตั้งแต่อายุ 8 ขวบ ซ่อนตัวในถังไม้ล่องน้ำมาถึงเกาะของชาวฟิลิสเตีย\nในกายไหลเวียนด้วยสายเลือดต่ำต้อย อ่อนแอ ต่ำทราม และเต็มไปด้วยความทะเยอทะยาน\nขึ้นเป็นหัวหน้าได้ไม่ถึงเดือนก็ถูกตัดศีรษะ ระยะเวลาครองตำแหน่งอยู่ในอันดับที่ 13 เมื่อเทียบกับหัวหน้าคนอื่นๆ\nตำแหน่งหัวหน้าของชาวฟิลิสเตียไม่ใช่ตำแหน่งที่ใครจะทำไปจนเกษียณได้ง่ายๆ หรอกนะ"
  },
  CollectionHall_57628_LockTip = {
    Text = "ผ่านด่านการล่องเรือในจิตสำนึก「The Fall of Giants」เพื่อปลดล็อก"
  },
  CollectionHall_57628_Title = {
    Text = "อีเกิร์น"
  },
  CollectionHall_57629_Desc = {
    Text = "<Title:คำแนะนำ>\n\n\nเธอเคยเป็นสถานีกลางของอาณาจักรนิรันดร์ ควบคุมทางเข้าออกระหว่างอาณาจักรและโลกภายนอก ทำหน้าที่ชี้นำพลเมืองที่หลงทางให้กลับสู่บ้านเกิด \nเมื่ออาณาจักรหลับลึกและตกลงสู่ห้วงทะเลวนเรื่อย ๆ ฟาร์โรสก็สูญเสียลิงก์กับบ้านเกิดของเธอ \nเธอไม่สามารถติดต่อเมืองหลวงได้ และไม่พบร่องรอยใด ๆ ในมหาสมุทรที่กว้างใหญ่ \n\nในฐานะประภาคารกลางทะเล แต่ไม่สามารถส่องสว่างเพื่อชี้ทางกลับบ้านได้ นี่ช่างเป็นเรื่องที่น่าขันยิ่ง \n\nในช่วงเวลาที่ยาวนานและโดดเดี่ยว เธอค่อย ๆ บ้าคลั่งและไร้ความสามารถ จนก่อให้เกิดภัยพิบัติทางทะเลหลายครั้งในประวัติศาสตร์ จนกระทั่งถูกปราบโดยฮีโร่โบราณคนหนึ่งเมื่อหมดแรง \n\nในการวิจัยภายหลัง มีนักวิชาการบางรายเชื่อว่าความคลั่งของฟาร์โรสอาจเป็นสาเหตุที่ทำให้มหาสมุทรจมหายไป \nทุกอย่างเป็นเพียงการคาดเดา จนถึงตอนนี้ อดีตของสาวผู้ศรัทธานี้ยังคงเป็นปริศนา"
  },
  CollectionHall_57629_LockTip = {
    Text = "ปลุก「ฟาร์โรส」แล้วปลดล็อก"
  },
  CollectionHall_57629_Title = {
    Text = "ฟารอส"
  },
  CollectionHall_57630_Desc = {
    Text = "<Title:บทนำ>\nเป็นลูกชายของตระกูลขุนนางเล็กๆ ในดัชชีแห่งหนึ่ง แม้จะเกิดในตระกูลขุนนาง แต่บิดาของเขาไม่มีผลงานใดๆ อนาคตของเขาก็มองเห็นได้ชัดว่าจะธรรมดาสามัญ \nจนกระทั่งครั้งหนึ่งเมื่อถูกบิดาพาไปงานเลี้ยงวันคริสต์มาสเพื่อเข้าพบดยุค เขาได้ดูแลและใส่ใจเจ้าหญิงที่ป่วยซึ่งอายุเท่ากันในงานเลี้ยง ทำให้ดยุคมองเขาในแง่ใหม่ และด้วยคำพูดเล่นของดยุค เขาได้กลายเป็นสมาชิกสำรองของอัศวินแห่งดัชชี เริ่มเข้าร่วมการฝึกฝนอย่างเป็นทางการในกองกำลังอัศวิน \nจนกระทั่งสงครามมาถึง กองทัพที่อ่อนแอของดัชชีไม่สามารถหยุดยั้งกองทัพม้าเหล็กได้ มีผู้บาดเจ็บและเสียชีวิตจำนวนมาก แต่โอกีลยังคงเป็น “อัศวิน” คนสุดท้ายที่ปกป้องเจ้าหญิง \nเขาจับหอกขนาดใหญ่ที่ยังสูงเกินไปไว้ในมือ และยืนขวางประตูห้องของเจ้าหญิงตลอดกาล"
  },
  CollectionHall_57630_LockTip = {
    Text = "ผ่านด่านการล่องเรือในจิตสำนึก「คำอธิษฐานของอัศวิน」เพื่อปลดล็อก"
  },
  CollectionHall_57630_Title = {
    Text = "โอเกียร์"
  },
  CollectionHall_57631_Desc = {
    Text = "<Title:ประวัติย่อ>\nนักเต้นรำอัจฉริยะที่เต้นรำในเปลวเพลิง.\nครอบครัวของเธอทำหน้าที่เป็นนักเต้นรำในราชสำนักมานับร้อยปี แม้ราชอาณาจักรจะเปลี่ยนแปลง โรงเรียนจะไม่มีอีกต่อไป แต่เธอก็ไม่เคยสูญเสียจิตวิญญาณแห่งการเต้นรำที่สง่างามและงดงาม.\nเมื่ออายุ 18 ปี เธอเข้าร่วมคณะบัลเล่ต์ท้องถิ่น และในไม่ช้าก็กลายเป็นนักเต้นรำหลักที่ไม่มีใครโต้แย้งได้.\n\nอย่างไรก็ตาม หลังจากการแสดงรอบปฐมทัศน์ประสบความสำเร็จ ผู้จัดการกลุ่มเต้นรำกลับส่งลิซไปยังห้องของพ่อค้ารวยๆ โดยอ้างว่าเป็นการ「แนะนำ」.\nที่จริงแล้ว บัลเล่ต์ได้เปลี่ยนไปจากเดิม มรดกทางวัฒนธรรมอันสูงส่งได้กลายเป็นทุนที่เด็กหญิงๆ ใช้เพื่อเพิ่มมูลค่าของพวกเธอ.\nดังนั้นเธอจึงหนีออก ถูกจับกลับมา แล้วก็หนีอีก... ในที่สุด 「ความหยิ่งยโส」ของเธอก็ทำให้เหล่าคนมีอำนาจโกรธแค้น.\nพวกเขาทรมานลิซทั้งทางร่างกายและจิตใจ เธอต้องหมุนตัวและเต้นรำอย่างไม่หยุดหย่อน แม้ปลายเท้าจะแตกและเลือดสีดำไหลนองพื้นก็ตาม.\n\nในที่สุด ในระหว่างการแสดงปกติครั้งหนึ่ง เมื่อการเต้นรำถึงจุดสูงสุด เพลิงไฟก็ลุกโชนขึ้นมาจากฝ่าเท้าของเธอ.\nเธอจะเผาทำลายความอยุติธรรมและความชั่วร้ายทั้งมวล."
  },
  CollectionHall_57631_LockTip = {
    Text = "ปลุก「ลิซ」แล้วปลดล็อก"
  },
  CollectionHall_57631_Title = {Text = "ลิซ"},
  CollectionHall_57632_Desc = {
    Text = "<Title:เรื่องย่อ>\nถูกกดขี่ ถูกรับเลี้ยง ถูกทอดทิ้ง... เรื่องราวมาถึงจุดนี้ไม่ต่างอะไรจากชิโลในเส้นเวลาอีกโลกหนึ่ง แต่เลือดเดียวกันกลับหล่อเลี้ยงกิ่งไม้ที่แตกต่างออกไป\nจนกระทั่งเมื่อเธอตกลงไปในคุก นรกที่แท้จริงจึงเริ่มต้นขึ้น เธอพบด้วยความหวาดกลัวว่าชนชาติของเธอซึ่งควรจะเกลียดชังเจ้าของทาสเหมือนกัน กลับเกลียดชังเธอมากกว่า และความชั่วร้ายนั้นยิ่งรุนแรงขึ้น\nทุกวันทุกวัน เธอตกลงไปสู่การทรมานและความเจ็บปวดอย่างไม่มีที่สิ้นสุด ของขวัญจากโชคชะตาทำลายจิตใจของเธอลงอย่างหมดสิ้นพร้อมดอกผลและต้นทุน\nความเกลียดชังที่ควรจะมุ่งเป้าไปที่เจ้าของทาสกลับกลายเป็นความเกลียดชังต่อทุกคน และในขณะเดียวกัน เธอก็ถูกทุกคนเกลียดชัง สูญเสียตำแหน่งแห่งการดำรงอยู่ของตนเอง\nจนกระทั่งเมื่อเธอใช้การหลอมกร่อนหลบหนีออกจากคุก จิตใจของเธอก็เหลือเพียงความบ้าคลั่ง เธอคว้าพละกำลังที่ได้รับอย่างกะทันหัน พร้อมปลดปล่อยความโกรธแค้นอันไม่มีที่สิ้นสุดของเธอออกมา\nคืนนั้น เมืองทั้งเมืองต้องเผชิญกับสายฝนสีแดงของเลือด เธอยืนอยู่ในแม่น้ำสีแดงแห่งนั้น แหงนหน้าขึ้นและหัวเราะอย่างสะใจ"
  },
  CollectionHall_57632_LockTip = {
    Text = "ปลุก「โซ่เลือด·ชิโล」แล้วปลดล็อก"
  },
  CollectionHall_57632_Title = {
    Text = "เฮลอต: ตรวนสีชาด"
  },
  CollectionHall_57633_Desc = {
    Text = "<Title:บทนำ>\nผู้ก่อตั้งและประธานสมาคมนักประติมากรรม \nป่วยเป็นไข้ไขสันหลังอักเสบในวัยเด็ก ทำให้ต้องเรียนรู้ด้วยตนเองที่บ้าน และตั้งแต่นั้นมาก็ได้ตระหนักถึงข้อจำกัดของร่างกายมนุษย์ \nเมื่อโตขึ้นได้เข้าศึกษาที่มิซากะ และได้ค้นพบแนวทางการวิจัยภายใต้ความช่วยเหลือของอาจารย์ พร้อมทั้งรักษาโรคของตนเองจนหาย \nมักจะมีรอยยิ้มอ่อนโยนเสมอ แต่แท้จริงแล้วไม่ใส่ใจในความรู้สึกของมนุษย์เท่าใดนัก \nไม่ค่อยดูแลภาพลักษณ์ สภาพผมและโต๊ะทำงานมักจะรกพอ ๆ กัน \nในลิ้นชักโต๊ะทำงานเก็บแฟ้มเอกสารไว้ ข้างในมีบทความวิชาการที่โครว์ลีย์เคยตีพิมพ์เรียงไว้อย่างเป็นระเบียบ — นี่คือสิ่งที่เฮอร์เบิร์ตเคยทำที่มีระเบียบที่สุด"
  },
  CollectionHall_57633_LockTip = {
    Text = "เพื่อปลดล็อก ผ่านด่านการสอบสวนดำเนินการ บทที่ 1 「เรื่องลับของเขตตะวันออก」"
  },
  CollectionHall_57633_Title = {
    Text = "เฮอร์เบิร์ต"
  },
  CollectionHall_57634_Desc = {
    Text = "<Title:บทนำ>\nในสายตาของชาวฟีลิสเตีย เขาคือผู้นำที่กล้าหาญที่สุดตลอดกาล.\nร่างกายสูงใหญ่ แข็งแรง มีพละกำลังมหาศาล ในเวลาเพียงไม่กี่ปีหลังขึ้นมามีอำนาจ ก็นำพาชาวฟีลิสเตียกวาดล้างชนเผ่าต่างๆ รอบข้างได้อย่างราบคาบ โดยไม่เคยพ่ายแพ้.\nท่ามกลางคำชื่นชมและดอกไม้ เสียงชื่อเสียงของเขาดังไปไกล จนถึงขั้นละเลยคำเตือนของคนในเผ่า กระทำการประมาทศัตรู.\nความผิดพลาดเพียงเล็กน้อยทำให้กองทัพฟีลิสเตียพังพินาศ. เขาจึงยอมรับโทษ หนีลี้ภัยไปยังทะเลพร้อมผู้ติดตามเพียงคนเดียว.\nความโกรธแค้น ความไม่ยอมรับ... ช่วงเวลาน่าอับอายครั้งนี้จะต้องถูกจดจำไว้ เขายินดีมอบคอที่เปราะบางให้กับ 「แม่มด」 เพื่อหวังจะทวงคืนทุกอย่างที่เคยเป็นของเขา.\nเขาได้ก้าวสู่เส้นทางแห่งการแก้แค้นด้วยเลือดแล้ว."
  },
  CollectionHall_57634_LockTip = {
    Text = "ผ่านด่านการล่องเรือในจิตสำนึก「The Fall of Giants」เพื่อปลดล็อก"
  },
  CollectionHall_57634_Title = {
    Text = "โกไลแอท"
  },
  CollectionHall_57635_Desc = {
    Text = "<Title:ประวัติย่อ>\nเดิมทีเธอเป็นทาสชั้นต่ำ ความฉลาดและรูปร่างหน้าตาที่งดงามของเธอเมื่อยังเยาว์วัยดูเหมือนจะกำหนดชะตากรรมอันโหดร้ายของเธอไว้แล้ว\nแต่โชคชะตาที่ไม่คาดคิดได้นำพาให้เธอมาแทนที่ลูกสาวของผู้ปกครองที่เสียชีวิตไป และกลายเป็นบุตรบุญธรรมที่เชื่อฟังของพวกเขา ไม่มีใครจ้องมองเธอด้วยสายตาที่มองทาสอีกต่อไป\nเธอจากบ้านไปตั้งแต่อายุยังน้อย การใช้ชีวิตร่วมกันหลายปีทำให้เธอเห็นผู้หญิงที่อ่อนโยนคนนั้นเป็นแม่แท้ๆ ของเธอ จนกระทั่งเมื่อเธอเผลอช่วยเหลือชนเผ่าของเธอเองโดยบังเอิญ ผู้ปกครองที่เกลียดชังการรวมกลุ่มของทาสก็ทอดทิ้งเธอในทันที\nโชคชะตาได้เผยให้เห็นใบหน้าที่โหดร้ายที่ไม่เคยเปลี่ยนแปลง เธอกลายเป็นนักโทษในชั่วข้ามคืน หมักหมมความเกลียดชังในกรงขังและใช้ช่วงวัยรุ่นทั้งหมดไปกับเรื่องนี้\nหลังจากการหลอมกร่อนระเบิดขึ้นในคุก เธอพบว่าของเหลวสีดำนี้สามารถกัดกร่อนกุญแจมือได้ ดังนั้นเทพีแห่งการแก้แค้นจึงออกจากคุก และครั้งต่อไปที่เธอปรากฏตัว เธอได้แลกเปลี่ยนศีรษะของผู้ปกครองกับการปลดปล่อยชนชาติไทโลสโดยสมบูรณ์\nช่วงชีวิตที่เหลือของเธอผ่านไปกับการตามล่าเจ้าของทาสในอดีต จนกระทั่งกลายเป็นหลุมศพที่ไม่มีชื่อสลักคำสดุดีเอาไว้"
  },
  CollectionHall_57635_LockTip = {
    Text = "ปลุก「ชิโล」แล้วปลดล็อก"
  },
  CollectionHall_57635_Title = {
    Text = "เฮลอต"
  },
  CollectionHall_57636_Title = {
    Text = "ผู้อยู่อาศัยในความมืด"
  },
  CollectionHall_57637_Desc = {
    Text = "<Title:ประวัติย่อ>\nแตกต่างจากหญิงสาวในยุคนั้นที่มักปรากฏตัวในสนามรบในฐานะผู้ดูแลทางการแพทย์ เธอในช่วงชีวิตก่อนเป็นนักรบที่กล้าหาญและภาคภูมิใจในสิ่งนั้น\nเธอเชื่อมั่นว่ามาตุภูมิของเธอนั้นบริสุทธิ์ และการที่มาตุภูมิพิชิตดินแดนอื่นจะนำพาอนาคตที่ดีขึ้นให้แก่โลก\nในสมรภูมิรบหนึ่งที่ดุเดือด เธอได้รับบาดเจ็บสาหัสจากการพยายามช่วยเหลือทหารใหม่คนหนึ่ง ภายหลังแม้จะรอดชีวิตมาได้แต่ก็ต้องทนทุกข์กับอาการบาดเจ็บที่ทำให้ไม่สามารถเคลื่อนไหวได้สะดวก เพื่อที่จะยังคงรับใช้ชาติ เธอจึงไม่ได้ออกจากกองทัพ แต่ถอนตัวจากกองกำลังแนวหน้าและเปลี่ยนไปทำหน้าที่ครูฝึกทหารใหม่\n\nเมื่อเวลาผ่านไป บรรดาทหารใหม่ที่หยิ่งยโสเริ่มไม่พอใจที่ครูฝึกของพวกเขาคือ “คนพิการ” ในกองทัพจึงเริ่มมีเสียงซุบซิบนินทาเกี่ยวกับเธอ\nเมื่อเธอตระหนักถึงเรื่องนี้ เธอพยายามเสนอความคิดเห็นกับทหารใหม่ที่เธอเคยช่วยชีวิตไว้—เขาตอนนี้ได้เลื่อนตำแหน่งเป็นพันโทแล้ว อย่างไรก็ตาม ทหารนายนั้นกลับเยาะเย้ยขาที่บาดเจ็บของเธอเหมือนคนอื่นๆ\nการถูกดูหมิ่นเช่นนั้นทำให้เธอโกรธจนต้องออกจากกองทัพ\nนอกเหนือจากกองทัพและสนามรบ เธอได้เห็นภาพรวมของโลกอย่างแท้จริง: “วีรบุรุษสงคราม” ถูกเพื่อนร่วมชาติทอดทิ้ง และ “การปลดปล่อย” ที่เธอเคยภูมิใจนั้นกลับนำมาซึ่งการล่าอาณานิคมและความทุกข์ยากแก่ประชาชนในท้องถิ่น\nจิตใจของเธอปั่นป่วน หลังจากนั้นเธอได้ทุ่มเทตนเองให้กับการปลดปล่อยที่แท้จริง ความรู้สึกถึงความยุติธรรมและความละอายได้นำทางเธอให้ทำสิ่งที่ “ถูกต้อง” อย่างแท้จริง\nน่าเศร้าที่อาการเน่าเปื่อยที่ขาซึ่งบาดเจ็บนั้นไม่เคยหายสนิท และเธอก็จบชีวิตลงด้วยความทุกข์ทรมานก่อนที่จะสามารถไถ่บาปเสร็จสิ้น\nหลังจากถูกปลุกอีกครั้ง เธอรู้สึกขอบคุณไทอีสเสมอ และพยายามอย่างเต็มที่ที่จะช่วยให้เผ่าอารันดำรงอยู่ต่อไป"
  },
  CollectionHall_57637_LockTip = {
    Text = "ปลุก「เอลวา」แล้วปลดล็อก"
  },
  CollectionHall_57637_Title = {
    Text = "อัลวา"
  },
  CollectionHall_57638_Desc = {
    Text = "<Title:บทนำ>\nเคยเป็นโกเลมแห่งโรมันโบราณ, นักสู้ดาวรุ่ง, นักรบสุดท้ายแต่เพียงผู้เดียว.\nเกิดมาเพื่อปฏิบัติตามเจตนาบ้าคลั่งของจักรพรรดิคาลิกูลา, กำจัดศัตรูทางการเมืองทั้งปวง: ลุง, พี่ชาย, น้องสาว...\nจักรพรรดิผู้ยังเยาว์ทรุดเข่าลงต่อหน้าภูเขาศพของญาติ, ชูแขนขึ้น, ร้องไห้และหัวเราะไปพร้อมกัน.\nอูฟฮาชรู้สึกสับสน: โกเลมสามารถร้องไห้, หัวเราะ, แต่ไม่อาจทำให้หัวเราะไปพร้อมกับน้ำตาอาบหน้าได้.\nต่อมา, จักรพรรดิโหดถูกประหาร. ก่อนการลงโทษ, เขาสวมกอดอูฟฮาช.\nแต่เขาไม่ได้พูดอะไรเลย.\nอาวุธที่สูญเสียเจ้าของได้ระเหเร่ร่อนนับแต่นั้น, จนกระทั่งพบเจ้าใหม่.\nเขายังคงรู้สึกสับสนกับมนุษย์."
  },
  CollectionHall_57638_LockTip = {
    Text = "เพื่อปลดล็อก ผ่านด่านการล่องเรือในจิตสำนึก「เลือดกับทราย」"
  },
  CollectionHall_57638_Title = {
    Text = "อูฟฮาช"
  },
  CollectionHall_57639_Desc = {
    Text = "<Title:ประวัติย่อ>\nได้รับการยกย่องว่าเป็น 「ไข่มุกที่เปล่งประกายที่สุดแห่งลอนดีเนี่ยน」 ทุกคำพูดและการกระทำของเธอได้รับความสนใจจากมหาชนอย่างเต็มที่\nครั้งหนึ่งเคยทำสัญญากับเทพเจ้าที่ชั่วร้ายที่สุด และฟื้นคืนชีพใหม่ด้วย 「ความตาย」 ของตนเอง\nเกี่ยวกับตัวตนที่แท้จริงของเธอ ผู้คนต่างพูดถึงกันไปต่างๆ นานา\nสุภาพสตรีชั้นสูง นางสนม พ่อค้า นักการเมือง ราชินีผู้นำแฟชั่น...\nตัวตนที่แท้จริงของเธอเลือนหายไปแล้ว\nหรือว่าการที่เธอมีหลายแง่มุมเช่นนี้ จะเป็นตัวตนที่แท้จริงของเธอ?"
  },
  CollectionHall_57639_LockTip = {
    Text = "ผ่านด่านภารกิจพิเศษ「คำสรรเสริญกุหลาบ」ปลดล็อก"
  },
  CollectionHall_57639_Title = {
    Text = "โซเรล"
  },
  CollectionHall_57640_Desc = {
    Text = "<Title:บทนำ>\nเคยเป็นคุณหนูแห่งขุนนางโรมันโบราณ บิดาของเธอเป็นเจ้าของสถานที่ฝึกนักสู้\nอาศัยอำนาจจากเหล่านักสู้ทาสที่แข็งแกร่งซึ่งอยู่รายล้อม เธอจึงใช้ชีวิตอย่างโอ้อวดและไม่มีใครกล้าขัดใจในเมืองคาปัว\nแต่ทว่า ความน่าขันก็คือ สุดท้ายเธอกลับต้องขอร้องให้ทาสนักสู้ที่เธอเกลียดที่สุดฆ่าเธอ\nยิ่งไปกว่านั้น เมื่อกลายเป็นร่างกายที่ตื่นขึ้น เธอดันมาพบกับ「ทาสนักสู้」คนนั้นอีกครั้งที่โรงเรียน\nแน่นอนว่า การเผชิญหน้าของพวกเขาจะไม่มีทางเต็มไปด้วยความอบอุ่นแน่นอน"
  },
  CollectionHall_57640_LockTip = {
    Text = "ผ่านด่านการล่องเรือในจิตสำนึก「ทายาทแห่งความซีด」เพื่อปลดล็อก"
  },
  CollectionHall_57640_Title = {
    Text = "อกริปปา"
  },
  CollectionHall_57641_Desc = {
    Text = "<Title:ประวัติย่อ>\nหญิงสาวบนเรือที่ถูกสร้างขึ้นตามประเพณีอันล้าหลังของเหล่ากะลาสี แท้จริงแล้วเป็นเพียงบุตรสาวที่ถูกครอบครัวยากจนขายไป เป็นผู้ปกป้องการเดินเรือที่ถูกมัดไว้กับเสากระโดงเรือวันแล้ววันเล่า\nชีวิตที่ไร้อิสระและทางเลือกทำให้เธอไร้ซึ่งความรู้สึกสุขหรือทุกข์ เกือบจะไร้ซึ่งตัวตน เหลือเพียงเรือลำนี้ที่เป็นที่คุ้นเคยที่สุดสำหรับเธอ\nชีวิตที่ไร้พลังกลับถูกฝากความหวังดีไว้ เธอถูกห้ามพูดคุยกับลูกเรือจนชินกับการเหม่อ ความปรารถนาแรงกล้าและนกทะเลที่โบยบินข้างเสากระโดงสามารถดึงดูดสายตาของเธอได้\nในที่สุด เรือที่เธอปกป้องประสบกับการหลอมกร่อน ส่งผลให้มีผู้บาดเจ็บและเสียชีวิตจำนวนมาก เธอถูกประชาชนที่โกรธแค้นลงโทษด้วยการจมน้ำตาย"
  },
  CollectionHall_57641_LockTip = {
    Text = "ปลดล็อกหลังการปลุก「ฮิลีย์สเตอร์」"
  },
  CollectionHall_57641_Title = {
    Text = "เซเลสเท"
  },
  CollectionHall_57642_Desc = {
    Text = "<Title:บทนำ>\nผู้แกะสลักจากสีไค  \nมีข่าวลือว่าเขาเป็นทายาทของตระกูลชื่อดัง แต่ได้ตัดขาดจากครอบครัวเพื่อไล่ตามความฝันด้านศิลปะและไปยังสีไคเพื่อเรียนรู้ภายใต้ปรมาจารย์ประติมากรรมชื่อดังนามว่าโอกุสต์  \nเขามีพรสวรรค์ที่ทำให้คนสิ้นหวัง แต่ไม่เคยมีแม้แต่คำเดียวในประวัติศาสตร์ศิลปะ  \nหลังจากกลายเป็นร่างกายที่ตื่นขึ้น เขาได้เข้าใจใหม่เกี่ยวกับการปั้นและการแกะสลัก และกลายเป็นที่รู้จักในฐานะ 「ศิลปินบ้าคลั่ง」 \nเขาถือผู้พิทักษ์เป็นแรงบันดาลใจใหม่ และสายตาที่มองผู้พิทักษ์นั้นเต็มไปด้วยความอ่อนโยนแปลกๆ  \nโอ้ นั่นคือสายตาที่ไม่มีสิ่งเจือปนใดๆ สายตาที่พินิจพิเคราะห์วัสดุที่เขารัก"
  },
  CollectionHall_57642_LockTip = {
    Text = "ปลดล็อกหลังจากผ่านด่าน การล่องเรือในจิตสำนึก「การแกะสลักที่งดงามดุจบทเพลง」"
  },
  CollectionHall_57642_Title = {
    Text = "ซังก้า"
  },
  CollectionHall_57643_Desc = {
    Text = "<Title:แนะนำ>\nเคยเป็นสาวใช้ในอาณาจักรอะคีเมนิดโบราณ \nเธอไม่ได้รับเลือกให้ปฏิบัติหน้าที่ในงานเลี้ยงใหญ่แห่งศตวรรษ จึงจมน้ำเพื่อนของเธอในทะเลสาบและสวมรอยแทน \nในที่สุด ในงานเลี้ยงนั้น เธอถูกเปลี่ยนเป็นสัตว์ประหลาดสีเขียวที่น่าเกลียด \nเธอมีความปราดเปรื่องและความคล่องแคล่ว สามารถถือจานได้พร้อมกันสิบใบและเคลื่อนไหวอย่างชำนาญในฝูงชน \nแนวคิดเรื่องอาหารของเธอล้าหลังจากวัฒนธรรมการกินสมัยใหม่อย่างมาก \nบางครั้งเธอก็สงสัยว่าตัวเองกลายเป็นสัตว์ประหลาดเพราะถูกลงโทษจากการฆ่าคน \nแต่เธอก็ไม่เคยเรียนรู้จากความผิดพลาด และจะทำเหมือนไม่มีอะไรเกิดขึ้นในไม่ช้า \nท้ายที่สุดแล้ว สิ่งเดียวที่ชาวเอริวานเรียนรู้จากประวัติศาสตร์ก็คือ: \nชาวเอริวานไม่เคยเรียนรู้จากบทเรียน"
  },
  CollectionHall_57643_LockTip = {
    Text = "ปลุก「คาเรน」แล้วปลดล็อก"
  },
  CollectionHall_57643_Title = {
    Text = "คาเรน"
  },
  CollectionHall_57644_Desc = {
    Text = "<Title:บทนำ>\nผู้คุมเรือนจำซึ่งตั้งอยู่ที่@2 มีความสุขกับการทรมานนักโทษ \nผู้บังคับบัญชาเคยให้คำมั่นกับเธอว่าจะย้ายเธอกลับไปยังลอนดีเนี่ยนในอีกสามปี แต่การแย่ลงของปรากฏการณ์หลอมละลายและการเปลี่ยนแปลงของกระแสพลังงานใต้ดินทำให้เธอถูกลืมไว้บนแผ่นดินไกลโพ้น \nเด็กสาวไม่ท้อแท้ เธอเฝ้ารออยู่ท่ามกลางซากปรักหักพัง โดยหวังว่าจะได้รับการเรียกตัวกลับมาในสักวันหนึ่ง \nจนกระทั่งนักโทษคนสุดท้ายเสียชีวิต เธอจึงกลายเป็นสิ่งมีชีวิตเพียงหนึ่งเดียวบนเกาะแห่งนี้ \nผู้คุมที่ไม่มีนักโทษ กับนักโทษแล้วต่างกันอย่างไร? \nเด็กสาวปฏิเสธที่จะครุ่นคิด เธอยังคงรอคอยวันที่จะถูกเรียกตัวกลับมา"
  },
  CollectionHall_57644_LockTip = {
    Text = "ปลุก「พันเดีย」หลังจากปลดล็อก"
  },
  CollectionHall_57644_Title = {
    Text = "แพนเดีย"
  },
  CollectionHall_57645_Title = {
    Text = "เกินกว่าหมื่นปี"
  },
  CollectionHall_57646_Desc = {
    Text = "<Title:คำอธิบาย>\nสัตว์เลี้ยงที่ฟรานซิสเลี้ยงดูไว้\nเดิมทีเธอคือ「ลิซ่า」เด็กสาวที่มีบุคลิกสดใสถูกเปลี่ยนสภาพให้กลายเป็นร่างผสมระหว่างคนและสัตว์โดยสมาคมนักประติมากรรม ต่อมาถูกลิลลี่รับเลี้ยงและอาศัยอยู่ในโรงพยาบาลบ้าชั่วคราว\nแม้ว่าจะสูญเสียรูปลักษณ์ของมนุษย์และความสามารถในการพูด แต่คูมก็ยังคงเก็บบางส่วนของจิตใจของลิซ่าไว้ได้ และสามารถแสดงเจตนาของตัวเองผ่านการเคลื่อนไหวร่างกายอย่างง่ายๆ\nเธอได้เลือกทางของตัวเองแล้ว"
  },
  CollectionHall_57646_LockTip = {
    Text = "ผ่านด่านการสอบสวนดำเนินการ บทที่ 4 「ในที่เงียบงัน」 เพื่อปลดล็อก"
  },
  CollectionHall_57646_Title = {Text = "คุม"},
  CollectionHall_57647_Desc = {
    Text = "<Title:คำแนะนำ>\nเภสัชกรลึกลับ ปัจจุบันเป็นที่ปรึกษาทางวิทยาศาสตร์ของสมาคมนักประติมากรรม \nมีข่าวลือว่ามารดาของเขาเป็นชาวนาในชนบท และเธอถูกเลือกให้ตั้งครรภ์บุตรของเทพงูกำมะถันผู้ยิ่งใหญ่ \nเขาได้รับโรคแพลงซ์จากมารดาและมีนิสัยอ่อนโยน เป็นเพื่อนคนเดียวที่เฮอร์เบิร์ตไว้วางใจ \nหลงใหลในการศึกษากายวิภาค สารอะโรมาติก และกลิ่นของผลเบลลาดอนนาเมื่อเผาไหม้ \nผลงานมากมาย หนังสือตัวแทนของเขาคือ «บันทึกยา» ซึ่งได้รับการยกย่องว่าเป็นคัมภีร์ไบเบิลแห่งพิษวิทยา \nแช่อยู่ในสารพิษนานาชนิดมาโดยตลอด แม้แต่ลมหายใจที่เขาปล่อยออกมาก็มีพิษร้ายแรง ควรอยู่ห่างจากเขาไว้——นี่คือคำแนะนำเดียวของผู้เขียน"
  },
  CollectionHall_57647_LockTip = {
    Text = "ผ่านด่านการสอบสวนดำเนินการ บทที่ 2 「หุ่นขี้ผึ้ง」เพื่อปลดล็อก"
  },
  CollectionHall_57647_Title = {
    Text = "อัลบิโน"
  },
  CollectionHall_57648_Desc = {
    Text = "<Title:คำแนะนำ>\nนักเรียนของวอลด์ ฟิลิปส์ ผู้พิทักษ์คนแรกของมิซากะ \nอาศัยอยู่ในพื้นที่ลับใต้ดินเป็นเวลานาน มีเพียงไม่กี่คนที่รู้ถึงการมีอยู่ของเขา \nพลังจิตยอดเยี่ยม ตลอดหลายปีที่ผ่านมาได้ใช้วิธีลับเฉพาะเพื่อรักษาชีวิต เพื่อปกป้องความปลอดภัยของมิซากะ \nคาดการณ์ว่าผู้พิทักษ์จะมีบทบาทสำคัญในอนาคต จึงอนุญาตให้ผู้พิทักษ์สามารถติดต่อเขาได้ตลอดเวลา \nทั้งเพื่อฝึกฝนและสังเกต"
  },
  CollectionHall_57648_LockTip = {
    Text = "ผ่านด่านการสอบสวนดำเนินการ บทที่ 2 「หุ่นขี้ผึ้ง」เพื่อปลดล็อก"
  },
  CollectionHall_57648_Title = {
    Text = "อลิสแตร์"
  },
  CollectionHall_57649_Desc = {
    Text = "<Title:คำอธิบาย>\nมนุษย์ที่มีเชื้อสายของผู้เหยียบทะเลอย่างบางเบา เกิดในตระกูลออร์นโบราณ ตระกูลนี้เคยประสบเหตุการณ์ไม่คาดฝัน ส่วนหนึ่งของสมาชิกจะค่อยๆ เปลี่ยนเป็นสัตว์ประหลาดที่มีใบหน้าน่าเกลียดหลังจากโตเป็นผู้ใหญ่ และจบชีวิตลงด้วยความเจ็บปวด บิดาของเขาทนไม่ไหวกับการกลายพันธุ์และฆ่าตัวตายหลังจากเขาเกิดได้ไม่นาน\nเติบโตมาท่ามกลางความเกลียดชังของมารดาและการกลั่นแกล้งของเพื่อนร่วมวัย ทำให้บุคลิกของเขาเปลี่ยนเป็นคนเงียบขรึมและโดดเดี่ยว\nเมื่ออายุสิบหกปี เขาพบข้อความในสมุดบันทึกที่เหลือโดยลุงของเขาซึ่งกล่าวถึงเชื้อสายสูงส่งของตระกูลอย่างคลุมเครือ จากนั้นเขาก็ได้รับชัยชนะทางจิตใจ ฝันว่าจะได้พลังมหาศาลและเห็นการกลั่นแกล้งเป็นบททดสอบของผู้ถูกเลือก รอวันที่พวกเขาจะมาขอความเมตตา\nเมื่อเข้าสู่วัยผู้ใหญ่ เขาหลบเข้าไปในถ้ำเพื่อรอการเปลี่ยนแปลง แต่กลับหยุดอยู่ในรูปร่างครึ่งคนครึ่งปลา ถูกมารดาร้องกรีดร้องไล่ออกและไม่สามารถกลับบ้านได้\nสุดท้ายเขากระโดดลงทะเลเพื่อตามหาชนเผ่า แต่กลับจมน้ำตายเพราะเหงือกที่ยังพัฒนาไม่เต็มที่"
  },
  CollectionHall_57649_LockTip = {
    Text = "ปลุก「เคคอส」แล้วปลดล็อก"
  },
  CollectionHall_57649_Title = {
    Text = "เคคัส"
  },
  CollectionHall_57650_Desc = {
    Text = "<Title:บทนำ>\nมาจากตระกูลคาวенดิชที่เก่าแก่ที่สุดในราชอาณาจักร เธอเคยเป็นไข่มุกในมือของพ่อแม่ แต่โชคร้ายที่ติดเชื้อการหลอมกร่อน\nถูกขังอยู่ใต้ดินเป็นเวลาสามปี ความกระหายนั้นเพิ่มขึ้นทุกวัน\nพี่ชายจึงสั่งให้คนไปหาคนเร่ร่อนและหญิงขายบริการที่พลัดหลงในย่านตะวันออก มาเป็น「อาหาร」ประจำวันของน้องสาว\nทำให้ประชาชนในเมืองต่างหวาดกลัว ตำรวจทั้งกรมต้องออกปฏิบัติการจนสามารถจับพี่น้องคู่นี้ได้ในที่สุด\nนับจากนั้น เหตุการณ์ 「แวมไพร์」 ที่สะเทือนเมืองลอนดีเนี่ยนก็ได้ยุติลงชั่วคราว"
  },
  CollectionHall_57650_LockTip = {
    Text = "ปลุก「เรย่า」หลังจากปลดล็อก"
  },
  CollectionHall_57650_Title = {
    Text = "ลีห์"
  },
  CollectionHall_57651_Desc = {
    Text = "<Title:คำอธิบาย>\nสาวโรงงานทอผ้าจากย่านตะวันออกของลอนดีเนี่ยน\nถูกลักพาตัวโดยสมาคมนักประติมากรรมและถูกทำให้กลายเป็นหุ่นขี้ผึ้งหลังจากติดเชื้อการหลอมกร่อน\n「24」คือหมายเลขการทดลอง และในขณะเดียวกันก็เป็นจำนวนบุคลิกภาพที่ได้รับการวินิจฉัยครั้งแรก\nขณะที่ผู้เขียนบันทึกอยู่นี้ จำนวนบุคลิกภาพของเธอยังคงเพิ่มขึ้นเรื่อยๆ\nในอนาคต อาณาจักรที่ประกอบไปด้วย「24」เหล่านี้จะต้องเจริญรุ่งเรืองและเต็มไปด้วยพลังชีวิตอย่างแน่นอน"
  },
  CollectionHall_57651_LockTip = {
    Text = "ผ่านด่านพิเศษ「การแบ่งเซลล์ที่สงบสัก」ปลดล็อก"
  },
  CollectionHall_57652_Desc = {
    Text = "<Title:ประวัติย่อ>\nเมื่อยังมีชีวิตอยู่ ได้รับการติดเชื้อจากการหลอมกร่อนพร้อมกับบิดา ทนทุกข์ทรมานจากการรักษาอย่างเชื่อฟังท่ามกลางความเจ็บปวดของครอบครัว\nมารดาสูญเสียสามีและลูกสาวพร้อมกันจนนิสัยเปลี่ยนไป ในระหว่างการสำรวจเอลวอส ได้บังเอิญเข้าร่วมพิธีกรรมของโบสถ์แห่งตะเกียง และบังเอิญปลุกลิลลี่ขึ้นมา เนื่องจากการปลุกที่ผิดปกติ ลิลลี่กลายเป็นตุ๊กตาที่ไร้อารมณ์ มีปฏิกิริยาก็ต่อเมื่อได้ยินคำสั่งเท่านั้น\nมารดาลืมภาพลักษณ์ของลิลลี่เนื่องจากการหลอมกร่อน มองว่าลิลลี่ที่ถูกปลุกขึ้นมาเป็นสัตว์ประหลาดและทดลองกับเธอ เพื่อหวังให้ลูกสาวที่แท้จริงฟื้นคืนชีพ\nในที่สุดได้ติดตามผู้พิทักษ์ไปยังมิซากะ เรียกผู้พิทักษ์ว่ามารดา และพึ่งพาผู้พิทักษ์อย่างมาก"
  },
  CollectionHall_57652_LockTip = {
    Text = "ผ่านด่านภารกิจพิเศษ「เรื่องราวของเวทมนตร์」ปลดล็อค"
  },
  CollectionHall_57652_Title = {
    Text = "ลิลลี่"
  },
  CollectionHall_57653_Desc = {
    Text = "<Title:บทนำ>\nตุ๊กตาหุ่นขี้ผึ้งของโรเจอร์ส.\n\nเหมือนกับเด็กๆ ที่ส่งเสียงดังในตู้รถไฟ เป็นพวกที่ถูกตามใจจนเสียคน.\nสิ่งที่พึ่งพาอาศัย ไม่ก็แค่ดวงตาสีเขียวอมเทาคู่นั้น — มันคือสิ่งเดียวที่「นายหุ่นขี้ผึ้ง」ทิ้งไว้ให้โรเจอร์ส.\nเคยเผชิญกับพละกำลังที่ขัดขืนไม่ได้ในโดเมนเทียมของ「24」 กลายเป็นจอร์จแบนราบ และสำเร็จในการจุดชนวนความโกรธของโรเจอร์ส."
  },
  CollectionHall_57653_LockTip = {
    Text = "ผ่านด่านการสอบสวนดำเนินการ บทที่ 2 「หุ่นขี้ผึ้ง」เพื่อปลดล็อก"
  },
  CollectionHall_57653_Title = {
    Text = "จอร์จ"
  },
  CollectionHall_57654_Desc = {
    Text = "<Title:บทนำ>\nเด็กกำพร้าจากสถานสงเคราะห์คนยากจนลิลเลียน และเป็นเพื่อนสนิทที่สุดของเจนกิน.\nเคยถูกสมาคมช่างแกะสลักดัดแปลงร่างกาย และได้เห็นเด็กกำพร้าคนอื่นๆ ตายอย่างน่าสลดต่อหน้าต่อตา จึงรู้สึกผิดอย่างสุดซึ้งที่ตนเองรอดชีวิตและเลือกนิ่งเงียบ.\nในที่สุดได้กระโดดลงจากหอระฆัง เพื่อปลดปล่อยตัวเองอย่างสิ้นเชิง.\nอ้อมแขนมักอุ้มตุ๊กตาหมีไว้เสมอ เธอตั้งชื่อมันว่า「บ็อบบี้」.\nชอบของขวัญ, กระโปรงสวยๆ และลูกอมสีทอง.\nกลัวความมืดนิดหน่อย ต้องอุ้ม「บ็อบบี้」ถึงจะกล้านอนหลับ. หากคุณร้องเพลงกล่อมเปลให้เธอฟัง เด็กหญิงจะรู้สึกขอบคุณและรักคุณตลอดไป.\nเหมือนดังที่เจนกินเคยทำเพื่อเธอมาก่อน."
  },
  CollectionHall_57654_LockTip = {
    Text = "ปลุก「ไอจิส」แล้วปลดล็อก"
  },
  CollectionHall_57654_Title = {
    Text = "ไอจิส"
  },
  CollectionHall_57716_Desc = {
    Text = "<Title:แนะนำ>\nเดิมทีเป็นนักวิจัยที่หมกมุ่นอยู่กับการสร้างหุ่นยนต์อัตโนมัติ ได้รับชิ้นส่วนพลังงานที่มีแกนเงินเป็นแกนกลางจากดาฟเดล\nเนื่องจากเพื่อนนักวิจัยหมายปองชิ้นส่วนพลังงาน ทั้งสองจึงทะเลาะกันหลายครั้ง จนในที่สุดการแย่งชิงอย่างโกรธแค้นจนถึงขั้นตัดขาดกันก็นำไปสู่การระเบิดของห้องปฏิบัติการ ไม่ทราบว่าเพราะเหตุใด เธอตื่นขึ้นมาในร่างของหุ่นยนต์และตระหนักด้วยความหวาดกลัวว่า ในหุ่นยนต์อัตโนมัติที่ไม่ควรมีชีวิตนี้ นอกจากเธอแล้ว ยังมีจิตสำนึกอีกดวงหนึ่งอยู่ด้วย\nเธอช่วยเพื่อนออกมาจากซากปรักหักพังที่กำลังลุกไหม้ด้วยความเชื่อมั่นแบบไหน และเดินทางไปยังชานเมืองด้วยความเชื่อมั่นแบบไหน ไม่มีใครรู้อีกแล้ว อัจฉริยะด้านกลไกที่ไม่มีใครรู้จักผู้นี้หายไปจากโลกนี้ เหลือเพียงข่าวเกี่ยวกับการระเบิด ชิ้นส่วนที่กระจัดกระจายอยู่เต็มพื้น และแกนเงินที่หลงเหลืออยู่เพียงชิ้นเดียว\nสิ่งที่ถูกปลุกขึ้นมาจากสิ่งเหล่านั้น จะเป็นการดำรงอยู่แบบไหนกัน?"
  },
  CollectionHall_57716_LockTip = {
    Text = "ผ่านด่านการล่องเรือในจิตสำนึก「แกนบิดเบือน」ปลดล็อค"
  },
  CollectionHall_57716_Title = {
    Text = "เอริกา"
  },
  CollectionHall_57717_Desc = {
    Text = "<Title:คำแนะนำ>\nผู้ส่งสารและตัวแทนของ@2 มักจะแปลงร่างเป็นมนุษย์เพื่อเดินทางในโลกมนุษย์\nปีศาจที่บริสุทธิ์——ไม่มีอนาคต ไม่มีศรัทธา ไม่มีอุดมการณ์\nใช้ความปรารถนาเป็นเหยื่อล่อ และความวุ่นวายเป็นอาหาร หลงใหลในการหลอกลวงและการล่อลวงมนุษย์\nชำนาญในการเล่นกับกฎ มนุษย์ที่ทำสัญญากับเขาสุดท้ายแล้วจะเสียทุกอย่างจนหมดสิ้น\nทนายความที่ฉลาดที่สุดก็ไม่สามารถได้ประโยชน์แม้แต่น้อยจากเขา\nบางครั้งเขาจะปลอมตัวเป็นเด็ก อย่างไรก็ตาม สิ่งนี้ไม่ได้ทำให้ใครลดความระมัดระวังลง\nเพราะความน่ากลัวของเขาไม่ได้อยู่ที่รูปลักษณ์ภายนอก"
  },
  CollectionHall_57717_LockTip = {
    Text = "ผ่านด่านภารกิจพิเศษ「คำสรรเสริญกุหลาบ」ปลดล็อก"
  },
  CollectionHall_57718_Desc = {
    Text = "<Title:คำแนะนำ>\nจิตแพทย์ผู้เชี่ยวชาญด้านโรคลมชัก โรคฮิสทีเรีย และอาการวิตกกังวลนอนไม่หลับ \nมีความถนัดในการใช้การสะกดจิตเพื่อช่วยให้ผู้ป่วยเปิดเผยความในใจ \nมีข่าวลือว่าผู้ป่วยของเธอจบชีวิตด้วยวิธีการฆ่าตัวตายที่เต็มไปด้วย「ศิลปะ」แต่เธอมักจะเปลี่ยนตัวตนและเปิดคลินิกใหม่ก่อนที่ตำรวจจะมาถึง \nเหล่าคนดังหลายคนเคยเดินทางไปยังคลินิกของเธอ โดยเธอได้รับการกล่าวถึงว่าเป็น「ผู้หญิงที่ครอบครองความลับครึ่งหนึ่งของเมืองลอนดีเนี่ยน」\nโรเจอร์สเคยเป็นลูกค้าระยะยาวของเธอ — บางที แรงบันดาลใจทางศิลปะที่ผิดปกติของเขาอาจเกี่ยวข้องกับจิตแพทย์คนนี้ด้วยหรือไม่?"
  },
  CollectionHall_57718_LockTip = {
    Text = "เพื่อปลดล็อก ผ่านด่านการสอบสวนดำเนินการ บทที่ 1 「เรื่องลับของเขตตะวันออก」"
  },
  CollectionHall_57718_Title = {
    Text = "คลีเมนไทน์"
  },
  CollectionHall_57719_Desc = {
    Text = "<Title:ประวัติย่อ>\nช่างทำหุ่นขี้ผึ้งที่มุ่งมั่นสู่ความเป็นเลิศ ปัจจุบันดำรงตำแหน่งผู้อำนวยการพิพิธภัณฑ์หุ่นขี้ผึ้งโรเจอร์ส \nในวัยเด็กเขาถูกกีดกันเนื่องจากพูดติดอ่าง และเคยถูกล้อว่า 「จนแทบไม่มีอะไรเหลือ」 \nพ่อที่มีตำแหน่งสูง แม่ที่มีปัญหาทางจิตใจ และคดีลักพาตัวที่สะเทือนทั้งประเทศ... \nจากปัจจัยโศกนาฏกรรมทั้งหมดนี้ โรเจอร์สไม่ทำให้ทุกคนผิดหวัง โดยการก้าวข้ามแม่ของเขา กลายเป็นบุคคลที่บ้าที่สุดในสการ์โบโรห์ \nสมาชิกที่ได้รับความนิยมจากสุภาพสตรีมากที่สุดในสมาคมนักประติมากรรม และเป็นสุภาพบุรุษที่มีอารมณ์มั่นคงอย่างยิ่ง——ตราบใดที่ไม่กล่าวถึงศิลปะ"
  },
  CollectionHall_57719_LockTip = {
    Text = "ผ่านด่านการสอบสวนดำเนินการ บทที่ 2 「หุ่นขี้ผึ้ง」เพื่อปลดล็อก"
  },
  CollectionHall_57719_Title = {
    Text = "โรเจอร์ส"
  },
  CollectionHall_57720_Desc = {
    Text = "<Title:ประวัติย่อ>\nแม่เป็นช่างซ่อมเครื่องจักรที่ยอดเยี่ยม ได้รับความนิยมเพราะฝีมือดีและราคาถูก \nเมื่ออายุแปดขวบ พ่อออกไปทะเลแล้วไม่กลับมาอีกเลย จากนั้นเธอก็ใช้ชีวิตพึ่งพากันกับแม่ โดยทำร้านซ่อมเครื่องจักรด้วยกัน ทั้งสองพยายามสร้างรถจักรยานล้อเดียวจากชิ้นส่วนที่สะสมไว้ หวังว่าจะได้ขี่รถผจญภัยด้วยกันในอนาคต เพื่อทำตามความฝันของแม่ในวัยสาว \nเมื่ออายุสิบสามปี แม่เสียชีวิตเพราะป่วย เธอจึงรับงานบนเรือที่ให้ค่าตอบแทนสูงเพื่อให้ได้ชิ้นส่วนเพิ่มเติมมาสร้างรถจักรยานล้อเดียวให้เสร็จ \nขณะที่เรือกำลังเดินทางกลับ เกิดพายุใหญ่และเรือถูกดูดเข้าไปในกระแสน้ำวนอย่างกะทันหัน เธอให้ชุดดำน้ำเพียงชุดเดียวแก่เพื่อนสนิท จากนั้นเธอจับจี้ห้อยรูปหอยสังข์ที่แม่ทิ้งไว้ให้และเสียชีวิตลงในกระแสน้ำที่เต็มไปด้วยการหลอมกร่อน เหลือเพียงซากและเงินใจลอยไปตามกระแสน้ำในมหาสมุทร"
  },
  CollectionHall_57720_LockTip = {
    Text = "ปลุก「นอร์ดิลา」แล้วปลดล็อก"
  },
  CollectionHall_57720_Title = {
    Text = "นอติลา"
  },
  CollectionHall_58148_Desc = {
    Text = "<Title:แนะนำ>\nเจ้าหญิงน้อยที่ถูกเลี้ยงดูโดยมหาปุโรหิตแห่งท้องทะเล อีกนามหนึ่งคือ 「นักบุญหญิง」\nเติบโตมาอย่างทะนุถนอมตั้งแต่เด็ก เป็นสุภาพสตรีอย่างแท้จริง ร่มกันแดดในมือสามารถปกป้องผิวขาวนวลของเธอได้ และยังกันสิ่งสกปรกอัปมงคลทั้งปวงออกไป\nแม้เธอจะรู้ดีว่าตัวเองก็เป็นผลผลิตของ 「สิ่งอัปมงคล」 บางอย่าง——การถือกำเนิดของเธอมิได้เป็นไปตามกฎธรรมชาติ แต่เพื่อจะเป็น 「มารดา」 ให้กำเนิดบุตรแห่งคำทำนาย\nขนมกินไม่หมด ชุดสไตล์ตะวันตกทันสมัยที่สุด บ่าวไพร่นับไม่ถ้วนคอยรับใช้รอบกาย... เธอเวียนวนอยู่ในโลกวัตถุอันวุ่นวาย ปิดกั้นความหวาดหวั่นและความไม่สงบในใจไว้แน่นหนา\nความพยายามนี้จบลงด้วยความล้มเหลวในที่สุด เพราะหัวใจที่เสรีไม่ยอมรับการประนีประนอมใดๆ"
  },
  CollectionHall_58148_LockTip = {
    Text = "ปลุก「มอร์ฟี่」แล้วปลดล็อก"
  },
  CollectionHall_58148_Title = {
    Text = "เมอร์ฟี่"
  },
  CollectionHall_59454_Desc = {
    Text = "<Title:ประวัติย่อ>\nเด็กหญิงจากหมู่บ้านชาวประมงชายฝั่งแห่งหนึ่ง พ่อแม่ของเธอเป็นลูกเรือเดินสมุทร ทำให้เธอเติบโตมาพร้อมกับคุณยายและเชื่อในนิทานที่คุณยายแต่งขึ้นอย่างไร้เดียงสา — ครอบครัวของพวกเธอเป็นลูกหลานแห่งอาณาจักรแอตแลนติส หากเธอเติบโตอย่างเชื่อฟังและมีเพื่อนมากมาย เพื่อนๆ จะช่วยพาเธอกลับไปยังบ้านเกิดใต้ทะเล\nหลังจากคุณยายเสียชีวิต เจ้าของพิพิธภัณฑ์สัตว์น้ำได้มาซื้อปลาและจ้างเธอผู้สดใสและร่าเริงเป็นผู้บรรยาย ทำให้เธอโชคดีที่ได้ใช้ชีวิตวัยเด็กที่เต็มไปด้วยสีสัน\nหลังจากปลาที่ถูกการหลอมกร่อนปนเปื้อนพิพิธภัณฑ์สัตว์น้ำทั้งหมด พิพิธภัณฑ์สัตว์น้ำประกาศล้มละลาย เธอผู้ตกงานนำแมงกะพรุนที่ชอบใส่ขวดแล้วกลับหมู่บ้านห่างไกล แต่ไม่นานการหลอมกร่อนก็เข้าปกคลุมเธอและหมู่บ้านทั้งหมด...\nเมื่อถูกปลุก ความทรงจำของเธอยังเลอะเลือน เชื่อมั่นว่าตัวเองเป็น “มนุษย์ใต้ทะเล” และไม่ลดละที่จะเชิญชวนเพื่อนๆ ไปเยี่ยมชมบ้านเกิดของเธอ"
  },
  CollectionHall_59454_LockTip = {
    Text = "ปลดล็อกหลังจากผ่านด่าน 「ทุกอย่างเป็นปกติ」 ในการล่องเรือในจิตสำนึก"
  },
  CollectionHall_59454_Title = {
    Text = "ออริตา"
  },
  CollectionHall_59455_Desc = {
    Text = "<Title:บทนำ>\nผู้ชายที่ได้รับการยกย่องว่ามี 「โชคดีแท้」.\nการที่มีพรสวรรค์เช่นนี้,      การเป็นนักพนันเป็นเรื่องที่แสนจะธรรมดา.\nแต่เขาก็เป็นนักสืบที่ค่อนข้างยอดเยี่ยมเช่นกัน.\nไม่เพียงแค่นั้น,      เขายังเป็นคนจน,      เพราะเขามักจะหมดทุนแบบรวดเร็วที่สุดเสมอ.\nขัดแย้ง,      ซับซ้อน. นี่คือการประเมินทั้งหมดที่เรามีต่อตัวผู้ชายนี้.\nเทพีแห่งโชคชะตาเอ็นดูเขา,      「N」 ที่มีต้นกำเนิดไม่ชัดเจนเอ็นดูเขา,      แม้แต่เจ้าของบาร์ที่ขี้ลังเลที่สุดก็ยินดีให้ส่วนลดกับเขา.\nทุกคนเอ็นดูเขา,      แต่เขาไม่เคยหยุดย่างก้าว จึงได้เปิดใช้รอบใหม่ในการผจญภัยเกม.\nเขาเพียงแต่เอ็นดูสิ่งที่ไม่รู้จัก."
  },
  CollectionHall_59455_LockTip = {
    Text = "ผ่านด่านพิเศษ「การล่าอย่างสนุกสนาน!」ปลดล็อก"
  },
  CollectionHall_59455_Title = {
    Text = "ไรเกอร์"
  },
  CollectionHall_59456_Desc = {
    Text = "<Title:ประวัติย่อ>\nเกิดในครอบครัวขุนนางที่เสื่อมถอย แม้จะป่วยเป็นโรคหืดเรื้อรังมาตั้งแต่กำเนิด แต่ก็ได้รับความรักและเอาใจใส่อย่างเต็มที่จากพ่อแม่\nเนื่องจากความเจ็บปวดจากโรคทำให้ไม่สามารถออกจากบ้านได้ และมักจะมีความคิดอยากฆ่าตัวตาย พ่อแม่จึงพาเธอออกไปเที่ยวไกลเป็นครั้งแรกเพื่อผ่อนคลายจิตใจ แต่กลับทำให้เธอติดเชื้อการหลอมกร่อนโดยบังเอิญ\nเมื่อกลับถึงบ้าน พ่อแม่ที่เต็มไปด้วยความรู้สึกผิดได้ส่งเธอเข้าสถานพยาบาล โดยออกเดินเรือไปค้าขายเพื่อหาเงินค่ารักษา พร้อมทั้งท่องโลกเพื่อตามหาวิธีการรักษา\nเมื่อการหลอมกร่อนรุกล้ำมากขึ้น ความปรารถนาที่จะตายของเธอก็ยิ่งหนักขึ้น แต่ด้วยความรู้สึกผิดที่เป็นภาระให้พ่อแม่ เธอจึงอดทนต่อความปรารถนาในการแสวงหาความตายและการปลดปล่อย เพื่อไม่ให้พ่อแม่ต้องเสียใจมากกว่านี้\nหลังจากได้รับข่าวว่าพ่อแม่เสียชีวิตระหว่างทางมาเยี่ยมเธอเพราะเรือล่มจมน้ำ เธอซึ่งไม่มีความผูกพันใดๆ ในโลกนี้อีก ก็ได้ลอบออกจากสถานพยาบาลในยามราตรี ก้าวเท้าไปยังทะเลลึกทีละก้าว\nเมื่อน้ำทะเลท่วมถึงกะโหลกศีรษะ หยดของเหลวสีดำจากเครื่องหมายสามเหลี่ยมการหลอมกร่อนถูกชะล้างออกไป ร่างกายที่ป่วยเรื้อรังมาอย่างยาวนานได้รับการปลดปล่อยอย่างยากจะอธิบายได้——นี่เป็นครั้งแรก และครั้งเดียวที่เธอหายใจได้อย่างสะดวก"
  },
  CollectionHall_59456_LockTip = {
    Text = "ปลุก「หนิงเฟย่า」หลังจากปลดล็อก"
  },
  CollectionHall_59456_Title = {
    Text = "นิมเฟีย"
  },
  CollectionHall_61045_LockTip = {
    Text = "ผ่านด่านการสอบสวนดำเนินการ 8-1 เพื่อเปิดใช้งาน"
  },
  CollectionHall_61045_Title = {
    Text = "A Minor: เพลงสุดท้าย"
  },
  CollectionHall_62183_Title = {
    Text = "08 เพลงสุดท้าย"
  },
  CollectionHall_62184_Desc = {
    Text = "<Title:บทนำ>\nวาทยกรและนักดนตรีที่มีชื่อเสียงระดับโลก แม้ว่าจะดูอายุน้อย แต่การแสดงซิมโฟนีที่เขาอำนวยเพลงได้จัดแสดงไปทั่วโลกแล้ว และแต่ละครั้งก็มีผู้คนมากมายจนแน่นขนัด\nในฐานะอัจฉริยะที่มีชื่อเสียงที่สุดในวงการดนตรีคลาสสิก ข้อมูลส่วนตัวใดๆ ของแฮมลินไม่มีใครรู้เลย ซึ่งทำให้คณะกรรมการตรวจสอบเกิดความสนใจ ในการสอบสวนระยะยาว พวกเขาพบว่าสถานที่แสดงของแฮมลินมีความสอดคล้องอย่างมากกับเส้นทางการเคลื่อนไหวของโบสถ์แห่งตะเกียง\nก่อนที่พวกเขาจะค้นพบความจริง ความจริงก็ปรากฏต่อพวกเขาเอง——ในเหตุการณ์ที่โบสถ์แห่งตะเกียงบุกโจมตีเมืองมิซากะ แฮมลินได้แสดงบทบาทสำคัญมาก\nตอนนี้ทุกคนถึงได้เข้าใจว่า แท้จริงแล้วเวทีที่สำคัญที่สุดของวาทยกรผู้เป็นอัจฉริยะคนนี้ ไม่เคยอยู่ภายในโรงละครเลย"
  },
  CollectionHall_62184_LockTip = {
    Text = "ปลดล็อกหลังจากผ่านด่านการสอบสวนดำเนินการ บทที่ 8 「บทเพลงสุดท้าย」"
  },
  CollectionHall_62184_Title = {
    Text = "ฮาเมลน์"
  },
  CollectionHall_65503_Title = {
    Text = "ผู้กลับมาสู่เอลวอส"
  },
  CollectionHall_65509_Desc = {
    Text = "<Title:คำแนะนำ>\nเด็กนักเลงจากเขตตะวันออก รวมถึงเป็นน้องสาวของ「24」\nเธอถนัดทักษะพิเศษสามอย่างคือ ลักเล็กขโมยน้อย ทะเลาะวิวาท และหนีเมื่อเห็นสถานการณ์ไม่ดี\nใครก็ตามจะไม่ได้รับผลประโยชน์ใดๆ จากตัวเธอ\nโอ้ ใช่แล้ว เธอยังมีหนูตัวเล็กชื่อ「บราวน์」ที่อยู่เคียงข้างเสมอ\nบราวน์นั้นสุขุมและใจเย็น ซึ่งตรงข้ามกับบุคลิกของเจนกินเป็นอย่างดี\nดังนั้นแม้ว่าในเขตตะวันออกของลอนดีเนี่ยน จะมีผู้หิวโหยและหนาวเย็นทำอาหารจากหนู แต่เจนกินไม่เคยคิดจะทำเช่นนั้น"
  },
  CollectionHall_65509_LockTip = {
    Text = "ผ่านด่านการสอบสวนดำเนินการ บทที่ 2 「หุ่นขี้ผึ้ง」เพื่อปลดล็อก"
  },
  CollectionHall_65509_Title = {
    Text = "เจนกิน"
  },
  CollectionHall_65602_Title = {
    Text = "ขอให้ล่าสนุก"
  },
  CollectionHall_67375_Title = {
    Text = "09 เมื่อความฝันอันยาวนานสิ้นสุดลง"
  },
  CollectionHall_70283_LockTip = {
    Text = "ผ่านด่านการสอบสวนดำเนินการ 9-13 เพื่อเปิดใช้งาน"
  },
  CollectionHall_70283_Title = {
    Text = "จากความลืม  <▼>"
  },
  CollectionHall_70542_LockTip = {
    Text = "ต้องผ่านด่านกิจกรรมของตัวละครจำกัดเวลา「การฟื้นคืนชีพของเทพเจ้า：สายตาจากทะเลลึก」หนึ่งด่านใดก็ได้"
  },
  CollectionHall_70542_Title = {
    Text = "การฟื้นคืนชีพของเทพเจ้า：การจ้องมองแห่งทะเลลึก"
  },
  CollectionHall_70543_LockTip = {
    Text = "ต้องผ่านด่านกิจกรรมของตัวละครแบบจำกัดเวลา「คลื่นแห่งกิเลส：ความปรารถนาที่ปั่นป่วน」อย่างน้อยหนึ่งด่านใดก็ได้"
  },
  CollectionHall_70543_Title = {
    Text = "คลื่นแห่งกิเลส：ความปรารถนาที่ปั่นป่วน"
  },
