  CollectionHall_70555_Title = {
    Text = "ก่อนที่ฤดูใบไม้ผลิจะร่วงโรย：เรื่องราวในอดีตของสวน"
  },
  CollectionHall_70839_Desc = {
    Text = "<Title:คำอธิบาย>\nประจบสอพลอ โลภ ปลอมแปลง ผู้อำนวยการสถานรับเลี้ยงเด็กกำพร้าลิลลี่เหมือนนักแสดงที่ไม่เก่งกาจ แสดงเป็นขอทานต้อยต่ำในสนามชื่อเสียงของลอนดีเนี่ยน\nเธอวิ่งเต้นไปทั่ว ใช้คำเยินยอที่ดูโง่เขลาเพื่อขอเศษเงินจากซอกนิ้วของเหล่าคนดัง มาใช้ในการดำเนินงานที่ลำบากของสถานรับเลี้ยงเด็กกำพร้า เธอรับความเยาะเย้ยและคำด่าไว้คนเดียว และใช้เสียงเพลงอ่อนโยนกล่อมเด็กๆ ในสถานรับเลี้ยงให้หลับ\nลอนดีเนี่ยนทอดทิ้งพวกเขา แต่สถานรับเลี้ยงเด็กกำพร้าลิลลี่ไม่เคยทำเช่นนั้น ซาร่าเตรียมพร้อมแล้วที่จะทำทุกอย่างเท่าที่สามารถเพื่อปกป้องเด็กๆ เหล่านี้ ให้พวกเขาสามารถมีชีวิตรอดอย่างราบรื่นท่ามกลางหมอกและลมหนาวของลอนดีเนี่ยน\nแต่อุดมคติอันต้อยต่ำของเธอล้มเหลว เธอและเด็กๆ ต้องตายในแผนการร้ายของสมาคมนักประติมากรรม สำหรับสมาคมนักประติมากรรมแล้ว เธอและเด็กๆ ที่เธอรักนั้นเป็นเพียงเม็ดทรายเล็กๆ ในอาคารใหญ่โต ที่ขาดคุณค่าและปราศจากความงาม การมีชีวิตของพวกเขาไม่มีความสำคัญ และการตายของพวกเขาก็ไม่ควรค่าแก่การเอ่ยถึง\nเธอได้เผาผลาญทุกอย่างของตัวเองจนหมดสิ้น แสงไฟนั้นดับลงอย่างรวดเร็ว เหลือเพียงแค่ลมหนาวของลอนดีเนี่ยนที่ยังคงเย็นยะเยือก"
  },
  CollectionHall_70839_LockTip = {
    Text = "ผ่านด่านบทที่ 1 เพื่อปลดล็อก"
  },
  CollectionHall_70839_Title = {Text = "Sarah"},
  CollectionHall_70884_Desc = {
    Text = "<Title:ภาพรวมกิจกรรม A.F.185>\nตัวแทนจากประเทศต่างๆ ได้ลงนามในข้อตกลงมิสดิเทียที่สหพันธ์คงที่ ตัดสินใจร่วมมือกันต่อสู้กับเผ่าพันธุ์และบดบังการย่อยสลาย พร้อมกันนั้นแต่ละประเทศได้บรรลุข้อตกลงเกี่ยวกับแนวทางการรักษาความลับเกี่ยวกับการมีอยู่ของเผ่าพันธุ์และการปกปิดปรากฏการณ์การย่อยสลาย\nข้อตกลงในครั้งนี้กำหนดว่า วิทยาลัยจะยังคงมีอิสระ ไม่อยู่ภายใต้ประเทศใดประเทศหนึ่ง มีสิทธิ์ในการจัดตั้งสำนักงานประจำในแต่ละประเทศ มีสิทธิ์ในการติดต่อสื่อสารโดยตรงกับผู้นำของแต่ละประเทศ และมีสิทธิ์ในการเข้าถึงข้อมูลเกี่ยวกับเผ่าพันธุ์และการย่อยสลายของแต่ละประเทศ\nมหาวิทยาลัยมีธากจึงกลายเป็นองค์กรระหว่างประเทศที่เป็นกลางอย่างสมบูรณ์\n\n<Title:ภาพรวมกิจกรรม A.F.186>\nบุคคลที่เข้าร่วมในการแก้ไขและลงนามข้อตกลงได้ทำการตั้งคณะกรรมการประจำที่มิสดิเทีย โดยคณะกรรมการนี้มีทีมปฏิบัติการของตนเอง เพื่อรับประกันการบังคับใช้ข้อตกลง การประชุมลับได้ถูกจัดตั้งขึ้น และโครงสร้างขององค์กรก็ได้ถูกกำหนดขึ้น\n\n<Title:ภาพรวมกิจกรรม A.F.187>\nวิทยาลัยมีธากได้เปลี่ยนชื่ออย่างเป็นทางการเป็นมหาวิทยาลัยมีธาก\nในระยะเวลาต่อมา ปรากฏการณ์การย่อยสลายเกิดขึ้นบ่อยครั้งมากขึ้นและมีขนาดใหญ่ขึ้นเรื่อยๆ มหาวิทยาลัยมีธากยืนอยู่แนวหน้า กลายเป็นเสาหลักในการต่อต้านการย่อยสลายของมนุษย์"
  },
  CollectionHall_70884_LockTip = {
    Text = "ผ่านด่านการสอบสวนดำเนินการ 9-13 เพื่อเปิดใช้งาน"
  },
  CollectionHall_70885_Desc = {
    Text = "<Title:A. F. 75>\nอลิสแตร์ทำนายถึงการเกิดรอยแตกขนาดใหญ่ในอาณาจักรลีโอ วาร์ดนำทีมสืบสวนไปจัดการกับเหตุการณ์นี้ มีการสละชีพมากมายในเหตุการณ์นี้.\n\n<Title:A. F. 77>\nรอยแตกไม่สามารถปิดได้ แต่เริ่มมีเสถียรภาพมากขึ้น ด้วยความร่วมมือและการสนับสนุนจากรัฐบาล วาร์ดได้สร้างฐานที่ตั้งของ 「มุมมองแห่งความจริง」 ขึ้นเหนือรอยแตกขนาดใหญ่.\nรอยแตกขนาดใหญ่ได้รับหมายเลขอย่างเป็นทางการ L-01 และชื่อเรียกอีกอย่างว่า 「สระดำ」.\n\n<Title:A. F. 88>\n「สระดำ」 เกิดความผิดปกติและขยายตัวออกไป ในขณะนี้ 「มุมมองแห่งความจริง」 ที่อยู่ในบริเวณรอบด้านได้รับความเสียหายอย่างหนัก วาร์ดยังได้รับบาดเจ็บระหว่างการจัดการ.\nเนื่องจากไม่สามารถปิดสระดำได้ ทาวิลจึงตกลงไปในนั้นเพื่อรักษาความสงบเรียบร้อย ทำให้สระดำมีเสถียรภาพชั่วคราว.\n\n<Title:A. F. 90>\nการขยายฐานที่ตั้งของ 「มุมมองแห่งความจริง」 และการก่อตั้งวิทยาลัยมีธากขึ้น โดยวาร์ดเป็นผู้อำนวยการคนแรก.\nตั้งแต่นั้นมา ผู้คนเริ่มฝึกอบรมเจ้าหน้าที่สืบสวนที่มีพลังจิตวิญญาณเพียงพออย่างเป็นระบบ เพื่อที่จะต่อสู้กับวิกฤติการย่อยสลายที่ทวีความรุนแรงขึ้น.\n\n<Title:A. F. 92>\nการบาดเจ็บของวาร์ดจากเหตุการณ์สระดำแย่ลง และเขาได้เสียชีวิตในที่สุด.\nร่างของวาร์ดถูกฝังอยู่ในวิทยาลัย โดยทำหลุมศพให้เป็นรูปกุญแจซึ่งเปิดตำนานของกุญแจใหญ่.\nซิลเวอร์เซนที่ถูกสร้างขึ้นหลังเสียชีวิตได้รับการทำกุญแจเงินโดยอลิสแตร์เอง โดยระบุหมายเลข K-0001 และจากนั้นอลิสแตร์ได้กลายเป็นผู้พิทักษ์รุ่นแรกที่มีบทบาทโดดเด่นในภายนอก.\nในปีเดียวกัน เคลาลร์คชซึ่งไปสืบสวนที่เลมวาชีเพื่อหาวิธีการรักษาวาร์ดได้หายสาบสูญ ตั้งแต่นั้นมาผู้คนก็ไม่ทราบเรื่องราวของเขา."
  },
  CollectionHall_70885_LockTip = {
    Text = "ผ่านด่านการสอบสวนดำเนินการ 9-13 เพื่อเปิดใช้งาน"
  },
  CollectionHall_70886_Desc = {
    Text = "<Title:A.F.306>\nเฮอร์เบิร์ตได้รับเงินทุนจากมูลนิธิกรีน โดยความช่วยเหลือจากโบสถ์แสงศักดิ์สิทธิ์ เขาจึงก่อตั้งสมาคมประติมากร\nในปีนั้น ดอลล์เข้าเรียนที่มหาวิทยาลัยมีธาก ในฐานะนักวิชาการอัจฉริยะ ดอลล์ได้เข้าร่วมการวิจัยของนักศึกษาระดับบัณฑิตและปริญญาเอกทันที และในวันต่อมาได้ผลักดันการพัฒนาเทคโนโลยีเศษเงินที่มีธากอย่างมาก\n\n<Title:A.F.307>\nเฮอร์เบิร์ตร่วมมือกับโบสถ์แสงศักดิ์สิทธิ์โจมตีที่มีธาก เพื่อตามหาสาวพรหมจรรย์ที่ถูกเปลี่ยนตัวไปในขณะนั้น\n\n<Title:A.F.309>\nผู้รอดชีวิตจากเหตุการณ์การย่อยสลาย วิลเลียมเข้าร่วมที่มีธากตามคำแนะนำของนักสืบฟินโกล\n\n<Title:A.F.310>\nคณะกรรมการตรวจสอบร่วมของมหาวิทยาลัยมีธากจับกุมสมาชิกส่วนใหญ่ของสมาคมประติมากร ก่อนที่มันจะขยายใหญ่ขึ้น เฮอร์เบิร์ตและสมาชิกหลักหลายคนหลบหนีไปและออกไปทำงานในที่มืด ต่อมา เฮอร์เบิร์ตได้ติดต่อโรเจอร์สเพื่อเริ่มการทำงานร่วมกัน\nในปีนั้น ซัลวาดอร์ได้รับตำแหน่งบิชอปของเขตใหญ่ศักดิ์สิทธิ์ และชอร์ทได้รับตำแหน่งรักษาการอธิการ\n\n<Title:A.F.313>\nตามคำสั่งของเฮอร์เบิร์ต โรเจอร์สได้บริจาคเงินให้กับบ้านพักคนไร้บ้านลิเลียน โดยกลายเป็นผู้สนับสนุนเพียงคนเดียว\n\n<Title:A.F.314>\nระเบิดครั้งใหญ่ที่อคุทเกิดขึ้น\nโดยการมอบหมายของอลิสแตร์ วิลเลียมและราโมน่าได้เดินทางไปยังอคุท และพบ @3 ที่สูญเสียความทรงจำทั้งหมดในซากปรักหักพังจากการระเบิด นำมันกลับไปยังมีธากเพื่อการฝึกอบรมพิเศษ"
  },
  CollectionHall_70886_LockTip = {
    Text = "ผ่านด่านการสอบสวนดำเนินการ 9-13 เพื่อเปิดใช้งาน"
  },
  CollectionHall_70887_Desc = {
    Text = "<Title:ภาพรวมกิจกรรม A. F. 263>\nฟรานซิสเกิดขึ้น\n\n<Title:ภาพรวมกิจกรรม A. F. 289>\nหลังจากสูญเสียลูกสาว ฟรานซิสเข้าร่วมทีมสำรวจไปยังเอลวอส\nในปีเดียวกัน ทีมสำรวจทั้งหมดเสียชีวิต\n\n<Title:ภาพรวมกิจกรรม A. F. 290>\nโรเจอร์สเกิดขึ้น\nในปีเดียวกัน ฟรานซิสได้อัญเชิญลิลลี่ขึ้นมาในเอลวอส และไปยังลาย โดยมีความช่วยเหลือจากมูลนิธิ เขาได้จัดตั้งโรงพยาบาลจิตเวชและสร้างเวลาที่หยุดนิ่งขึ้น\n\n<Title:ภาพรวมกิจกรรม A. F. 292>\nดอลล์เกิดขึ้น\n\n<Title:ภาพรวมกิจกรรม A. F. 297>\nเฮอร์เบิร์ตเป็นนักศึกษาใหม่เข้าเรียนที่มีธาก โดยมีอายุ 17 ปี\n\n<Title:ภาพรวมกิจกรรม A. F. 298>\nเทียนใช้บุตรอันเป็นคู่แฝดเพื่อทำพิธีอัญเชิญเทพเจ้า เด็กซ์เตอร์แทรกซึมเข้าไปในพิธี และลักพาลาโมนา ซึ่งกำลังจะถูกใช้เป็นร่างของเทพมาออกไปได้ ส่งผลให้พิธีล้มเหลว\nลามอนน่าได้กลายเป็นลูกสาวบุญธรรมของเด็กซ์เตอร์\n\n<Title:ภาพรวมกิจกรรม A. F. 300>\nโรเจอร์สถูก 「ประติมากรรมขี้ผึ้ง」 ลักพาตัวไป หลังจากนั้น 「ประติมากรรมขี้ผึ้ง」 เสียชีวิต โรเจอร์สได้รับการช่วยเหลือ\nในปีเดียวกัน ซัลวาดอร์ถูกปลุกขึ้นจากบิชอปประจำโบสถ์ใหญ่ในตอนนั้น ในฐานะผู้ช่วยบาทหลวงให้บริการอยู่ที่โบสถ์ใหญ่\n\n<Title:ภาพรวมกิจกรรม A. F. 304>\nชอร์ทเข้าเรียนที่มีธากในฐานะนักศึกษาใหม่\n\n<Title:ภาพรวมกิจกรรม A. F. 305>\nมหาวิทยาลัยมีธากมีการปลุกตื่นนักเรียนเฮอร์เบิร์ต เพื่อสร้างร่างทดลองอย่างผิดกฎ เมื่อความประพฤติของเขาถูกเปิดเผย เขาได้ฆ่าอาจารย์ของตนคือคลอว์ลี่และหนีไป เมื่ออายุ 25 ปี"
  },
  CollectionHall_70887_LockTip = {
    Text = "ผ่านด่านการสอบสวนดำเนินการ 9-13 เพื่อเปิดใช้งาน"
  },
  CollectionHall_70888_Desc = {
    Text = "<Title:B.F.？？？>\nภัยพิบัติที่เกิดขึ้นทั่วโลกได้ทำลายพื้นที่ขนาดใหญ่ น้ำท่วม แผ่นดินไหว ความผิดปกติของสนามแม่เหล็ก สภาพอากาศที่แปลกประหลาดทำให้เมืองและหมู่บ้านจมอยู่ใต้น้ำ และหินแข็งที่เคยฝังอยู่ใต้ทะเลกลับกลายเป็นยอดเขาใหม่ มนุษย์ชาติเสียหายอย่างหนัก\n\n<Title:A.F.0>\nแผ่นดินเก่าได้รับการจมลงด้วยน้ำทะเลและแผ่นดินใหม่ได้ผุดขึ้นมาจากผิวน้ำ\nในโลกที่เปลี่ยนแปลงอย่างสิ้นเชิงนี้ ผู้คนได้ละทิ้งปฏิทินเดิม และต่อสู้ดิ้นรนเพื่อสร้างใหม่ด้วยซากของอารยธรรม ก้าวเข้าสู่ยุคใหม่: ยุคอุทกภัย"
  },
  CollectionHall_70888_LockTip = {
    Text = "ผ่านด่านการสอบสวนดำเนินการ 9-13 เพื่อเปิดใช้งาน"
  },
  CollectionHall_70888_Title = {
    Text = "B.F.???—A.F.0"
  },
  CollectionHall_70889_Desc = {
    Text = "<Title:A.F.55>\nเคลาร์เคชใช้การสืบสวนของตนเองเป็นช่องทางในการค้นหาสมาคมลับกุญแจเงินด้วยตนเอง และเข้าร่วมได้สำเร็จ โดยหวังจะอาศัยพลังของสมาคมลับเพื่อช่วยมนุษยชาติฟื้นฟูขึ้นใหม่\nในปีเดียวกัน เคลาร์เคชสังเกตเห็นการเคลื่อนไหวของฮวาร์ดและทาวี จึงเริ่มจับตาดูความเคลื่อนไหวของพวกเขา\n\n<Title:A.F.58>\nเคลาร์เคชสร้างกุญแจเงินแบบใช้ครั้งเดียวขึ้นมาได้ ก้าวขึ้นเป็นผู้นำสมาคมลับคนใหม่ในตำแหน่ง \"ช่างกุญแจ\" และเริ่มใช้สมาคมลับเผยแพร่ความรู้ออกไปอย่างลับๆ เพื่อช่วยมนุษยชาติฟื้นฟู\nในปีเดียวกัน เคลาร์เคชติดต่อกับฮวาร์ดและทาวี โดยสัญญาว่าจะให้ความช่วยเหลือด้านเงินทุนและกำลังคนแก่ฮวาร์ด\n\n<Title:A.F.62>\nอลิสแตร์ · โอเวนส์ เกิดในครอบครัวแพทย์ชนบทธรรมดาแห่งชานเมืองลอนดิเนียน\n\n<Title:A.F.64>\nเคลาร์เคชที่สืบสวนเสร็จสิ้นแล้วยอมรับในอุดมการณ์ของฮวาร์ด เมื่อเผชิญกับฮวาร์ดที่ไม่ยอมถูกผูกมัดด้วยกฎของสมาคมลับ ทั้งสองฝ่ายจึงบรรลุความสัมพันธ์ร่วมมืออย่างเท่าเทียมภายใต้คำแนะนำและการเป็นสักขีพยานของทาวี\nหลังได้รับความช่วยเหลือด้านเงินทุนและกำลังคนจากสมาคมลับ การวิจัยของฮวาร์ดก้าวหน้ายิ่งขึ้น ยืนยันลักษณะเฉพาะของการกัดกร่อน ความสัมพันธ์ระหว่างการกัดกร่อนกับสิ่งกลายพันธุ์ และสรุปลักษณะเฉพาะของแต่ละระยะการรุกรานของการกัดกร่อนเบื้องต้น\n\n<Title:A.F.65>\nเคลาร์เคช ฮวาร์ด ทาวี พร้อมด้วยสมาชิกสมาคมลับหลายคน ร่วมกันจัดตั้งหน่วยสืบสวนชุดแรกที่มีภารกิจในการติดตามการกัดกร่อนและป้องกันการแพร่กระจายของมัน โดยตั้งชื่อว่า \"สายตาแห่งสัจธรรม\"\n\n<Title:A.F.70>\nฮวาร์ดสรุปลักษณะเฉพาะและกฎเกณฑ์ของการกัดกร่อนและการรุกรานของมันอีกครั้ง บันทึกลักษณะเฉพาะเชิงพื้นที่ของการกัดกร่อนเป็นครั้งแรก และเขียนเป็น《การศึกษาเบื้องต้นว่าด้วยการกัดกร่อนและกฎเกณฑ์ของมัน》เพื่อให้สมาชิกใหม่ที่เข้าร่วมหน่วยสืบสวนใช้อ่านศึกษา\n\n<Title:A.F.72>\nฮวาร์ดช่วยอลิสแตร์จากครอบครัวที่ล่มสลายเพราะการกัดกร่อน และรับเขาเป็นลูกศิษย์\nในปีเดียวกัน ฮวาร์ดและหน่วย \"สายตาแห่งสัจธรรม\" ภายใต้การนำของเขาขยายขนาดขึ้นเรื่อยๆ จนดึงดูดความสนใจจากทางการ"
  },
  CollectionHall_70889_LockTip = {
    Text = "ผ่านด่านการสอบสวนดำเนินการ 9-13 เพื่อเปิดใช้งาน"
  },
  CollectionHall_70890_Desc = {
    Text = "<Title:A. F. 30>\nวอร์ด ฟิลิปส์เกิดในครอบครัวเศรษฐีที่เมืองชาลอมทางตะวันออกของสาธารณรัฐแอกโล\n\n<Title:A. F. 38>\nเคลาร์คล์ชเกิดขึ้น พ่อแม่ของเขาเสียชีวิตไม่นานหลังจากที่เขาเกิด และเขาต้องอยู่กับพี่สาวเพื่อเอาตัวรอด\n\n<Title:A. F. 48>\nวอร์ดแสดงให้เห็นถึงพรสวรรค์ในด้านเคมีและฟิสิกส์ตั้งแต่อายุยังน้อย เขาสอบเข้าคณะเคมีที่มหาวิทยาลัยรัฐโมสเวตูเซในอายุ 18 ปี โดยเป็นนักเรียนของนักเคมีชื่อดัง นาธานีล มิลตัน\n\n<Title:A. F. 50>\nคุณปู่ โรเจอร์ ฟิลิปส์ผู้เป็นพระคุณเสียชีวิต และต่อมา พ่อของเขาหายไป วอร์ดไปสอบสวนที่บ้านของตาและตามรอยการที่พ่อของเขาไปที่อาณาจักรลีโอ ในที่นั้นเขาได้ค้นพบความลับที่ซ่อนอยู่มานานของครอบครัว นั่นคือสูตรลับที่ได้มาจากผู้ที่นับถือศาสนานอกรีต(กุญแจเงิน) ในช่วงยุคตามล่าพ่อมด\nสูตรโบราณถูกบันทึกอยู่ในแผ่นหนังแกะ แต่มีหลายส่วนที่เสียหาย วอร์ดใช้เวลาหลายปีในการทดลองและสามารถเติมเต็มมันได้\n\n<Title:A. F. 53>\nจากสูตรที่เติมเต็ม วอร์ดประสบความสำเร็จในการสร้างกุญแจเงินใบแรก เนื่องจากข้อบกพร่องในสูตร กุญแจเงินนี้จึงเสียหายเมื่อใช้ครั้งเดียวและไม่สามารถใช้ซ้ำได้\nไม่ว่าจะอย่างไรก็ตาม ด้วยกุญแจเงินแบบใช้ครั้งเดียวนี้ วอร์ดได้พบกับตัวแทนแห่งปัญญา ทาวิล และได้ทราบว่าโลกกำลังเผชิญกับ 「ภัยพิบัติสีดำ」 ที่ใกล้จะมาถึง\nเพื่อป้องกันภัยพิบัติ วอร์ดตกลงกับทาวิลและทำการเชื่อมโยงกับทาวิลเพื่อรับวิธีการทำผู้ปลุกตื่นและสูตรกุญแจเงินที่สมบูรณ์\nในเวลาถัดมา วอร์ดได้เดินทางไปมา ศึกษาการย่อยสลายและรอยแตก และตั้งชื่อมัน โดยพยายามหาวิธีที่จะต่อต้านการย่อยสลาย."
  },
  CollectionHall_70890_LockTip = {
    Text = "ผ่านด่านการสอบสวนดำเนินการ 9-13 เพื่อเปิดใช้งาน"
  },
  CollectionHall_70891_Desc = {
    Text = "หลังจากเสร็จสิ้นการเรียนและการฝึกอบรมในระดับเตรียมความพร้อมเป็นเวลาหนึ่งปี @3 ได้ขึ้นดำรงตำแหน่งผู้พิทักษ์อย่างเป็นทางการ และเริ่มนำร่างกายที่ตื่นขึ้นและพละกำลังอื่นๆ ในโรงเรียนเพื่อดำเนินการสอบสวนเหตุการณ์ที่เกี่ยวข้องกับการหลอมกร่อน \n ในปีเดียวกันนั้น โบสถ์แห่งตะเกียงร่วมมือกับสายลับภายในโรงเรียนมิซากะบุกโจมตีมิซากะอีกครั้ง ส่งผลให้เกิดความวุ่นวายในสระดำ เปิดประตูสู่ความสิ้นหวัง และดึงดูดความสนใจของเจตจำนงสูงสุด \n ในขณะที่คาดัสกำลังจะถูกกลืนกินโดยการหลอมกร่อน @3 ได้ดูดซึมอำนาจของสามโครงสร้าง จากนั้นเผชิญหน้ากับสายตาของเจตจำนงสูงสุดภายในประตู \n ในที่สุด เจตจำนงสูงสุดได้กลับไปสู่การหลับใหลอีกครั้ง และคาดัสก็รอดพ้นจากการทำลายล้าง \n @3 สละชีวิตตนเอง \n เนื่องจากบันทึกทั้งหมดที่เกี่ยวข้องกับเขาหรือเธอจะถูกหลอมกร่อนและไม่สามารถเก็บรักษาไว้ได้ มิซากะจึงตัดสินใจฝ่าฝืนกฎโดยเก็บกุญแจเงินที่เขาหรือเธอใช้ในชีวิตไว้ในพิพิธภัณฑ์ประวัติศาสตร์ของโรงเรียน เพื่อรำลึกถึงผลงานของพวกเขา \n ไม่มีใครทราบชื่อของ%hisorher% แต่หมายเลข K-0617 จะคงอยู่ตลอดไป"
  },
