  },
  CollectionHall_71011_Title = {
    Text = "ฝนตกที่สุสานแห่งกุญแจ"
  },
  CollectionHall_71012_Desc = {
    Text = "เหตุผลและหวังของการคงอยู่ สถิตอยู่ในแสงวาบของกุญแจเงิน \n ผู้สืบทอดได้จารึกหลักฐานในขณะนี้ และผู้แสวงหาได้สาบานกันที่นี่แล้ว"
