  CollectionHall_89415_Desc = {
    Text = "ไม่ต้องพูดมาก เมื่อคุณมาที่นี่ คุณจะได้รับความช่วยเหลืออันจริงใจที่สุด.\nคนนำทางผู้ยิ้มแย้มได้ยื่นมือออกมาเพื่อคุณ เธอจะพาคุณเข้าไปในที่ที่คุณไม่เคยเห็นและลึกเข้าไปในห้วงจิตใจของคุณ."
