  CollectionHall_89419_Desc = {
    Text = "กระแสน้ำระยิบระยับถักร่วมกันเป็นม่านภายใต้แรงจูงใจจากท้องฟ้า ชายพื้นเมืองมาถึงทางทะเลátuเขตแดน"
