  },
  CollectionHall_89420_Desc = {
    Text = "ท่านกษัตริย์เป็นสูงสุด ท่านกษัตริย์มีอำนาจไม่มีขอบ ท่านกษัตริย์นั่งอยู่สูงสำหรับทรรศนียภาพที่โดดเด่นทุกอย่างที่มองลงไปด้วยความเหงาในอาณาจักรของเขา"
