  CollectionHall_89420_Title = {
    Text = "หลับใหลในเหวลึกของกษัตริย์"
  },
  CollectionHall_89706_Desc = {
    Text = "<Title:ภาพรวม>\nเด็กกำพร้า มีที่มาที่ไม่ทราบ ตั้งแต่เริ่มมีความทรงจำก็ถูกสมาชิกทีมเก็บไปอยู่ด้วย อยู่บนเรือ\nเพราะประสบการณ์นี้ คาปัสเซนต์จึงเติบโตขึ้นมาพร้อมกับความปรารถนาและความอยากรู้อยากเห็นในมหาสมุทร.\nเมื่อเธอโตขึ้น จะเลือกทำอาชีพที่เกี่ยวข้องกับมหาสมุทรและเรือ—ผู้ควบคุมทิศทาง\nตั้งแต่นั้นมา สาวน้อยที่รักมหาสมุทรก็ล่องเรือไปตลอดกาล เธอจะนำทางเรือภายใต้แสงดาว\nเธอเกิดมาในมหาสมุทร และอยู่ในเรือ「เกิดมา」\nเธอไม่หวาดกลัวที่จะ「ตาย」ในมหาสมุทร และในเรือ\nนี่คือชีวิตของเธอ"
  },
  CollectionHall_89706_LockTip = {
    Text = "การตื่น「คลอปเพอแซนท์」จะปลดล็อก"
  },
  CollectionHall_89706_Title = {
    Text = "คอร์โปซานต์"
  },
  CollectionHall_89968_Desc = {
    Text = "การฆ่า ความเกลียดชัง ความบ้าคลั่งและความเจ็บปวด ทุ่งรบไม่เคยขาดสิ่งเหล่านี้ เมื่อคุณเดิมพันชีวิตของคุณบนโต๊ะเล่นไพ่ของมอนสเตอร์ คุณควรคิดถึงความวุ่นวายสีแดงที่จะเกิดขึ้นอย่างไร."
  },
  CollectionHall_89968_LockTip = {
    Text = "ผ่านการล่องเรือในจิตสำนึก「เลือดและทราย」"
  },
  CollectionHall_89968_Title = {
    Text = "สุญญากาศสีแดง"
  },
  CollectionHall_89969_Desc = {
    Text = "ตามตำนานกล่าวว่า ผู้นำทางจะกลายเป็นแสงสีกระดาษฟ้าและขาวที่ยอดเสาต่อจากการตาย และยังคงชี้นำการเดินเรือของเรือ.\nดังนั้นเมื่อเธอจุดไฟชีวีตนที่ยอดเสา เธอเห็นเส้นทางแห่งความหวังนั้นหรือไม่?"
  },
  CollectionHall_89969_LockTip = {
    Text = "บรรลุการเดินทางด้วยความตระหนักใน「การนำทางสุดท้าย」"
  },
  CollectionHall_89969_Title = {
    Text = "ไฟแห่งเซนต์แอลโม"
  },
  CollectionHall_89970_Desc = {
    Text = "ชะตาชีวิตที่เธอเกิดมาก็เต็มไปด้วยความเกลียดกาจ การฆ่า และการต่อสู้ที่ไม่สิ้นสุด\nเมื่อเธอทิ้งทุกสิ่งที่อบอุ่นและเลือกที่จะถือมีดและปืน เพลงแซวแห่งชะตากรรมก็เริ่มบรรเลงเพื่อเธอ\nเธอถูกกำหนดให้เป็นนักรบ ใช้เลือดของศัตรูทำความสะอาดความเกลียดชัง และใช้ชีวิตที่ไม่มีเกียรติแต่ไม่มีความกลัวและไม่สำนึกเสีย"
  },
  CollectionHall_89970_LockTip = {
    Text = "ทำภารกิจ「เอลวอสผู้กลับมา」สำเร็จ"
  },
  CollectionHall_89970_Title = {
    Text = "ใช้เลือดชำระแค้น"
  },
  CollectionHall_89971_Desc = {
    Text = "พระอาทิตย์สีเลือดตกต่ำ หมู่ทรายสีเหลืองที่เต็มไปด้วยเลือด.\nสุดยอดนักรบยืนอยู่ในสนามรบที่ใกล้จะสัมผัสความมืด,     นึกถึงเปลวไฟสีทองและเกียรติยศในวันเก่า.\nนกแร้งที่กรีดร้องไม่รู้จบบินขึ้น,     บังแสงสุดท้ายอย่างสมบูรณ์.ภายใต้การชักชวนที่ยิ่งใหญ่,     เหล่าวิญญาณซึ่งบีบอัดอยู่ในทะเลทราย จะมาเป็นเพื่อนร่วมฝัง 그เขา."
  },
  CollectionHall_89971_LockTip = {
    Text = "สำเร็จการล่องเรือในจิตสำนึก「เลือดและทราย」ระดับยาก"
  },
  CollectionHall_89971_Title = {
    Text = "แสงแดงอาบเลือด"
  },
  CollectionHall_89972_Desc = {
    Text = "หากโลกนี้ติดอยู่ในความมืด ฉันจะเป็นโคมไฟสุดท้าย\nหากในคนกลุ่มไม่มีความยุติธรรม ฉันจะส่งเสียงให้คนอ่อนแอสุด"
  },
  CollectionHall_89972_LockTip = {
    Text = "บรรลุการเดินทางด้วยความตระหนักใน「การนำทางสุดท้าย」"
  },
  CollectionHall_89972_Title = {
    Text = "ไฟเทียนยามค่ำคืน"
  },
  CollectionHall_89973_Desc = {
    Text = "นั่นคือการต่อสู้โชคชะตาของเธอ นั่นคือสนามรบที่เธอต้องไป\nเธอได้สละทุกความอ่อนไหว ความลังเล ความกลัวจากอดีตไปแล้ว\nเธอไม่เคยรู้สึกเสียใจ เพราะเธอได้เข้าใจความหมายของการต่อสู้ในชีวิตนี้แล้ว\nเธอไม่เคยโดดเดี่ยว เพราะเงาสะท้อนบนใบมีดในมือเธอคือใบหน้าของตัวเองที่หยิ่งยโส"
  },
  CollectionHall_89973_LockTip = {
    Text = "เคลียร์ภารกิจ「ผู้กลับมาแห่งเอลวอส」ระดับยาก"
  },
  CollectionHall_89973_Title = {
    Text = "ถามกับภูเขา"
  },
  CollectionHall_89974_Desc = {
    Text = "เฮ้โย เฮ้โย ขึ้นสมอ เรือใบขึ้น สูงขึ้นปลดเชือกลอย.\nผู้นำทางของเราได้ปีนขึ้นไปที่ยอดเสา ธงสีสดใสได้ถูกชูขึ้นสูง.\nออกเดินทาง ออกเดินทาง สู่ทิศทางที่เธอชี้นำ เราจะออกเดินทางกันแล้ว！"
  },
  CollectionHall_89974_LockTip = {
    Text = "บรรลุการเดินทางด้วยความตระหนักใน「การนำทางสุดท้าย」"
  },
  CollectionHall_89974_Title = {
    Text = "บันทึกการนำทาง"
  },
  CollectionHall_89975_Desc = {
    Text = "ทุกครั้งที่ออกเรือ เธอพร้อมเสมอที่จะเขียนพินัยกรรมใหม่\nเพลงที่ถูกส่งต่อรุ่นต่อรุ่นเสมือนเพลงกล่อมในความฝัน โอบรับวิญญาณของเธออย่างอ่อนโยน\nธงที่สดใสโบกศัตรูในลม เนื้อของเธออาจจะสลายเน่าและจมลึกทะเลลึก แต่วิญญาณของเธอจะยืนอยู่บนเรือของเธอ ฉายระยับแสงสุดที่ไม่มีจุดสิ้นสุดสู่ดวงดาวและทะเล"
  },
  CollectionHall_89975_LockTip = {
    Text = "บรรลุการเดินทางด้วยความตระหนักใน「การนำทางสุดท้าย」"
  },
  CollectionHall_89975_Title = {
    Text = "บทเพลงแห่งผู้บังคับการ"
  },
  CollectionHall_89976_Desc = {
    Text = "ในทะเลทรายคูซิ ลมทรายเป็นแขกที่ไม่สิ้นสุด เม็ดทรายที่บินว่อนอยู่ทั่วจะเต็มปากและจมูกของคนที่ยังมีชีวิตอยู่ และฝังศพที่ตายไปไม่มีชื่อเรียก\nมีเพียงสัตว์ที่กระหายคาโรซึ่งจะสูบไอของอาหารสุดยอดในสายลม"
  },
  CollectionHall_89976_LockTip = {
    Text = "ผ่านการล่องเรือในจิตสำนึก「เลือดและทราย」"
  },
  CollectionHall_89976_Title = {
    Text = "ทรายเหลืองและสัตว์ร้าย"
  },
  CollectionHall_89977_Desc = {
    Text = "พระอาทิตย์ในทะเลทรายนั้นต่างจากที่อื่น มันซีดจางและแสบตา แต่ไม่เคยหวานนุ่มเลยแม้แต่น้อย สัตว์ป่าไม่สามารถจินตนาการถึงฤดูใบไม้ผลิที่คุณพูดถึง งั้นก็คงต้องให้คุณไปดูพระอาทิตย์ที่แท้จริงแทน."
  },
  CollectionHall_89977_LockTip = {
    Text = "ผ่านการล่องเรือในจิตสำนึก「เลือดและทราย」"
  },
  CollectionHall_89977_Title = {
    Text = "เลือดและทรายที่ไม่มีวันกลับคืน"
  },
  CollectionHall_89978_Desc = {
    Text = "หิมะใหญ่ลงมาไม่หยุด สีขาวครอบด้วยศีรษะของนักรบ\nความทรงจำตลอดชีวิตของเธอไหลเผชิญ เธอเดินผ่านที่ลึกลับของใจคน ต้องไปยังภูเขาอันยิ่งใหญ่\nการหักหลัง การทิ้ง การปกป้อง ทุกความเจ็บปวดและความโกรธ ก็เป็นแต่การต่อสู้อีกครั้งและอีกครั้ง กับคน กับภูเขา กับตัวเอง\nเธอมองไปที่ผู้นำของเธอ มองไปที่เพื่อนใหม่ที่คุ้นเคยและที่ไม่รู้จัก และแสดงรอยยิ้มที่ไม่ชำนาญ\nเธออาจจะได้ชัยชนะคืนหรืออาจจะตายบนสนามต่อสู้ แต่แม้กระทั่งเมื่อขึ้นสวรรค์หรือตกนรก เธอจะไม่วางดาบที่อยู่ในมือของเธอ\nเพื่อไม่ให้เสียสิ่งเหล่านี้ไปอีกครั้ง คราวนี้เธอเลือกที่จะยกดาบซึ่งเรียกว่าดาบปกป้อง ไปสู่สนามต่อสู้ของเธอเพียงลำพัง"
  },
  CollectionHall_89978_LockTip = {
    Text = "ทำภารกิจ「เอลวอสผู้กลับมา」สำเร็จ"
  },
  CollectionHall_89978_Title = {
    Text = "เพื่อไม่ให้การสูญเสียเกิดขึ้นในวันพรุ่งนี้"
