  },
  CollectionHall_90415_Title = {
    Text = "นอกขอบฟ้า·บน"
  },
  CollectionHall_90416_Desc = {
    Text = "<Title:คำอธิบาย>\nสินค้าแปรงทองที่ถูกฝึกฝนโดยโบสถ์แสงศักดิ์สิทธิ์เพื่อทำพิธีอัญเชิญเทพ ได้รับการอภัยจากการถูกทิ้งในกองขยะเนื่องจากเป็นคู่แฝด.\nเขาและพอลลักซ์น้องชายถูกเคารพตั้งแต่เด็กว่าเป็นเด็กศักดิ์สิทธิ์ ได้รับการฝึกฝนเข้มงวด และถูกฉีดซับให้ทราบถึงเทววิทยาของคนถือไฟ หนึ่งเดียวของข้อมูลที่เกี่ยวกับโลกภายนอกคือหนังสือคัดลอกมือเล่มหนาหนักที่ถูกเครื่องบูชาจากผู้ศรัทธา.\nตอนเป็นวัยรุ่นหลังจากที่น้องชายถูกโบสถ์ดำเนินการเปลี่ยนแปลงอย่างทารุณ สองคนตัดสินใจหนีไปแสวงหาเสรีภาพ แต่ถูกจับกลับอย่างรวดเร็ว.\nเขาถูกแช่ในบ่อน้ำการย่อยสลายที่เรียกว่า 「บ่อบาป」 ใช้ 「การบำบัดบาป」 เพื่อรักษาแผล ได้รับความทุกข์ทรมานอันยาวนาน.\nสุดท้ายจึงถูกลืมเลือนจากคนนอกจากจูเลียต รวมถึงพอลลักซ์ ความสัมพันธ์กับน้องชายก็กลายเป็นเข้มข้นมากขึ้น.\nจากนั้นจึงสงบเสียนอกสังเวียน แสดงเป็นคนเชื่อฟังโบสถ์ แต่อยู่ภายในไม่ยอมสำเร็จในการหนีน้องชายอีกครั้ง รอโอกาสที่จะได้รับเสรีภาพอีกครั้ง."
  },
  CollectionHall_90416_LockTip = {
    Text = "ปลดล็อกหลังจาก 「คาสโตร์」 ตื่นขึ้น"
  },
  CollectionHall_90416_Title = {
    Text = "คาสเตอร์"
  },
  CollectionHall_94552_LockTip = {
    Text = "ต้องผ่านกิจกรรมที่มีเวลาจำกัด「การพิชิตอันยิ่งใหญ่: การล่าสSacred」ในระดับใดก็ได้"
  },
  CollectionHall_94552_Title = {
    Text = "การพิชิตอันยิ่งใหญ่: การล่าสัตว์อันศักดิ์สิทธิ์"
  },
  CollectionHall_94553_Desc = {
    Text = "<Title:บทนำ>\nโบสถ์แห่งตะเกียงได้สร้างผลิตภัณฑ์ทดลองคู่แฝดที่มีไว้เพื่อพิธีกรรมการเรียกเทพเจ้า และในช่วงเวลาที่พวกเขาถูกตัดสินว่าเป็นการทดลองที่ล้มเหลว และกำลังจะถูกทิ้งอย่างโหดร้าย ก็ได้เกิดการแยกตัวจากเลือดและเนื้อของพี่ชาย\nความผูกพันที่พยายามจะมีชีวิตรอดเช่นนั้นไม่ใช่โชคดี แต่เป็นการเปลี่ยนชะตากรรมของทั้งสองจากโศกนาฏกรรมที่สั้นลงไปเป็นโศกนาฏกรรมที่ยาวนานมากขึ้น\nอาจจะมาจากความลับของคู่แฝด เขามีสีผิวและบุคลิกที่ตรงกันข้ามกับพี่ชาย ในฐานะที่เป็นคู่แฝดที่ร่าเริงและฉลาดกว่า มักจะทำพฤติกรรมที่ขัดกับการควบคุม เหมือนกับเด็กซนในครอบครัวธรรมดา—จนกระทั่งถูกเลือกให้เป็นภาชนะของเทพเจ้าเพื่อการฝึกฝน และเริ่มมีพิธีกรรมการ 「ปรับเปลี่ยนศักดิ์สิทธิ์」 ที่เจ็บปวดและเต็มไปด้วยเลือดเป็นประจำ\nเพราะไม่สามารถทนต่อความเจ็บปวดและชะตากรรมที่สิ้นหวัง ในการร้องขอและวางแผนของเขา พี่น้องทั้งสองได้วางแผนโดยใช้ภาษาลับมาหลายปี จนในที่สุดก็สามารถหลบหนีออกมาได้\nแต่พวกเขาก็ไม่สามารถมีความสุขได้นานนัก จนถูกทหารของโบสถ์จับกลับมา โดยมีคำสั่งของลิเยตให้ถอนปีกอันเป็นอิสระของเขา และทำการล้างสมองอย่างรุนแรง จนทำให้เขาลืมพี่ชายและเริ่มสนุกกับความรู้สึกที่เป็นบุตรแห่งศักดิ์สิทธิ์และได้รับการยกย่อง\nจนกระทั่งในการหลบหนีครั้งที่สอง เขาได้ฟื้นคืนความทรงจำจากการตายของพี่ชายและพิธีกรรมการเรียกเทพเจ้า ทำให้เขาได้ถูกจุดประกายด้วยความเกลียดชังและโกรธแค้นที่ 「หัวใจศักดิ์สิทธิ์」 และทำให้การต่อสู้กับโบสถ์แห่งตะเกียงกลายเป็นทิศทางใหม่ในชีวิตของเขา."
  },
  CollectionHall_94553_LockTip = {
    Text = "ผ่านโลกแห่งความฝัน「นอกภาพขอบฟ้า·ล่าง」ปลดล็อก"
  },
  CollectionHall_94553_Title = {
    Text = "โพลลักซ์"
  },
  CollectionHall_95436_Desc = {
    Text = "บินไป,      บินไป,      นกใช้ปีกทั้งสองต่อสู้กับแรงโน้มถ่วงที่หนักหนา ขึ้นไปสูงขึ้น,      ขึ้นไปสูงขึ้น ผ่านกระแสลมที่ปั่นป่วนและการวนรอบดิ่ง พร้อมกับบินไปที่ที่สูงขึ้นเรื่อยๆ.\nแต่เขาไม่รู้ ว่าที่เท้าของเขามีเส้นสายที่ไม่สามารถมองเห็นได้เชื่อมโยงไว้ เขาอาจไม่เคยกลายเป็นนกที่แท้จริง แม้จะบิน แต่ก็ไม่มีอะไรนอกจากนกกระดาษที่น่าสงสาร.\nตอนนี้ เส้นว่าวกำลังตึงขึ้น"
  },
  CollectionHall_95436_LockTip = {
    Text = "บรรลุสั่งการทั้งหมดในความฝันโลก「ขอบฟ้าไปทั่วส่วนที่เหนือกว่า」"
  },
  CollectionHall_95436_Title = {
    Text = "นกกระดาษ"
  },
  CollectionHall_95437_Desc = {
    Text = "คุณเห็นใบหน้านั้น ใบหน้าที่อ่อนโยน สงบ และสวยงาม\nมันละลายไปในความทรงจำของคุณอย่างรวดเร็ว แต่คุณยังคงจะจำได้ตลอดว่า หลังจากคืนฝนยาวนานนั้น สิ่งที่ได้เห็นคือสีของแสงอรุณอ่อน"
  },
  CollectionHall_95437_LockTip = {
    Text = "ทำภารกิจบันทึกพิเศษ「เมืองฝนเงาลึกลับ」สำเร็จ"
  },
  CollectionHall_95437_Title = {
    Text = "ลึกเข้าไปในม่านฝน"
  },
  CollectionHall_95438_Desc = {
    Text = "เป็นแมว เป็นแมวที่ไร้กังวล แค่ใช้เวลากับคนที่รักทุกวัน นอนตากแดดข้างเธอ.\nนี่คือความฝันเล็กๆ ที่สวยงามในใจของเธอ แต่ความฝันนั้น มักจะเปราะบางและแตกง่ายเสมอ"
  },
  CollectionHall_95438_LockTip = {
    Text = "ทำภารกิจพิเศษสำเร็จ 「การแบ่งเซลล์อย่างสงบ」"
  },
  CollectionHall_95438_Title = {
    Text = "ความปรารถนาของแมว"
  },
  CollectionHall_95439_Desc = {
    Text = "แม้ว่าทุกสิ่งในโลกจะกลายเป็นเถ้าถ่าน แม้ทุกอย่างจะถูกเมือกย่อยสลายดื่มด่ำ น้ำเมือกที่ไร้เดียงสาก็ยังสามารถจมอยู่ในความฝันของตนเองได้ตลอดไป.\nที่นั่น ทุกอย่างกลับสู่สิ่งเดิม มีเพียงเสียงหัวเราะ มีเพียงความสุข"
  },
  CollectionHall_95439_LockTip = {
    Text = "สำเร็จการล่องเรือในจิตสำนึก 「ทุกอย่างเป็นปกติ」 ระดับยาก"
  },
  CollectionHall_95439_Title = {
    Text = "จมอยู่ในความโกลาหล"
  },
  CollectionHall_95440_Desc = {
    Text = "ฤดูหนาวในลอนเดเนียมไม่ค่อยมีหิมะตก ทุกครั้งที่หิมะโปรยปรายลงมาก็จะทำให้เด็ก ๆ สนุกสนาน\nคุณตื่นจากความฝันอันแสนอบอุ่น ยื่นมือออกไปนอกหน้าต่างflakes หิมะหนึ่งกลีบตกลงบนฝ่ามือ และละลายอย่างยินดีในความอบอุ่น\nหิมะที่ลอยละล่องผ่านการเดินทางอันสั้นในท้องฟ้า กลับคืนสู่แผ่นดิน กลับไปสู่น้ำที่มืดมิด กลับสู่บ้านและการเกิดใหม่ของทุกหยดน้ำ\nในหิมะครั้งแรกในปีนี้ เธอคนหนึ่งก็กลับบ้านของเธออีกครั้ง\nราตรีสวัสดิ์ หิมะ; ราตรีสวัสดิ์ 「24」."
  },
  CollectionHall_95440_LockTip = {
    Text = "ทำภารกิจพิเศษสำเร็จ 「การแบ่งเซลล์อย่างสงบ」"
  },
  CollectionHall_95440_Title = {
    Text = "ราตรีสวัสดิ์ สะเก็ดหิมะ"
  },
  CollectionHall_95441_Desc = {
    Text = "ปะการังสีขาวแพร่กระจายเป็นกิ่งก้าน เติบโตเป็นพระราชวังสีขาวล้วน\nในเสาโค้งที่ผิดรูป มีปลาหลากสีว่ายอย่างอิสระ\nร่างกายลงลึก วิญญาณล่องลอย\nคุณยินดีที่จะสูญเสียลมหายใจ ร่วมกับเธอ จมอยู่ในฝันสีขาว\nนั้นคือปาฏิหาริย์ของทะเล นั้นคือน้ำบ้านสีอบอุ่น"
  },
  CollectionHall_95441_LockTip = {
    Text = "เสร็จสิ้นการดำดิ่งจิตสำนึก 「การแกะสลักอันไพเราะ」"
  },
  CollectionHall_95441_Title = {
    Text = "พระราชวังสีขาวสะอาด"
  },
  CollectionHall_95442_Desc = {
    Text = "ติ๊ดติ๊ด——รถไฟออกเดินทาง！\nให้ฉันพFreunde ของฉันเดินทางไปยังอาณาจักรเทพนิยายที่ไม่มีความเจ็บปวดอย่างสมบูรณ์ตลอดไป"
  },
  CollectionHall_95442_LockTip = {
    Text = "การล่องเรือในจิตสำนึก「ทุกอย่างเหมือนเดิม」"
  },
  CollectionHall_95442_Title = {
    Text = "ความฝันที่ไร้เดียงสา"
  },
  CollectionHall_95443_Desc = {
    Text = "เธอคือฆาตกรหรือ? เธอดูเหมือนจะเป็นคนรักที่คุณได้พบกันอีกครั้งหลังจากเวลานาน.\nน้ำฝน,      ใบไม้แห้งและกลิ่นหอมหวานของดอกไม้,      คุณขยับจมูก,      พยายามดมกลิ่นเลือดจากกลิ่นชื้นเหล่านั้น เพื่อยืนยันว่าที่เธอนั้นมีความผิด แต่คุณไม่พบกลิ่นอะไรเลย.\nเธอก็ไม่เคยคิดจะอธิบาย ในพายุหมอกที่คลุมเธอ,      คุณตกลงไปในฝันสีเทาของเธอ."
  },
  CollectionHall_95443_LockTip = {
    Text = "ทำภารกิจบันทึกพิเศษ「เมืองฝนเงาลึกลับ」สำเร็จ"
  },
  CollectionHall_95443_Title = {
    Text = "ผู้ต้องสงสัย"
  },
  CollectionHall_95444_Desc = {
    Text = "ความกระหายเช่นนี้เธอเคยประสบเช่นกัน.\nโง่เขลา เหลือร้ายและโดดเดี่ยว.\nเธอมีโชค เพราะเธอสิ้นสุดการเร่ร่อนอันยาวนาน และมีความทรงจำที่อบอุ่นสำหรับการเคี้ยวตลอดชีวิต.\nตอนนี้เธอคว้าเปลือกของเชื้อสายเดียวกัน นำวิญญาณที่สับสนไปยังฝันที่สงบ."
  },
  CollectionHall_95444_LockTip = {
    Text = "ทำภารกิจ 「เงาลึกลับในเมืองฝน」ระดับยาก"
  },
  CollectionHall_95444_Title = {
    Text = "ความฝันของสัตว์ป่า"
  },
  CollectionHall_95445_Desc = {
    Text = "จากมีดแหลมของฉัน เสียบไปที่หัวใจของฉัน.\nในการเผชิญหน้ากับโชคชะตาที่โหดร้ายและชีวิตที่ขมขื่น ฉันรู้สึกล้วนราบรื่น ไม่มีกำลังน้อยนิด.\nฉันคิดว่าจะเป็นฉันได้ยังไง?ฉันทำได้ดีไหม?\nคำถามที่มาจากฉัน ฉันก็ไม่สามารถตอบได้"
  },
  CollectionHall_95445_LockTip = {
    Text = "ทำภารกิจพิเศษสำเร็จ 「การแบ่งเซลล์อย่างสงบ」"
  },
  CollectionHall_95445_Title = {
    Text = "ถามฉัน"
  },
  CollectionHall_95446_Desc = {
    Text = "หืม? คุณดูเหมือนจะเปลี่ยนไปเป็นคนละคนใช่ไหม?\nตามสายตาที่สดใสขึ้น? ตามท่าทางที่กระฉับกระเฉงขึ้น? หรือในร่างที่ธรรมดานี้ วิญญาณที่ถูกเปลี่ยนแล้วที่เป็นเจ้าของ?"
  },
  CollectionHall_95446_LockTip = {
    Text = "เสร็จสิ้นการดำดิ่งจิตสำนึก 「การแกะสลักอันไพเราะ」"
  },
  CollectionHall_95446_Title = {
    Text = "การย้ายวิญญาณ"
  },
  CollectionHall_95447_Desc = {
    Text = "ไม่ว่าในวันหิมะ, ฝน, วันแดด, หรือวันครึ้ม วันนี้น้ำในแม่น้ำยังคงไหลอย่างเงียบสงบ"
  },
  CollectionHall_95447_LockTip = {
    Text = "ทำภารกิจพิเศษสำเร็จ 「การแบ่งเซลล์อย่างสงบ」"
  },
  CollectionHall_95447_Title = {
    Text = "แม่น้ำอันเงียบสงบ"
  },
  CollectionHall_95448_Desc = {
    Text = "น้ำทะเลหลั่งไหล หัวของคุณหวีดหวิว.\nดวงตาเป็นร้อยจับจ้องมาที่คุณ ปากเป็นร้อยแสดงความโกรธ\nพวกมันจะกลืนคุณ พวกมันจะกลืนกินคุณ\nคุณหลับตาอย่างหวาดกลัว เมื่อคุณลืมตาขึ้นอีกที คุณพบว่าพวกมันอยู่ใกล้คุณ"
  },
  CollectionHall_95448_LockTip = {
    Text = "ทำภารกิจบันทึกพิเศษ「เมืองฝนเงาลึกลับ」สำเร็จ"
  },
  CollectionHall_95448_Title = {
    Text = "ท้องทะเลหัว"
  },
  CollectionHall_95449_Desc = {
    Text = "เธอสัญญากับคุณว่าจะพาคุณกลับบ้านด้วยกัน.\n——ในท่าทีที่คงอยู่,      กลับสู่บ้านที่เงียบสงบ,      เต็มไปด้วยปาฏิหาริย์และความงดงาม."
  },
  CollectionHall_95449_LockTip = {
    Text = "เสร็จสิ้นการดำดิ่งจิตสำนึก 「การแกะสลักอันไพเราะ」"
  },
  CollectionHall_95449_Title = {
    Text = "ศิลปะปูนซีเมนต์"
  },
  CollectionHall_95450_Desc = {
    Text = "แขกผู้มีเกียรติคนนั้นมองไปที่หลังของคาสโทร์ด้วยความหวัง ในแสงจันทร์พึมพำคำพยากรณ์ของโชคชะตา：「เขาจะออกไป จะต่อสู้ดิ้นรนในพายุ ความสูงส่งที่ทำให้เขาบินสูง จะทำให้เขาตกลงมาเช่นกัน.」"
  },
  CollectionHall_95450_LockTip = {
    Text = "บรรลุสั่งการทั้งหมดในความฝันโลก「ขอบฟ้าไปทั่วส่วนที่เหนือกว่า」"
  },
  CollectionHall_95450_Title = {
    Text = "ในพายุ"
  },
  CollectionHall_95451_Desc = {
    Text = "เกิดจากความงดงาม ตายจากความงาม.\nเธอคืออัจฉริยะ คนบ้า ปีศาจ เธอคือผู้ประหารที่เย็นชาก็ได้ เป็นคนรักที่อบอุ่นของคุณ.\nเธอใช้ความรักอันร้อนแรงในการสร้างคุณให้เป็นงานชิ้นเอกที่สมบูรณ์แบบ.\nเธอจะกอดคุณ จับมือที่เย็นชาของคุณไว้ เธอจะพาคุณกลับไปยังบ้านของศิลปะพร้อมกับเธอ."
  },
  CollectionHall_95451_LockTip = {
    Text = "สำเร็จการล่องเรือในจิตสำนึก 「การแกะสลักอันไพเราะ」 ระดับยาก"
  },
  CollectionHall_95451_Title = {
    Text = "ความตายที่สวยงาม"
  },
  CollectionHall_95452_Desc = {
    Text = "มหาสมุทรได้ยินเสียงเรียกของฉัน ดังนั้นจึงส่งคุณมาที่ข้างๆฉัน.\nจากนั้นเราก็พูดคุย ตลกขบขัน เล่นสนุกกัน จะกลายเป็นเพื่อนที่ดีที่สุดในโลก.\nในเมืองแห่งความตายที่เต็มไปด้วยการย่อยสลายนี้."
  },
  CollectionHall_95452_LockTip = {
    Text = "การล่องเรือในจิตสำนึก「ทุกอย่างเหมือนเดิม」"
  },
  CollectionHall_95452_Title = {
    Text = "กรุณาเป็นเพื่อนของฉัน"
  },
  CollectionHall_95453_Desc = {
    Text = "กลับมาเถิด ทั้งหมดที่กล้าหาญ ทั้งหมดที่ขลาด ทั้งหมดที่ฉลาด ทั้งหมดที่โง่เขลา ทั้งหมดที่แข็งแกร่ง ทั้งหมดที่อ่อนแอ.\nให้หัวใจที่เต็มไปด้วยความสุข ความเศร้า ความโกรธ ความเจ็บปวด และความเหนื่อยล้า สลายไป.\nพวกเราจะอยู่ด้วยกัน.\nเธอจะอยู่ด้วยกันตลอดไป."
  },
  CollectionHall_95453_LockTip = {
    Text = "เคลียร์ภารกิจ 「การแบ่งเซลล์ของความสงบ」 ระดับยาก"
  },
  CollectionHall_95453_Title = {
    Text = "กลับคืนหาเธอ"
  },
  CollectionHall_95454_Desc = {
    Text = "ความว่างเปล่าและรอยแตกจากวิญญาณนี้สามารถที่เติมเต็มได้โดยแค่เทพนิยายที่บริสุทธิ์ที่สุด\nสักวันหนึ่ง เธอจะบอกลาความเจ็บปวดและกลับสู่「บ้าน」ที่เต็มไปด้วยความสุขในเทพนิยาย"
  },
  CollectionHall_95454_LockTip = {
    Text = "การล่องเรือในจิตสำนึก「ทุกอย่างเหมือนเดิม」"
  },
  CollectionHall_95454_Title = {
    Text = "นิทานสยองขวัญอันไร้เดียงสา"
  },
  CollectionHall_95455_Desc = {
    Text = "ตรอกที่อัดแน่นด้วยความมืด,     ลึกและแคบเสมอมีช่วงเวลาแห่งการเปลี่ยนแปลงโชคชะตามากมาย.การพบกัน,     การโต้เถียง,     การแยกทาง,     หรือแม้แต่ความรุนแรง,     การกลั่นแกล้ง,     การฆาตกรรม.\nโชคดีที่เรื่องราวของวันนี้ไม่ได้เกิดฉากที่นองเลือดในช่วงหลัง แต่ใครจะพูดได้ว่า สิ่งที่เกิดขึ้นก่อนหน้านี้ไม่ใช่โศกนาฏกรรมจริง ๆ ?"
  },
  CollectionHall_95455_LockTip = {
    Text = "บรรลุสั่งการทั้งหมดในความฝันโลก「ขอบฟ้าไปทั่วส่วนที่เหนือกว่า」"
