  CollectionHall_97736_Title = {
    Text = "ข้อความชั่วคราว"
  },
  CollectionHall_97896_LockTip = {
    Text = "ต้องผ่านช่วงเวลาจำกัดกิจกรรม 「ถ้าทุกอย่างปกติ: เรื่องใหม่ภายใต้แสงอาทิตย์」 ให้ได้ในระดับใดระดับหนึ่ง"
  },
  CollectionHall_97896_Title = {
    Text = "ถ้าทุกอย่างยังคงเป็นปกติดี"
  },
  CollectionHall_98502_LockTip = {
    Text = "ผ่านด่านแรกของการล่องเรือในจิตสำนึก「กลางวันอมตะ」เพื่อปลดล็อก"
  },
  CollectionHall_98502_Title = {
    Text = "การล่าที่ไม่มีที่สิ้นสุด"
  },
  CollectionHall_98636_Desc = {
    Text = "ผู้ลบหลู่กระตุ้นคลื่นสีน้ำเงินเข้ม ราชาผู้โดดเดี่ยวเผชิญกับคลื่นยักษ์ที่สูงถึงพันเมตร.\nเส้นผมของเขาปลิวไปตามสายลม กระดูกและเลือดของเขาก็คือการประกาศอย่างมีเกียรติ ในรอยยิ้มที่ดูถูก เขาจะมอบตัวเองให้กับความตายและพระจันทร์.\nดังนั้นทะเลทั้งปวงได้หยุดนิ่งในขณะนั้น น้ำแข็งที่แขวนอยู่ถูกทำให้หยุดนิ่งใต้พระจันทร์เต็มดวง ทุกอย่างกลับคืนสู่ความเงียบ ทุกอย่างกลับคืนสู่ความสงบในอาณาจักรของเขา."
  },
  CollectionHall_98636_LockTip = {
    Text = "เสร็จสิ้นการดำเนินการสืบสวน·ยาก บทดาว 3-10 ปลดล็อก"
  },
  CollectionHall_98636_Title = {
    Text = "เทศกาลพระจันทร์เต็มดวง"
  },
  CollectionHall_98637_Desc = {
    Text = "การทำอาหารกับคนตายเป็นศิลปะที่มีเกียรติ.\nเขาใช้มีดและพายสอบถามคำสุดท้ายที่ยังไม่ทันได้พูด เขาใช้น้ำและไฟเติมเต็มความปรารถนาในนาทีสุดท้าย.\nทุกความทรงจำที่น่าอึดอัดใจ ความเจ็บปวด และความเปรี้ยว จะกลายเป็นงานที่ส่องสว่างและมีกลิ่นหอม เพื่อให้ผู้คนได้ลิ้มลองและเก็บรักษา"
  },
  CollectionHall_98637_LockTip = {
    Text = "เสร็จสิ้นการดำเนินการสืบสวน บทดาว 3-11 ปลดล็อก"
  },
  CollectionHall_98637_Title = {
    Text = "เจ้าของโต๊ะอาหาร"
  },
  CollectionHall_98638_Desc = {
    Text = "เด็กๆ ร้องไห้ ร้องแหลม รำคาญใจ.\nพระองค์คือศูนย์กลางของจักรวาล พระองค์คือทุกสิ่งในที่นี้.\nพระองค์ต้องการให้ทุกสายตามองเห็น มีอาณาเขต รายล้อม เชื่อฟัง และบูชาพระองค์"
  },
  CollectionHall_98638_LockTip = {
    Text = "สำเร็จการดำเนินการ \"การสืบสวน\"·ความยาก 6-10 ปลดล็อค"
  },
  CollectionHall_98638_Title = {
    Text = "การถือกำเนิดของพระเจ้า"
  },
  CollectionHall_98639_Desc = {
    Text = "เขาเก็บรักษาการตายทุกรายการ ไม่ใช่ด้วยการแกว่งเคียวอย่างไร้หัวใจ.\nเขาเคยมีมือที่อบอุ่นและจิตใจที่อ่อนไหว.\nเมื่อเขาชิมความเศร้าของจิตวิญญาณ เขาจะเปื้อนน้ำตาในทันที.\nเมื่อเขาชิมความเกลียดชังอย่างลึกซึ้ง เขาจะสั่งลงการพิพากษาแทน.\nเขาขอสัญญาในนามของเจ้าแห่งการฝังศพ: ทุกคนที่บูชาความตายจะต้องหายไปในหมอกเย็นเยือก."
  },
  CollectionHall_98639_LockTip = {
    Text = "เสร็จสิ้นการดำเนินการสืบสวน บทดาว 3-11 ปลดล็อก"
  },
  CollectionHall_98639_Title = {
    Text = "การมองของเทพเจ้าแห่งความตาย"
  },
  CollectionHall_98640_Desc = {
    Text = "รสชาติหวานหอมจากเลือดและเนื้อ และเนื้อเยื่อที่ขาดเป็นความทรงจำที่เขาคุ้นเคยและฝังลึกในใจ\nเขาเข้าใจแล้วว่าทำไมเมืองฝังศพนี้ยังคงมีอยู่จนถึงวันนี้ ไม่ได้เกิดจากพลังของผู้มีชีวิต แต่เป็นการบูชายัญจากผู้ตาย\nอีกหนึ่งเส้นเลือดสีแดงถูกกลืนลงไปในลำคอ เขาหรี่ตามอง ปล่อยให้กลิ่นหอมแต่ละอย่างซึมซาบลงในความทรงจำ ทำให้คนสนิทและประชาชนของเขาจะอยู่ในร่างของเขาตลอดไป\nพวกเขาตกลงที่จะอยู่ร่วมกันตลอดไป"
  },
  CollectionHall_98640_LockTip = {
    Text = "เสร็จสิ้นการดำเนินการสืบสวน·ยาก บทดาว 3-10 ปลดล็อก"
  },
  CollectionHall_98640_Title = {
    Text = "สัญญาเลือด"
  },
  CollectionHall_98641_Desc = {
    Text = "ใต้แสงจันทร์ มีดพิธีส่องประกายดึงดูดใจ\nเธอเผชิญความตายที่แน่วแน่ เพื่อพิสูจน์เจตจำนงอิสระที่เธอโหยหา"
  },
  CollectionHall_98641_LockTip = {
    Text = "สำเร็จการดำเนินการ \"การสืบสวน\" 6-15 ปลดล็อค"
  },
  CollectionHall_98641_Title = {
    Text = "แสงจันทร์เย็น"
  },
  CollectionHall_98642_Desc = {
    Text = "เขาสั่งสอนชนเผ่าของเขาว่าจะต่อสู้ จะฆ่า และจะอยู่รอด แต่ไม่เคยสอนว่าควรหนีอย่างไรเมื่อเผชิญกับศัตรูที่มากกว่าหมายเลขของเขา.\nดังนั้นเขาจึงไม่หนี.\nแค่ศีรษะเท่านั้น ยื่นมาเถอะ!\nเขารู้เห็นแล้ว: ผู้มีความทะเยอทะยานที่แสวงหาความแข็งแกร่งจะพบจุดจบที่เป็นนิยามของโชคชะตาในระหว่างการไล่ล่า."
  },
  CollectionHall_98642_LockTip = {
    Text = "การล่องเรือในจิตสำนึก「การล่มสลายของยักษ์ใหญ่」"
  },
  CollectionHall_98642_Title = {
    Text = "ฉันไม่กลัวความตาย"
  },
  CollectionHall_98643_Desc = {
    Text = "ชะแบะ,      ชะแบะ.\nพระเจ้ากระตุกปากของพระองค์และยินดีรับความศรัทธาทั้งหมดและผู้ศรัทธา himself."
  },
  CollectionHall_98643_LockTip = {
    Text = "สำเร็จการดำเนินการ \"การสืบสวน\" 6-15 ปลดล็อค"
  },
  CollectionHall_98643_Title = {
    Text = "มื้อแรก"
  },
  CollectionHall_98644_Desc = {
    Text = "คนในเผ่าต่อกันเข้ามาอย่างรวดเร็ว ต้องการจะเข่นฆ่าผู้นำที่พ่ายแพ้และลี้ภัย. และผู้นำที่เกรียงไกรที่สุดในประวัติศาสตร์ฟิลิส ซึ่งมีพลังเจ็บปวดไม่ยอมแพ้ แสดงให้เห็นถึงการตอบสนองด้วยการฆ่าฟัน.\nในเสียงร้องแห่งความทุกข์ที่ไม่มีที่สิ้นสุด ดาบขนาดใหญ่ดื่มเลือดอย่างหิวโหย ปรากฏร่องรอยการต่อสู้ของเขา — โหดเหี้ยม อหังการ ป่าเถื่อน และขี้โวยวาย.\nสำหรับศัตรู ไม่จำเป็นต้องเห็นใจ.\nพวกมันเป็นแค่บันไดที่จำเป็นให้เขาหวนคืนสู่อำนาจสูงสุดอีกครั้ง."
  },
  CollectionHall_98644_LockTip = {
    Text = "การล่องเรือในจิตสำนึก「การล่มสลายของยักษ์ใหญ่」"
  },
  CollectionHall_98644_Title = {
    Text = "การสังหารที่จำเป็น"
  },
  CollectionHall_98645_Desc = {
    Text = "ในวินาทีที่หันหลังกลับ เอลตันเหมือนกลายเป็นเด็กหนุ่มที่เพิ่งออกทะเลอีกครั้ง ท้องฟ้าสีฟ้าผสานไปกับทะเลกว้างใหญ่ โลกกว้างพอที่จะบรรจุทุกความทะเยอทะยานและความฝันได้.\nสิ่งที่แตกต่างคือในครั้งนี้เขาเห็นภาพของความฝันที่เป็นจริงอย่างชัดเจน และมีเส้นทางกลับไปยังดินแดนแห่งความฝันซึ่งเต็มไปด้วยนกขาว"
  },
  CollectionHall_98645_LockTip = {
    Text = "สำเร็จการดำเนินการ \"การสืบสวน\"·ความยาก 6-10 ปลดล็อค"
  },
  CollectionHall_98645_Title = {
    Text = "บ้านนกขาว"
  },
  CollectionHall_98646_Desc = {
    Text = "เวลามาถึงแล้ว,      พระจันทร์เงินลอยอยู่สูง.\nจงทำให้ปลายเท้าที่แข็งเกร็งขยับขึ้น,      คืนนี้จะต้องเฉลิมฉลองช่วงเวลานี้.\nเธอได้ก้าวเข้าสู่การเดินทางครั้งสุดท้าย และเราจะใช้กระเพาะอาหารของเราร่วมกันส่งเธอสู่สุสาน.\nคำเปล่งออกมาให้คุณหนึ่งคำ,      ให้ฉันหนึ่งคำ,      จากนี้ไปไม่มีใครจะลืมเลย."
  },
  CollectionHall_98646_LockTip = {
    Text = "เสร็จสิ้นการดำเนินการสืบสวน บทดาว 3-11 ปลดล็อก"
  },
  CollectionHall_98646_Title = {
    Text = "รำลึกถึงดนตรีแห่งการพักผ่อน"
  },
  CollectionHall_98647_Desc = {
    Text = "ถ้าปาฏิหาริย์มีรูปทรง มันก็น่าจะเป็นมืออันประนมของเธอ\nหากพระเจ้ามีรูปร่าง มันก็คงจะเป็นใบหน้าที่สงบของเธอ"
  },
  CollectionHall_98647_LockTip = {
    Text = "สำเร็จการดำเนินการ \"การสืบสวน\" 6-15 ปลดล็อค"
  },
  CollectionHall_98647_Title = {
    Text = "เทพธิดาสีขาวบริสุทธิ์"
  },
  CollectionHall_98648_Desc = {
    Text = "เฉลิมฉลองเถิด เพื่อนรัก♪\nกระดูกใต้แสงจันทร์เบ่งบานอย่างเงียบงัน เธอผู้เป็นที่รักถูกวางไว้บนจาน♪\nแขกทุกคนมาถึงแล้ว! ร้องเพลง เต้นรำ♪\nเราจะไม่ภาวนาให้ผู้ล่วงลับ เราจะไม่ไว้ทุกข์ให้ศพ♪\nเธอได้มอบความจำไว้กับฉัน เธอได้มอบน้ำตาไว้กับฉัน♪\nให้เรากลืนวิญญาณและซากเน่าของเธอลงไป♪\nในงานเลี้ยงแห่งความตาย เราจะได้พบกันอีกครั้ง♪"
  },
  CollectionHall_98648_LockTip = {
    Text = "เสร็จสิ้นการดำเนินการสืบสวน บทดาว 3-11 ปลดล็อก"
  },
  CollectionHall_98648_Title = {
    Text = "เพลงของซากศพ"
  },
  CollectionHall_98649_Desc = {
    Text = "ผู้คนกลัวเขาเพราะความแข็งแกร่งของเขา บูชเขาเพราะความโหดร้ายของเขา เกลียดชังและดูถูกเขา แต่ก็เพราะความล้มเหลวของเขาที่ล้อเลียนและเนรเทศเขา.\nแต่เสียงรบกวนของผู้อ่อนแอมันไม่มีความหมาย สายตาของยักษ์ยังคงมีไว้สำหรับผู้แข็งแกร่ง.\nในมหาสมุทรแห่งการถูกเนรเทศเขาได้วางชีวิตของตัวเองเป็นเดิมพันก้าวเข้าสู่เส้นทางการค้นหาพลังที่แน่นอน."
  },
  CollectionHall_98649_LockTip = {
    Text = "การล่องเรือในจิตสำนึก「การล่มสลายของยักษ์ใหญ่」"
  },
  CollectionHall_98649_Title = {
    Text = "ก้าวเข้าสู่เส้นทางใหม่"
  },
  CollectionHall_98650_Desc = {
    Text = "เขาจำเธอได้.\nเด็กคนนั้นที่ถูกเขากอดไว้ในผ้าห่มอย่างแน่นหนากลางพายุ\nในที่สุดเขาก็ส่งเธอไปยังเหวลึกโดยใช้มือของเขาเอง——เพื่อแลกเปลี่ยนความฝันที่นกขาวบินได้กับจิตสำนึกของเขา\nเขาหวังว่าความฝันที่สวยงามของชีวิตจะเป็นจริง จากนี้ไป ถึงเวลาที่ต้องใช้ชีวิตที่เหลือคืนความผิดทุกอย่างที่มืดมน."
  },
  CollectionHall_98650_LockTip = {
    Text = "สำเร็จการดำเนินการ \"การสืบสวน\" 6-15 ปลดล็อค"
  },
  CollectionHall_98650_Title = {
    Text = "การชำระคืน"
  },
  CollectionHall_98651_Desc = {
    Text = "การพลัดพรากและความตาย เป็นสภาวะที่ไม่สามารถหลีกหนีได้ในโลกนี้.\nจากการสูญเสียและการตายมากมาย และเดินเข้าสู่หนทางที่ไม่แน่นอน ความเศร้าโศกเล็กน้อยวนเวียนอยู่ในใจคุณ แต่เมื่อได้เห็นชีวิตของผู้ที่มีชีวิตอยู่ระหว่างความตาย เห็นกษัตริย์ที่ทำให้ความตายกลายเป็นจุดจบที่อ่อนโยน คุณก็ไม่กลัวอนาคตที่ไม่รู้จักอีกต่อไป.\nดอกไม้สีม่วงที่ไม่ลืมส่งถึงคุณบนไหล่ เป็นการส่งมอบความห่างไกลไปยังเขา.\nคุณรู้ว่าหากยังไงก็ตาม เส้นทางกลับของคุณจะไม่โดดเดี่ยว"
  },
  CollectionHall_98651_LockTip = {
    Text = "เสร็จสิ้นการดำเนินการสืบสวน·ยาก บทดาว 3-10 ปลดล็อก"
  },
  CollectionHall_98651_Title = {
    Text = "อย่าลืมการบอกลา"
  },
  CollectionHall_98652_Desc = {
    Text = "「ในนามของเพื่อนของท่าน ราชา และเจ้าของแผ่นดินที่เงียบสงบนี้ ข้าขอเชิญท่าน——จงตื่นขึ้น! กลับสู่บ้านเกิดที่ท่านรัก! ขับไล่ผู้ที่รบกวนความสงบสุขของเราออกไปตลอดกาล!」"
  },
  CollectionHall_98652_LockTip = {
    Text = "เสร็จสิ้นการดำเนินการสืบสวน บทดาว 3-11 ปลดล็อก"
  },
  CollectionHall_98652_Title = {
    Text = "ความโกรธของทุกสรรพสิ่ง"
  },
  CollectionHall_98653_Desc = {
    Text = "เธอกับพระองค์ไม่สามารถอยู่ร่วมกันได้ จึงมีมีดแทงเข้าไปในหัวใจสองดวง นั่นคือการตอบแทนให้กับพระเจ้า"
  },
  CollectionHall_98653_LockTip = {
    Text = "สำเร็จการดำเนินการ \"การสืบสวน\" 6-15 ปลดล็อค"
  },
  CollectionHall_98653_Title = {
    Text = "วันแห่งการถือกำเนิดของพระเจ้า"
  },
  CollectionHall_98654_Desc = {
    Text = "คุณไม่เคยนึกเลยว่าการสนทนากับกษัตริย์จะเริ่มต้นจากการเต้นร่วมกัน.\nการบุกเข้ามาอย่างดุดัน การทดลองที่หลงใหล การโจมตีและการป้องกัน การเผชิญหน้าและการถอย คุณทั้งสองลับๆต่อสู้กันในผ้าพันรอบที่หมุนวน.\nการทำธุรกรรมจบลงอย่างสง่างามที่การบรรยายสุดท้าย เส้นผมของกษัตริย์ปลิวลงมา และคุณเห็นความยินดีระยิบระยับในดวงตาที่มีหมอกคลุม.\nอ้าว? เมื่อกี้ถูกเขาพาไปไหนหรือเปล่า?"
  },
  CollectionHall_98654_LockTip = {
    Text = "เสร็จสิ้นการดำเนินการสืบสวน บทดาว 3-11 ปลดล็อก"
  },
  CollectionHall_98654_Title = {
    Text = "การทูตทังโก"
  },
  CollectionHall_98655_Desc = {
    Text = "สิ่งที่คุณเคยเห็นมันวับแวมและดูหมิ่น แต่กลับเป็นการกลับมาที่อ่อนโยนที่สุดในชีวิตของพวกเขา"
  },
  CollectionHall_98655_LockTip = {
    Text = "เสร็จสิ้นการดำเนินการสืบสวน บทดาว 3-11 ปลดล็อก"
  },
  CollectionHall_98655_Title = {
    Text = "สถานที่พักผ่อนของซากศพ"
  },
  CollectionHall_98656_Desc = {
    Text = "ดวงดาราเพียงแค่โคจรในเส้นทาง, แต่ชีวิตในอนุภาคต้องพบการทรมานอยู่หลายครั้ง."
  },
  CollectionHall_98656_LockTip = {
    Text = "สำเร็จการดำเนินการ \"การสืบสวน\" 6-15 ปลดล็อค"
  },
  CollectionHall_98656_Title = {
    Text = "ดาวบิดเบี้ยว"
  },
  CollectionHall_98657_Desc = {
    Text = "เมื่อเผชิญกับแม่มดที่สามารถฆ่าคนในพริบตา, ผู้ที่อ่อนแอต้องกลัว, เคารพ, กลับใจ, อ้อนวอนขอความคุ้มครอง.\nแต่เขาจะไม่มีทางทำแบบนั้น\nเขาเห็นพลังนี้, กระหายต่อพลังนี้, และไม่ว่าต้องจ่ายราคาที่ต้องจ่ายยังไง, เขาจะต้องได้พลังนี้\nแล้วเขาก็จะกลับมาอีกครั้ง, ทำให้ชื่อเสียงของเขากระหึ่มไปยังทุกซอกทุกมุมที่เพอริชิตเหยียบทับ"
  },
  CollectionHall_98657_LockTip = {
    Text = "Hoàn thành 「การล่องเรือในจิตสำนึก การล่มสลายของยักษ์」ระดับความยาก: ยาก"
  },
  CollectionHall_98657_Title = {
    Text = "ความทะเยอทะยานของยักษ์"
  },
  CollectionHall_99651_Desc = {
    Text = "<Bold:ปลาคอดเงิน24>\nทุกครั้งที่เดินผ่านร้านอาหารทอดปลา ฉันไม่สามารถหยุดตัวเองให้ไม่กรีดร้องได้.\nทำไมที่บาดเจ็บต้องเป็นปลาคอดเงินเสมอ? เราไม่ใช่ปลาคอดที่แท้จริงเลยนะ!\nเนื้อแน่น รสชาติอร่อย มันเป็นความผิดของเราหรือ?\n\n<Bold:วิฬาร24>\nดูดน้ำ……เมี้ยว เมี้ยวเมี้ยว (เห็นด้วย)!\n\n<Bold:ปลาคอดเงิน24>\nในราชอาณาจักรเลโอ ทุกนาทีมีปลาคอดเงินหนึ่งตัวที่ตายอย่างไม่เป็นธรรมกลายเป็นอาหารของมนุษย์.\nใช่ ในช่วงที่เรากำลังพูดกัน มีปลาคอดเงิน 10 ตัวที่สละชีพอย่างกล้าหาญ.\nทั้งหมด 10 ตัว! พ่อพระขา คุณได้ยินเสียงกรีดร้องของพวกมันไหม?\n\n<Bold:วิฬาร24>\nอืม……เมี้ยว? เมี้ยวเมี้ยว เมี้ยว เมี้ยว (ที่ไหน)?\n\n<Bold:ปลาคอดเงิน24>\nมันก็แค่คำเปรียบเปรยเท่านั้น โง่จัง คุณอาจจะโง่ไปหน่อย แต่คุณมีหัวใจทองคำที่สามารถเอาชนะสัญชาตญาณสัตว์และมุมมองที่แคบได้.\nฟังนะ ต่อไปฉันมีแผนการที่ต้องการให้คุณมาช่วยดำเนินการด้วยกัน...\n\n——คัดจาก《เหตุการณ์ระเบิดร้านอาหารทอดปลาประมาณจอห์น·บทสรุปคดี：คำให้การ B-03》。เนื่องจากในช่วงเวลานั้นโรงพยาบาลจิตเวชเบธเลเฮมเต็ม จึงปฏิเสธการรับตัวผู้ต้องสงสัย หลังจากถูกขังในหอคอยลอนดีเนี่ยนเป็นเวลา 23 วันจึงได้รับการปล่อยตัว。"
  },
  CollectionHall_99651_Title = {
    Text = "ความมุ่งมั่นของปลาคอดเงิน"
  },
  CollectionHall_99653_Desc = {
    Text = "เพื่อรอคอย「ช่วงเวลานั้น」 สาวน้อยจึงหลับใหลอยู่ใต้ธารน้ำแข็ง อันหนาวเหน็บของเอลวอสปิดกั้นร่างกายของเธอ แต่ไม่สามารถปิดกั้นจิตสำนึกของเธอได้ทั้งหมด \n จิตสำนึกนั้นมาจากเด็กคนหนึ่ง และก็ยังมาจากแม่อีกคน ในครรภ์มืดมิดของพระธิดา เทพเจ้าทรงสืบทอดห้วงฝันอันยาวนาน \n ในเวลาสองสิบห้าปี เธอเคยคิดอะไรไว้บ้าง มีความผูกพันอะไรบ้าง หรือมีความหวังอะไรบ้างไหม? \n จนถึงวันนี้ คำถามเหล่านี้ไม่มีใครสามารถตอบได้ ส่วนสาวน้อยคนนั้น... เธอจะบอกความจริงใจกับคนรอบข้างหรือไม่? ก็ให้ทุกอย่างอยู่ในกำมือของเวลาและอนาคตเถอะ。"
  },
  CollectionHall_99653_Title = {
    Text = "หลับใหลใต้ธารน้ำแข็ง"
  },
  CollectionHall_99654_Desc = {
    Text = "วิญญาณที่เงียบสงบและตายไปแล้วเท่านั้นที่ควรค่าแก่การลิ้มลอง การดิ้นรนของคนมีชีวิตจะทำให้รสชาติยุ่งเหยิง\nจานถูกนำมาเสิร์ฟในขณะที่ยังมีความร้อนที่เหลืออยู่ หัวใจหนึ่งดวงนอนอยู่ตรงกลางอย่างมั่นคง ผิวหน้าบวมขึ้นเล็กน้อย เหมือนเพิ่งเต้นจบการเต้นสุดท้าย สองลูกตาตกแต่งอยู่ข้างๆ มีรูม่านตาที่บรรจุความตกตะลึงในวินาทีสุดท้ายก่อนตาย ถูกต้มจนกลายเป็นสีขาวนวลอ่อน\nเขายกมีดขึ้น ค่อยๆ ฉีกหัวใจ แต่จู่ๆ ก็หยุดลง\nวิญญาณของมันยังคงกรีดร้องด้วยเสียงแหบแห้ง ความหลงใหลนั้นยังคงอยู่ในหลอดเลือด ไม่สามารถหายไปได้ทั้งหมด เขาวางมีดลง ประสานมือทั้งสองเข้าด้วยกัน ฟังเสียงของอันเดดอย่างเงียบๆ\nหัวใจดวงนี้มาจากกวีที่ทนทุกข์ทรมานจากโรคภัยก่อนตาย การสูญเสียอย่างยาวนานได้ปลดปล่อยเขาจากความตาย แต่ยังคงมีความเสียดายต่อชีวิตที่หลงเหลืออยู่ เขารู้ว่าต้องการให้หัวใจนี้ “เข้ารส” จริงๆ ต้องให้ความเคารพต่ออาหารอย่างเพียงพอ วิธีเดียวคือการรอ——\nรอความหลงใหลที่พันกันอยู่ในเนื้อแตกสลายไปในความตาย; รอเสียงสะท้อนสุดท้ายของความทรงจำของผู้ตายกลายเป็นกลิ่นหอมที่ซึมซาบอยู่บนผนังหลอดเลือด\nเขาวางมืออย่างสง่างามบนหัวเข่า หลับตาลง สูดหายใจลึกๆ\nกลิ่นหอมค่อยๆ แผ่กระจายอยู่ในอากาศ เป็นกลิ่นที่ซับซ้อนและอ่อนโยน มีทั้งการสั่นไหวของคนรักและความขมขื่นของการจากลา ผสมผสานกับกลิ่นหมึก สมุนไพร และความหวาดกลัวเล็กน้อยเหมือนน้ำค้างในตอนเช้า\nเขานั่งอย่างเงียบๆ ใต้ต้นไม้ที่มีชีวิตเติบโตอย่างร่มรื่น รอให้ผลไม้ที่สุกงอมตกลงมาอย่างตรงเวลา。"
  },
  CollectionHall_99654_Title = {
    Text = "อาหารเลิศรส"
  },
  CollectionHall_99655_Desc = {
    Text = "ดอกไม้ที่ถูกวางไว้นานจนเหี่ยวเฉาและแห้งผาก\nจะไม่มีวันได้พบกับเจ้าของของมัน"
  },
  CollectionHall_99655_Title = {
    Text = "ดอกไม้ที่ไม่ได้ส่ง"
  },
  CollectionHall_99656_Desc = {
    Text = "ตั้งแต่เกิดมา สองพี่น้องก็ไม่ได้รับอนุญาตให้ใช้ปีกบินได้ตามใจชอบ แขนที่เติบโตขึ้นเป็นคู่ที่สองบนหลังของพวกเขานั้นเหมือนกับเครื่องบูชาที่แสดงถึงอำนาจของบุตรศักดิ์สิทธิ์ ถูกกำหนดท่าทางที่ควรจะเป็นอยู่เสมอ \n ในวัยเด็ก โพลลักซ์เป็นคนที่รักปีกคู่ของพวกเขามากที่สุด ทุกวันเขาจะจัดระเบียบและทาใช้น้ำมันหอมให้กับขนปีก จนมันเปล่งประกายเหมือนผ้าไหม \n เขามักจะใช้ช่วงเวลาที่ไม่มีใครอยู่แอบกระพือปีกที่เริ่มเติบโตในช่วงเวลาสั้น ๆ ในขณะที่คาสเตอร์มองด้วยความตกใจและสั่นคลอนขึ้นจากพื้น เพื่อไปสัมผัสกับโดมที่ประดับประดา \n เมื่อเปรียบเทียบกับความสามารถของโพลลักซ์ในการทำให้ปีกของเขาเคลื่อนไหวได้อย่างยืดหยุ่นในท่าทางต่าง ๆ คาสเตอร์มักรู้สึกว่าปีกของเขานั้นเชื่องช้าเหมือนกับแผ่นไม้ สองพี่น้องใช้เวลาลับหลังในทุกคืนหลังนอน คาสเตอร์ก็เฝ้ามองโพลลักซ์กระโดดและหมุนวนในความมืด โดยเลียนแบบการบินในกรงเล็ก ๆ \n 「ปีกของน้องชายสวยมาก แต่สำหรับฉัน อาจจะไม่มีวันเรียนรู้การบินได้เลย」 คาสเตอร์คิด \n ดังนั้นในคืนที่พวกเขาหลบหนี คาสเตอร์จึงได้สัมผัสถึงความสดชื่นและความสบายของลมเย็นที่ยกปีกขึ้นเป็นครั้งแรก โพลลักซ์ที่มีความชำนาญมากกว่าจับมือของพี่ชายที่บินไปอย่างงุ่มง่ามอย่างแน่นหนา และหัวเราะเสียงดังในอากาศ ขณะบินออกเป็นเส้นโค้งที่ดิ่งและหมุนเหมือนกับนกที่แท้จริงซึ่งเป็นของท้องฟ้า \n คาสเตอร์หันไปมองแสงจันทร์ที่ฉายลงบนปีกที่ยาวและแข็งแรงของโพลลักซ์ ที่สะท้อนแสงสีเขียวอันเจิดจ้าในขนปีก \n 「นั่นจะต้องเป็นสิ่งที่สวยที่สุดในโลก ไม่ว่าจะเผชิญกับอะไรก็ตาม ฉันต้องปกป้องโพลลักซ์ ปกป้องปีกคู่นั้นให้ได้」 \n อย่างรวดเร็ว ชีวิตที่ยากลำบากในนอกพื้นที่ทำให้ปีกของโพลลักซ์ได้รับบาดเจ็บจากสัตว์ร้าย คาสเตอร์รู้สึกเจ็บปวดและเก็บขนปีกที่โพลลักซ์ทิ้งไว้ในอ้อมอกของเขา พร้อมกับสาบานว่าจะไม่ให้เหตุการณ์เช่นนี้เกิดขึ้นอีกครั้ง แต่เขาไม่รู้ว่า ในอนาคตขนนกที่โดดเดี่ยวนี้จะกลายเป็นสิ่งที่มีค่าที่สุดของเขา กลายเป็นสิ่งที่เขายึดถือไว้เกี่ยวกับปีกคู่นั้น。"
  },
  CollectionHall_99656_Title = {
    Text = "ขนนกที่โดดเดี่ยว"
  },
  CollectionHall_99657_Desc = {
    Text = "ตู——ตู——\nเสียงหวูดดังขึ้น เรือสำราญได้เข้าจอดอย่างปลอดภัยภายใต้การนำของคอร์โปซานต์\nผู้โดยสารหัวเราะและเดินลงบันไดเรือ ยกหมวกขอบคุณเธอ ขณะที่นักเดินเรือพากันเข้ามาแสดงความชื่นชม\n「ทำได้ดีมาก คอร์โปซานต์ ถ้าไม่ใช่เพราะการเตือนล่วงหน้าของคุณ เราคงจะถูกพายุกลืนกินแล้ว」\n「ใช่แล้ว ขอบคุณคำแนะนำที่ถูกต้องของคุณ เราจึงไม่หลงทางในทะเล!」\nนักเดินเรือหัวเราะและตบไหล่เธอ แสดงความชื่นชม\nในความเป็นจริง คอร์โปซานต์ไม่สามารถปรับตัวให้เข้ากับการเข้าสังคมในระยะใกล้เช่นนี้ได้ สมองที่เคร่งเครียดและมีเหตุผลของเธอ ไม่มีความคิดใดๆ นอกเหนือจาก「งาน」และ「หน้าที่」\nดังนั้น เธอจึงต้องถือว่านี่เป็นส่วนหนึ่งของ「งาน」และ「หน้าที่」\n「ฉันแค่ทำงานของตัวเองเท่านั้น ในฐานะผู้บังคับการ หน้าที่ของฉันคือการนำทางให้พวกคุณกลับบ้านอย่างปลอดภัย」\nคำตอบที่สุภาพแต่ไร้สีสัน แต่เหล่านักเดินเรือที่รู้จักเธอดีกลับหัวเราะออกมา กล่าวลาเธอและร้องเพลงเรือ เดินออกไปจากท่าเรือ\n「เรือโนดีลูสในที่สุดก็สามารถออกเดินทางได้ ออกเดินทางเถอะ โนดีลูส」\nเสียงเพลงค่อยๆ ห่างออกไป ขณะที่คอร์โปซานต์ยังคงยืนอยู่ที่ชายฝั่ง เธอกำลังเตรียมพร้อมสำหรับการออกเดินทางในอนาคต\nทะเลมีอารมณ์แปรปรวน ไม่มีผู้บังคับการคนไหนสามารถรับประกันได้ว่าตนจะชนะในทุกครั้ง เธอก็เช่นกัน แต่เธอเต็มใจที่จะใช้เวลาอย่างมหาศาลเพื่อเพิ่มโอกาสแม้เพียงนิดเดียว\nตรวจสอบ, เดินตรวจ, เรียนรู้, ตรวจสอบ ทุกอย่างในชีวิตของเธอดูเหมือนจะเหลือเพียง「งาน」เพียงอย่างเดียว\nแต่เธอยินดี เพราะทุกอย่างนี้คือเพื่อช่วงเวลานั้น ช่วงเวลาที่สำเร็จในการนำทางและนำทุกคนกลับบ้านอย่างปลอดภัย。"
  },
  CollectionHall_99657_Title = {
    Text = "ผู้นำทางแห่งท้องทะเล"
  },
  CollectionHall_99658_Desc = {
    Text = "ในความลึกอันไม่มีที่สิ้นสุด บัลลังก์สีเขียวตั้งตระหง่านอยู่ \n ผ้าคลุมฟ้าต่ำลง ดาวดาวสั่นไหว ทุกสิ่งเงียบงัน \n\n สิ่งมีชีวิตโบราณและลึกลับได้จางหายไป \n หลายชั่วอายุคน สรรพชีวิตขับขานในความฝัน \n ในน้ำที่มืดมิด ความลับที่ถูกปิดซ่อน \n เสียงกระซิบของคุณดั่งคลื่นซัดเข้ามา จมลงในห้วงลึกของจิตใจ \n\n ในความฝันอันไม่มีที่สิ้นสุด ผู้เผยพระวจนะและคนบ้าร่วมเดินทาง \n ตามหาจิตวิญญาณที่มองไม่เห็น ความกลัวและความเคารพสลับสับเปลี่ยน \n เส้นทางที่พันธนาการด้วยสาหร่ายสีเขียว ราวกับการบันทึกชะตากรรม \n นำใจของผู้หลงทางไปยังบัลลังก์สีเขียว \n อ่า ความไร้สาระและความจริงของจักรวาล \n ที่จุดตัดระหว่างความฝันและความเป็นจริง แสงสว่างนิรันดร์กระพริบ。"
  },
  CollectionHall_99658_Title = {
    Text = "บัลลังก์หินสีฟ้า"
  },
  CollectionHall_99660_Desc = {
    Text = "ทุกคนต่างต้องการเอาชนะชะตากรรม แต่ทุกคนก็กลัวชะตากรรมเช่นกัน。\nผู้กล้าร้องคำรามแห่งการต่อสู้ ขณะที่ผู้ขลาดกลัวส่งเสียงต่ำ ๆ แสดงความเชื่อฟัง แต่มีเพียงเขาเท่านั้นที่ค้นพบความลับในการเอาชนะชะตากรรม。\nนั่นคือการเชิญชวนชะตากรรมให้มาร่วมเดิมพันอย่างต่อเนื่อง กระตุ้นให้ชะตากรรมเปิดโต๊ะพนันรอบถัดไป。\nเขาไม่เคยกลัวชะตากรรม เพราะเขาเชื่อว่าตนจะไม่แพ้。\nเขาไม่เคยถามว่าจะเดิมพันอะไร ไม่ว่าจะต้องวางชิปอะไร เขาก็ไม่ลังเล รวมถึงชีวิตของเขาเอง。\nด้วยปืนรูเล็ต เขาทำให้ผู้แพ้ที่ติดการพนันหนีไปนับไม่ถ้วน จนกลายเป็นนักพนันบ้าอันเลื่องชื่อของลอนดีเนี่ยน。\nน่าเสียดายที่ไม่มีคู่ต่อสู้ที่สูสีมันช่างเหงาเหลือเกิน。\nจนกระทั่งเขาได้พบกับผู้ชายคนนั้น。\nเขาเอาชนะมนุษย์มากมาย และในที่สุดก็ได้นั่งที่โต๊ะพนันของชะตากรรม。\nไม่นานเขาก็สูญเสียทุกอย่างไป และได้กลับคืนมาพร้อมผลกำไรทั้งหมด。\nจนกระทั่งเมื่อเขาฟื้นคืนชีพเป็นสัตว์ร้าย เขาได้เห็นปืนที่ยิงลูกกระสุนสุดท้ายออกมาอยู่บนพื้น。\nเขาได้บรรจุลูกกระสุนกลับเข้าไปใหม่ และกดไกปืนไปที่หัวของตัวเองอีกครั้ง。\nในความเงียบ เขายิ้มออกมา。\nเขายังไม่แพ้ ดังนั้นวันหนึ่งเขาจะชนะในที่สุด。\nเขายังคงเชื่อเช่นนั้น แม้จะต้องเดิมพันทุกสิ่งทุกอย่าง。"
  },
  CollectionHall_99660_Title = {
    Text = "วงล้อชะตากรรม"
  },
  CollectionHall_99663_Desc = {
    Text = "หญิงสาวลึกลับคนนั้นมาหาเธอหลังจากงานศพ\n「เด็กน่าสงสาร」 เธอพูด 「เธอไม่ควรต้องประสบกับความโชคร้ายนี้」\n「เธอไม่รู้เหรอ? หลังจากที่เขาฆ่าไมลี่ ทอมป์สันก็ไปหาตัวเขา ชายผู้ชื่อเอ็ดเวิร์ดคนนี้ควรจะตายตั้งแต่ปีที่แล้ว แต่มีคนช่วยเขา」\n「เธอถามทำไม? โอ้ ฉันจะรู้ได้อย่างไร บางทีอาจจะเป็นเพราะพวกเขาเป็นพวกเดียวกัน หรือไม่ก็... คนบาปคนนั้นอาจไม่รู้ด้วยซ้ำว่าเขาทำบาปอะไร เขาพูดว่าอย่างไรนะ? ใช่แล้ว การให้อภัย การให้อภัยแก่คนบาป การให้อภัยต่อความผิดที่พวกเขาก่อขึ้น」\n「เขาเชื่อว่าทุกคนควรมีโอกาสครั้งที่สอง เธอคิดว่าไง? เราควรให้โอกาสเอ็ดเวิร์ดอีกครั้งไหม หลังจากที่เขาฆ่าไมลี่ ฆ่าน้องสาวของเธอ และแม่ของเธอ?」\n「ถูกต้อง คนแบบนี้จะไม่เปลี่ยนแปลง ตลอดไป ดังนั้น เธอรู้ว่าต้องทำอย่างไรใช่ไหม?」\nถูกต้อง คนแบบนี้จะไม่เปลี่ยนแปลง ต้องการสิ้นสุดคนเหล่านี้ ความชั่วร้ายนี้ โศกนาฏกรรมแบบนี้ ก็แค่...\nเปิดเผยความปรารถนาของพวกเขาให้เห็น ให้พวกเขาเปิดเผยด้านที่น่าสมเพช ดูพวกเขาฆ่าฟันกันเอง ต่อสู้กันเอง ทำให้พวกเขาบริสุทธิ์โดยสิ้นเชิง——\nต้อนรับสู่ดินแดนที่ปราศจากบาป。"
  },
  CollectionHall_99663_Title = {
    Text = "คนในกระจก"
  },
  CollectionHall_99666_Desc = {
    Text = "ฝูงแกะมากมายเดินไปเดินมาอยู่ในทุ่งหญ้าอันกว้างใหญ่\nในโลกนี้มีแกะมากมาย และแกะเกิดมาคือเพื่อให้คนเลี้ยงนำทาง\nเธอเป็นผู้เผยพระวจนะของโลกนี้มาตลอด ถือไม้เท้าของความรู้ในมือ\nเธอเป็นคนเลี้ยงแกะที่ดีเสมอ ตั้งใจที่จะนำฝูงแกะไปยังเส้นทางที่ถูกต้อง\nเธอใช้ไม้เท้าทำการสอนลูกแกะ และใช้ไม้เท้าขับไล่หมาป่า\nเธอยกไม้เท้าของคนเลี้ยงแกะขึ้น เพราะเธอมักจะมองเห็นเส้นทางข้างหน้าได้ก่อนเสมอ\nครั้งหนึ่งเธอนำฝูงแกะไปยังแหล่งน้ำที่อุดมสมบูรณ์ ไปยังทุ่งหญ้าที่สดใหม่\nตอนนี้เธอได้เห็นความจริงของโลกแล้ว จึงนำฝูงแกะไปยังอ้อมกอดสุดท้าย\nเดินมาทางนี้ อย่าหันหลังกลับ\nเธอยิ้มและโบกไม้เท้าของปัญญา\nดังนั้นแกะจึงไม่เห็นหน้าผาข้างหน้า\nหนึ่งตัว สองตัว\nแกะตกลงไป คนเลี้ยงแกะร้องเพลง\nโปรดติดตามคนเลี้ยงแกะผู้ไม่เห็นแก่ตัว เธอได้ชี้ทางที่แท้จริงให้กับคุณแล้ว\nไม่ต้องกลัว แม้จะเดินผ่านหุบเขาแห่งความตาย ไม้เท้าของเธอยังคงอยู่กับคุณ\nจนกว่าจะก้าวเข้าสู่ความทำลายล้างร่วมกัน\n"
  },
  CollectionHall_99666_Title = {
    Text = "ไม้เท้าของคนเลี้ยงแกะ"
  },
  CollectionHall_99667_Desc = {
    Text = "พระองค์ทรงคลุมเครืออยู่ในความเคออสที่ไร้ขอบเขต บางครั้งก็เพียงส่งสายตาไปยังสรรพชีวิตที่นอนอยู่บนโลกนี้ \n\n ผู้ที่ยังสามารถมองเห็นได้ เช่น โซเรล พระองค์มอบ 「ข้อเสนอของสัญญา」 ที่ยากจะปฏิเสธให้กับพวกเขา \n สำหรับผู้ที่หยาบกระด้างและน่าเบื่อ พระองค์จะลบล้างร่างกายของพวกเขา ทิ้งไว้เพียงตาที่ไม่สามารถร้องไห้ได้อีกต่อไป \n ตาเหล่านี้เรียกว่า 「ผู้ที่ได้รับความโปรดปราน」 \n\n พวกเขาเปล่งประกายสลัวในถ้ำ เต็มไปด้วยความหวังและความสิ้นหวัง รอคอยการอัญเชิญของพระองค์ \n แต่หนึ่งพันปีผ่านไป หนึ่งหมื่นปีผ่านไป ผู้ที่ได้รับความโปรดปรานยังคงถูกลืมในมุมมืด \n\n 「นั้น... พวกเจ้าต้องมีเหตุผลบางอย่างที่ถูกทิ้งไว้ใช่ไหม ภารกิจของพวกเจ้าคืออะไร?」 \n 「เรากำลังรอคอย」 \n 「รอคอยอะไร?」 \n 「รอคอย... แค่รอคอยเท่านั้น」 \n 「จะรู้สึกเจ็บปวดไหม?」 \n 「ตรงกันข้าม ความรักของพระองค์เต็มเปี่ยมในร่างกายเรา เพราะนี่คือสิ่งเดียวที่เราทำได้」 \n 「เมื่อเข้าใจสิ่งนี้แล้ว จึงจะเป็นผู้ศรัทธาที่แท้จริง」"
  },
  CollectionHall_99667_Title = {
    Text = "ล้านสายตาแห่งรัก"
  },
  CollectionHall_99668_Desc = {
    Text = "ชื่อของเธอคือการปรากฏตัวของปัญญา。\nเธอรู้ทุกความรู้ในโลก เป็นสิ่งที่นักวิชาการของมิซากะทุกคนปรารถนาในที่สุด。\nเพียงแค่ได้ยินคำพูดเพียงไม่กี่คำ ก็สามารถได้รับการเปิดเผยอย่างลึกซึ้ง。\nแต่เธอบอกว่า เธอเป็นเพียงผู้เฝ้าประตู。\nประตูนั้นเป็นประตูแบบไหน?\nไม่มีใครเคยเห็นประตูนั้น นักวิชาการจึงเรียกมันว่าความจริง。\nเธอคือผู้เฝ้าประตูแห่งความจริง เป็นอาธีน่าที่ปกป้องมิซากะ。\nทาวีไม่ได้ปฏิเสธการคาดเดานี้ เธอเพียงแค่จ้องมองที่นี่อย่างไม่เปลี่ยนแปลง จ้องมองไปยังโลกนี้。\nเงียบงันและมีความเห็นอกเห็นใจ。\nถ้าหากวันหนึ่งคุณเห็นประตูนั้น คุณจะเห็นดวงตาที่คุ้นเคยอย่างยิ่งอยู่บนประตู。\nความสนใจนั้นสงบและยั่งยืน。\nทะลุผ่านกาลเวลา ทะลุผ่านจิตวิญญาณของคุณ。"
  },
  CollectionHall_99668_Title = {
    Text = "ประตูแห่งความจริง"
  },
  CollectionHall_99670_Desc = {
    Text = "สาวน้อยที่กลับคืนสู่ชีวิตใหม่ด้วยการอาบเลือดสีดำ ในท่ามกลางทรายและลมที่หมุนอยู่ในทะเลทรายมานับพันปี ได้ยกเมล็ดเลือดศักดิ์สิทธิ์ของแม่ไม้ผู้สมบูรณ์ขึ้นมาด้วยความหวัง\n\n「ตราบใดที่เมล็ดพันธุ์นี้ยังอยู่บนโลก สายโลหิตของต้นไม้จะไม่มีวันขาด」\n\nอีกพันปีผ่านไป เมล็ดพันธุ์นี้ได้พยานรู้เห็นถึงความรุ่งเรืองและตกต่ำของเชื้อสายต้นไม้ ได้สัมผัสถึงการพลัดพรากและการสูญหาย ได้ผ่านช่วงแห่งความดับสูญและการเกิดใหม่ จนถึงวันที่สายน้ำที่ไหลรินกลายเป็นเลือดดำข้น มันจึงทำหน้าที่สืบทอดครั้งสุดท้าย\n\nนั่นคือการจุมพิตที่ลุกโชนและร้อนแรง เต็มไปด้วยความปรารถนาอันยังไม่สมหวัง และความเศร้าโศกที่ยังไม่กล้าเอื้อนเอ่ย พร้อมกับเสียงเต้นของหัวใจที่อบอุ่นซึ่งโอบล้อมผู้สืบทอดรุ่นใหม่อย่างแนนแน่น\n\nสีสันเหมือนปัทมะและความแวววาวเหมือนหยกขาวนั้น จะก้าวข้ามจุดสิ้นสุดสีดำไปพร้อมกับจังหวะชีวิต\n\nจากนั้น เมล็ดพันธุ์แรกของโลกใหม่ จะเติบโตขึ้นจากพื้นดินด้วยพรของเธอ กลายเป็นไม้ใหญ่ครอบคลุมแผ่นฟ้ามหาสมุทร。"
  },
  CollectionHall_99670_Title = {
    Text = "การจูบลามไฟ"
  },
  CollectionHall_99671_Desc = {
    Text = "หลังจากได้เกิดใหม่ คลีเมนไทน์ก็เหมือนกับหนอนน้อยที่ยังไม่เข้าใจอะไร เดินผ่านโลกมนุษย์และโลกที่ไม่ใช่เผ่าพันธุ์ของเธอ รู้สึกสับสนและงุนงง。\nจนกระทั่งเสียงที่นำมาซึ่งการเปิดเผยดังขึ้น——\n「ขอโทษครับ คุณหมอชาร์ล็อตต์ใช่ไหม? ผมมาหา... หา คุณหมอชาร์ล็อตต์เพื่อขอคำปรึกษาทางจิตใจ...」\nคลีเมนไทน์ในที่สุดก็รู้สึกตัว เธอไม่สนใจว่าชาร์ล็อตต์คือใคร แต่รู้สึกอยากรู้เกี่ยวกับคำใหม่ที่ผู้มาเยือนพูดถึง: 「คำปรึกษาทางจิตใจ」\nแต่เธอเป็นนักล่าที่มีความเป็นผู้ใหญ่ จะไม่มีวันเปิดเผยความไม่รู้ของตัวเอง ดังนั้นเธอจึงยิ้มออกมา ราวกับว่าเธอคือชาร์ล็อตต์ คือการไถ่บาปที่ผู้มาเยือนพูดถึง。\nน้ำตา ความทรมาน ความสิ้นหวัง ไม่ต้องกระตุ้น ผู้มาเยือนก็สามารถบีบคั้นความเจ็บปวดจากจิตวิญญาณของเธอออกมาได้。\nก่อนที่จะจากไป ผู้มาเยือนมองคลีเมนไทน์ด้วยใบหน้าที่ผ่อนคลาย และพูดว่า: 「ขอบคุณที่คุณยินดีฟังเรื่องเหล่านี้ ฉันรู้สึกดีขึ้นมาก」\nแล้วก็มีเสียงประตูปิด และเสียงหัวเราะของคลีเมนไทน์ที่เกิดขึ้นจากการได้ลิ้มรสความหวานเป็นครั้งแรก。\nเสียงหัวเราะนี้เริ่มต้นเบาๆ เหมือนเสียงหึ่งของหนอนน้อย จากนั้นก็ดังขึ้นเรื่อยๆ ราวกับเสียงกรีดร้องของแมลงที่โตเต็มวัย。\nและในเสียงหัวเราะนี้ คลีเมนไทน์ซึ่งเป็นเผ่าพันธุ์แมลงก็เติบโตขึ้นอย่างรวดเร็ว。\nสิ่งที่เกิดขึ้นต่อไปนั้นเป็นไปตามธรรมชาติ เธอกลายเป็นนักจิตวิทยา เดินด้วยรอยยิ้มและลูกตุ้ม เข้าไปในจิตใจของผู้ป่วยแต่ละคน。\nเธอยังคงเดินอยู่ในโลกมนุษย์ ยังคงไม่เป็นส่วนหนึ่งของโลกที่เต็มไปด้วยความเจริญ แต่ไม่รู้สึกสับสนหรืองุนงงอีกต่อไป。\nเพราะทั้งโลกและมนุษย์คือสนามล่าสมองของเธอ。"
  },
  CollectionHall_99671_Title = {
    Text = "ลูกตุ้มสะกดจิต"
  },
  CollectionHall_99672_Desc = {
    Text = "ดวงอาทิตย์ปล่อยพลังงานมากกว่า 300 จูลต่อวินาที ซึ่งมีส่วนหนึ่งหลายพันล้านส่วนจะมาในรูปแบบของแสงและความร้อน เดินทางมากกว่า 14.7 พันล้านเมตรจากอวกาศมาถึงโลก\nพลังงานเหล่านี้ตอบสนองความต้องการของสิ่งมีชีวิตทั้งหมดบนโลก ทำให้ทุกสายพันธุ์ในสามโดเมนที่ซับซ้อน ใหญ่โต และโกลาหลนี้สามารถสืบพันธุ์และพัฒนาได้อย่างราบรื่น\n\n「นี่คือความจริงของโลก ไม่มีสถานการณ์ใดที่จะเปลี่ยนแปลงมันได้。」\nเขาย้ำเตือนตนเองเช่นนี้อย่างต่อเนื่อง เพื่อรักษาความมั่นคงทางจิตใจ\n「แต่ทำไม...มันถึงร้อนและสว่างขนาดนี้。」\nเพราะสิ่งที่อยู่ห่างออกไป 14.7 พันล้านเมตรนั้น กำลังค่อย ๆ เข้ามาอยู่ในดวงตาของเขา\nแสงและความร้อนกำลังแผ่ออกมาจากรูม่านตาของเขา เผาผลาญทุกตารางนิ้วของร่างกายที่หรูหรา\n「ฉันเข้าใจแล้ว ฉันเข้าใจแล้ว ฉันเข้าใจว่าทำไมแสงจึงมาถึงโลกหลังจาก 8 นาที 20 วินาที。」\n「เพราะเราไม่สามารถจ่ายค่าธรรมเนียมในการเผชิญหน้ากับแสงสว่างได้。」\nเมื่อเขายอมรับทุกอย่าง เขาก็เริ่มหัวเราะเสียงดัง\n「แท้จริงแล้วฉันใกล้ชิดดวงอาทิตย์มากกว่าผู้ที่ชื่ออิคารัส。」"
  },
  CollectionHall_99672_Title = {
    Text = "ดวงอาทิตย์ที่กำลังเข้าใกล้"
  },
  CollectionHall_99673_Desc = {
    Text = "「ยังไม่สมบูรณ์แบบพอ คืนนี้ต้องฝึกอีกสิบรอบ ความสามารถของคุณธรรมดา หากต้องการเข้าร่วมวงดนตรีต้องพยายามมากกว่านี้ รู้ไหม?」\n「ครับ ท่านพ่อ。」\nการบรรเลงแบบไหนถึงเรียกว่าสมบูรณ์แบบ?\nมือของเขาไม่หยุดเคลื่อนไหว ไม่อนุญาตให้ตัวเองเกิดความผิดพลาดแม้แต่ครั้งเดียว\nเขาตำหนิตัวเองที่มีความคิดฟุ้งซ่าน ดูถูกความธรรมดาของตัวเอง\nโน้ตนับไม่ถ้วนลอยอยู่ในสายตา ทุกวัน ทุกวัน ทุกอย่างในชีวิตของเขามีแต่เสียงเพลง\nโชคดีที่เขาเข้าใกล้การบรรเลงที่สมบูรณ์แบบมากขึ้นทุกวัน เขามองไปยังแสงสว่างที่ปลายทางในความฝัน เหมือนกับว่าไม่สามารถสัมผัสมันได้ตลอดไป\nความปรารถนาที่จะสมบูรณ์แบบได้ฝังลึกอยู่ในจิตวิญญาณของเขา แต่ไม่ใช่ทุกคนที่ยินดีที่จะทำเช่นนี้\n「เพื่อพระองค์ เพื่อผู้คน นำเสนอเสียงเพลงที่สมบูรณ์แบบที่สุด นี่ไม่ใช่หน้าที่ของวงดนตรีหรอกหรือ?」\nเขามองไปยังใบหน้าที่แสดงถึงความไม่พอใจ เหมือนกับดูถูกตัวเองในอดีต\nท่านพ่อ วงดนตรีในวังก็แค่นี้เอง\nเขาทิ้งเป้าหมายที่เคยเคารพไว้ และดื้อรั้นเดินต่อไปบนเส้นทางการแสวงหาความสมบูรณ์แบบ\nเขาไม่สามารถหยุดมือเพื่อจับมือพวกเขาได้ เช่นเดียวกับที่เขาไม่สามารถหยุดมือของตัวเองในอดีต\nทุกวัน ทุกวัน เขายังคงบรรเลงต่อไป\nเสียงเพลงคือชีวิตของเขา\nนอกจากเสียงเพลง เขาก็ไม่มีอะไรเลย。"
  },
  CollectionHall_99673_Title = {
    Text = "การเล่นที่ไม่เคยหยุดนิ่ง"
  },
  CollectionHall_99674_Desc = {
    Text = "เธอยืนอยู่บนยอดเขา ยกอาวุธสีดำในมือขึ้น\nในพายุหิมะที่โหมกระหน่ำ เธอเผชิญหน้ากับภูเขาที่บ้าคลั่งนั้น เผชิญหน้ากับชะตากรรมที่ถูกทอดทิ้ง ถูกหักหลัง และถูกเหยียบย่ำ\nเธอจะต้องชนะในที่สุด หิมะและน้ำแข็งจะต้องละลาย เมื่อนั้น เธอจะปรากฏตัวในรูปแบบใหม่อีกครั้ง เธอพูดเช่นนี้\nเอลวอสเป็นดินแดนที่หนาวเย็นจัด ที่นั่นหิมะและลมพายุจะไม่จางหายตลอดทั้งปี นี่เป็นเรื่องปกติ เหมือนกับนักรบที่แข็งแกร่งเพียงใดก็ไม่อาจต่อกรกับสิ่งที่สูงส่งได้ เหมือนกับคนที่แข็งแกร่งเพียงใดก็ไม่อาจเอาชนะชะตากรรมของตนเองได้\nแต่ภูเขาหิมะนั้นในที่สุดก็ละลายไป ไม่ใช่เหรอ?"
  },
  CollectionHall_99674_Title = {
    Text = "รอจนกว่าภูเขาหิมะจะละลาย"
  },
  CollectionHall_99676_Desc = {
    Text = "พระมเหสีคนแรกมาจากอีซาราว。\nเขามีตาที่เป็นเอกลักษณ์ของชาวอีซาราว สีทองอ่อน ที่เปล่งประกายแสงน้อยๆ ในคืนที่มืดมิดของท้องฟ้าไกลๆ。\nแต่แสงนั้นหายไปพร้อมกับการล่มสลายของอีซาราว วันดาจึงดึงวัตถุสุดท้ายขึ้นมาจากโคลนมืดมิดและเก็บรักษาอย่างทะนุถนอม。\nเธอได้พบกับพระมเหสีคนที่สองและสามที่ภูเขาฟราน。\nพวกเขาคือคู่แฝดที่โลภมาก วันดาเคยหวังที่จะใช้พลังของพวกเขาในการสร้างเมืองในทะเลสาบที่หายไป。\nเธอถูกหลอกลวง ดังนั้นหนามสันหลังจึงฝังลึกลงไปในกระดูกของพวกเขา。ในความชาบด วันดาได้ดึงดวงตาที่ต่ำต้อยและไร้มารยาททั้งสองคู่มาออก และทิ้งพวกมันไว้เป็นรอยแผลของการมาเยือนของเธอ。\nพระมเหสีคนที่สี่ วันดาจำได้ว่าเขาชื่อ「จอห์น」。\nเขาคือคนที่น่าเบื่อและเป็นใบ้ แต่ทำให้เธอรู้สึกสบายใจพอสมควร สิ่งที่ทำให้เธอมีความสุขยิ่งขึ้นคือ「จอห์น」ก็มีดวงตาสีทองอ่อนเช่นเดียวกันกับเธอแทบจะเหมือนกัน。\n\n「เอาตาของพระมเหสีออกมาเถอะ」\n「ตามคำขอของท่าน... แต่พระมเหสีทำผิดอะไรหรือไม่?」\nวันดาเขย่าถ้วยน้ำขุ่นในมือ รู้สึกถึงมลทินที่ลอยอยู่บนปลายลิ้น มันช่างโง่เขลาจริงๆ ที่แม้แต่การวางยา ก็ทำได้อย่างหยาบกระด้างเช่นนี้。\nเมื่อมองดู「จอห์น」ที่เต็มไปด้วยรอยแผลจากการย่อยสลาย เธอนึกถึงดวงตาที่ไร้ชีวิตที่เคยส่งเธอออกจากบ้านเกิดในตอนที่ยังอยู่ห่างไกลจากดวงดาว。\nและดวงตาของ「จอห์น」ในขณะนี้ก็เหมือนกัน。\n「...ก็แค่บอกว่าเขาขาดอารมณ์ขันก็พอ」"
  },
  CollectionHall_99676_Title = {
    Text = "มุมมองของอิซาราอู"
  },
  CollectionHall_99678_Desc = {
    Text = "ตั้งแต่บทกวีของเธอโด่งดังในเวสต์ไซด์ เพื่อนสนิทของเธอก็ยิ่งกระตือรือร้นที่จะนำดอกไม้มาให้เธอมากยิ่งขึ้น  \n「ไม่จำเป็นต้องมีดอกไม้มากขนาดนี้ โคเล็ตต์ นี่มันเสียเปล่าจริงๆ」  \nดอกกุหลาบที่นำมาในวันนี้กองรวมกับที่นำมาเมื่อวาน ก่อนหน้า และก่อนหน้านั้น ดอกไม้เก่าบางส่วนเริ่มเน่าเพราะอัดแน่นเกินไป  \n「จะเสียเปล่าได้ยังไงล่ะ เราเคยตกลงกันไว้นะว่าจะเอาดอกไม้ของฉันมาแลกกับบทกวีของเธอ」  \nโคเล็ตต์ส่ายหัวและมองเธออย่างกระอักกระอ่วน  \nใช่แล้ว การเอาดอกไม้มาแลกกับบทกวี นั่นคือคำมั่นสัญญาของพวกเธอ เธอสัมผัสได้ว่ามีบางสิ่งเปลี่ยนไป แต่มันเป็นสิ่งที่เธอไม่อยากคิดต่อ  \nเธอยังคงเขียนบทกวี เขียนทั้งวันทั้งคืน แต่ละบทที่เคยไหลรินจากปลายปากกาของเธออย่างธรรมชาติ บัดนี้กลับดูฝืดเคือง  \nสายตาของเพื่อนขณะนำดอกไม้มามอบให้ทำให้เธอรู้สึกห่างเหินขึ้นเรื่อยๆ เธอมองดอกกุหลาบที่เน่าเปื่อยเต็มห้อง สูดกลิ่นเน่าเฟะจากดอกไม้ที่โรยรา และรู้สึกเสียใจและเศร้าหมอง  \nแต่เธอก็ไม่เคยหยุดเขียนบทกวี  \n「ฉันจะใช้ดอกไม้ที่เติบโตจากแผ่นดินนี้ซื้อเสื้อผ้า ซื้อของกิน สักวันหนึ่ง แม้แต่บ้านชั้นบนของตึกนั่น ฉันก็จะซื้อให้ได้!」  \n「ทุกคนล้วนมีสิ่งที่เกิดมาเพื่อทำ ฉันเกิดมาเพื่อพยายามเพื่อสวนดอกไม้นี้ เพื่อบ้านหลังนั้น... ส่วนเธอ เธอเกิดมาเพื่อเขียนบทกวี」  \n「ฉันเชื่อในตัวเธอ ออร์ล่า! จากวันนี้ไป บทกวีทั้งหมดของเธอฉันจะเก็บรักษาไว้อย่างดี ต่อจากนี้ ฉันจะขอดอกไม้ของฉันมาแลกกับบทกวีของเธอก็แล้วกัน!」  \nดอกไม้และบทกวี คือคำสัญญาที่พวกเธอให้แก่กัน  \nเธอไม่เคยหยุดเขียนเลย。"
  },
  CollectionHall_99678_Title = {
    Text = "ดอกไม้และบทกวีของอดีต"
  },
  CollectionHall_99679_Desc = {
    Text = "ความสัมพันธ์ระหว่างแม่มดกับหมวกปีกกว้าง บางครั้งก็เหมือนกับความสัมพันธ์ระหว่างไข่กับไก่ แยกไม่ออกว่าหมวกทำให้แม่มดมีชื่อเสียง หรือแม่มดทำให้หมวกมีชื่อเสียง \n แต่โดยรวมแล้ว ดาฟเดลมีหมวกปีกกว้างที่สง่างามเช่นนี้ \n หมวกใบนี้แต่เดิมเป็นของเจ้าของร้านคนก่อน ขณะนั้นชื่อของดาฟเดลยังไม่ใช่ชื่อของดาฟเดล เธอยังเป็นเพียงวิญญาณที่พึ่งถูกปราบและสับสน เป็นสัตว์ร้ายที่ไร้เดียงสา \n ผู้หญิงที่ยิ้มแย้มเสมอพาเธอไป เหมือนกับการสอนเด็กๆ อย่างอดทนและค่อยเป็นค่อยไป สอนเธอวิธีการเป็น 「มนุษย์」 และเคล็ดลับในการติดต่อกับผู้คน \n เมืองท่าเต็มไปด้วยการค้า มีวัฒนธรรมของมนุษย์ที่หลากหลายที่สุดในช่วงเวลานั้น ถนนที่มีร้านค้าแลกเปลี่ยนเต็มไปด้วยร้านค้ามากมายที่เกือบจะมีทุกอย่าง และเจ้าของร้านสามารถพูดคุยกับทุกคนราวกับเป็นเพื่อนเก่า \n 「เธอเก่งจริงๆ」 ดาฟเดลในขณะนั้นคิด 「แต่ก็ไม่แปลก ไม่มีใครไม่ชอบเธอ」 \n เจ้าของร้านชอบเดินเล่น ดังนั้นดาฟเดลที่แสดงบทบาทเป็นมนุษย์ที่ถูกเธอเฉือนหัวมาตลอดพันปี จึงถูกขอให้แสดงความคิดเห็นเป็นครั้งแรก \n 「คุณคิดว่าหมวกใบไหนสวย? หมวกใบนี้หรือหมวกปีกกว้างใบนี้?」 \n ผู้หญิงลองสวมหมวกมากมายต่อหน้ากระจก หมวกเหล่านี้สำหรับดาฟเดลแล้ว เป็นเพียงเครื่องมือที่ใช้ในการห่อหุ้มร่างกายและทำให้ตัวเองดูเหมือนมนุษย์มากขึ้น \n แต่ในวันนั้น เธอมองไปที่หมวกปีกกว้างที่ดูเหมือนดอกไม้ขนาดใหญ่บนหัวของเจ้าของร้าน ในหัวของเธอจึงเกิดภาพผู้หญิงที่สวมหมวกใบนี้เดินเล่นอยู่ที่ชายหาด \n 「ใบนี้」 เธอพูดขึ้นทันที 「แค่ใบนี้」 \n เจ้าของร้านหันกลับมาด้วยความประหลาดใจ ราวกับว่าไม่คิดว่าเธอจะชัดเจนในความชอบของเธอเช่นนี้ \n 「ดีเลย แน่นอนว่ามันเป็นหมวกที่ดี และเมื่อได้เลือกโดยคุณ ฉันจะดูแลมันอย่างดี」 \n ไม่รู้ว่าเป็นการกระตุ้นดาฟเดลหรือไม่ หมวกใบนี้จึงกลายเป็นเครื่องประดับประจำหัวของเธอ ตามที่เจ้าของร้านสัญญา จนกระทั่งสุดท้ายเธอได้วางมันลงในมือของดาฟเดลพร้อมกับหัวที่ยิ้มอยู่ \n 「มันเป็นหมวกที่ดีจริงๆ ฉันจะดูแลมันอย่างดี」 \n ดอกไม้สีม่วงดำที่เบ่งบาน สุดท้ายก็เบ่งบานบนหัวของเจ้าของใหม่。"
  },
  CollectionHall_99679_Title = {
    Text = "หมวกแม่มดขอบกว้าง"
  },
  CollectionHall_99683_Desc = {
    Text = "ในนิมิตแห่งบัลลังก์ พระราชาทรงรับฟังคำแนะนำจากเทพเจ้า：\nพายุของลีมูเรียจะสงบลง เหวของลีมูเรียจะจางหายไป。\nใช้ความฝันเป็นศาลา ใช้ดวงดาวเป็นเทียน พระราชาจะทรงคุ้มครองประชากรที่ดีของพระองค์ นำพาอาณาจักรแห่งพระเจ้ามาสู่พวกเรา。\n\nผู้ศรัทธาแห่งพระองค์ จงเปิดใจต้อนรับพระองค์。\nในเหวที่ห่างไกลและมืดมิด วิญญาณอันยิ่งใหญ่โบราณกำลังนอนหลับ ฟังเสียงกระซิบจากเทพเจ้า。\nพระประสงค์ของพระองค์เหมือนตาข่ายดวงดาวที่ถักทอ พระองค์รอคอยให้ท่านเข้าสู่ความฝันในสุญญตาอันเป็นนิรันดร์。\n\nพายุสงบลง น้ำไม่เคลื่อนไหว；\nแผ่นดินสงบลง แผ่นดินอยู่ในความสงบ。\nภัยพิบัติในความฝันที่สงบของพระองค์ได้กลายเป็นความว่างเปล่า，\nประชาชนอยู่ภายใต้การคุ้มครองของพระองค์อย่างปลอดภัย。\nขอให้เสียงเพลงของเราเดินทางข้ามเอควอ ขอให้พระองค์ประทานคำทำนายเพื่อหลีกเลี่ยงภัยพิบัติ，\nนำพาเราไปสู่ความสงบสุขและสวรรค์อันไม่มีที่สิ้นสุด。\nความเชื่อของเราอยู่กับพระองค์ จนกระทั่งดวงดาวดับสูญ จนกระทั่งเวลาสิ้นสุด。\n"
  },
  CollectionHall_99683_Title = {
    Text = "การเรียกของทะเลลึก"
  },
  CollectionHall_99684_Desc = {
    Text = "วันที่เจ็ดที่เริ่มเปลี่ยนเป็นซอมบี้ เขากำลังคร่ำครวญอยู่ในความเจ็บปวดจากแขนขาที่เริ่มเน่าเปื่อย ทุกการเคลื่อนไหวเล็กน้อยดึงเอาเส้นประสาทที่ไวต่อการสัมผัส ทำให้เกิดความเจ็บปวดเหมือนถูกฉีกขาด... พร้อมกับประกายแรงบัลดาลใจที่ทำให้ขนลุก\nอย่างไรก็ตาม เงาที่เต็มไปด้วยความกังวลยังคงปกคลุมศิลปินผู้นี้—เขาต้องการแปรงแบบไหนกันแน่ที่จะสามารถวาดภาพความจริงที่สุดยอดที่สุดออกมาได้?\nพิคแมนมองไปรอบๆ ด้วยตาที่อ่อนแอ จากอิฐที่อยู่ข้างบ้านไปจนถึงกิ่งไม้บนหลุมศพ สุดท้าย สายตาของเขาก็ไปหยุดที่กระดูกขาวที่เปลือยอยู่ในขาขวาที่เหี่ยวเฉาและเน่าเปื่อยของเขา\nเหมือนกับได้ยินเสียงเรียกที่ศักดิ์สิทธิ์ พิคแมนจึงดึงกระดูกขาออกมา ใช้นิ้วมือถูเลือดและเนื้อที่ติดอยู่จนหมด ก่อนจะทำให้มันกลายเป็นแปรงที่แข็งแกร่ง\nเขาขัดปลายแปรงให้แหลมคมเหมือนเขี้ยว แต่ก่อนที่ปลายแปรงจะกัดลงบนผ้าใบ มันกลับทิ่มเข้าไปที่ปลายนิ้วที่ผอมแห้งของเจ้าของ ก่อนที่พิคแมนจะรู้สึกเจ็บและปล่อยมือ ทำให้แปรงหลุดจากการควบคุมของเขา\nมันเต้นรำ! กระโดด! หมุน! มันเต้นรำอย่างบ้าคลั่งบนผ้าใบ สลักเส้นสายที่ยุ่งเหยิงและบ้าคลั่ง เส้นสายที่เพิ่มจำนวนขึ้นอย่างบ้าคลั่ง ดึงดูดให้เกิดคราบสีมืดที่มีรูปร่างแปลกประหลาด ขยายตัวอย่างช้าๆ แต่มั่นคงกัดกินคอของพิคแมน\nความสุขในชั่วขณะหนึ่งเหมือนกับมีเข็มทิ่มทะลุหัวใจที่ยังเหลืออยู่ของเขา—อวัยวะที่บวมเป่ง รูปร่างที่ยุ่งเหยิงทำให้เขาสั่นสะท้านด้วยความกลัว แต่ก็ทำให้ประสาทสัมผัสที่กำลังจะเหี่ยวเฉาฟื้นคืนชีพขึ้นมา มันแสดงออกถึงความเจ็บปวด ความแปลกประหลาด และความปรารถนาในวิธีที่กลับกันและไม่มีระเบียบ สร้างพลังที่ไม่อาจปกปิดได้\nในความผิดเพี้ยนนี้ พิคแมนเหมือนจะเข้าใกล้ 「ความงาม」 ในศักดิ์สิทธิ์มากขึ้น\nเมื่อทุกอย่างสงบลง พิคแมนยื่นกรงเล็บที่ถูกกัดกร่อนออกมา ลูบไล้แปรงสีขาวนั้นซ้ำไปซ้ำมา ในร่างที่ยังคงมีรูปร่างมนุษย์นี้ มีความปรารถนาที่ร้อนแรงและเร่งด่วนมากขึ้น\nเขาจะสร้างผลงานชิ้นเอกนี้ให้เสร็จสมบูรณ์ด้วยแปรงนี้。"
  },
  CollectionHall_99684_Title = {
    Text = "แปรงที่ปรารถนา"
  },
  CollectionHall_99687_Desc = {
    Text = "「บุตรศักดิ์สิทธิ์คือผู้ที่ถูกมองโดยผู้ถือไฟ เกิดมาได้รับการมงคลวาทจากพระองค์。」\n「บุตรศักดิ์สิทธิ์ควรเผยแพร่เจตจำนงของพระองค์ มอบแสงสว่างให้กับผู้มีความเชื่อมั่นที่ชอบธรรม。」\n「บุตรศักดิ์สิทธิ์ต้องรักษาความบริสุทธิ์ของจิตวิญญาณ。」\n「บุตรศักดิ์สิทธิ์ควรละเว้นจากความใคร่ทางโลก ปฏิบัติอย่างเคร่งครัด และให้บริการแสงสว่างอย่างเต็มที่。」\n「บุตรศักดิ์สิทธิ์ไม่ควรพูดมาก ไม่ควรพูดจาไร้สาระ。」\n「บุตรศักดิ์สิทธิ์ควรอยู่ห่างจากบาป อยู่ห่างจากผู้ที่มีบาป ไม่ให้จิตวิญญาณที่แปดเปื้อนมาปนเปื้อนเขา。」\n「บุตรศักดิ์สิทธิ์……」\nตั้งแต่เขามีความทรงจำ กฎเกณฑ์หนึ่งแล้วหนึ่งกฎเกณฑ์ก็เหมือนโซ่ตรวนที่ผูกพันเขา ขึ้นไปบนแท่นที่เคารพ แต่ทำให้เขาไม่สามารถประพฤติตนไม่เหมาะสม ไม่สามารถก้มหน้าหรือปล่อยให้ความโกรธและความดีใจควบคุมเขาได้。\nเขาถูกสวมใส่เสื้อคลุมที่กว้างใหญ่และหรูหรา ท่ามกลางเหล่าบริกรนับไม่ถ้วน ตามคำร้องขอแสดงบทบาทเป็นตัวแทนที่ศักดิ์สิทธิ์ มองไปยังผู้ศรัทธาที่มีความเชื่อมั่นที่คุกเข่าลงและระมัดระวังจูบชายเสื้อของเขา。\nบุตรศักดิ์สิทธิ์ควรเป็นเช่นนี้ ไม่มีใครสนใจว่าใต้ใบหน้าที่ภาคภูมิใจและไม่เปลี่ยนแปลงนั้น มีอารมณ์และความชอบใดบ้าง。\nเช่นเดียวกับที่เขาชินกับรอยยิ้มที่ภาคภูมิใจนั้น ในช่วงเวลาที่ไม่มีใคร เขายังไม่รู้ว่าตนเองต้องการแสดงออกถึงอารมณ์แบบไหน。\n「บุตรศักดิ์สิทธิ์โพลลักซ์ ท่านควรไปยังพิธีอวยพรแล้ว。」สาวใช้ที่ก้มหน้าต่ำกล่าวด้วยความเคารพ จัดระเบียบชีวิตที่ไม่เปลี่ยนแปลงของเขา。\nเขาหันหลังและเงยหน้าขึ้น แสดงรอยยิ้มที่ไม่เปลี่ยนแปลงเช่นกัน ราวกับสวมหน้ากากศักดิ์สิทธิ์。\nความสับสน ความว่างเปล่า และความเหงาทั้งหมดถูกปกคลุมอยู่ใต้หน้ากากนั้น ราวกับว่าไม่เคยมีอยู่จริง。"
  },
  CollectionHall_99687_Title = {
    Text = "โพลักซ์SR (Temporary Text)"
  },
  CollectionHall_99691_Desc = {
    Text = "เรื่องเล่ามีเวทมนตร์ ฟรานซิสเคยบอกลิลี่แบบนี้ \nในตอนนั้นเธอมักจะนั่งถือหนังสือนิยายอยู่ริมหน้าต่าง แสงแดดต้นฤดูร้อนทำให้เสื้อโค้ทสีขาวอุ่นขึ้นเล็กน้อย ปล่อยกลิ่นหอมอบอุ่นและอ่อนโยนออกมา \nเธอเล่าเรื่องด้วยน้ำเสียงนุ่มนวลเรื่อยๆ แต่ด้วยความเหนื่อยล้าจากการมุ่งมั่นทำงานผ่าตัดเป็นเวลานานเมื่อค่ำคืนก่อน ทำให้ในที่สุดฟรานซิสก็หลับไปก่อนที่เรื่องเล่าจะจบลง \nลิลี่ไม่เคยต่อว่าแม่ของเธอ เพราะใบหน้าที่เหนื่อยล้าของแม่ที่พิงขอบหน้าต่างทำให้รู้สึกอบอุ่นใจอย่างน่าประหลาด \n\nปัจจุบัน ฟิล์มแทนที่หนังสือเล่าเรื่องราวและเวทมนตร์ เช่นเดียวกับที่ฟิล์มใหม่แทนที่ฟิล์มเก่าที่ถูกเด็กๆ ทำเสียโดยความไม่ระวัง และเหมือนกับเสียงหัวเราะของเพื่อนใหม่ที่เข้ามาแทนเวลาสงบสุขผสานกับความเจ็บปวดในอดีต \nแต่ความทรงจำที่ถูกซ่อนไว้ ยังคงเหมือนฟิล์มที่ถูกเปิดเผย มันหลับใหลอยู่ในมุมที่ไม่เป็นที่รู้จัก และถึงแม้มันจะไม่ได้พบแสงสว่างอีกเลย ก็ยังคงเปล่งประกายสดใสเสมอ。"
  },
  CollectionHall_99691_Title = {
    Text = "มนต์ของม้วนฟิล์ม 35 มม."
